INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38890, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原資", "is_correct": true, "explanation": "「新しい店を開く」ための元になるお金を表し、文の意味に合う。"}, {"text": "原則", "is_correct": false, "explanation": "決まりや基本を表す語で、店を開く元手の意味にならない。"}, {"text": "原野", "is_correct": false, "explanation": "手つかずの野原を表す語で、お金の意味にならない。"}, {"text": "原文", "is_correct": false, "explanation": "翻訳前の文章を表す語で、元手の意味にならない。"}], "explanations": {"原資": "「新しい店を開く」ための元になるお金を表し、文の意味に合う。", "原則": "決まりや基本を表す語で、店を開く元手の意味にならない。", "原野": "手つかずの野原を表す語で、お金の意味にならない。", "原文": "翻訳前の文章を表す語で、元手の意味にならない。"}, "sentence_index": 0, "correct_answer": "原資"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水は酸素と水素の原資からできている。", "explanation": "ここは〈原子〉の意味。読みは同じげんしだが、原資はお金のもとを指すので、化学の話には合わない。"}, {"text": "事故の原資は、居眠り運転だと警察が発表した。", "explanation": "原資はお金やもののもとを指すので、事故の理由を述べるこの文には合わない。"}, {"text": "この島には、人の手が加わらない原資の森が残っている。", "explanation": "ここは〈原始〉の意味。原資はお金やもののことで、人の手が加わらない自然のままの状態は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38890, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原資", "is_correct": true, "explanation": "「原資が少ないので」の空所に入り、商品を作るための元手を表す。"}, {"text": "原爆", "is_correct": false, "explanation": "爆弾を表す語で、元手の意味にならない。"}, {"text": "原盤", "is_correct": false, "explanation": "録音用の原版を表す語で、元手の意味にならない。"}, {"text": "原罪", "is_correct": false, "explanation": "宗教上の語で、元手の意味にならない。"}], "explanations": {"原資": "「原資が少ないので」の空所に入り、商品を作るための元手を表す。", "原爆": "爆弾を表す語で、元手の意味にならない。", "原盤": "録音用の原版を表す語で、元手の意味にならない。", "原罪": "宗教上の語で、元手の意味にならない。"}, "sentence_index": 6, "correct_answer": "原資"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この原資を開拓して、広い畑にした。", "explanation": "原資はお金のもとを指すので、開拓して畑にする土地の話には合わない。"}, {"text": "ローンの原資を毎月返している。", "explanation": "原資は事業などを始めるお金のもとで、借りた金額の返済の話には合わない。"}, {"text": "裁判で原資の主張が認められた。", "explanation": "原資はお金のもとを指すので、裁判での主張の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38890, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家を建てる原資を、父が残してくれた土地を売ったお金だ。", "corrected_sentence": "家を建てる原資は、父が残してくれた土地を売ったお金だ。", "error_description": "「原資は」の「は」が「を」になっている。原資は主題として「は」で受けるべきで、「を」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38890, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の祭りの原資を集まるため、寄付を呼びかけた。", "corrected_sentence": "町の祭りの原資を集めるため、寄付を呼びかけた。", "error_description": "「集める」が「集まる」になっている。「原資を」を取る他動詞は「集める」で、自動詞「集まる」とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「原資に回す」の形で、充てる先（方向）を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「回した」の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、ここでは「回す」の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、名詞同士をつなぐだけで動詞の対象は示さない。"}], "correct_answer": "に", "explanations": {"に": "「原資に回す」の形で、充てる先（方向）を示す。", "が": "主格を示すが、「回した」の対象にはならない。", "と": "並列や相手を示すが、ここでは「回す」の対象にならない。", "の": "連体修飾の助詞で、名詞同士をつなぐだけで動詞の対象は示さない。"}, "error_tags": {"が": "主格（主語）", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原資を無駄に使わない」の目的語で、使う対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「使う」の対象を「原資へ」とは言わず、ここでは合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「原資より使わない」では使う対象にならず意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「使わない」の目的語にはならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「原資を無駄に使わない」の目的語で、使う対象を示す。", "へ": "方向を示すが、「使う」の対象を「原資へ」とは言わず、ここでは合わない。", "より": "比較を示すが、「原資より使わない」では使う対象にならず意味が通らない。", "が": "主格を示すが、「使わない」の目的語にはならず、文が成り立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "が": "主格（主語）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を始めたり、作り出したりするためのもとになるお金や資源。", "primary_collocate": null, "pronunciation": "げんし", "ipa": "ɡeɲɕi", "syllable_count": 3, "sentences": [{"text": "事業を始める原資として、銀行からお金を借りた。", "target_word": "原資", "complexity_tier": "T3", "furigana": "じぎょうをはじめるげんしとして、ぎんこうからおかねをかりた。", "sentence_source": "generated"}, {"text": "農家の人たちは、収穫の一部を来年の原資に回した。", "target_word": "原資", "complexity_tier": "T3", "furigana": "のうかのひとたちは、しゅうかくのいちぶをらいねんのげんしにまわした。", "sentence_source": "generated"}, {"text": "このファンドの原資は、世界中の投資家から集められている。", "target_word": "原資", "complexity_tier": "T3", "furigana": "このファンドのげんしは、せかいじゅうのとうしかからあつめられている。", "sentence_source": "generated"}, {"text": "原資がなくなる前に、新しい収入を探さなければならない。", "target_word": "原資", "complexity_tier": "T3", "furigana": "げんしがなくなるまえに、あたらしいしゅうにゅうをさがさなければならない。", "sentence_source": "generated"}, {"text": "彼女は自分の貯金を原資に、パン屋を始めた。", "target_word": "原資", "complexity_tier": "T3", "furigana": "かのじょはじぶんのちょきんをげんしに、パンやをはじめた。", "sentence_source": "generated"}, {"text": "映画を作る原資が集まらず、撮影は延期になった。", "target_word": "原資", "complexity_tier": "T3", "furigana": "えいがをつくるげんしがあつまらず、さつえいはえんきになった。", "sentence_source": "generated"}, {"text": "奨学金の原資は、卒業生の寄付でできている。", "target_word": "原資", "complexity_tier": "T3", "furigana": "しょうがくきんのげんしは、そつぎょうせいのきふでできている。", "sentence_source": "generated"}, {"text": "原資をむだに使わないよう、毎月の計画を立てた。", "target_word": "原資", "complexity_tier": "T3", "furigana": "げんしをむだにつかわないよう、まいつきのけいかくをたてた。", "sentence_source": "generated"}, {"text": "村は観光の収入を原資にして、古い橋を直した。", "target_word": "原資", "complexity_tier": "T3", "furigana": "むらはかんこうのしゅうにゅうをげんしにして、ふるいはしをなおした。", "sentence_source": "generated"}, {"text": "商売の原資が少ないうちは、大きな店を借りないほうがいい。", "target_word": "原資", "complexity_tier": "T3", "furigana": "しょうばいのげんしがすくないうちは、おおきなみせをかりないほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原資", "label": "基本形"}], "register": "formal", "sense_fingerprint": "物事を始めたり作ったりするための元手となるお金や資源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原資", "is_correct": true, "explanation": "「事業を始める」ための元手となるお金を表し、文の意味に合う。"}, {"text": "原野", "is_correct": false, "explanation": "手つかずの野原を表す語で、事業の元手の意味にならない。"}, {"text": "原文", "is_correct": false, "explanation": "翻訳前の文章を表す語で、元手の意味にならない。"}, {"text": "原油", "is_correct": false, "explanation": "地下から採れる石油を表す語で、元手の意味にならない。"}], "explanations": {"原資": "「事業を始める」ための元手となるお金を表し、文の意味に合う。", "原野": "手つかずの野原を表す語で、事業の元手の意味にならない。", "原文": "翻訳前の文章を表す語で、元手の意味にならない。", "原油": "地下から採れる石油を表す語で、元手の意味にならない。"}, "sentence_index": 0, "correct_answer": "原資"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判で原資の主張が認められた。", "explanation": "原資はお金や資源のもとを指すので、裁判で訴える人の主張の話には合わない。"}, {"text": "この村では、今も原資の暮らしが続いている。", "explanation": "ここは〈原始〉の意味。原資は始めるためのお金や資源を指すので、昔ながらの自然な暮らしを表す原始とは合わない。"}, {"text": "故障の原資は、古い部品だと分かった。", "explanation": "原資はお金やもののもとを指すので、故障の理由を述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原資", "is_correct": true, "explanation": "「奨学金の原資」として、奨学金を作る元のお金を表す。"}, {"text": "原爆", "is_correct": false, "explanation": "爆弾を表す語で、奨学金の元手の意味にならない。"}, {"text": "原盤", "is_correct": false, "explanation": "録音用の原版を表す語で、元手の意味にならない。"}, {"text": "原罪", "is_correct": false, "explanation": "宗教上の語で、元手の意味にならない。"}], "explanations": {"原資": "「奨学金の原資」として、奨学金を作る元のお金を表す。", "原爆": "爆弾を表す語で、奨学金の元手の意味にならない。", "原盤": "録音用の原版を表す語で、元手の意味にならない。", "原罪": "宗教上の語で、元手の意味にならない。"}, "sentence_index": 6, "correct_answer": "原資"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水は酸素と水素の原資からできている。", "explanation": "原資はお金のもとを指すので、開拓して畑にする土地の話には合わない。"}, {"text": "ローンの原資を毎月返している。", "explanation": "原資は事業などを始めるお金のもとで、借りた金額の返済の話には合わない。"}, {"text": "この原資を開拓して、広い畑にした。", "explanation": "ここは〈原野〉の意味。原資はお金のもとを指すので、開拓する土地の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店を開く原資は、親からお金を借りた。", "corrected_sentence": "店を開く原資として、親からお金を借りた。", "error_description": "「原資は」と主題にしているが、お金を借りるのは人なので、原資を主語にする文は成り立たない。「原資として」と用途を述べる形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38891, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "原資を足りなくて、計画を延期した。", "corrected_sentence": "原資が足りなくて、計画を延期した。", "error_description": "「原資が足りない」の「が」が「を」になっている。「足りない」は「〜が足りない」と主語に「が」をとるので、「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "分散の対義語。物が一か所に集まる意味で、「公園の遊具は広い敷地に分散して置かれている」と対になる。"}, {"text": "連結", "is_correct": false, "explanation": "つなげる意味で、分散の対義語にはならない。"}, {"text": "整備", "is_correct": false, "explanation": "整えて使える状態にする意味で、分散の対義語にはならない。"}, {"text": "搬入", "is_correct": false, "explanation": "物を建物の中に運び入れる意味で、分散の対義語にはならない。"}], "correct_answer": "集中", "explanations": {"集中": "分散の対義語。物が一か所に集まる意味で、「公園の遊具は広い敷地に分散して置かれている」と対になる。", "連結": "つなげる意味で、分散の対義語にはならない。", "整備": "整えて使える状態にする意味で、分散の対義語にはならない。", "搬入": "物を建物の中に運び入れる意味で、分散の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "分散の対義語。物事が一か所に集まる意味で、「谷のあちこちに村が分散している」と対になる。"}, {"text": "停滞", "is_correct": false, "explanation": "物事が進まず止まる意味で、分散の対義語にはならない。"}, {"text": "規則", "is_correct": false, "explanation": "決まり事の意味で、分散の対義語にはならない。"}, {"text": "運搬", "is_correct": false, "explanation": "物を運ぶ意味で、分散の対義語にはならない。"}], "correct_answer": "集中", "explanations": {"集中": "分散の対義語。物事が一か所に集まる意味で、「谷のあちこちに村が分散している」と対になる。", "停滞": "物事が進まず止まる意味で、分散の対義語にはならない。", "規則": "決まり事の意味で、分散の対義語にはならない。", "運搬": "物を運ぶ意味で、分散の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものが一か所にまとまっていないで、いろいろな場所に分かれていること。", "primary_collocate": null, "pronunciation": "ぶんさん", "ipa": "bɯɴsaɴ", "syllable_count": 4, "sentences": [{"text": "町には小さな店が分散していて、買い物に行くのが不便だ。", "target_word": "分散", "complexity_tier": "T3", "furigana": "町[まち]には小[ちい]さな店[みせ]が分散[ぶんさん]していて、買[か]い物[もの]に行[い]くのが不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "島に人家が分散しているので、郵便の配達に時間がかかる。", "target_word": "分散", "complexity_tier": "T3", "furigana": "島[しま]に人家[じんか]が分散[ぶんさん]しているので、郵便[ゆうびん]の配達[はいたつ]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "会社の事務所が市内に分散しているため、会議のたびに移動が必要だ。", "target_word": "分散", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の事務所[じむしょ]が市内[しない]に分散[ぶんさん]しているため、会議[かいぎ]のたびに移動[いどう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "公園の遊具は広い敷地に分散して置かれている。", "target_word": "分散", "complexity_tier": "T3", "furigana": "公園[こうえん]の遊具[ゆうぐ]は広[ひろ]い敷地[しきち]に分散[ぶんさん]して置[お]かれている。", "sentence_source": "generated"}, {"text": "荷物を三つの部屋に分散して置いた。", "target_word": "分散", "complexity_tier": "T3", "furigana": "荷物[にもつ]を三[みっ]つの部屋[へや]に分散[ぶんさん]して置[お]いた。", "sentence_source": "generated"}, {"text": "山の中に集落が分散しており、バスの本数が少ない。", "target_word": "分散", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]に集落[しゅうらく]が分散[ぶんさん]しており、バスの本数[ほんすう]が少[すく]ない。", "sentence_source": "generated"}, {"text": "倉庫が各地に分散していれば、災害のとき全部を失わずにすむ。", "target_word": "分散", "complexity_tier": "T3", "furigana": "倉庫[そうこ]が各地[かくち]に分散[ぶんさん]していれば、災害[さいがい]のとき全部[ぜんぶ]を失[うしな]わずにすむ。", "sentence_source": "generated"}, {"text": "参加者は会場のあちこちに分散して座っていた。", "target_word": "分散", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]は会場[かいじょう]のあちこちに分散[ぶんさん]して座[すわ]っていた。", "sentence_source": "generated"}, {"text": "病院が一か所に集まらず分散しているので、患者は迷いやすい。", "target_word": "分散", "complexity_tier": "T3", "furigana": "病院[びょういん]が一[いっ]か所[しょ]に集[あつ]まらず分散[ぶんさん]しているので、患者[かんじゃ]は迷[まよ]いやすい。", "sentence_source": "generated"}, {"text": "谷のあちこちに小さな村が分散している。", "target_word": "分散", "complexity_tier": "T3", "furigana": "谷[たに]のあちこちに小[ちい]さな村[むら]が分散[ぶんさん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分散する", "label": "dictionary form (suru verb)"}, {"form": "分散した", "label": "past"}, {"form": "分散して", "label": "te-form"}], "register": "neutral", "sense_fingerprint": "建物・人・物などが一か所に集まらず、あちこちの場所に散らばっている配置の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "店が町の複数の場所に散らばっているという意味に合う。"}, {"text": "道路", "is_correct": false, "explanation": "道を指す名詞で、「店が〜していて」の述語にならない。"}, {"text": "郊外", "is_correct": false, "explanation": "町の外側の地域を指す名詞で、「店が〜していて」の動詞にはならない。"}, {"text": "駅前", "is_correct": false, "explanation": "場所を指す名詞で、「店が〜していて」の述語として文が成り立たない。"}], "explanations": {"分散": "店が町の複数の場所に散らばっているという意味に合う。", "道路": "道を指す名詞で、「店が〜していて」の述語にならない。", "郊外": "町の外側の地域を指す名詞で、「店が〜していて」の動詞にはならない。", "駅前": "場所を指す名詞で、「店が〜していて」の述語として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本を内容ごとに分散して、整理した。", "explanation": "ここは〈分類〉（種類ごとに仕分ける）の意味。〈分散〉は場所に散らばって分かれる意味で、内容で仕分ける場面には合わない。"}, {"text": "土地の価格の分散を三年分計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。場所に散らばる意味とは別で、価格の計算には合わない。"}, {"text": "エンジンの回転数の分散を計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。場所に散らばる意味とは別で、回転数の計算には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "倉庫が各地に散らばって配置されているという意味に合う。"}, {"text": "海岸", "is_correct": false, "explanation": "海辺の地域を指す名詞で、「〜していれば」の述語にならない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を止める場所を指す名詞で、倉庫の状態を表す動詞にはならない。"}, {"text": "幹線", "is_correct": false, "explanation": "主要な路線を指す名詞で、「倉庫が〜していれば」の述語にならない。"}], "explanations": {"分散": "倉庫が各地に散らばって配置されているという意味に合う。", "海岸": "海辺の地域を指す名詞で、「〜していれば」の述語にならない。", "駐車場": "車を止める場所を指す名詞で、倉庫の状態を表す動詞にはならない。", "幹線": "主要な路線を指す名詞で、「倉庫が〜していれば」の述語にならない。"}, "sentence_index": 6, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谷の一か所に小さな村が分散している。", "explanation": "一か所に集まった状況を述べるのに「分散」を使っており、意味が矛盾する。〈分散〉は離れて散らばる意味で、一か所に集まる状況とは合わない。"}, {"text": "生徒を背の順に分散させた。", "explanation": "ここは〈整列〉（決まった順に並べる）の意味。〈分散〉は離れて散らばらせる意味で、背の順に並べる場面には合わない。"}, {"text": "テストの点数の分散を計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。場所に散らばる意味とは別で、点数の計算には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷物を二つの倉庫に分散て置いた。", "corrected_sentence": "荷物を二つの倉庫に分散して置いた。", "error_description": "〈分散する〉の連用形の「て」形は「分散して」。「分散て」は「し」が抜けた誤った活用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38892, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店舗の分散を進んでいる。", "corrected_sentence": "店舗の分散が進んでいる。", "error_description": "「分散が進む」のように、進むは自動詞なので主語に「が」を使う。「分散を進んでいる」は「を」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「リスクを分散する」で、リスクが分散の対象なので対格の「を」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「リスクの分散」のように名詞につなぐ形になり、「分散する」と続けると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「分散する」の対象にならず、「リスクへ分散する」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」では対象を示せず、「リスクより分散する」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「リスクを分散する」で、リスクが分散の対象なので対格の「を」が正しい。", "の": "「リスクの分散」のように名詞につなぐ形になり、「分散する」と続けると文が成り立たない。", "へ": "方向を表す「へ」は「分散する」の対象にならず、「リスクへ分散する」は不自然。", "より": "比較を表す「より」では対象を示せず、「リスクより分散する」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "分散の対義語。物事が一か所に集まる意味で、「一つの会社に頼らず、仕事を分散させる」と対になる。"}, {"text": "固定", "is_correct": false, "explanation": "位置や状態を変えずに定めておく意味で、分散の対義語にはならない。"}, {"text": "継続", "is_correct": false, "explanation": "途切れずに続く意味で、分散の対義語にはならない。"}, {"text": "保存", "is_correct": false, "explanation": "大切に残しておく意味で、分散の対義語にはならない。"}], "correct_answer": "集中", "explanations": {"集中": "分散の対義語。物事が一か所に集まる意味で、「一つの会社に頼らず、仕事を分散させる」と対になる。", "固定": "位置や状態を変えずに定めておく意味で、分散の対義語にはならない。", "継続": "途切れずに続く意味で、分散の対義語にはならない。", "保存": "大切に残しておく意味で、分散の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "分散の対義語。注意が一点に集まる意味で、「注意が分散する」と対になる。"}, {"text": "停滞", "is_correct": false, "explanation": "物事が進まず止まる意味で、分散の対義語にはならない。"}, {"text": "規則", "is_correct": false, "explanation": "決まり事の意味で、分散の対義語にはならない。"}, {"text": "運搬", "is_correct": false, "explanation": "物を運ぶ意味で、分散の対義語にはならない。"}], "correct_answer": "集中", "explanations": {"集中": "分散の対義語。注意が一点に集まる意味で、「注意が分散する」と対になる。", "停滞": "物事が進まず止まる意味で、分散の対義語にはならない。", "規則": "決まり事の意味で、分散の対義語にはならない。", "運搬": "物を運ぶ意味で、分散の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が一か所に集中せず、複数の場所や要素に分かれている状態。", "primary_collocate": null, "pronunciation": "ぶんさん", "ipa": "bɯɴsaɴ", "syllable_count": 4, "sentences": [{"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "分散", "complexity_tier": "T3", "furigana": "特[とく]に注目[ちゅうもく]すべきは、天井[てんじょう]の重量[じゅうりょう]を分散[ぶんさん]させる「リブ・ヴォールト」と、壁[かべ]の外側[そとがわ]から支[ささ]える「フライング・バットレス」と呼[よ]ばれる技術[ぎじゅつ]です。", "sentence_source": "mined"}, {"text": "リスクを分散するために、投資先を複数に分けた。", "target_word": "分散", "complexity_tier": "T3", "furigana": "リスクを分散[ぶんさん]するために、投資先[とうしさき]を複数[ふくすう]に分[わ]けた。", "sentence_source": "generated"}, {"text": "橋は重さが分散する構造になっているので、とても丈夫です。", "target_word": "分散", "complexity_tier": "T3", "furigana": "橋[はし]は重[おも]さが分散[ぶんさん]する構造[こうぞう]になっているので、とても丈夫[じょうぶ]です。", "sentence_source": "generated"}, {"text": "一つの会社に頼らず、仕事を分散させたほうが安全だ。", "target_word": "分散", "complexity_tier": "T3", "furigana": "一[ひと]つの会社[かいしゃ]に頼[たよ]らず、仕事[しごと]を分散[ぶんさん]させたほうが安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "権力が一人に集中せず分散していると、不正が起こりにくい。", "target_word": "分散", "complexity_tier": "T3", "furigana": "権力[けんりょく]が一人[ひとり]に集中[しゅうちゅう]せず分散[ぶんさん]していると、不正[ふせい]が起[お]こりにくい。", "sentence_source": "generated"}, {"text": "災害に備えて、データを複数のサーバーに分散して保存している。", "target_word": "分散", "complexity_tier": "T3", "furigana": "災害[さいがい]に備[そな]えて、データを複数[ふくすう]のサーバーに分散[ぶんさん]して保存[ほぞん]している。", "sentence_source": "generated"}, {"text": "負担を分散できれば、一人あたりの仕事は軽くなる。", "target_word": "分散", "complexity_tier": "T3", "furigana": "負担[ふたん]を分散[ぶんさん]できれば、一人[ひとり]あたりの仕事[しごと]は軽[かる]くなる。", "sentence_source": "generated"}, {"text": "人口が都市に集中しすぎないよう、工場の分散が進められた。", "target_word": "分散", "complexity_tier": "T3", "furigana": "人口[じんこう]が都市[とし]に集中[しゅうちゅう]しすぎないよう、工場[こうじょう]の分散[ぶんさん]が進[すす]められた。", "sentence_source": "generated"}, {"text": "力が分散してしまい、チームは試合に勝てなかった。", "target_word": "分散", "complexity_tier": "T3", "furigana": "力[ちから]が分散[ぶんさん]してしまい、チームは試合[しあい]に勝[か]てなかった。", "sentence_source": "generated"}, {"text": "注意が分散すると、勉強の効率が落ちます。", "target_word": "分散", "complexity_tier": "T3", "furigana": "注意[ちゅうい]が分散[ぶんさん]すると、勉強[べんきょう]の効率[こうりつ]が落[お]ちます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分散する", "label": "dictionary form (suru verb)"}, {"form": "分散した", "label": "past"}, {"form": "分散させる", "label": "causative"}], "register": "neutral", "sense_fingerprint": "力・負担・リスクなどが一点に集まらず複数に分けられること(抽象的な分け方)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "「天井の重量を分散させる」の形で、重さを複数の箇所に分けて支えるという意味に合う。"}, {"text": "支柱", "is_correct": false, "explanation": "柱を指す名詞で、「を〜させる」の形で動詞として使えないため、ここには入らない。"}, {"text": "外壁", "is_correct": false, "explanation": "建物の外側の壁を指す名詞で、「重量を〜させる」の動作の対象にはならない。"}, {"text": "鉄骨", "is_correct": false, "explanation": "建材を指す名詞で、「を〜させる」と続く動詞にはならず、文が成り立たない。"}], "explanations": {"分散": "「天井の重量を分散させる」の形で、重さを複数の箇所に分けて支えるという意味に合う。", "支柱": "柱を指す名詞で、「を〜させる」の形で動詞として使えないため、ここには入らない。", "外壁": "建物の外側の壁を指す名詞で、「重量を〜させる」の動作の対象にはならない。", "鉄骨": "建材を指す名詞で、「を〜させる」と続く動詞にはならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "書類の枚数の分散を計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。物事を複数に分ける意味とは別で、枚数の計算には合わない。"}, {"text": "この会社の利益の分散を毎年計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。物事を複数に分ける意味とは別で、利益の計算には合わない。"}, {"text": "機械を部品ごとに分散して、掃除した。", "explanation": "ここは〈分解〉（組み立てを外して部品に分ける）の意味。〈分散〉は場所に散らばって分かれる意味で、部品に外す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "「負担を分散できれば」で、負担を複数に分けるという意味に合う。"}, {"text": "人手", "is_correct": false, "explanation": "人の手や働き手を指す名詞で、「負担を〜できれば」と続けると意味が通らない。"}, {"text": "給料", "is_correct": false, "explanation": "報酬を指す名詞で、負担の動作の述語にはならない。"}, {"text": "休日", "is_correct": false, "explanation": "休みの日を指す名詞で、「負担を〜できれば」の動詞にはならない。"}], "explanations": {"分散": "「負担を分散できれば」で、負担を複数に分けるという意味に合う。", "人手": "人の手や働き手を指す名詞で、「負担を〜できれば」と続けると意味が通らない。", "給料": "報酬を指す名詞で、負担の動作の述語にはならない。", "休日": "休みの日を指す名詞で、「負担を〜できれば」の動詞にはならない。"}, "sentence_index": 6, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で道路が二つに分散された。", "explanation": "ここは〈分断〉（つながりが切れて別々になる）の意味。〈分散〉は物が散らばる意味なので、道路が途切れる状況には合わない。"}, {"text": "この本のページ数の分散を計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。物事を複数に分ける意味とは別で、ページ数の計算には合わない。"}, {"text": "与党の支持率の分散を計算した。", "explanation": "ここは〈統計の分散〉（数値のばらつき）の意味。物事を複数に分ける意味とは別で、支持率の計算には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷重を分散れば、柱の負担は小さくなる。", "corrected_sentence": "荷重を分散すれば、柱の負担は小さくなる。", "error_description": "〈分散する〉の仮定形は「分散すれば」。「分散れば」は動詞の「す」が抜けた誤った活用で、日本語として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38893, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の分散を進んだ。", "corrected_sentence": "工場の分散が進んだ。", "error_description": "「分散が進む」のように、進むは自動詞なので主語に「が」を使う。「分散を進んだ」は「を」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "配布", "is_correct": true, "explanation": "正解。配って広く渡す意味で、配ったものを集め戻す回収の対義語として辞書で対になる。"}, {"text": "購入", "is_correct": false, "explanation": "代金を払って買うこと。配ることの反対にはならず、回収とは対にならない。"}, {"text": "受領", "is_correct": false, "explanation": "物を受け取ること。回収と同じく物を扱うが、対義語ではない。"}, {"text": "納品", "is_correct": false, "explanation": "注文の品を届けること。回収の対義語として登録されていない。"}], "correct_answer": "配布", "explanations": {"配布": "正解。配って広く渡す意味で、配ったものを集め戻す回収の対義語として辞書で対になる。", "購入": "代金を払って買うこと。配ることの反対にはならず、回収とは対にならない。", "受領": "物を受け取ること。回収と同じく物を扱うが、対義語ではない。", "納品": "注文の品を届けること。回収の対義語として登録されていない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「回収が遅れて」の主語になる「が」で、回収に直接つく。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示すが、「回収を遅れて」では文の流れが合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」だが、「回収へ遅れて」は文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「回収と遅れて」は文に合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「回収が遅れて」の主語になる「が」で、回収に直接つく。", "を": "動作の対象を示すが、「回収を遅れて」では文の流れが合わない。", "へ": "方向を示す「へ」だが、「回収へ遅れて」は文に合わない。", "と": "並列や相手を示すが、「回収と遅れて」は文に合わない。"}, "error_tags": {"を": "object_marker", "へ": "direction_or_target", "と": "parallel_or_partner"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "配布", "is_correct": true, "explanation": "正解。配って広く渡す意味で、集め戻す回収の対義語として辞書で対になる。"}, {"text": "寄贈", "is_correct": false, "explanation": "団体などに無償で贈ること。回収の対義語としては登録されていない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作ること。回収とは対にならない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売ること。配ることや集めることとは対にならない。"}], "correct_answer": "配布", "explanations": {"配布": "正解。配って広く渡す意味で、集め戻す回収の対義語として辞書で対になる。", "寄贈": "団体などに無償で贈ること。回収の対義語としては登録されていない。", "製造": "物を作ること。回収とは対にならない。", "販売": "商品を売ること。配ることや集めることとは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "使ったものを戻すこと。", "primary_collocate": null, "pronunciation": "かいしゅう", "ipa": "kaiɕɯː", "syllable_count": 4, "sentences": [{"text": "先生は授業の終わりに、テストの用紙を回収した。", "target_word": "回収", "complexity_tier": "T3", "furigana": "先生(せんせい)は授業(じゅぎょう)の終(お)わりに、テストの用紙(ようし)を回収(かいしゅう)した。", "sentence_source": "generated"}, {"text": "会社は欠陥のある商品を回収することにした。", "target_word": "回収", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は欠陥(けっかん)のある商品(しょうひん)を回収(かいしゅう)することにした。", "sentence_source": "generated"}, {"text": "貸した本の回収に、一週間もかかった。", "target_word": "回収", "complexity_tier": "T3", "furigana": "貸(か)した本(ほん)の回収(かいしゅう)に、一週間(いっしゅうかん)もかかった。", "sentence_source": "generated"}, {"text": "配った資料は、会議のあとすぐに回収する。", "target_word": "回収", "complexity_tier": "T3", "furigana": "配(くば)った資料(しりょう)は、会議(かいぎ)のあとすぐに回収(かいしゅう)する。", "sentence_source": "generated"}, {"text": "使い終わったマイクを回収して、倉庫にしまった。", "target_word": "回収", "complexity_tier": "T3", "furigana": "使(つか)い終(お)わったマイクを回収(かいしゅう)して、倉庫(そうこ)にしまった。", "sentence_source": "generated"}, {"text": "投げた網の回収は、漁師の大切な仕事だ。", "target_word": "回収", "complexity_tier": "T3", "furigana": "投(な)げた網(あみ)の回収(かいしゅう)は、漁師(りょうし)の大切(たいせつ)な仕事(しごと)だ。", "sentence_source": "generated"}, {"text": "打ち上げたロケットの一部は、海で回収された。", "target_word": "回収", "complexity_tier": "T3", "furigana": "打(う)ち上(あ)げたロケットの一部(いちぶ)は、海(うみ)で回収(かいしゅう)された。", "sentence_source": "generated"}, {"text": "アンケートの回収が遅れて、集計が始められない。", "target_word": "回収", "complexity_tier": "T3", "furigana": "アンケートの回収(かいしゅう)が遅(おく)れて、集計(しゅうけい)が始(はじ)められない。", "sentence_source": "generated"}, {"text": "宿題のノートは、朝のうちに回収しておいた。", "target_word": "回収", "complexity_tier": "T3", "furigana": "宿題(しゅくだい)のノートは、朝(あさ)のうちに回収(かいしゅう)しておいた。", "sentence_source": "generated"}, {"text": "撮影が終わったので、借りていた衣装を回収した。", "target_word": "回収", "complexity_tier": "T3", "furigana": "撮影(さつえい)が終(お)わったので、借(か)りていた衣装(いしょう)を回収(かいしゅう)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回収する", "label": "する動詞 終止形"}, {"form": "回収した", "label": "過去形"}, {"form": "回収して", "label": "て形"}, {"form": "回収される", "label": "受身形"}], "register": "neutral (plain style)", "sense_fingerprint": "配った・貸した・使ったものを集めて手元に戻すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回収", "is_correct": true, "explanation": "正解。配ったものや使ったものを集めて戻す意味で、「回収した」が文に合う。"}, {"text": "回転", "is_correct": false, "explanation": "物が円を描いて回ること。用紙を集める意味にならず、文の動作と合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解くこと。用紙を対象にできず、文の動作と合わない。"}, {"text": "回復", "is_correct": false, "explanation": "元の状態に戻ること。病気や体力に使い、用紙は対象にならない。"}], "explanations": {"回収": "正解。配ったものや使ったものを集めて戻す意味で、「回収した」が文に合う。", "回転": "物が円を描いて回ること。用紙を集める意味にならず、文の動作と合わない。", "解散": "集まりを解くこと。用紙を対象にできず、文の動作と合わない。", "回復": "元の状態に戻ること。病気や体力に使い、用紙は対象にならない。"}, "sentence_index": 0, "correct_answer": "回収"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪が治って、ようやく体力を回収した。", "explanation": "ここは〈回復〉の意味。回収は配ったり使ったりしたものを集め戻すことで、体力には使わない。"}, {"text": "畑で育てた野菜を、すべて回収した。", "explanation": "ここは〈収穫〉の意味。作物を取り入れることは収穫で、回収は使ったものを集め戻す場合に使う。"}, {"text": "子どものころから、珍しい切手を回収している。", "explanation": "ここは〈収集〉の意味。趣味で集めるのは収集で、回収は使ったものを集め戻す場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回収", "is_correct": true, "explanation": "正解。海に落ちたロケットの部品を集めて戻す意味で、「回収された」が文に合う。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。部品に使えず、「延期された」は文の意味に合わない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べること。海で部品に対して行う動作として文に合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解くこと。ロケットの部品を対象にできず、文に合わない。"}], "explanations": {"回収": "正解。海に落ちたロケットの部品を集めて戻す意味で、「回収された」が文に合う。", "延期": "予定を先に延ばすこと。部品に使えず、「延期された」は文の意味に合わない。", "点検": "状態を調べること。海で部品に対して行う動作として文に合わない。", "解散": "集まりを解くこと。ロケットの部品を対象にできず、文に合わない。"}, "sentence_index": 6, "correct_answer": "回収"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は前の発言を回収した。", "explanation": "ここは〈撤回〉の意味。回収は物を集め戻すことで、発言を取り消す意味では使わない。"}, {"text": "山で珍しい植物を回収した。", "explanation": "ここは〈採取〉の意味。標本として植物を取ることは採取で、使ったものを戻す意味の回収は合わない。"}, {"text": "地球は太陽のまわりを回収している。", "explanation": "ここは〈公転〉の意味。天体が軌道を回ることは公転で、回収は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "係の人は、配り終えた紙を回収にして数えた。", "corrected_sentence": "係の人は、配り終えた紙を回収して数えた。", "error_description": "「回収」の後に余分な「に」が入り「回収にして」になっている。「回収して」が正しく、回収は「する」の形で動詞として続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38894, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は欠陥品を回収しいる。", "corrected_sentence": "会社は欠陥品を回収している。", "error_description": "「回収」に続く動詞の活用が誤っている。「回収している」の「て」が抜けて「しいる」になっている。正しくは「回収している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38895, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「回収を行う」で動作の対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「回収が行っている」は文の動作と合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「回収で行っている」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すが、「回収と行っている」は文に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「回収を行う」で動作の対象を示す「を」。", "が": "主語を示すが、「回収が行っている」は文の動作と合わない。", "で": "場所や手段を示すが、「回収で行っている」は意味が通らない。", "と": "相手や並列を示すが、「回収と行っている」は文に合わない。"}, "error_tags": {"が": "subject_marker", "で": "means_or_location", "と": "parallel_or_partner"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
