INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38895, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "不要になったものや資源を集めて、もう一度使えるようにすること。", "primary_collocate": null, "pronunciation": "かいしゅう", "ipa": "kaiɕɯː", "syllable_count": 4, "sentences": [{"text": "月曜日は、古新聞の回収の日だ。", "target_word": "回収", "complexity_tier": "T3", "furigana": "月曜日(げつようび)は、古新聞(ふるしんぶん)の回収(かいしゅう)の日(ひ)だ。", "sentence_source": "generated"}, {"text": "町では、ペットボトルの回収を週に一度行っている。", "target_word": "回収", "complexity_tier": "T3", "furigana": "町(まち)では、ペットボトルの回収(かいしゅう)を週(しゅう)に一度(いちど)行(おこな)っている。", "sentence_source": "generated"}, {"text": "スーパーの入口で、牛乳パックの回収をしている。", "target_word": "回収", "complexity_tier": "T3", "furigana": "スーパーの入口(いりぐち)で、牛乳(ぎゅうにゅう)パックの回収(かいしゅう)をしている。", "sentence_source": "generated"}, {"text": "空き缶の回収が進んで、資源として再利用されている。", "target_word": "回収", "complexity_tier": "T3", "furigana": "空(あ)き缶(かん)の回収(かいしゅう)が進(すす)んで、資源(しげん)として再利用(さいりよう)されている。", "sentence_source": "generated"}, {"text": "古い服は回収されて、新しい製品に生まれ変わる。", "target_word": "回収", "complexity_tier": "T3", "furigana": "古(ふる)い服(ふく)は回収(かいしゅう)されて、新(あたら)しい製品(せいひん)に生(う)まれ変(か)わる。", "sentence_source": "generated"}, {"text": "回収された紙は、工場でトイレットペーパーになる。", "target_word": "回収", "complexity_tier": "T3", "furigana": "回収(かいしゅう)された紙(かみ)は、工場(こうじょう)でトイレットペーパーになる。", "sentence_source": "generated"}, {"text": "家電の回収を頼むと、部品を取り出して再利用してくれる。", "target_word": "回収", "complexity_tier": "T3", "furigana": "家電(かでん)の回収(かいしゅう)を頼(たの)むと、部品(ぶひん)を取(と)り出(だ)して再利用(さいりよう)してくれる。", "sentence_source": "generated"}, {"text": "ごみの分別が悪いと、資源の回収ができない。", "target_word": "回収", "complexity_tier": "T3", "furigana": "ごみの分別(ぶんべつ)が悪(わる)いと、資源(しげん)の回収(かいしゅう)ができない。", "sentence_source": "generated"}, {"text": "牛乳びんは回収して洗い、もう一度使う。", "target_word": "回収", "complexity_tier": "T3", "furigana": "牛乳(ぎゅうにゅう)びんは回収(かいしゅう)して洗(あら)い、もう一度(いちど)使(つか)う。", "sentence_source": "generated"}, {"text": "使用済みのインクカートリッジは、店で回収している。", "target_word": "回収", "complexity_tier": "T3", "furigana": "使用済(しようず)みのインクカートリッジは、店(みせ)で回収(かいしゅう)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回収する", "label": "する動詞 終止形"}, {"form": "回収した", "label": "過去形"}, {"form": "回収して", "label": "て形"}, {"form": "回収される", "label": "受身形"}], "register": "neutral (plain style)", "sense_fingerprint": "ごみ・古紙・空き缶などの資源を集めて再利用につなげること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 牛乳パック (Zipf 2.43)']::text[], '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38895, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回収", "is_correct": true, "explanation": "正解。古新聞を集めて資源にする日なので、「古新聞の回収の日」が自然。"}, {"text": "配達", "is_correct": false, "explanation": "物を届けること。古新聞の集まりの日として文に合わない。"}, {"text": "販売", "is_correct": false, "explanation": "売ること。「古新聞の販売の日」は文の意味に合わない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べること。古新聞の日の意味として合わない。"}], "explanations": {"回収": "正解。古新聞を集めて資源にする日なので、「古新聞の回収の日」が自然。", "配達": "物を届けること。古新聞の集まりの日として文に合わない。", "販売": "売ること。「古新聞の販売の日」は文の意味に合わない。", "点検": "状態を調べること。古新聞の日の意味として合わない。"}, "sentence_index": 0, "correct_answer": "回収"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "田んぼの米の回収が進んで、もうすぐ食べられる。", "explanation": "ここは〈収穫〉の意味。作物を取り入れることは収穫で、資源として集める回収とは違う。"}, {"text": "夏休みに、虫の回収をした。", "explanation": "ここは〈採集〉の意味。虫や植物を採ることは採集で、回収は合わない。"}, {"text": "古い校舎を回収した。", "explanation": "ここは〈解体〉の意味。建物を壊すことは解体で、回収は資源として集め直す場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38895, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回収", "is_correct": true, "explanation": "正解。家電を回収して部品を再利用する流れなので、「家電の回収を頼む」が文に合う。"}, {"text": "製造", "is_correct": false, "explanation": "物を作ること。部品を再利用する流れの依頼として文に合わない。"}, {"text": "販売", "is_correct": false, "explanation": "売ること。部品を取り出して再利用する文脈に合わない。"}, {"text": "設計", "is_correct": false, "explanation": "構造を考えて図にすること。依頼の対象として文に合わない。"}], "explanations": {"回収": "正解。家電を回収して部品を再利用する流れなので、「家電の回収を頼む」が文に合う。", "製造": "物を作ること。部品を再利用する流れの依頼として文に合わない。", "販売": "売ること。部品を取り出して再利用する文脈に合わない。", "設計": "構造を考えて図にすること。依頼の対象として文に合わない。"}, "sentence_index": 6, "correct_answer": "回収"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯機の中で、服が回収している。", "explanation": "ここは〈回転〉の意味。洗濯機の中で回ることは回転で、回収は合わない。"}, {"text": "山で石炭を回収している。", "explanation": "ここは〈採掘〉の意味。地中から資源を掘り出すことは採掘で、回収は合わない。"}, {"text": "キャンプ場から、全員が回収した。", "explanation": "ここは〈撤収〉の意味。場所から引き上げることは撤収で、回収は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38895, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、ペットボトルの回収ための箱を置いた。", "corrected_sentence": "市は、ペットボトルの回収のための箱を置いた。", "error_description": "「回収」の後に必要な「の」が抜けている。「回収のための箱」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38895, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は使い終わった電池を回収ている。", "corrected_sentence": "店は使い終わった電池を回収している。", "error_description": "「回収している」の「し」が抜けて「回収ている」になっている。「回収している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「レジの前」の位置・所属を示す「の」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「レジを前に」は目的語の形になり、場所の関係として合わない。"}, {"text": "に", "is_correct": false, "explanation": "「レジに前に」は「に」が続いて不自然で、「前」を修飾できない。"}, {"text": "で", "is_correct": false, "explanation": "「レジで前に」は手段・場所の「で」だが、「前」の位置は示せない。"}], "correct_answer": "の", "explanations": {"の": "「レジの前」の位置・所属を示す「の」。正解。", "を": "「レジを前に」は目的語の形になり、場所の関係として合わない。", "に": "「レジに前に」は「に」が続いて不自然で、「前」を修飾できない。", "で": "「レジで前に」は手段・場所の「で」だが、「前」の位置は示せない。"}, "error_tags": {"を": "目的語", "に": "位置・到達", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「レジに行く」の到達点を示す「に」。正解。"}, {"text": "が", "is_correct": false, "explanation": "「レジが行く」は主語になり、「行く」の目的地を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「レジで行く」は手段・場所の「で」で、移動先は示せない。"}, {"text": "の", "is_correct": false, "explanation": "「レジの行く前に」は名詞修飾で、「行く」の目的地を示せない。"}], "correct_answer": "に", "explanations": {"に": "「レジに行く」の到達点を示す「に」。正解。", "が": "「レジが行く」は主語になり、「行く」の目的地を示せない。", "で": "「レジで行く」は手段・場所の「で」で、移動先は示せない。", "の": "「レジの行く前に」は名詞修飾で、「行く」の目的地を示せない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おみせで おかねを はらう ところ。", "primary_collocate": null, "pronunciation": "れじ", "ipa": "ɾeʑi", "syllable_count": 2, "sentences": [{"text": "レジでおかねをはらって、ふくろをもらいました。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジでおかねをはらって、ふくろをもらいました。", "sentence_source": "generated"}, {"text": "レジの前に、人がならんでいます。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジの前[まえ]に、人[ひと]がならんでいます。", "sentence_source": "generated"}, {"text": "おみせのレジは、入口の近くにあります。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "おみせのレジは、入口[いりぐち]の近[ちか]くにあります。", "sentence_source": "generated"}, {"text": "おかしをレジに持って行きました。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "おかしをレジに持[も]って行[い]きました。", "sentence_source": "generated"}, {"text": "かごをもってレジへ向かい、順番を待った。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "かごを持[も]ってレジへ向[む]かい、順番[じゅんばん]を待[ま]った。", "sentence_source": "generated"}, {"text": "今日はレジがこんでいて、十分まちました。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "今日[きょう]はレジがこんでいて、十分[じゅっぷん]まちました。", "sentence_source": "generated"}, {"text": "レジでカードを出して、はらいました。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジでカードを出[だ]して、はらいました。", "sentence_source": "generated"}, {"text": "レジに行く前に、買うものをもう一度見た。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジに行[い]く前[まえ]に、買[か]うものをもう一度[いちど]見[み]た。", "sentence_source": "generated"}, {"text": "となりのレジのほうが早く進んでいた。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "となりのレジのほうが早[はや]く進[すす]んでいた。", "sentence_source": "generated"}, {"text": "レジのところで、わすれものに気づきました。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジのところで、わすれものに気[き]づきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レジ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "店で代金を払う場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レジ", "is_correct": true, "explanation": "「おかねを払う場所」の意味のレジ。正解。"}, {"text": "店員", "is_correct": false, "explanation": "人を表す語。「店員でおかねをはらって」では場所にならない。"}, {"text": "袋", "is_correct": false, "explanation": "商品を入れる物で、お金を払う場所にはならない。"}, {"text": "客", "is_correct": false, "explanation": "買う人を表す語。「客でおかねをはらって」は成り立たない。"}], "explanations": {"レジ": "「おかねを払う場所」の意味のレジ。正解。", "店員": "人を表す語。「店員でおかねをはらって」では場所にならない。", "袋": "商品を入れる物で、お金を払う場所にはならない。", "客": "買う人を表す語。「客でおかねをはらって」は成り立たない。"}, "sentence_index": 0, "correct_answer": "レジ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅のレジで、乗り換えの道を聞きました。", "explanation": "ここは〈案内所〉の意味。乗り換えの道を聞くのは案内所で、会計をするレジとは言わない。"}, {"text": "美術館のレジで、絵をながめました。", "explanation": "ここは〈展示室〉の意味。絵をながめるのは展示室で、会計をするレジとは合わない。"}, {"text": "レジで、おかねをおろしました。", "explanation": "ここは〈窓口〉の意味。預金をおろすのは窓口で、会計をするレジとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レジ", "is_correct": true, "explanation": "会計をする場所のレジ。「レジでカードを出して」が自然に成り立つ。正解。"}, {"text": "店長", "is_correct": false, "explanation": "人を表す語で、カードを出す場所にはならない。"}, {"text": "鍵", "is_correct": false, "explanation": "開け閉めに使う道具で、「鍵でカードを出して」は成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "植物で、会計の場所にはならない。「花でカードを出して」は意味が通らない。"}], "explanations": {"レジ": "会計をする場所のレジ。「レジでカードを出して」が自然に成り立つ。正解。", "店長": "人を表す語で、カードを出す場所にはならない。", "鍵": "開け閉めに使う道具で、「鍵でカードを出して」は成り立たない。", "花": "植物で、会計の場所にはならない。「花でカードを出して」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "レジ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末はレジで海へ行きました。", "explanation": "ここは〈レジャー〉（休みに楽しむこと）の意味。おかねを払う場所のレジとは別の語。"}, {"text": "レジで服を試着しました。", "explanation": "ここは〈試着室〉の意味。服を試す場所で、会計をするレジとは違う。"}, {"text": "レジで部品を組み立てました。", "explanation": "ここは〈作業場〉の意味。部品を組み立てる場所で、会計をするレジとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "買い物を終えて、レジをおかねをはらいました。", "corrected_sentence": "買い物を終えて、レジでおかねをはらいました。", "error_description": "「レジを」が誤り。「おかねをはらう」場所を表すのは「で」なので、正しくは「レジで」。「を」が二つ重なっている点も誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38896, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会計のとき、レジを並んで待ちました。", "corrected_sentence": "会計のとき、レジに並んで待ちました。", "error_description": "「レジを」が誤り。「並ぶ」は場所を示す「に」を使うので、正しくは「レジに並んで」。「並ぶ」に「を」は付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
