INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38897, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「レジから出てくる」の起点を示す「から」。正解。"}, {"text": "と", "is_correct": false, "explanation": "「レジと出てくる」は並列の「と」で、出どころを示せない。"}, {"text": "で", "is_correct": false, "explanation": "「レジで出てくる」は動作の場所を示すだけで、出どころは示せない。"}, {"text": "の", "is_correct": false, "explanation": "「レジの自動的に出てくる」は文が続かず、成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「レジから出てくる」の起点を示す「から」。正解。", "と": "「レジと出てくる」は並列の「と」で、出どころを示せない。", "で": "「レジで出てくる」は動作の場所を示すだけで、出どころは示せない。", "の": "「レジの自動的に出てくる」は文が続かず、成り立たない。"}, "error_tags": {"と": "並列", "で": "手段・場所", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38897, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "店で代金の計算や支払いをする機械。また、その場所。", "primary_collocate": null, "pronunciation": "れじ", "ipa": "ɾeʑi", "syllable_count": 2, "sentences": [{"text": "店員がレジに金額を入力すると、合計が表示された。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "店員[てんいん]がレジに金額[きんがく]を入力[にゅうりょく]すると、合計[ごうけい]が表示[ひょうじ]された。", "sentence_source": "generated"}, {"text": "このレジは、バーコードを読み取って値段を計算する。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "このレジは、バーコードを読[よ]み取[と]って値段[ねだん]を計算[けいさん]する。", "sentence_source": "generated"}, {"text": "最近は、客が自分で支払うレジが増えた。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "最近[さいきん]は、客[きゃく]が自分[じぶん]で支払[しはら]うレジが増[ふ]えた。", "sentence_source": "generated"}, {"text": "レジの故障で、会計がしばらく止まってしまった。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジの故障[こしょう]で、会計[かいけい]がしばらく止[と]まってしまった。", "sentence_source": "generated"}, {"text": "閉店後、店長はレジの現金を数えて記録した。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "閉店後[へいてんご]、店長[てんちょう]はレジの現金[げんきん]を数[かぞ]えて記録[きろく]した。", "sentence_source": "generated"}, {"text": "レジが混んでいたので、別の列に並び直した。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジが混[こ]んでいたので、別[べつ]の列[れつ]に並[なら]び直[なお]した。", "sentence_source": "generated"}, {"text": "新しいレジを入れてから、会計の時間が短くなった。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "新[あたら]しいレジを入[い]れてから、会計[かいけい]の時間[じかん]が短[みじか]くなった。", "sentence_source": "generated"}, {"text": "レシートはレジから自動的に出てくる。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レシートはレジから自動的[じどうてき]に出[で]てくる。", "sentence_source": "generated"}, {"text": "アルバイトの初日は、レジの使い方を教わった。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "アルバイトの初日[しょにち]は、レジの使[つか]い方[かた]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "レジで電子マネーを使うと、支払いが早く済む。", "target_word": "レジ", "complexity_tier": "T3", "furigana": "レジで電子[でんし]マネーを使[つか]うと、支払[しはら]いが早[はや]く済[す]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レジ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "店で会計を処理する機械・会計の場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38897, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レジ", "is_correct": true, "explanation": "店で会計を処理する機械のレジ。正解。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる物で、金額を入力する機械にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "季節を表す語で、金額を入力する対象にはならない。"}, {"text": "割引", "is_correct": false, "explanation": "値引きのことで、金額を入力する対象にはならない。"}], "explanations": {"レジ": "店で会計を処理する機械のレジ。正解。", "財布": "お金を入れる物で、金額を入力する機械にはならない。", "季節": "季節を表す語で、金額を入力する対象にはならない。", "割引": "値引きのことで、金額を入力する対象にはならない。"}, "sentence_index": 0, "correct_answer": "レジ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅のレジで、乗り換えの道を聞きました。", "explanation": "ここは〈案内所〉の意味。乗り換えの道を聞くのは案内所で、会計をするレジとは言わない。"}, {"text": "夏休みはレジで家族と出かけました。", "explanation": "ここは〈レジャー〉の意味。休みに出かけて楽しむことで、会計機のレジとは別の語。"}, {"text": "レジで、聴診器を当てて診察を受けました。", "explanation": "ここは〈診察室〉の意味。診察を受ける場所で、店の会計機のレジとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38897, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レジ", "is_correct": true, "explanation": "店で会計を処理する機械のレジ。「新しいレジを入れて」が自然。正解。"}, {"text": "性格", "is_correct": false, "explanation": "人の性質を表す語で、店に入れる物にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、店に入れる物として成り立たない。"}, {"text": "夢", "is_correct": false, "explanation": "将来の願いを表す語で、「入れる」対象にはならない。"}], "explanations": {"レジ": "店で会計を処理する機械のレジ。「新しいレジを入れて」が自然。正解。", "性格": "人の性質を表す語で、店に入れる物にはならない。", "天気": "空模様のことで、店に入れる物として成り立たない。", "夢": "将来の願いを表す語で、「入れる」対象にはならない。"}, "sentence_index": 6, "correct_answer": "レジ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保険のレジで、書類に署名しました。", "explanation": "ここは〈窓口〉の意味。保険の手続きをする窓口で、店の会計機のレジとは言わない。"}, {"text": "レジで、乗車券を買いました。", "explanation": "ここは〈切符売り場〉の意味。乗車券を買う所で、店の会計機のレジとは合わない。"}, {"text": "レジで、新しい案を話し合いました。", "explanation": "ここは〈会議室〉の意味。話し合う場所で、代金を払うレジとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38897, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店長がレジを現金を確認した。", "corrected_sentence": "店長がレジの現金を確認した。", "error_description": "「レジを」が誤り。「現金」を修飾するには「の」を使うので、正しくは「レジの現金」。「を」を二つ続けることはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38897, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会計を終えて、レジへレシートを受け取った。", "corrected_sentence": "会計を終えて、レジからレシートを受け取った。", "error_description": "「レジへ」が誤り。「受け取る」の出どころを示すのは「から」なので、正しくは「レジから」。「へ」は方向を表すため合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38898, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「袋の中」の「の」で、袋と場所を示す「中」をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「袋が中に」は場所を示す文にならない。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示すが、「袋を中に」は文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「袋と中に」は文に合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「袋の中」の「の」で、袋と場所を示す「中」をつなぐ。", "が": "主語を示すが、「袋が中に」は場所を示す文にならない。", "を": "動作の対象を示すが、「袋を中に」は文に合わない。", "と": "並列や相手を示すが、「袋と中に」は文に合わない。"}, "error_tags": {"が": "subject_marker", "を": "object_marker", "と": "parallel_or_partner"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
