INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38898, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を入れて運んだり、しまったりするための入れ物。", "primary_collocate": null, "pronunciation": "ふくろ", "ipa": "ɸɯkɯɾo", "syllable_count": 3, "sentences": [{"text": "スーパーで買った野菜を、大きな袋に入れました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "スーパーで買[か]った野菜[やさい]を、大[おお]きな袋[ふくろ]に入[い]れました。", "sentence_source": "generated"}, {"text": "袋の中に、おかしが三つ入っています。", "target_word": "袋", "complexity_tier": "T3", "furigana": "袋[ふくろ]の中[なか]に、おかしが三[みっ]つ入[はい]っています。", "sentence_source": "generated"}, {"text": "袋が小さすぎて、本が入りませんでした。", "target_word": "袋", "complexity_tier": "T3", "furigana": "袋[ふくろ]が小[ちい]さすぎて、本[ほん]が入[はい]りませんでした。", "sentence_source": "generated"}, {"text": "雨がふってきたので、かばんを袋に入れてぬれないようにしました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "雨[あめ]がふってきたので、かばんを袋[ふくろ]に入[い]れてぬれないようにしました。", "sentence_source": "generated"}, {"text": "母は、ごみを袋に入れて外に出しました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "母[はは]は、ごみを袋[ふくろ]に入[い]れて外[そと]に出[だ]しました。", "sentence_source": "generated"}, {"text": "袋を開けると、いいにおいがしました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "袋[ふくろ]を開[あ]けると、いいにおいがしました。", "sentence_source": "generated"}, {"text": "この袋は、うすいのですぐ破れてしまいます。", "target_word": "袋", "complexity_tier": "T3", "furigana": "この袋[ふくろ]は、うすいのですぐ破[やぶ]れてしまいます。", "sentence_source": "generated"}, {"text": "弟は、ひろった石を袋に入れて持ち帰りました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "弟[おとうと]は、ひろった石[いし]を袋[ふくろ]に入[い]れて持[も]ち帰[かえ]りました。", "sentence_source": "generated"}, {"text": "袋がいっぱいになったので、もう一つもらいました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "袋[ふくろ]がいっぱいになったので、もう一[ひと]つもらいました。", "sentence_source": "generated"}, {"text": "おみやげの袋を、友だちにわたしました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "おみやげの袋[ふくろ]を、友[とも]だちにわたしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "基本形"}, {"form": "ふくろ", "label": "ひらがな表記"}], "register": "丁寧", "sense_fingerprint": "物を入れて運ぶ・しまうための入れ物(日常の基本語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: ひろっ (Zipf 2.25)']::text[], '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38898, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "袋", "is_correct": true, "explanation": "正解。野菜を入れる大きな入れ物なので、「大きな袋に入れました」が自然。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描いた案内図。野菜を入れる入れ物として文に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書く道具。野菜を入れる対象として文に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具。野菜を入れる入れ物として文に合わない。"}], "explanations": {"袋": "正解。野菜を入れる大きな入れ物なので、「大きな袋に入れました」が自然。", "地図": "紙に描いた案内図。野菜を入れる入れ物として文に合わない。", "鉛筆": "書く道具。野菜を入れる対象として文に合わない。", "時計": "時刻を示す道具。野菜を入れる入れ物として文に合わない。"}, "sentence_index": 0, "correct_answer": "袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理を袋に乗せて、食卓まで運びました。", "explanation": "ここは〈盆〉の意味。料理を乗せて運ぶのは盆で、袋には乗せない。"}, {"text": "ジャムを袋に入れて、ふたを閉めました。", "explanation": "ここは〈瓶〉の意味。ふたは瓶などにあるもので、袋には使わない。"}, {"text": "鏡を袋に入れて、顔を映しました。", "explanation": "ここは〈鏡〉の意味。顔を映すのは鏡で、袋では映らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38898, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "袋", "is_correct": true, "explanation": "正解。うすくて破れやすい入れ物なので、「この袋は破れる」が文に合う。"}, {"text": "黒板", "is_correct": false, "explanation": "授業で書く板。破れやすい入れ物として文に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具。破れるという文脈に合わない。"}, {"text": "本棚", "is_correct": false, "explanation": "本を置く家具。うすいものとして破れる文脈に合わない。"}], "explanations": {"袋": "正解。うすくて破れやすい入れ物なので、「この袋は破れる」が文に合う。", "黒板": "授業で書く板。破れやすい入れ物として文に合わない。", "時計": "時刻を示す道具。破れるという文脈に合わない。", "本棚": "本を置く家具。うすいものとして破れる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙を袋に入れて、切手をはりました。", "explanation": "ここは〈封筒〉の意味。手紙を入れて切手をはるのは封筒で、袋は合わない。"}, {"text": "絵を袋にはめて、壁に飾りました。", "explanation": "ここは〈額〉の意味。絵をはめて飾るのは額で、袋にははめない。"}, {"text": "おさらを袋に並べて、食器棚にしまいました。", "explanation": "ここは〈皿〉の意味。食器を並べてしまうのは皿で、袋には並べない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
