INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38899, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物品を入れるための容器。布や紙、ビニールなどで作られる。", "primary_collocate": null, "pronunciation": "ふくろ", "ipa": "ɸɯkɯɾo", "syllable_count": 3, "sentences": [{"text": "紙で作られた袋は、水にぬれると破れやすいです。", "target_word": "袋", "complexity_tier": "T3", "furigana": "紙[かみ]で作[つく]られた袋[ふくろ]は、水[みず]にぬれると破[やぶ]れやすいです。", "sentence_source": "generated"}, {"text": "布の袋なら、何度でも洗って使えます。", "target_word": "袋", "complexity_tier": "T3", "furigana": "布[ぬの]の袋[ふくろ]なら、何度[なんど]でも洗[あら]って使[つか]えます。", "sentence_source": "generated"}, {"text": "ビニールの袋に入れると、中身が湿りません。", "target_word": "袋", "complexity_tier": "T3", "furigana": "ビニールの袋[ふくろ]に入[い]れると、中身[なかみ]が湿[しめ]りません。", "sentence_source": "generated"}, {"text": "米を入れる丈夫な袋が、倉庫にたくさん積んであります。", "target_word": "袋", "complexity_tier": "T3", "furigana": "米[こめ]を入[い]れる丈夫[じょうぶ]な袋[ふくろ]が、倉庫[そうこ]にたくさん積[つ]んであります。", "sentence_source": "generated"}, {"text": "店では、買い物をした客に紙の袋を渡しています。", "target_word": "袋", "complexity_tier": "T3", "furigana": "店[みせ]では、買[か]い物[もの]をした客[きゃく]に紙[かみ]の袋[ふくろ]を渡[わた]しています。", "sentence_source": "generated"}, {"text": "この袋は布でできているので、軽くて持ち運びやすいです。", "target_word": "袋", "complexity_tier": "T3", "furigana": "この袋[ふくろ]は布[ぬの]でできているので、軽[かる]くて持[も]ち運[はこ]びやすいです。", "sentence_source": "generated"}, {"text": "袋の口をひもでしばって、中身がこぼれないようにしました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "袋[ふくろ]の口[くち]をひもでしばって、中身[なかみ]がこぼれないようにしました。", "sentence_source": "generated"}, {"text": "環境のために、ビニールの袋を使う量を減らしています。", "target_word": "袋", "complexity_tier": "T3", "furigana": "環境[かんきょう]のために、ビニールの袋[ふくろ]を使[つか]う量[りょう]を減[へ]らしています。", "sentence_source": "generated"}, {"text": "祖母は、古い着物の布で小さな袋を縫ってくれました。", "target_word": "袋", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、古[ふる]い着物[きもの]の布[ぬの]で小[ちい]さな袋[ふくろ]を縫[ぬ]ってくれました。", "sentence_source": "generated"}, {"text": "紙の袋は、リサイクルに出すことができます。", "target_word": "袋", "complexity_tier": "T3", "furigana": "紙[かみ]の袋[ふくろ]は、リサイクルに出[だ]すことができます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "基本形"}, {"form": "ふくろ", "label": "ひらがな表記"}], "register": "丁寧", "sense_fingerprint": "布・紙・ビニールなど素材で作られた容器(素材や用途に注目)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ぬれる (Zipf 1.65)','sentence 2 above tier T2: contains vocabulary far above tier T2: 湿り (Zipf 2.0)','sentence 6 above tier T2: contains vocabulary far above tier T2: しばっ (Zipf 2.15)']::text[], '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38899, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "袋", "is_correct": true, "explanation": "正解。紙で作られた入れ物で、水にぬれると破れやすいので文に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "料理に使う金属や陶器の器。紙で作られた物としては文に合わない。"}, {"text": "鏡", "is_correct": false, "explanation": "姿を映す道具。紙で作られた入れ物として文に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具。紙で作られた入れ物として文に合わない。"}], "explanations": {"袋": "正解。紙で作られた入れ物で、水にぬれると破れやすいので文に合う。", "鍋": "料理に使う金属や陶器の器。紙で作られた物としては文に合わない。", "鏡": "姿を映す道具。紙で作られた入れ物として文に合わない。", "時計": "時刻を示す道具。紙で作られた入れ物として文に合わない。"}, "sentence_index": 0, "correct_answer": "袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジャムを袋に詰めて、ふたをして保存しました。", "explanation": "ここは〈瓶〉の意味。ふたを閉めて保存するものは瓶で、袋にはふたがない。"}, {"text": "スープを袋に入れて、缶切りで開けました。", "explanation": "ここは〈缶〉の意味。缶切りで開けるものは缶で、袋には使わない。"}, {"text": "新しい窓を袋に取り付けました。", "explanation": "ここは〈窓〉の意味。建物に取り付けるのは窓で、袋は取り付けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38899, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "袋", "is_correct": true, "explanation": "正解。口をひもでしばって中身を守る入れ物なので、「袋の口」が文に合う。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う小さな紙片。口をしばる入れ物として文に合わない。"}, {"text": "日記", "is_correct": false, "explanation": "その日の出来事を書く帳面。口をひもでしばる物として文に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "光や空気を入れる開口部。口をひもでしばる対象として文に合わない。"}], "explanations": {"袋": "正解。口をひもでしばって中身を守る入れ物なので、「袋の口」が文に合う。", "切手": "郵便に使う小さな紙片。口をしばる入れ物として文に合わない。", "日記": "その日の出来事を書く帳面。口をひもでしばる物として文に合わない。", "窓": "光や空気を入れる開口部。口をひもでしばる対象として文に合わない。"}, "sentence_index": 6, "correct_answer": "袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "表札を袋に彫って、門に掲げました。", "explanation": "ここは〈表札〉の意味。名前を彫って門に掲げるのは表札で、袋には彫らない。"}, {"text": "おさらを袋に並べて、食器棚にしまいました。", "explanation": "ここは〈皿〉の意味。食器を並べてしまうのは皿で、袋には並べない。"}, {"text": "雨の日に袋をさして歩きました。", "explanation": "ここは〈傘〉の意味。雨をよけてさすのは傘で、袋ではさせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38899, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "袋を口を閉じて、棚にしまいました。", "corrected_sentence": "袋の口を閉じて、棚にしまいました。", "error_description": "「袋の口」の「の」が「を」になっている。「を」が二つ重なり不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38899, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は、紙の袋を無料に配っています。", "corrected_sentence": "店は、紙の袋を無料で配っています。", "error_description": "「無料で」の「で」が「に」になっている。「無料」は「で」で副詞的に続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
