INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38900, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "エコは、ちきゅうにやさしいことをいうことばです。", "primary_collocate": null, "pronunciation": "えこ", "ipa": "eko", "syllable_count": 2, "sentences": [{"text": "このお店は紙のストローを使っていて、とてもエコです。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "このお店[みせ]は紙[かみ]のストローを使[つか]っていて、とてもエコです。", "sentence_source": "generated"}, {"text": "水を出しっぱなしにしないのは、エコな習慣です。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "水[みず]を出[だ]しっぱなしにしないのは、エコな習慣[しゅうかん]です。", "sentence_source": "generated"}, {"text": "電気をこまめに消すのは、手軽にできるエコの一つです。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "電気[でんき]をこまめに消[け]すのは、手軽[てがる]にできるエコの一つ[ひとつ]です。", "sentence_source": "generated"}, {"text": "私の家では、エコな暮らしを心がけています。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]では、エコな暮[く]らしを心[こころ]がけています。", "sentence_source": "generated"}, {"text": "自転車で通うのは、車より空気がきれいでエコです。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]で通[かよ]うのは、車[くるま]より空気[くうき]がきれいでエコです。", "sentence_source": "generated"}, {"text": "エコな車は、ガソリンをあまり使いません。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコな車[くるま]は、ガソリンをあまり使[つか]いません。", "sentence_source": "generated"}, {"text": "古い服をもう一度着るのは、とてもエコだと思います。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "古[ふる]い服[ふく]をもう一度[いちど]着[き]るのは、とてもエコだと思[おも]います。", "sentence_source": "generated"}, {"text": "ごみを分けて出すのは、エコな生活の基本です。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "ごみを分[わ]けて出[だ]すのは、エコな生活[せいかつ]の基本[きほん]です。", "sentence_source": "generated"}, {"text": "この電球は長く使えるので、エコだと聞きました。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "この電球[でんきゅう]は長[なが]く使[つか]えるので、エコだと聞[き]きました。", "sentence_source": "generated"}, {"text": "エコに暮らすために、レジ袋をもらわないようにしています。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコに暮[く]らすために、レジ袋[ぶくろ]をもらわないようにしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エコ", "label": "基本形"}, {"form": "エコな", "label": "連体形"}, {"form": "エコに", "label": "連用形"}, {"form": "エコだ", "label": "終止形"}], "register": "polite", "sense_fingerprint": "地球や自然にやさしいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38900, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エコ", "is_correct": true, "explanation": "正解。形状詞の「エコ」が「です」で述語になり、環境にやさしいという意味に合う。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は目立つことを表し、紙のストローの話の評価としては合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は人の性格を表し、お店の道具には使わない。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈」は気分を表し、ストローの特徴の評価には合わない。"}], "explanations": {"エコ": "正解。形状詞の「エコ」が「です」で述語になり、環境にやさしいという意味に合う。", "派手": "「派手」は目立つことを表し、紙のストローの話の評価としては合わない。", "陽気": "「陽気」は人の性格を表し、お店の道具には使わない。", "退屈": "「退屈」は気分を表し、ストローの特徴の評価には合わない。"}, "sentence_index": 0, "correct_answer": "エコ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、エコな声で歌を練習しています。", "explanation": "ここは声の美しさの意味。エコは環境にやさしいという意味で、声の質には使わない。"}, {"text": "友だちの猫の名前はエコです。", "explanation": "ここは猫の名前として使っている。エコの「環境にやさしい」という意味とは違う。"}, {"text": "毎週末、窓辺でエコを眺めています。", "explanation": "ここはエコを眺める対象として使っている。エコは環境への配慮の意味で、眺める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38900, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エコ", "is_correct": true, "explanation": "正解。古い服を着ることが環境にやさしいという評価に合う。"}, {"text": "華麗", "is_correct": false, "explanation": "「華麗」は見た目の美しさを表し、服を着ることの環境面の評価には合わない。"}, {"text": "平和", "is_correct": false, "explanation": "「平和」は社会の状態を表し、服を再び着ることの評価には合わない。"}, {"text": "上品", "is_correct": false, "explanation": "「上品」は品のよさを表し、環境にやさしいかどうかの評価には合わない。"}], "explanations": {"エコ": "正解。古い服を着ることが環境にやさしいという評価に合う。", "華麗": "「華麗」は見た目の美しさを表し、服を着ることの環境面の評価には合わない。", "平和": "「平和」は社会の状態を表し、服を再び着ることの評価には合わない。", "上品": "「上品」は品のよさを表し、環境にやさしいかどうかの評価には合わない。"}, "sentence_index": 6, "correct_answer": "エコ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、朝ごはんにエコを食べています。", "explanation": "ここは食べ物として使っている。エコは環境への配慮の意味で、食べ物ではない。"}, {"text": "うちの犬の名前はエコです。", "explanation": "ここは犬の名前として使っている。エコの「環境にやさしい」という意味とは違う。"}, {"text": "披露宴でエコを歌いました。", "explanation": "ここは歌の対象として使っている。エコは環境への配慮の意味で、歌にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38900, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このバスは、ガソリンをあまり使わないのでエコに。", "corrected_sentence": "このバスは、ガソリンをあまり使わないのでエコです。", "error_description": "形状詞「エコ」は文末で「です」が要る。「に」は連用形で、文を終えられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "エコな", "is_correct": true, "explanation": "連体形。名詞「習慣」を修飾するので「エコな」になる。"}, {"text": "エコで", "is_correct": false, "explanation": "中止形。文を続ける形で、名詞「習慣」を直接修飾できないので「エコで習慣」とは言えない。"}, {"text": "エコに", "is_correct": false, "explanation": "連用形。「エコに」は動詞などを修飾する形で、名詞「習慣」の前には置けない。"}, {"text": "エコだ", "is_correct": false, "explanation": "終止形。文を言い切る形で、名詞を修飾できないので「習慣」の前には使えない。"}], "correct_form": "エコな", "base_form": "エコ", "form_label": "連体形", "sentence_index": 1, "explanations": {"エコな": "連体形。名詞「習慣」を修飾するので「エコな」になる。", "エコで": "中止形。文を続ける形で、名詞「習慣」を直接修飾できないので「エコで習慣」とは言えない。", "エコに": "連用形。「エコに」は動詞などを修飾する形で、名詞「習慣」の前には置けない。", "エコだ": "終止形。文を言い切る形で、名詞を修飾できないので「習慣」の前には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38900, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マイバッグを持つのは、エコだ買い物の第一歩です。", "corrected_sentence": "マイバッグを持つのは、エコな買い物の第一歩です。", "error_description": "形状詞「エコ」が名詞を修飾するには「な」が要る。「だ」は文を言い切る形で、名詞の前では使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "エコな", "is_correct": true, "explanation": "連体形。名詞「生活」を修飾するので「エコな」になる。"}, {"text": "エコなら", "is_correct": false, "explanation": "仮定形。「ならば」の意味で文を続けるため、名詞「生活」を修飾できない。"}, {"text": "エコだろう", "is_correct": false, "explanation": "推量形。文を言い切る形で、名詞「生活」の前には置けない。"}, {"text": "エコだし", "is_correct": false, "explanation": "理由を並べる接続形。文を続ける用法で、名詞「生活」を修飾できない。"}], "correct_form": "エコな", "base_form": "エコ", "form_label": "連体形", "sentence_index": 7, "explanations": {"エコな": "連体形。名詞「生活」を修飾するので「エコな」になる。", "エコなら": "仮定形。「ならば」の意味で文を続けるため、名詞「生活」を修飾できない。", "エコだろう": "推量形。文を言い切る形で、名詞「生活」の前には置けない。", "エコだし": "理由を並べる接続形。文を続ける用法で、名詞「生活」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「考える」の対象のエコを示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「エコが考えて」ではエコが考える主体になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、考える対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を表し、「考えて」の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「考える」の対象のエコを示す。", "が": "「が」は主語を示すので、「エコが考えて」ではエコが考える主体になり不自然。", "へ": "「へ」は方向を表し、考える対象を示せない。", "の": "「の」は所属や修飾を表し、「考えて」の対象にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「広める」の対象のエコを示す。"}, {"text": "が", "is_correct": false, "explanation": "「エコが広めるために」は主語として不自然。「広める」の対象は「を」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、広める対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、広める対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「広める」の対象のエコを示す。", "が": "「エコが広めるために」は主語として不自然。「広める」の対象は「を」で示す。", "と": "「と」は並列や引用を表し、広める対象を示せない。", "より": "「より」は比較を表し、広める対象を示せない。"}, "error_tags": {"が": "主語", "と": "並列・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "環境に配慮した行動や考え方を表す言葉。", "primary_collocate": null, "pronunciation": "えこ", "ipa": "eko", "syllable_count": 2, "sentences": [{"text": "最近は、買い物でもエコを意識する人が増えました。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "最近[さいきん]は、買[か]い物[もの]でもエコを意識[いしき]する人[ひと]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "会社では、エコを考えて紙の使い方を見直しました。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "会社[かいしゃ]では、エコを考[かんが]えて紙[かみ]の使[つか]い方[かた]を見直[みなお]しました。", "sentence_source": "generated"}, {"text": "エコの意識が高い人は、マイボトルを持ち歩きます。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコの意識[いしき]が高[たか]い人[ひと]は、マイボトルを持[も]ち歩[ある]きます。", "sentence_source": "generated"}, {"text": "エコが大切だと分かっていても、毎日続けるのは大変です。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコが大切[たいせつ]だと分[わ]かっていても、毎日[まいにち]続[つづ]けるのは大変[たいへん]です。", "sentence_source": "generated"}, {"text": "この町では、エコを進めるために、バスの本数を増やしました。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "この町[まち]では、エコを進[すす]めるために、バスの本数[ほんすう]を増[ふ]やしました。", "sentence_source": "generated"}, {"text": "エコを目的に、通勤の方法を変えた人もいます。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコを目的[もくてき]に、通勤[つうきん]の方法[ほうほう]を変[か]えた人[ひと]もいます。", "sentence_source": "generated"}, {"text": "エコの考え方は、小学校の授業でも教えています。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコの考[かんが]え方[かた]は、小学校[しょうがっこう]の授業[じゅぎょう]でも教[おし]えています。", "sentence_source": "generated"}, {"text": "エコを広めるために、市が無料の講座を開きました。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコを広[ひろ]めるために、市[し]が無料[むりょう]の講座[こうざ]を開[ひら]きました。", "sentence_source": "generated"}, {"text": "彼は、エコのために車をやめて自転車に乗っています。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "彼[かれ]は、エコのために車[くるま]をやめて自転車[じてんしゃ]に乗[の]っています。", "sentence_source": "generated"}, {"text": "エコは、お金の節約にもなると言われています。", "target_word": "エコ", "complexity_tier": "T3", "furigana": "エコは、お金[かね]の節約[せつやく]にもなると言[い]われています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エコ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "環境への配慮を心がける行動や考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エコ", "is_correct": true, "explanation": "正解。環境に配慮する行動を指し、「を意識する」に合う。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は持ち物で、買い物で意識する対象にならない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は物で、「を意識する」という人の心の動きの対象にはならない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の部分で、買い物の場で人が意識する対象にならない。"}], "explanations": {"エコ": "正解。環境に配慮する行動を指し、「を意識する」に合う。", "名刺": "名刺は持ち物で、買い物で意識する対象にならない。", "石鹸": "石鹸は物で、「を意識する」という人の心の動きの対象にはならない。", "天井": "天井は建物の部分で、買い物の場で人が意識する対象にならない。"}, "sentence_index": 0, "correct_answer": "エコ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この池はエコが豊かで、魚の種類が多いです。", "explanation": "ここは生態系の意味。環境への配慮を指す語義とは違うので合わない。"}, {"text": "うちの犬の名前はエコです。", "explanation": "ここは犬の名前として使っている。エコの「環境にやさしい」という意味とは違う。"}, {"text": "毎晩、十分なエコを取っています。", "explanation": "ここは睡眠（眠ること）の意味。エコは環境への配慮なので、睡眠の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エコ", "is_correct": true, "explanation": "正解。環境に配慮する考え方を指し、「の考え方」に合う。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物で、考え方として授業で教える対象にならない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は持ち物で、授業で教える考え方の名前にならない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は物で、授業で教える「考え方」の対象とは合わない。"}], "explanations": {"エコ": "正解。環境に配慮する考え方を指し、「の考え方」に合う。", "財布": "財布は持ち物で、考え方として授業で教える対象にならない。", "傘": "傘は持ち物で、授業で教える考え方の名前にならない。", "手紙": "手紙は物で、授業で教える「考え方」の対象とは合わない。"}, "sentence_index": 6, "correct_answer": "エコ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の植木に、毎朝エコを水やりしています。", "explanation": "ここは植物（草木）の意味。エコは環境に配慮する考え方で、植物は指さない。"}, {"text": "うちの猫の名前はエコです。", "explanation": "ここは猫の名前として使っている。エコの「環境にやさしい」という意味とは違う。"}, {"text": "休日はエコを炒めて楽しんでいます。", "explanation": "ここは料理（食べ物を作ること）の意味。エコは環境に配慮する考え方で、食材や料理は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族みんなでエコが考えて、電気を節約しています。", "corrected_sentence": "家族みんなでエコを考えて、電気を節約しています。", "error_description": "「考える」の対象は「を」で示す。「が」は主語を示すので、エコが考える主体になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38901, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地元のエコが関心を持つ人が増えました。", "corrected_sentence": "地元のエコに関心を持つ人が増えました。", "error_description": "「関心を持つ」は「に」で対象を示す。「が」は主語につくので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
