INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38902, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "することやしないことが、もうきまっていること。", "primary_collocate": null, "pronunciation": "きまり", "ipa": "kimaɾi", "syllable_count": 3, "sentences": [{"text": "毎朝六時に起きて走るのが、私の決まりです。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]六時[ろくじ]に起[お]きて走[はし]るのが、私[わたし]の決[き]まりです。", "sentence_source": "generated"}, {"text": "夜十時を過ぎたらゲームをしないのが、わが家の決まりです。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "夜[よる]十時[じゅうじ]を過[す]ぎたらゲームをしないのが、わが家[や]の決[き]まりです。", "sentence_source": "generated"}, {"text": "日曜日は家族で夕食を作るのが、いつもの決まりです。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は家族[かぞく]で夕食[ゆうしょく]を作[つく]るのが、いつもの決[き]まりです。", "sentence_source": "generated"}, {"text": "祖父は、食事の前に必ず手を合わせる決まりでした。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "祖父[そふ]は、食事[しょくじ]の前[まえ]に必[かなら]ず手[て]を合[あ]わせる決[き]まりでした。", "sentence_source": "generated"}, {"text": "朝ごはんのあと、祖母は必ずお茶を飲みます。それが祖母の決まりです。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんのあと、祖母[そぼ]は必[かなら]ずお茶[ちゃ]を飲[の]みます。それが祖母[そぼ]の決[き]まりです。", "sentence_source": "generated"}, {"text": "寝る前に本を読むと決めたので、それが毎日の決まりになりました。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に本[ほん]を読[よ]むと決[き]めたので、それが毎日[まいにち]の決[き]まりになりました。", "sentence_source": "generated"}, {"text": "試合の前に同じ歌を聞くのが、あの選手の決まりです。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に同[おな]じ歌[うた]を聞[き]くのが、あの選手[せんしゅ]の決[き]まりです。", "sentence_source": "generated"}, {"text": "「帰ったら手を洗う」という決まりを、子どものころから続けています。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "「帰[かえ]ったら手[て]を洗[あら]う」という決[き]まりを、子[こ]どものころから続[つづ]けています。", "sentence_source": "generated"}, {"text": "毎月一日に神社へ行くのが、母の決まりです。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "毎月[まいつき]一日[ついたち]に神社[じんじゃ]へ行[い]くのが、母[はは]の決[き]まりです。", "sentence_source": "generated"}, {"text": "食事の後に歯をみがくのが決まりなので、忘れたことはありません。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "食事[しょくじ]の後[あと]に歯[は]をみがくのが決[き]まりなので、忘[わす]れたことはありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決まり", "label": "基本形"}, {"form": "きまり", "label": "ひらがな表記"}], "register": "丁寧", "sense_fingerprint": "個人や家庭でいつもそうすると定まっている習わし・やり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: みがく (Zipf 1.93)']::text[], '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38902, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決まり", "is_correct": true, "explanation": "「いつもそうすると定めた習わし」の意味で、毎朝走ることを表す文に合う。"}, {"text": "期限", "is_correct": false, "explanation": "物事をする期日を指す語。「毎朝走るのが私の期限です」では意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指す語。毎朝走るという習慣の説明にはならない。"}, {"text": "感想", "is_correct": false, "explanation": "感じたことを指す語。毎朝走るという習慣の説明にはならない。"}], "explanations": {"決まり": "「いつもそうすると定めた習わし」の意味で、毎朝走ることを表す文に合う。", "期限": "物事をする期日を指す語。「毎朝走るのが私の期限です」では意味が通らない。", "天気": "空模様を指す語。毎朝走るという習慣の説明にはならない。", "感想": "感じたことを指す語。毎朝走るという習慣の説明にはならない。"}, "sentence_index": 0, "correct_answer": "決まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は、和食が好きという決まりを守っている。", "explanation": "ここは〈好み〉（嗜好）の意味。好みは個人の嗜好で、自分で定めて守る決まりとは別の語。好みがある、と言うのが自然。"}, {"text": "彼女は子どものころの決まりに悩まされ、今も眠れない。", "explanation": "ここは〈トラウマ〉（心の傷）の意味。決まりは習わしや規則の語で、心の傷は表さない。"}, {"text": "彼は話すとき、つい指を鳴らす決まりがある。", "explanation": "ここは〈癖〉の意味。「つい」は無意識の動作を表し、自分で定めて守る決まりとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38902, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決まり", "is_correct": true, "explanation": "「試合の前に同じ歌を聞く」という定まった習わしを表し、文に合う。"}, {"text": "誤解", "is_correct": false, "explanation": "思い違いを指す語。選手の習慣を述べる空欄には入らない。"}, {"text": "予告", "is_correct": false, "explanation": "前もって知らせることを指す語。習慣の説明としては成り立たない。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを省みることを指す語。定まった習わしを表さない。"}], "explanations": {"決まり": "「試合の前に同じ歌を聞く」という定まった習わしを表し、文に合う。", "誤解": "思い違いを指す語。選手の習慣を述べる空欄には入らない。", "予告": "前もって知らせることを指す語。習慣の説明としては成り立たない。", "反省": "自分の行いを省みることを指す語。定まった習わしを表さない。"}, "sentence_index": 6, "correct_answer": "決まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父には、毎年冬に腰が痛む決まりがある。", "explanation": "ここは病気の意味（長く続く体の不調）で使われている。慢性の不調は決まりとは別の概念なので、習わしの意味では合わない。"}, {"text": "私は暑さに弱い決まりです。", "explanation": "ここは〈体質〉の意味。体質は生まれつきのもので、自分で定めて守る決まりとは合わない。"}, {"text": "彼は人を疑いやすい決まりだ。", "explanation": "ここは〈性格〉の意味。人の性質に決まりは使わないので、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38902, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うちには、靴を脱ぐ決まりをあります。", "corrected_sentence": "うちには、靴を脱ぐ決まりがあります。", "error_description": "「ある」の主語は「決まり」なので「が」が正しい。「を」を付けると目的語になり、「ある」と結びつかず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38902, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜は電気を消すのが、この家の決まりなっています。", "corrected_sentence": "夜は電気を消すのが、この家の決まりになっています。", "error_description": "「決まり」には「に」を付けて「になっている」と続ける。「に」がないと「決まりなっている」となり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語を示す「が」。「決まりがあります」で存在を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「決まりを」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用の働きで、存在を表す「ある」とは結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、存在を表す文の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語を示す「が」。「決まりがあります」で存在を表す。", "を": "「ある」は目的語を取らないので、「決まりを」では文が成り立たない。", "と": "「と」は並列や引用の働きで、存在を表す「ある」とは結びつかない。", "へ": "「へ」は方向を示すので、存在を表す文の主語にはならない。"}, "error_tags": {"を": "目的語", "と": "並列・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「変える」の目的語を示す「を」。変える対象の決まりを表す。"}, {"text": "が", "is_correct": false, "explanation": "「変える」の主語は人なので、決まりを主語にする「が」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「変える」は対象を「を」で示すので、「決まりに」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、変える対象を表す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「変える」の目的語を示す「を」。変える対象の決まりを表す。", "が": "「変える」の主語は人なので、決まりを主語にする「が」は合わない。", "に": "「変える」は対象を「を」で示すので、「決まりに」では文が成り立たない。", "より": "「より」は比較を示すので、変える対象を表す文には合わない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のやり方や順序などを、社会やグループの中で決めたルールや約束。", "primary_collocate": null, "pronunciation": "きまり", "ipa": "kimaɾi", "syllable_count": 3, "sentences": [{"text": "学校の決まりで、校内ではぼうしをかぶってはいけません。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "学校[がっこう]の決[き]まりで、校内[こうない]ではぼうしをかぶってはいけません。", "sentence_source": "generated"}, {"text": "このアパートには、ごみを出す日の決まりがあります。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "このアパートには、ごみを出[だ]す日[ひ]の決[き]まりがあります。", "sentence_source": "generated"}, {"text": "図書館の決まりを守って、本を期限までに返しました。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "図書館[としょかん]の決[き]まりを守[まも]って、本[ほん]を期限[きげん]までに返[かえ]しました。", "sentence_source": "generated"}, {"text": "新しい決まりができて、会議は三十分で終わることになりました。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "新[あたら]しい決[き]まりができて、会議[かいぎ]は三十分[さんじっぷん]で終[お]わることになりました。", "sentence_source": "generated"}, {"text": "決まりを知らなかった私は、プールで注意されました。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "決[き]まりを知[し]らなかった私[わたし]は、プールで注意[ちゅうい]されました。", "sentence_source": "generated"}, {"text": "スポーツには、それぞれ細かい決まりがあります。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "スポーツには、それぞれ細[こま]かい決[き]まりがあります。", "sentence_source": "generated"}, {"text": "町の決まりでは、犬の散歩のときにふんを持ち帰ることになっています。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "町[まち]の決[き]まりでは、犬[いぬ]の散歩[さんぽ]のときにふんを持[も]ち帰[かえ]ることになっています。", "sentence_source": "generated"}, {"text": "クラブの決まりを変えるには、みんなの同意が必要です。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "クラブの決[き]まりを変[か]えるには、みんなの同意[どうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "決まりに従わない人が多くて、係の人が困っています。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "決[き]まりに従[したが]わない人[ひと]が多[おお]くて、係[かかり]の人[ひと]が困[こま]っています。", "sentence_source": "generated"}, {"text": "公園の決まりとして、夜九時以降は大声を出せません。", "target_word": "決まり", "complexity_tier": "T3", "furigana": "公園[こうえん]の決[き]まりとして、夜[よる]九時[くじ]以降[いこう]は大声[おおごえ]を出[だ]せません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決まり", "label": "基本形"}, {"form": "きまり", "label": "ひらがな表記"}], "register": "丁寧", "sense_fingerprint": "学校・団体・地域などで皆が守るよう定められたルール", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決まり", "is_correct": true, "explanation": "学校で定められたルールを表す。校内でぼうしをかぶらないという文に合う。"}, {"text": "予告", "is_correct": false, "explanation": "前もって知らせることを指す語。禁止の規則を述べる空欄には入らない。"}, {"text": "誤解", "is_correct": false, "explanation": "思い違いを指す語。学校の定めを述べる文には合わない。"}, {"text": "感想", "is_correct": false, "explanation": "感じたことを指す語。学校の定めの説明にはならない。"}], "explanations": {"決まり": "学校で定められたルールを表す。校内でぼうしをかぶらないという文に合う。", "予告": "前もって知らせることを指す語。禁止の規則を述べる空欄には入らない。", "誤解": "思い違いを指す語。学校の定めを述べる文には合わない。", "感想": "感じたことを指す語。学校の定めの説明にはならない。"}, "sentence_index": 0, "correct_answer": "決まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は腰の決まりが痛くて、歩けなかった。", "explanation": "ここは〈症状〉（病気による体の様子）の意味。症状は体の状態で、人が定めた決まりとは別の語。"}, {"text": "床の決まりは、拭いても落ちなかった。", "explanation": "ここは〈汚れ〉（よごれ）の意味。汚れは拭いて落とすもので、人が定めた決まりとは別の語。"}, {"text": "祖父には、昔から持病の決まりがあります。", "explanation": "ここは病気の意味（長く続く病気）で使われている。病気は体の状態で、人が定めて守る決まりとは別の概念なので、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決まり", "is_correct": true, "explanation": "町で定められた決めごとを表す。犬の散歩のふんの処理を述べる文に合う。"}, {"text": "勝因", "is_correct": false, "explanation": "勝った理由を指す語。ルールを述べる空欄には入らない。"}, {"text": "手応え", "is_correct": false, "explanation": "物事から感じる反応を指す語。決めごとの説明にはならない。"}, {"text": "寿命", "is_correct": false, "explanation": "生き物や物が続く期間を指す語。町の定めを述べる文には合わない。"}], "explanations": {"決まり": "町で定められた決めごとを表す。犬の散歩のふんの処理を述べる文に合う。", "勝因": "勝った理由を指す語。ルールを述べる空欄には入らない。", "手応え": "物事から感じる反応を指す語。決めごとの説明にはならない。", "寿命": "生き物や物が続く期間を指す語。町の定めを述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "決まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の決まりは、大会で優勝するほどだ。", "explanation": "ここは〈実力〉（力の程度）の意味。決まりは定められた規則や習わしで、力量には使わない。"}, {"text": "妹は甘い物に弱い決まりだ。", "explanation": "ここは〈体質〉の意味。体質は生まれつきのもので、人が定めて守る規則とは別の語。"}, {"text": "彼は冗談をよく言う決まりだ。", "explanation": "ここは〈性格〉の意味。人の性質に決まりは使わないので、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校の決まりに守らない生徒は、放課後に残されます。", "corrected_sentence": "学校の決まりを守らない生徒は、放課後に残されます。", "error_description": "「守る」の目的語は決まりなので「を」が正しい。「に」では「守らない」の目的語が成り立たず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38903, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の決まりを、夜は大声を出さないことになっています。", "corrected_sentence": "町の決まりで、夜は大声を出さないことになっています。", "error_description": "「決まり」を根拠として示すには「で」を使う。「を」を付けると目的語になり、「ことになっている」と続く文として不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語を示す「が」。胃に潰瘍が存在することを言う文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「潰瘍を」では存在を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、存在を表す「ある」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列の働きで、「潰瘍と」では存在の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語を示す「が」。胃に潰瘍が存在することを言う文に合う。", "を": "「ある」は目的語を取らないので、「潰瘍を」では存在を表せない。", "へ": "「へ」は方向を示すので、存在を表す「ある」の主語にはならない。", "と": "「と」は引用や並列の働きで、「潰瘍と」では存在の主語にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「痛くて」の主語は潰瘍なので、「が」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」では痛みの主体を示せず、痛む文の主語にならない。"}, {"text": "を", "is_correct": false, "explanation": "「痛くて」は目的語を取らないので、「潰瘍を」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すので、痛みの主語の役を果たさない。"}], "correct_answer": "が", "explanations": {"が": "「痛くて」の主語は潰瘍なので、「が」が正しい。", "に": "「に」では痛みの主体を示せず、痛む文の主語にならない。", "を": "「痛くて」は目的語を取らないので、「潰瘍を」では文が成り立たない。", "から": "「から」は起点や理由を示すので、痛みの主語の役を果たさない。"}, "error_tags": {"に": "位置・相手", "を": "目的語", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだのなかで、いたくなったり、きずができたりするところです。", "primary_collocate": null, "pronunciation": "かいよう", "ipa": "kaijoː", "syllable_count": 4, "sentences": [{"text": "口の中に潰瘍ができて、食事のたびに痛みます。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "口[くち]の中[なか]に潰瘍[かいよう]ができて、食事[しょくじ]のたびに痛[いた]みます。", "sentence_source": "generated"}, {"text": "医者に、胃に潰瘍があると言われました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、胃[い]に潰瘍[かいよう]があると言[い]われました。", "sentence_source": "generated"}, {"text": "潰瘍のせいで、辛い物が食べられません。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "潰瘍[かいよう]のせいで、辛[から]い物[もの]が食[た]べられません。", "sentence_source": "generated"}, {"text": "潰瘍の薬を飲んでから、おなかの痛みが軽くなりました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "潰瘍[かいよう]の薬[くすり]を飲[の]んでから、おなかの痛[いた]みが軽[かる]くなりました。", "sentence_source": "generated"}, {"text": "兄は、ストレスが原因で潰瘍になりました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "兄[あに]は、ストレスが原因[げんいん]で潰瘍[かいよう]になりました。", "sentence_source": "generated"}, {"text": "舌にできた小さな潰瘍が、なかなか消えません。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "舌[した]にできた小[ちい]さな潰瘍[かいよう]が、なかなか消[き]えません。", "sentence_source": "generated"}, {"text": "検査をして、潰瘍がどこにあるか調べました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "検査[けんさ]をして、潰瘍[かいよう]がどこにあるか調[しら]べました。", "sentence_source": "generated"}, {"text": "潰瘍が痛くて、夜よく眠れませんでした。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "潰瘍[かいよう]が痛[いた]くて、夜[よる]よく眠[ねむ]れませんでした。", "sentence_source": "generated"}, {"text": "父は、潰瘍の治療のため、一週間入院しました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "父[ちち]は、潰瘍[かいよう]の治療[ちりょう]のため、一週間[いっしゅうかん]入院[にゅういん]しました。", "sentence_source": "generated"}, {"text": "潰瘍の場所によって、痛みの出る時間がちがうそうです。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "潰瘍[かいよう]の場所[ばしょ]によって、痛[いた]みの出[で]る時間[じかん]がちがうそうです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潰瘍", "label": "基本形"}, {"form": "かいよう", "label": "ひらがな表記"}], "register": "丁寧", "sense_fingerprint": "体の中や口の中にできて痛むただれ・傷のある場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潰瘍", "is_correct": true, "explanation": "口の中にできて痛むただれ・傷を指す。食事のたびに痛むという文に合う。"}, {"text": "包帯", "is_correct": false, "explanation": "傷を覆う医療用の布。口の中にできるものではないので成り立たない。"}, {"text": "湿布", "is_correct": false, "explanation": "皮膚に貼る薬。口の中にできるものとしては文が通らない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を指す語。口の中に「できる」ものではない。"}], "explanations": {"潰瘍": "口の中にできて痛むただれ・傷を指す。食事のたびに痛むという文に合う。", "包帯": "傷を覆う医療用の布。口の中にできるものではないので成り立たない。", "湿布": "皮膚に貼る薬。口の中にできるものとしては文が通らない。", "体温": "体の温度を指す語。口の中に「できる」ものではない。"}, "sentence_index": 0, "correct_answer": "潰瘍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究者は、潰瘍の調査で深い海の生き物を調べた。", "explanation": "ここは同じ読みの〈海洋〉の意味。潰瘍は体の中や粘膜の傷で、海の調査には使わない。"}, {"text": "月の潰瘍を観測するため、望遠鏡を組み立てた。", "explanation": "ここは〈クレーター〉（くぼみ）の意味。潰瘍は体の傷で、天体の表面には使わない。"}, {"text": "道路の潰瘍をふさぐ工事が始まった。", "explanation": "ここは〈穴〉（くぼみや開いた所）の意味。潰瘍は体の傷で、道路の穴には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潰瘍", "is_correct": true, "explanation": "体内にできる深い傷。検査で場所を調べる対象として文に合う。"}, {"text": "血圧", "is_correct": false, "explanation": "血管の圧力を指す語。どこにあるかを調べる対象にはならない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを指す語。場所を調べる対象として成り立たない。"}, {"text": "発熱", "is_correct": false, "explanation": "体温が上がる症状を指す語。どこにあるかを調べる文には合わない。"}], "explanations": {"潰瘍": "体内にできる深い傷。検査で場所を調べる対象として文に合う。", "血圧": "血管の圧力を指す語。どこにあるかを調べる対象にはならない。", "食欲": "食べたい気持ちを指す語。場所を調べる対象として成り立たない。", "発熱": "体温が上がる症状を指す語。どこにあるかを調べる文には合わない。"}, "sentence_index": 6, "correct_answer": "潰瘍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で屋根の潰瘍を直すため、大工さんを呼んだ。", "explanation": "ここは〈潰れ〉（つぶれて壊れた所）の意味。潰瘍は体や粘膜の傷で、建物の損傷には使わない。"}, {"text": "地面の潰瘍で、車が通れなくなった。", "explanation": "ここは〈陥没〉（地面がへこみ落ちること）の意味。潰瘍は体の傷なので、地面の状態には使わない。"}, {"text": "壁に潰瘍が入ったので、業者に補修を頼んだ。", "explanation": "ここは〈亀裂〉（ひびわれ）の意味。潰瘍は体の傷で、壁のひびには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潰瘍に痛くて、食事ができません。", "corrected_sentence": "潰瘍が痛くて、食事ができません。", "error_description": "「痛い」の主語は潰瘍なので「が」が正しい。「に」では痛む主体が示せず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38904, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "潰瘍が治すまで、食事に気をつけます。", "corrected_sentence": "潰瘍が治るまで、食事に気をつけます。", "error_description": "「治る」は潰瘍が自然に回復する自動詞。「治す」は人が治療する他動詞なので、潰瘍を主語にできない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「深くなる」の主語を示す「が」。潰瘍が深くなる、という文の主語。"}, {"text": "を", "is_correct": false, "explanation": "「深くなる」は目的語を取らないので、「潰瘍を」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「深くなる」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列の働きで、「潰瘍と」では主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "「深くなる」の主語を示す「が」。潰瘍が深くなる、という文の主語。", "を": "「深くなる」は目的語を取らないので、「潰瘍を」では文が成り立たない。", "へ": "「へ」は方向を示すが、「深くなる」の主語にはならない。", "と": "「と」は引用や並列の働きで、「潰瘍と」では主語を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「再発しないように」の主語は潰瘍なので、「が」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、再発の主語にはなれず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、再発の主語を表す文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すので、再発の主語の役を果たさない。"}], "correct_answer": "が", "explanations": {"が": "「再発しないように」の主語は潰瘍なので、「が」が正しい。", "に": "「に」は位置や相手を示すので、再発の主語にはなれず文が成り立たない。", "より": "「より」は比較を示すので、再発の主語を表す文には合わない。", "から": "「から」は起点や理由を示すので、再発の主語の役を果たさない。"}, "error_tags": {"に": "位置・相手", "より": "比較", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだの組織（そしき）や粘膜（ねんまく）にできる深い傷（きず）で、治るのに時間がかかることがあります。", "primary_collocate": null, "pronunciation": "かいよう", "ipa": "kaijoː", "syllable_count": 4, "sentences": [{"text": "胃の粘膜に深い潰瘍ができると、治るまでに時間がかかります。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "胃[い]の粘膜[ねんまく]に深[ふか]い潰瘍[かいよう]ができると、治[なお]るまでに時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "潰瘍が深くなると、出血することがあります。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "潰瘍[かいよう]が深[ふか]くなると、出血[しゅっけつ]することがあります。", "sentence_source": "generated"}, {"text": "検査で、十二指腸の粘膜に潰瘍が見つかりました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "検査[けんさ]で、十二指腸[じゅうにしちょう]の粘膜[ねんまく]に潰瘍[かいよう]が見[み]つかりました。", "sentence_source": "generated"}, {"text": "皮膚の潰瘍は、血のめぐりが悪いと治りにくいです。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "皮膚[ひふ]の潰瘍[かいよう]は、血[ち]のめぐりが悪[わる]いと治[なお]りにくいです。", "sentence_source": "generated"}, {"text": "薬で治療しても、潰瘍が完全に治るには数か月かかります。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "薬[くすり]で治療[ちりょう]しても、潰瘍[かいよう]が完全[かんぜん]に治[なお]るには数[すう]か月[げつ]かかります。", "sentence_source": "generated"}, {"text": "潰瘍の部分の組織を取って、くわしく調べました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "潰瘍[かいよう]の部分[ぶぶん]の組織[そしき]を取[と]って、くわしく調[しら]べました。", "sentence_source": "generated"}, {"text": "長く続く潰瘍は、ほかの病気のしるしかもしれません。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]く潰瘍[かいよう]は、ほかの病気[びょうき]のしるしかもしれません。", "sentence_source": "generated"}, {"text": "医師は、潰瘍が再発しないように生活を見直すよう勧めました。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "医師[いし]は、潰瘍[かいよう]が再発[さいはつ]しないように生活[せいかつ]を見直[みなお]すよう勧[すす]めました。", "sentence_source": "generated"}, {"text": "大腸の粘膜にできる潰瘍が原因で、腹痛が続くことがあります。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "大腸[だいちょう]の粘膜[ねんまく]にできる潰瘍[かいよう]が原因[げんいん]で、腹痛[ふくつう]が続[つづ]くことがあります。", "sentence_source": "generated"}, {"text": "内視鏡を使うと、粘膜にある潰瘍の様子がよくわかります。", "target_word": "潰瘍", "complexity_tier": "T3", "furigana": "内視鏡[ないしきょう]を使[つか]うと、粘膜[ねんまく]にある潰瘍[かいよう]の様子[ようす]がよくわかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潰瘍", "label": "基本形"}, {"form": "かいよう", "label": "ひらがな表記"}], "register": "丁寧", "sense_fingerprint": "組織や粘膜がただれてできる深い傷(医学用語・治りにくい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潰瘍", "is_correct": true, "explanation": "組織や粘膜にできる深い傷。深くできて治りにくいという文に合う。"}, {"text": "包帯", "is_correct": false, "explanation": "傷を覆う布。胃の粘膜に深くできるものではない。"}, {"text": "湿布", "is_correct": false, "explanation": "皮膚に貼る薬。胃の粘膜にできるものとして成り立たない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を指す語。深くできるものではない。"}], "explanations": {"潰瘍": "組織や粘膜にできる深い傷。深くできて治りにくいという文に合う。", "包帯": "傷を覆う布。胃の粘膜に深くできるものではない。", "湿布": "皮膚に貼る薬。胃の粘膜にできるものとして成り立たない。", "体温": "体の温度を指す語。深くできるものではない。"}, "sentence_index": 0, "correct_answer": "潰瘍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究所は、潰瘍の深さを測る船を作った。", "explanation": "ここは同じ読みの〈海洋〉の意味。潰瘍は体の傷で、海の深さを測る話には使わない。"}, {"text": "皮膚の潰瘍は、洗剤で拭けばきれいに消える。", "explanation": "ここは〈汚れ〉（よごれ）の意味。潰瘍は体の深い傷で、拭いて消えるものではない。"}, {"text": "壁の潰瘍は、乾燥すると広がりやすい。", "explanation": "ここは〈亀裂〉（ひびわれ）の意味。潰瘍は体の傷で、壁のひびには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潰瘍", "is_correct": true, "explanation": "体内の深い傷。長く続くと病気のしるしになりうるという文に合う。"}, {"text": "消毒液", "is_correct": false, "explanation": "傷を消毒する薬。長く続く症状としては成り立たない。"}, {"text": "花粉", "is_correct": false, "explanation": "植物から出る粉。病気のしるしとして続く文には合わない。"}, {"text": "絆創膏", "is_correct": false, "explanation": "傷を覆う貼り薬。長く続くしるしにはならない。"}], "explanations": {"潰瘍": "体内の深い傷。長く続くと病気のしるしになりうるという文に合う。", "消毒液": "傷を消毒する薬。長く続く症状としては成り立たない。", "花粉": "植物から出る粉。病気のしるしとして続く文には合わない。", "絆創膏": "傷を覆う貼り薬。長く続くしるしにはならない。"}, "sentence_index": 6, "correct_answer": "潰瘍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天井の潰瘍をふさぐため、補修材を塗った。", "explanation": "ここは〈穴〉（開いた所）の意味。潰瘍は体の傷で、天井の穴には使わない。"}, {"text": "地盤の潰瘍が広がって、工事が止まった。", "explanation": "ここは〈陥没〉（地面がへこみ落ちること）の意味。潰瘍は体の傷なので、地盤には使わない。"}, {"text": "ドアの潰瘍を直すため、金具を買った。", "explanation": "ここは〈潰れ〉（つぶれて壊れた所）の意味。潰瘍は体や粘膜の傷で、ドアの損傷には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潰瘍が治りにくくと、薬を長く飲みます。", "corrected_sentence": "潰瘍が治りにくいと、薬を長く飲みます。", "error_description": "「治りにくい」は形容詞なので、「と」の前は「い」が正しい。「くと」は活用の誤りで、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38905, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胃の潰瘍を治る薬を、毎朝飲んでいます。", "corrected_sentence": "胃の潰瘍を治す薬を、毎朝飲んでいます。", "error_description": "「治す」は他動詞で、「潰瘍を」と結びつく。「治る」は自動詞なので「潰瘍を」と結べず、誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「批判に対して」は「に」で対象を示す形。「対して」は「〜に」を取る。"}, {"text": "を", "is_correct": false, "explanation": "「対して」は「〜に」を取るので、「批判を対して」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すため、「批判で対して」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、反応の対象を示す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「批判に対して」は「に」で対象を示す形。「対して」は「〜に」を取る。", "を": "「対して」は「〜に」を取るので、「批判を対して」は成り立たない。", "で": "「で」は手段や場所を表すため、「批判で対して」は成り立たない。", "へ": "「へ」は方向を表すので、反応の対象を示す文には合わない。"}, "error_tags": {"を": "対象の格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「不満に対して」は「に」で対象を示す形。「対して」は「〜に」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「不満が対して」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すため、反応の対象を示す文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、対象を示す「対して」とは合わない。"}], "correct_answer": "に", "explanations": {"に": "「不満に対して」は「に」で対象を示す形。「対して」は「〜に」を取る。", "が": "「が」は主語を示すので、「不満が対して」は成り立たない。", "と": "「と」は相手や並列を表すため、反応の対象を示す文には合わない。", "から": "「から」は起点を表すので、対象を示す「対して」とは合わない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あることに対して、反応したり行動したりすること。", "primary_collocate": null, "pronunciation": "たいする", "ipa": "tai̯sɯɾɯ", "syllable_count": 4, "sentences": [{"text": "先生の質問に対して、彼はすぐに答えた。", "target_word": "対して", "complexity_tier": "T3", "furigana": "先生[せんせい]の質問[しつもん]に対[たい]して、彼[かれ]はすぐに答[こた]えた。", "sentence_source": "generated"}, {"text": "社長は厳しい批判に対して、何も言わなかった。", "target_word": "対して", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は厳[きび]しい批判[ひはん]に対[たい]して、何[なに]も言[い]わなかった。", "sentence_source": "generated"}, {"text": "市の計画に対して、住民から反対の声が上がった。", "target_word": "対して", "complexity_tier": "T3", "furigana": "市[し]の計画[けいかく]に対[たい]して、住民[じゅうみん]から反対[はんたい]の声[こえ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "犬は大きな音に対して、すぐに反応する。", "target_word": "対して", "complexity_tier": "T3", "furigana": "犬[いぬ]は大[おお]きな音[おと]に対[たい]して、すぐに反応[はんのう]する。", "sentence_source": "generated"}, {"text": "失礼な言葉に対して、彼女は静かに怒った。", "target_word": "対して", "complexity_tier": "T3", "furigana": "失礼[しつれい]な言葉[ことば]に対[たい]して、彼女[かのじょ]は静[しず]かに怒[おこ]った。", "sentence_source": "generated"}, {"text": "招待に対する返事は、今週中に出す必要がある。", "target_word": "対する", "complexity_tier": "T3", "furigana": "招待[しょうたい]に対[たい]する返事[へんじ]は、今週中[こんしゅうちゅう]に出[だ]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "子どものいたずらに対して、母ははっきり注意した。", "target_word": "対して", "complexity_tier": "T3", "furigana": "子[こ]どものいたずらに対[たい]して、母[はは]ははっきり注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "客の不満に対して、店は新しい方法を考えた。", "target_word": "対して", "complexity_tier": "T3", "furigana": "客[きゃく]の不満[ふまん]に対[たい]して、店[みせ]は新[あたら]しい方法[ほうほう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "彼は自分への悪口に対して、冷静に答えた。", "target_word": "対して", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]への悪口[わるぐち]に対[たい]して、冷静[れいせい]に答[こた]えた。", "sentence_source": "generated"}, {"text": "兄は私の意見に対して、いつも最後まで聞いてから答える。", "target_word": "対して", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]の意見[いけん]に対[たい]して、いつも最後[さいご]まで聞[き]いてから答[こた]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対する", "label": "辞書形"}, {"form": "対して", "label": "て形"}, {"form": "対した", "label": "た形"}, {"form": "対しない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "ある相手や出来事に向けて反応・行動する（〜に対して）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対して", "is_correct": true, "explanation": "「〜に対して」は、質問に向けた反応を表すので文の意味に合う。"}, {"text": "つれて", "is_correct": false, "explanation": "「〜につれて」は変化に伴って別の変化が起きることを表し、質問への反応を示す文脈に合わない。"}, {"text": "かけて", "is_correct": false, "explanation": "「〜にかけて」は期間や範囲を表すため、質問に答えるという意味にならない。"}, {"text": "わたって", "is_correct": false, "explanation": "「〜にわたって」は期間や範囲が広がることを表し、質問に反応する文には合わない。"}], "explanations": {"対して": "「〜に対して」は、質問に向けた反応を表すので文の意味に合う。", "つれて": "「〜につれて」は変化に伴って別の変化が起きることを表し、質問への反応を示す文脈に合わない。", "かけて": "「〜にかけて」は期間や範囲を表すため、質問に答えるという意味にならない。", "わたって": "「〜にわたって」は期間や範囲が広がることを表し、質問に反応する文には合わない。"}, "sentence_index": 0, "correct_answer": "対して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは、夕方、家に対して歩いて帰った。", "explanation": "ここは〈向かって〉の方向の意味と取り違えている。〈対して〉は反応や行動を向ける相手を示すので、移動の向きには使えず合わない。"}, {"text": "来年の予算に対して、会議が開かれる。", "explanation": "ここは〈関して〉の意味と取り違えている。〈対して〉は相手や出来事に反応・行動を向けるときに使うので合わない。"}, {"text": "子どもに対して、この本は難しい。", "explanation": "ここは〈にとって〉（立場から見た評価）の意味と取り違えている。〈対して〉は反応や行動を向ける相手を示すので、見方を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対して", "is_correct": true, "explanation": "「〜に対して」は、いたずらに向けた注意を表すので文の意味に合う。"}, {"text": "基づいて", "is_correct": false, "explanation": "「〜に基づいて」は根拠を表すため、注意する対象を示す文には合わない。"}, {"text": "限って", "is_correct": false, "explanation": "「〜に限って」は範囲を限る意味になり、注意するという文の流れに合わない。"}, {"text": "頼って", "is_correct": false, "explanation": "「頼る」は助けを求める意味なので、いたずらに注意する文には合わない。"}], "explanations": {"対して": "「〜に対して」は、いたずらに向けた注意を表すので文の意味に合う。", "基づいて": "「〜に基づいて」は根拠を表すため、注意する対象を示す文には合わない。", "限って": "「〜に限って」は範囲を限る意味になり、注意するという文の流れに合わない。", "頼って": "「頼る」は助けを求める意味なので、いたずらに注意する文には合わない。"}, "sentence_index": 6, "correct_answer": "対して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達の将来に対して話し合った。", "explanation": "ここは〈について〉の意味と取り違えている。〈対して〉は反応や行動を向ける対象を示すので、話題を指す場面では合わない。"}, {"text": "その事故に対して、電車が遅れた。", "explanation": "ここは〈〜によって〉（原因）の意味と取り違えている。〈対して〉は反応や行動を向ける相手を示すので、原因を表す使い方には合わない。"}, {"text": "夏休みに対して、毎日宿題を続けた。", "explanation": "ここは〈〜の間に〉（期間）の意味と取り違えている。〈対して〉は反応や行動を向ける対象を示すので、期間を表す使い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟の提案に対する、私は賛成した。", "corrected_sentence": "弟の提案に対して、私は賛成した。", "error_description": "「対して」が正しい。「対する」は後ろに名詞が続く形なので、「〜に対して、〜」の副詞句としては使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "対して", "is_correct": true, "explanation": "て形で、「厳しい批判に対して」と文中の副詞句として続き、後ろの文につながる。"}, {"text": "対する", "is_correct": false, "explanation": "辞書形は名詞を直接続ける形なので、「〜に対する〜」の形でないと文がつながらない。"}, {"text": "対した", "is_correct": false, "explanation": "た形は過去の出来事を表すため、この文の「〜に対して」という副詞句の形としては合わない。"}, {"text": "対せよ", "is_correct": false, "explanation": "命令形のため、「厳しい批判に対せよ」と続けても文として成り立たない。"}], "correct_form": "対して", "base_form": "対する", "form_label": "て形", "sentence_index": 1, "explanations": {"対して": "て形で、「厳しい批判に対して」と文中の副詞句として続き、後ろの文につながる。", "対する": "辞書形は名詞を直接続ける形なので、「〜に対する〜」の形でないと文がつながらない。", "対した": "た形は過去の出来事を表すため、この文の「〜に対して」という副詞句の形としては合わない。", "対せよ": "命令形のため、「厳しい批判に対せよ」と続けても文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38906, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい案を対して、会社は反対した。", "corrected_sentence": "新しい案に対して、会社は反対した。", "error_description": "「対して」は「に」を取る。「を」を付けると「対して」が成り立たず文が不自然になるので、正しくは「新しい案に対して」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "対して", "is_correct": true, "explanation": "て形で、「客の不満に対して」と文中の副詞句として続き、後ろの文につながる。"}, {"text": "対せよ", "is_correct": false, "explanation": "命令形のため、「客の不満に対せよ」と続けても文として成り立たない。"}, {"text": "対せず", "is_correct": false, "explanation": "「〜せず」は否定の意味になるため、新しい方法を考えたという文と合わない。"}, {"text": "対しよう", "is_correct": false, "explanation": "意志の形は「〜しよう」となり、過去の出来事を述べる文には合わない。"}], "correct_form": "対して", "base_form": "対する", "form_label": "て形", "sentence_index": 7, "explanations": {"対して": "て形で、「客の不満に対して」と文中の副詞句として続き、後ろの文につながる。", "対せよ": "命令形のため、「客の不満に対せよ」と続けても文として成り立たない。", "対せず": "「〜せず」は否定の意味になるため、新しい方法を考えたという文と合わない。", "対しよう": "意志の形は「〜しよう」となり、過去の出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上げる」の目的語を示す。「気勢を上げる」は集団で盛り上がる意味で、自然な言い方。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。気勢は上げられる対象なので「が」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示す。「気勢に上げる」とは言えない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す。「気勢で上げる」は不自然で、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「上げる」の目的語を示す。「気勢を上げる」は集団で盛り上がる意味で、自然な言い方。", "が": "主語を示す。気勢は上げられる対象なので「が」は合わない。", "に": "方向や相手を示す。「気勢に上げる」とは言えない。", "で": "場所や手段を示す。「気勢で上げる」は不自然で、目的語にならない。"}, "error_tags": {"が": "主語（上げる対象ではない）", "に": "方向・相手（目的語にならない）", "で": "場所・手段（目的語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「気勢」と「こもった声」をつなぎ、「気勢がこもった」という修飾関係を作る。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「こもる」は目的語をとらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「にこもる」は場所を表す。気勢は場所ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「気勢でこもった声」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「気勢」と「こもった声」をつなぎ、「気勢がこもった」という修飾関係を作る。", "を": "目的語を示す。「こもる」は目的語をとらないので合わない。", "に": "「にこもる」は場所を表す。気勢は場所ではないので合わない。", "で": "手段や場所を示す。「気勢でこもった声」は意味が通らない。"}, "error_tags": {"を": "目的語（「こもる」は取らない）", "に": "場所（気勢は場所ではない）", "で": "手段・場所（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで「やるぞ！」と思う気持ちのこと。", "primary_collocate": "上げる", "pronunciation": "きせい", "ipa": "kiseː", "syllable_count": 3, "sentences": [{"text": "試合の前に、選手たちは円陣を組んで気勢を上げた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、選手[せんしゅ]たちは円陣[えんじん]を組[く]んで気勢[きせい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "大会の前日、クラス全員が気勢を上げて練習に励んだ。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "大会[たいかい]の前日[ぜんじつ]、クラス全員[ぜんいん]が気勢[きせい]を上[あ]げて練習[れんしゅう]に励[はげ]んだ。", "sentence_source": "generated"}, {"text": "文化祭の準備で、みんなの気勢が高まってきた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]の準備[じゅんび]で、みんなの気勢[きせい]が高[たか]まってきた。", "sentence_source": "generated"}, {"text": "先生の一言で、チームの気勢が一気に上がった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "先生[せんせい]の一言[ひとこと]で、チームの気勢[きせい]が一気[いっき]に上[あ]がった。", "sentence_source": "generated"}, {"text": "雨が続いて、運動会に向けた気勢がそがれてしまった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いて、運動会[うんどうかい]に向[む]けた気勢[きせい]がそがれてしまった。", "sentence_source": "generated"}, {"text": "応援団の大きな声が、生徒たちの気勢をあおった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "応援団[おうえんだん]の大[おお]きな声[こえ]が、生徒[せいと]たちの気勢[きせい]をあおった。", "sentence_source": "generated"}, {"text": "負け続けたせいで、部員の気勢はすっかり弱まっていた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "負[ま]け続[つづ]けたせいで、部員[ぶいん]の気勢[きせい]はすっかり弱[よわ]まっていた。", "sentence_source": "generated"}, {"text": "気勢のこもった声で、全員が「がんばるぞ」と叫んだ。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "気勢[きせい]のこもった声[こえ]で、全員[ぜんいん]が「がんばるぞ」と叫[さけ]んだ。", "sentence_source": "generated"}, {"text": "みんなの気勢が盛んだったので、合唱は大成功だった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "みんなの気勢[きせい]が盛んだったので、合唱は大成功だった。", "sentence_source": "generated"}, {"text": "気勢が上がらないまま、私たちは本番の日を迎えた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "気勢[きせい]が上[あ]がらないまま、私[わたし]たちは本番[ほんばん]の日[ひ]を迎[むか]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気勢", "label": "base"}], "register": "neutral", "sense_fingerprint": "みんなで何かに取り組もうとする、盛り上がった気持ち。学校やチームの場面で使う。", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気勢", "is_correct": true, "explanation": "「上げる」と結びつき、試合前に集団で盛り上がる気持ちを表す。"}, {"text": "疲労", "is_correct": false, "explanation": "疲れのこと。「上げる」とは結びつかず、「円陣を組んで疲労を上げた」は不自然。"}, {"text": "失望", "is_correct": false, "explanation": "がっかりした気持ち。盛り上がる場面で「上げる」とは合わない。"}, {"text": "不安", "is_correct": false, "explanation": "心配な気持ち。「不安を上げる」とは言わず、円陣の場面に合わない。"}], "explanations": {"気勢": "「上げる」と結びつき、試合前に集団で盛り上がる気持ちを表す。", "疲労": "疲れのこと。「上げる」とは結びつかず、「円陣を組んで疲労を上げた」は不自然。", "失望": "がっかりした気持ち。盛り上がる場面で「上げる」とは合わない。", "不安": "心配な気持ち。「不安を上げる」とは言わず、円陣の場面に合わない。"}, "sentence_index": 0, "correct_answer": "気勢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は気勢がおだやかで、めったに人と争わない。", "explanation": "気勢は集団の活気や闘志を表すので、個人の生まれつきの性格の話には合わない。"}, {"text": "奥の部屋から、人の気勢がかすかに感じられた。", "explanation": "ここは〈気配〉（そこに人がいる様子）の意味。気勢は活気や闘志で、人の存在は指さない。"}, {"text": "ボイラーの気勢が強すぎて、配管が破裂した。", "explanation": "気勢は人の活気や闘志を表すので、機械の圧力の話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気勢", "is_correct": true, "explanation": "「弱まる」の主語になり、部員の活気を表す。"}, {"text": "勝利", "is_correct": false, "explanation": "勝つこと。部員の気持ちの状態を言う「弱まる」とは合わない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりのこと。「すっかり弱まっていた」とは言わない。"}, {"text": "日程", "is_correct": false, "explanation": "予定の順序。気持ちのように弱まることはない。"}], "explanations": {"気勢": "「弱まる」の主語になり、部員の活気を表す。", "勝利": "勝つこと。部員の気持ちの状態を言う「弱まる」とは合わない。", "規則": "決まりのこと。「すっかり弱まっていた」とは言わない。", "日程": "予定の順序。気持ちのように弱まることはない。"}, "sentence_index": 6, "correct_answer": "気勢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題集は量が多いが、気勢を持って最後まで解き続けた。", "explanation": "気勢は集団の活気や闘志を表すので、個人が粘り強く続ける力の話には合わない。"}, {"text": "この布は気勢が細かく、手触りがなめらかだ。", "explanation": "気勢は人の活気や闘志を表すので、布の織りの細かさの話には使えない。"}, {"text": "作業の気勢が悪く、いつも時間がかかる。", "explanation": "気勢は手際のよさを表さないので、作業の進め方の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "応援の練習で、部員たちは気勢が上げた。", "corrected_sentence": "応援の練習で、部員たちは気勢を上げた。", "error_description": "「上げる」は「気勢を上げる」と目的語に「を」を取る。ここの「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38910, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大会の日、部員たちは気勢を開いて入場した。", "corrected_sentence": "大会の日、部員たちは気勢を上げて入場した。", "error_description": "「気勢」には「上げる」を使う。「開く」は「気勢を開く」とは言わず、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「気勢」が「上がった」の主語になるので、ここでは「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「上がる」は目的語をとらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示す。「気勢に上がった」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す。「気勢で上がった」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「気勢」が「上がった」の主語になるので、ここでは「が」が正しい。", "を": "目的語を示す。「上がる」は目的語をとらないので合わない。", "に": "方向や相手を示す。「気勢に上がった」は不自然。", "で": "場所や手段を示す。「気勢で上がった」は意味が通らない。"}, "error_tags": {"を": "目的語（「上がる」は取らない）", "に": "方向（不自然）", "で": "手段・場所（意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「気勢」が「上がっていた」の主語になるので正しい。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す。「気勢と上がっていた」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「気勢へ上がっていた」とは言えない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「気勢から上がっていた」は不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「気勢」が「上がっていた」の主語になるので正しい。", "と": "相手や並列を示す。「気勢と上がっていた」は意味が通らない。", "へ": "方向を示す。「気勢へ上がっていた」とは言えない。", "から": "起点を示す。「気勢から上がっていた」は不自然。"}, "error_tags": {"と": "相手・並列（主語にならない）", "へ": "方向（不自然）", "から": "起点（不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "集団の中での活気や闘志。また、ある行動を起こそうとする勢い。", "primary_collocate": "上げる", "pronunciation": "きせい", "ipa": "kiseː", "syllable_count": 3, "sentences": [{"text": "デモの参加者は、広場で気勢を上げながら行進した。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "デモの参加者[さんかしゃ]は、広場[ひろば]で気勢[きせい]を上[あ]げながら行進[こうしん]した。", "sentence_source": "generated"}, {"text": "新しい社長の演説で、社員たちの気勢が上がった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]の演説[えんぜつ]で、社員[しゃいん]たちの気勢[きせい]が上[あ]がった。", "sentence_source": "generated"}, {"text": "敵の強さを見て、兵士たちの気勢はそがれてしまった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "敵[てき]の強[つよ]さを見[み]て、兵士[へいし]たちの気勢[きせい]はそがれてしまった。", "sentence_source": "generated"}, {"text": "野党は与党に対して、国会で気勢を上げた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "野党[やとう]は与党[よとう]に対[たい]して、国会[こっかい]で気勢[きせい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "労働組合は賃上げを求めて、駅前で気勢を上げた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "労働組合[ろうどうくみあい]は賃上[ちんあ]げを求[もと]めて、駅前[えきまえ]で気勢[きせい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "連勝したチームは気勢が盛んで、どこが相手でも負けなかった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "連勝[れんしょう]したチームは気勢[きせい]が盛[さか]んで、どこが相手[あいて]でも負[ま]けなかった。", "sentence_source": "generated"}, {"text": "工場の閉鎖が決まり、従業員の気勢は急に衰えた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "工場[こうじょう]の閉鎖[へいさ]が決[き]まり、従業員[じゅうぎょういん]の気勢[きせい]は急[きゅう]に衰[おとろ]えた。", "sentence_source": "generated"}, {"text": "選挙事務所では、候補者を囲んで気勢が上がっていた。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "選挙事務所[せんきょじむしょ]では、候補者[こうほしゃ]を囲[かこ]んで気勢[きせい]が上[あ]がっていた。", "sentence_source": "generated"}, {"text": "彼の厳しい一言が、集まった人々の気勢をそいだ。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "彼[かれ]の厳[きび]しい一言[ひとこと]が、集[あつ]まった人々[ひとびと]の気勢[きせい]をそいだ。", "sentence_source": "generated"}, {"text": "抗議の気勢は夜になっても収まらなかった。", "target_word": "気勢", "complexity_tier": "T3", "furigana": "抗議[こうぎ]の気勢[きせい]は夜[よる]になっても収[おさ]まらなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気勢", "label": "base"}], "register": "formal", "sense_fingerprint": "集団が示す活気や闘志、行動を起こそうとする勢い。デモ・組合・戦いなどの場面で使う。", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気勢", "is_correct": true, "explanation": "「上げる」と結びつき、デモで集団が示す活気や闘志を表す。"}, {"text": "眠気", "is_correct": false, "explanation": "眠い感じのこと。「広場で眠気を上げながら行進した」は言えない。"}, {"text": "落胆", "is_correct": false, "explanation": "がっかりすること。デモの勢いと合わず、「上げる」とも結びつかない。"}, {"text": "雑談", "is_correct": false, "explanation": "世間話のこと。「上げながら」と結びつかず、行進の場面に合わない。"}], "explanations": {"気勢": "「上げる」と結びつき、デモで集団が示す活気や闘志を表す。", "眠気": "眠い感じのこと。「広場で眠気を上げながら行進した」は言えない。", "落胆": "がっかりすること。デモの勢いと合わず、「上げる」とも結びつかない。", "雑談": "世間話のこと。「上げながら」と結びつかず、行進の場面に合わない。"}, "sentence_index": 0, "correct_answer": "気勢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は気勢をまっすぐ保ち、背筋を伸ばして座った。", "explanation": "気勢は集団の活気や闘志を表すので、体の構えの話には合わない。"}, {"text": "このパンは気勢がふんわりして、焼きたてのおいしさだ。", "explanation": "気勢は人の活気や闘志を表すので、パンの食感には使えない。"}, {"text": "このスープは気勢が深く、じっくり煮込んだ味がする。", "explanation": "気勢は味を表さないので、スープの味わいの話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気勢", "is_correct": true, "explanation": "「衰えた」の主語になり、従業員の活気を表す。"}, {"text": "規則", "is_correct": false, "explanation": "決まりのこと。衰えるものではないので合わない。"}, {"text": "名簿", "is_correct": false, "explanation": "名前を並べた帳面。「急に衰えた」とは言わない。"}, {"text": "予定", "is_correct": false, "explanation": "決まった計画のこと。「急に衰えた」とは言わない。"}], "explanations": {"気勢": "「衰えた」の主語になり、従業員の活気を表す。", "規則": "決まりのこと。衰えるものではないので合わない。", "名簿": "名前を並べた帳面。「急に衰えた」とは言わない。", "予定": "決まった計画のこと。「急に衰えた」とは言わない。"}, "sentence_index": 6, "correct_answer": "気勢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "選手は大きな気勢で拍手を受けたあと、冷静に試合を見ていた。", "explanation": "気勢は人の活気や闘志を表すので、拍手の音の大きさには使えない。"}, {"text": "午後から気勢が荒れて、雨が強くなった。", "explanation": "気勢は人々の活気を表すので、天候の話には使えない。"}, {"text": "弟は気勢が悪く、朝になるとふとんが床に落ちている。", "explanation": "気勢は人の活気や闘志を表すので、寝相の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抗議の集会で、参加者たちは気勢に上げた。", "corrected_sentence": "抗議の集会で、参加者たちは気勢を上げた。", "error_description": "「上げる」は「気勢を上げる」と目的語に「を」を取る。ここの「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38911, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になっても抗議の気勢は衰えるなかった。", "corrected_sentence": "夜になっても抗議の気勢は衰えなかった。", "error_description": "「衰える」の活用が誤り。否定過去は「衰えなかった」で、「衰えるなかった」は文法的に不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「柵を作った」で、作る対象の柵を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。柵は作られる対象なので「が」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す。「柵に作った」は目的語にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「柵へ作った」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「柵を作った」で、作る対象の柵を表す。", "が": "主語を示す。柵は作られる対象なので「が」は合わない。", "に": "場所を示す。「柵に作った」は目的語にならず不自然。", "へ": "方向を示す。「柵へ作った」とは言えない。"}, "error_tags": {"が": "主語（作る対象ではない）", "に": "場所（目的語にならない）", "へ": "方向（不自然）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「柵の外」の形で、柵に属する外側の位置を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「外」は目的語をとらないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す。「柵で外に」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。「柵と外に」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「柵の外」の形で、柵に属する外側の位置を示す。", "を": "目的語を示す。「外」は目的語をとらないので合わない。", "で": "場所や手段を示す。「柵で外に」は意味が通らない。", "と": "並列を示す。「柵と外に」は不自然。"}, "error_tags": {"を": "目的語（「外」は取らない）", "で": "場所・手段（意味が通らない）", "と": "並列（不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "さくは、にわやこうえんなどで、ばしょをわけるためにたてるもの。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "公園の花だんのまわりに、低い柵が立っている。", "target_word": "柵", "complexity_tier": "T3", "furigana": "公園[こうえん]の花[はな]だんのまわりに、低[ひく]い柵[さく]が立[た]っている。", "sentence_source": "generated"}, {"text": "犬が道に出ないように、庭に柵を作った。", "target_word": "柵", "complexity_tier": "T3", "furigana": "犬[いぬ]が道[みち]に出[で]ないように、庭[にわ]に柵[さく]を作[つく]った。", "sentence_source": "generated"}, {"text": "池に落ちると危ないので、子どもは柵の中に入れない。", "target_word": "柵", "complexity_tier": "T3", "furigana": "池[いけ]に落[お]ちると危[あぶ]ないので、子[こ]どもは柵[さく]の中[なか]に入[はい]れない。", "sentence_source": "generated"}, {"text": "柵の向こうで、ひつじが草を食べている。", "target_word": "柵", "complexity_tier": "T3", "furigana": "柵[さく]の向[む]こうで、ひつじが草[くさ]を食[た]べている。", "sentence_source": "generated"}, {"text": "弟はボールを取りに、柵を乗りこえて入った。", "target_word": "柵", "complexity_tier": "T3", "furigana": "弟[おとうと]はボールを取[と]りに、柵[さく]を乗[の]りこえて入[はい]った。", "sentence_source": "generated"}, {"text": "父は休みの日に、庭の柵にペンキをぬった。", "target_word": "柵", "complexity_tier": "T3", "furigana": "父[ちち]は休[やす]みの日[ひ]に、庭[にわ]の柵[さく]にペンキをぬった。", "sentence_source": "generated"}, {"text": "柵があるから、ここから先は入れません。", "target_word": "柵", "complexity_tier": "T3", "furigana": "柵[さく]があるから、ここから先[さき]は入[はい]れません。", "sentence_source": "generated"}, {"text": "公園の柵の外に、自転車を止めた。", "target_word": "柵", "complexity_tier": "T3", "furigana": "公園[こうえん]の柵[さく]の外[そと]に、自転車[じてんしゃ]を止[と]めた。", "sentence_source": "generated"}, {"text": "古くなった柵が、風で倒れてしまった。", "target_word": "柵", "complexity_tier": "T3", "furigana": "古[ふる]くなった柵[さく]が、風[かぜ]で倒[たお]れてしまった。", "sentence_source": "generated"}, {"text": "牧場では、馬が逃げないように柵で囲んである。", "target_word": "柵", "complexity_tier": "T3", "furigana": "牧場[ぼくじょう]では、馬[うま]が逃[に]げないように柵[さく]で囲[かこ]んである。", "sentence_source": "generated"}], "morphological_forms": [{"form": "柵", "label": "base"}], "register": "neutral", "sense_fingerprint": "庭や公園などで場所を分けるために立てる、囲いや仕切り。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 乗りこえ (Zipf 1.63)']::text[], 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柵", "is_correct": true, "explanation": "庭や公園で場所を区切る囲い。花だんのまわりに立つものとして合う。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描いた図。立てるものではないので合わない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車などに使う紙。立っているものではない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた便り。花だんのまわりに立つことはない。"}], "explanations": {"柵": "庭や公園で場所を区切る囲い。花だんのまわりに立つものとして合う。", "地図": "紙に描いた図。立てるものではないので合わない。", "切符": "乗車などに使う紙。立っているものではない。", "手紙": "書いた便り。花だんのまわりに立つことはない。"}, "sentence_index": 0, "correct_answer": "柵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の柵が伸びて、道の向こうまで茂っている。", "explanation": "柵は人が立てる囲いなので、伸びて茂る植物の話には合わない。"}, {"text": "母は柵を弾いて、子どもを寝かしつけた。", "explanation": "「弾く」の目的語は楽器などで、柵は弾けないので合わない。"}, {"text": "母は柵で野菜を切って、夕飯の準備をした。", "explanation": "柵は野菜を切る道具ではないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柵", "is_correct": true, "explanation": "「あるから」の主語になり、ここから先に入れない理由を示す。"}, {"text": "毛布", "is_correct": false, "explanation": "寝具の一種。入れないことの理由として「あるから」とは結びつかない。"}, {"text": "皿", "is_correct": false, "explanation": "料理をのせる器。入れない理由にはならない。"}, {"text": "雑誌", "is_correct": false, "explanation": "定期的に出る本。「ここから先は入れません」の理由にならない。"}], "explanations": {"柵": "「あるから」の主語になり、ここから先に入れない理由を示す。", "毛布": "寝具の一種。入れないことの理由として「あるから」とは結びつかない。", "皿": "料理をのせる器。入れない理由にはならない。", "雑誌": "定期的に出る本。「ここから先は入れません」の理由にならない。"}, "sentence_index": 6, "correct_answer": "柵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもは柵を読んで、夜になるまで過ごした。", "explanation": "「読む」の目的語は文章などで、柵は読めないので合わない。"}, {"text": "弟は柵をはいて、庭へ駆け出した。", "explanation": "「はく」の目的語は衣類などで、柵は身につけないので合わない。"}, {"text": "空に柵がぽつんと浮かんでいる。", "explanation": "柵は空に浮かぶものではないので、この文では不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は庭に柵が立てた。", "corrected_sentence": "父は庭に柵を立てた。", "error_description": "「立てる」は「柵を立てる」と目的語に「を」を取る。ここの「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38914, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子犬は柵を飛び越えるて、庭の外へ出てしまった。", "corrected_sentence": "子犬は柵を飛び越えて、庭の外へ出てしまった。", "error_description": "「飛び越える」の活用が誤り。接続は「飛び越えて」で、「飛び越えるて」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段や材料を示す。「木の柵で囲んで」と、囲いの材料を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「囲む」の主語にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「柵へ囲んで」は言えない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「柵から囲んで」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "手段や材料を示す。「木の柵で囲んで」と、囲いの材料を表す。", "が": "主語を示す。「囲む」の主語にはならないので合わない。", "へ": "方向を示す。「柵へ囲んで」は言えない。", "から": "起点を示す。「柵から囲んで」は意味が通らない。"}, "error_tags": {"が": "主語（囲む対象ではない）", "へ": "方向（不自然）", "から": "起点（意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「柵を設置し」と、設置の対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「柵が設置し」では柵が動作主になり、「市は…防いだ」の主語とずれて不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。「柵と設置し」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す。「柵より設置し」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「柵を設置し」と、設置の対象を表す。", "が": "主語を示す。「柵が設置し」では柵が動作主になり、「市は…防いだ」の主語とずれて不自然。", "と": "並列を示す。「柵と設置し」は不自然。", "より": "比較の基準を示す。「柵より設置し」は意味が通らない。"}, "error_tags": {"が": "主語（柵は設置される対象で、動作主ではない）", "と": "並列（不自然）", "より": "比較（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "柵は、木や金属などで作られた、領域を区切るための構造物です。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "工事現場には、金属の柵が並べて置いてある。", "target_word": "柵", "complexity_tier": "T3", "furigana": "工事現場[こうじげんば]には、金属[きんぞく]の柵[さく]が並[なら]べて置[お]いてある。", "sentence_source": "generated"}, {"text": "農場の周りを木の柵で囲んで、牛が外に出ないようにした。", "target_word": "柵", "complexity_tier": "T3", "furigana": "農場[のうじょう]の周[まわ]りを木[き]の柵[さく]で囲[かこ]んで、牛[うし]が外[そと]に出[で]ないようにした。", "sentence_source": "generated"}, {"text": "線路に人が入らないよう、駅の端に柵が設けられている。", "target_word": "柵", "complexity_tier": "T3", "furigana": "線路[せんろ]に人[ひと]が入[はい]らないよう、駅[えき]の端[はし]に柵[さく]が設[もう]けられている。", "sentence_source": "generated"}, {"text": "動物園では、ライオンと見学者の間に頑丈な柵がある。", "target_word": "柵", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、ライオンと見学者[けんがくしゃ]の間[あいだ]に頑丈[がんじょう]な柵[さく]がある。", "sentence_source": "generated"}, {"text": "柵が壊れていたため、羊の群れが山へ逃げ出した。", "target_word": "柵", "complexity_tier": "T3", "furigana": "柵[さく]が壊[こわ]れていたため、羊[ひつじ]の群[む]れが山[やま]へ逃[に]げ出[だ]した。", "sentence_source": "generated"}, {"text": "川沿いの道には、転落を防ぐための柵が続いている。", "target_word": "柵", "complexity_tier": "T3", "furigana": "川沿[かわぞ]いの道[みち]には、転落[てんらく]を防[ふせ]ぐための柵[さく]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "白い柵に囲まれた小さな家が、絵本のようだった。", "target_word": "柵", "complexity_tier": "T3", "furigana": "白[しろ]い柵[さく]に囲[かこ]まれた小[ちい]さな家[いえ]が、絵本[えほん]のようだった。", "sentence_source": "generated"}, {"text": "市はプールの周りに高い柵を設置し、子どもの侵入を防いだ。", "target_word": "柵", "complexity_tier": "T3", "furigana": "市[し]はプールの周[まわ]りに高[たか]い柵[さく]を設置[せっち]し、子[こ]どもの侵入[しんにゅう]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "古い木の柵は、雨で腐って折れやすくなっていた。", "target_word": "柵", "complexity_tier": "T3", "furigana": "古[ふる]い木[き]の柵[さく]は、雨[あめ]で腐[くさ]って折[お]れやすくなっていた。", "sentence_source": "generated"}, {"text": "台風で田んぼの柵が倒れ、修理が必要になった。", "target_word": "柵", "complexity_tier": "T3", "furigana": "台風[たいふう]で田[た]んぼの柵[さく]が倒[たお]れ、修理[しゅうり]が必要[ひつよう]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "柵", "label": "base"}], "register": "neutral", "sense_fingerprint": "木や金属で作られ、領域を区切ったり立ち入りや転落を防いだりする構造物。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柵", "is_correct": true, "explanation": "金属で作られた囲い。工事現場に並べて置いて使うものとして合う。"}, {"text": "手紙", "is_correct": false, "explanation": "文を書いた紙。金属のものではないので合わない。"}, {"text": "歌", "is_correct": false, "explanation": "音楽の作品。並べて置くものではない。"}, {"text": "絵本", "is_correct": false, "explanation": "絵のある本。金属で作るものではない。"}], "explanations": {"柵": "金属で作られた囲い。工事現場に並べて置いて使うものとして合う。", "手紙": "文を書いた紙。金属のものではないので合わない。", "歌": "音楽の作品。並べて置くものではない。", "絵本": "絵のある本。金属で作るものではない。"}, "sentence_index": 0, "correct_answer": "柵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家の柵が厚くて、外の音がまったく聞こえない。", "explanation": "柵は隙間があって音を遮らないので、壁の役にはならず、この文では不自然。"}, {"text": "母は柵を炊いて、夕飯の準備をした。", "explanation": "「炊く」の目的語は米などで、柵は炊けないので合わない。"}, {"text": "弟は柵をかぶって、庭へ出て行った。", "explanation": "「かぶる」の目的語は帽子などで、柵はかぶれないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柵", "is_correct": true, "explanation": "「白い柵に囲まれた」の形で、家を囲む囲いを表す。"}, {"text": "教科書", "is_correct": false, "explanation": "学習に使う本。白い囲いにはならない。"}, {"text": "新聞", "is_correct": false, "explanation": "毎日届く紙面。囲いには使わない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に貼る小さな紙。囲いにはならない。"}], "explanations": {"柵": "「白い柵に囲まれた」の形で、家を囲む囲いを表す。", "教科書": "学習に使う本。白い囲いにはならない。", "新聞": "毎日届く紙面。囲いには使わない。", "切手": "郵便に貼る小さな紙。囲いにはならない。"}, "sentence_index": 6, "correct_answer": "柵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は柵で豆をゆでて、スープを作った。", "explanation": "柵は豆をゆでる器ではないので、この文では使えない。"}, {"text": "家の柵から白い煙が上がっていた。", "explanation": "煙が出るのは煙突などで、柵から煙が出ることはないので不自然。"}, {"text": "祖父は柵をかけて、新聞を読んだ。", "explanation": "「かける」の目的語は眼鏡などで、柵はかけられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "運動会の準備で、生徒たちは柵が並べた。", "corrected_sentence": "運動会の準備で、生徒たちは柵を並べた。", "error_description": "「並べる」は「柵を並べる」と目的語に「を」を取る。ここの「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38915, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は庭の周りに柵を植えた。", "corrected_sentence": "父は庭の周りに柵を立てた。", "error_description": "「柵」には「立てる」を使う。「植える」は植物に使う動詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38916, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "すくうときに使う道具を示す「で」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「スプーンをよそった」は目的語になり、道具の意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「スプーンの」は所属を示すが、「よそう」の道具にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「スプーンへよそった」は方向を示し、道具として使う意味にならない。"}], "correct_answer": "で", "explanations": {"で": "すくうときに使う道具を示す「で」。正解。", "を": "「スプーンをよそった」は目的語になり、道具の意味にならない。", "の": "「スプーンの」は所属を示すが、「よそう」の道具にはならない。", "へ": "「スプーンへよそった」は方向を示し、道具として使う意味にならない。"}, "error_tags": {"を": "目的語", "の": "所属・修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38916, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "はかるための道具を示す「で」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「スプーンをこなをはかって」は目的語が二つ重なり、成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「スプーンからこなをはかって」は起点の意味になり、道具を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「スプーンにこなをはかって」は、道具や対象を示す形として不自然。"}], "correct_answer": "で", "explanations": {"で": "はかるための道具を示す「で」。正解。", "を": "「スプーンをこなをはかって」は目的語が二つ重なり、成り立たない。", "から": "「スプーンからこなをはかって」は起点の意味になり、道具を示せない。", "に": "「スプーンにこなをはかって」は、道具や対象を示す形として不自然。"}, "error_tags": {"を": "目的語（二重）", "から": "起点", "に": "到達・対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38916, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを すくう ときに つかう どうぐです。", "primary_collocate": null, "pronunciation": "すぷーん", "ipa": "sɯpɯːɴ", "syllable_count": 4, "sentences": [{"text": "スプーンで、さとうをすくいました。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "スプーンで、さとうをすくいました。", "sentence_source": "generated"}, {"text": "おおきなスプーンで、なべのスープをよそった。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "おおきなスプーンで、なべのスープをよそった。", "sentence_source": "generated"}, {"text": "コーヒーに、スプーンでさとうを入れます。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "コーヒーに、スプーンでさとうを入[い]れます。", "sentence_source": "generated"}, {"text": "スプーンが小さくて、たくさんすくえません。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "スプーンが小[ちい]さくて、たくさんすくえません。", "sentence_source": "generated"}, {"text": "引き出しに、スプーンが三本入っています。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しに、スプーンが三本[さんぼん]入[はい]っています。", "sentence_source": "generated"}, {"text": "くすりをスプーンにのせて、赤ちゃんに飲ませた。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "くすりをスプーンにのせて、赤[あか]ちゃんに飲[の]ませた。", "sentence_source": "generated"}, {"text": "このスプーンは木でできているので、あつくなりません。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "このスプーンは木[き]でできているので、あつくなりません。", "sentence_source": "generated"}, {"text": "スプーンでこなをはかって、ボウルに入れました。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "スプーンでこなをはかって、ボウルに入[い]れました。", "sentence_source": "generated"}, {"text": "土をスプーンですくって、小さなはちに入れた。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "土[つち]をスプーンですくって、小[ちい]さなはちに入[い]れた。", "sentence_source": "generated"}, {"text": "はかるときは、スプーンをすりきりにします。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "はかるときは、スプーンをすりきりにします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スプーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものをすくう道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38916, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スプーン", "is_correct": true, "explanation": "ものをすくう道具のスプーン。「スプーンで、さとうをすくいました」が成り立つ。正解。"}, {"text": "鍋", "is_correct": false, "explanation": "料理をする器で、砂糖をすくう道具にはならない。"}, {"text": "皿", "is_correct": false, "explanation": "料理を載せる器で、砂糖をすくう道具にはならない。"}, {"text": "包丁", "is_correct": false, "explanation": "切る道具で、すくうことはできない。"}], "explanations": {"スプーン": "ものをすくう道具のスプーン。「スプーンで、さとうをすくいました」が成り立つ。正解。", "鍋": "料理をする器で、砂糖をすくう道具にはならない。", "皿": "料理を載せる器で、砂糖をすくう道具にはならない。", "包丁": "切る道具で、すくうことはできない。"}, "sentence_index": 0, "correct_answer": "スプーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スプーンで、ごはんをつまみました。", "explanation": "ここは〈箸〉の動作。スプーンはすくう道具なので、つまむことはできない。"}, {"text": "スプーンで、野菜を切りました。", "explanation": "ここは〈包丁〉の動作。切る道具ではないので、スプーンでは野菜を切れない。"}, {"text": "スプーンで、くぎを打ちました。", "explanation": "ここは〈ハンマー〉の動作。打つ道具ではないので、くぎは打てない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38916, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スプーン", "is_correct": true, "explanation": "食べ物をすくう道具のスプーン。「このスプーンは木でできている」が成り立つ。正解。"}, {"text": "氷", "is_correct": false, "explanation": "水が凍ったもので、木で作られることはない。"}, {"text": "湯気", "is_correct": false, "explanation": "水蒸気で、木でできているものではない。"}, {"text": "灰", "is_correct": false, "explanation": "燃えかすで、木で作るものではない。"}], "explanations": {"スプーン": "食べ物をすくう道具のスプーン。「このスプーンは木でできている」が成り立つ。正解。", "氷": "水が凍ったもので、木で作られることはない。", "湯気": "水蒸気で、木でできているものではない。", "灰": "燃えかすで、木で作るものではない。"}, "sentence_index": 6, "correct_answer": "スプーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スプーンで、ゆかをはきました。", "explanation": "ここは〈ほうき〉の動作。ゆかをはく道具で、すくう道具のスプーンでは合わない。"}, {"text": "スプーンで、ケーキをさしました。", "explanation": "ここは〈フォーク〉の動作。さす道具ではないので、スプーンでは刺せない。"}, {"text": "スプーンで、歯をみがきました。", "explanation": "ここは〈歯ブラシ〉の動作。すくう道具のスプーンでは歯はみがけない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
