INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38917, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「スプーンが並んでいる」の主語を示す「が」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「スプーンを並んでいる」は、自動詞の「並ぶ」には目的語が付かないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「スプーンで並んでいる」は手段・場所を示し、主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「スプーンの並んでいる」は名詞修飾で、文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「スプーンが並んでいる」の主語を示す「が」。正解。", "を": "「スプーンを並んでいる」は、自動詞の「並ぶ」には目的語が付かないので合わない。", "で": "「スプーンで並んでいる」は手段・場所を示し、主語にはならない。", "の": "「スプーンの並んでいる」は名詞修飾で、文として成立しない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38917, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "スープや アイスクリームなどを すくって たべる ための どうぐです。", "primary_collocate": null, "pronunciation": "すぷーん", "ipa": "sɯpɯːɴ", "syllable_count": 4, "sentences": [{"text": "カレーを食[た]べるとき、箸[はし]よりスプーンのほうが楽[らく]です。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "カレーを食[た]べるとき、箸[はし]よりスプーンのほうが楽[らく]です。", "sentence_source": "generated"}, {"text": "アイスクリームを買ったら、店で小さなスプーンをくれた。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "アイスクリームを買[か]ったら、店[みせ]で小[ちい]さなスプーンをくれた。", "sentence_source": "generated"}, {"text": "子どもは、まだはしが使えないのでスプーンで食べる。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "子[こ]どもは、まだはしが使[つか]えないのでスプーンで食[た]べる。", "sentence_source": "generated"}, {"text": "スープが熱いので、スプーンでゆっくり飲んだ。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "スープが熱[あつ]いので、スプーンでゆっくり飲[の]んだ。", "sentence_source": "generated"}, {"text": "ヨーグルトを食べるために、スプーンを出した。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "ヨーグルトを食[た]べるために、スプーンを出[だ]した。", "sentence_source": "generated"}, {"text": "プリンは、小さなスプーンで食べるとおいしいです。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "プリンは、小[ちい]さなスプーンで食[た]べるとおいしいです。", "sentence_source": "generated"}, {"text": "赤ちゃんにスプーンでおかゆを食べさせた。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんにスプーンでおかゆを食[た]べさせた。", "sentence_source": "generated"}, {"text": "テーブルには、ナイフとフォークとスプーンが並んでいる。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "テーブルには、ナイフとフォークとスプーンが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "シチューはスプーンですくって食べます。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "シチューはスプーンですくって食[た]べます。", "sentence_source": "generated"}, {"text": "食べ終わったスプーンは、流しに置いてください。", "target_word": "スプーン", "complexity_tier": "T3", "furigana": "食[た]べ終[お]わったスプーンは、流[なが]しに置[お]いてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スプーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "スープやアイスをすくって食べる食器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38917, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スプーン", "is_correct": true, "explanation": "食べ物をすくって食べる道具のスプーン。「箸よりスプーンのほうが楽です」が成り立つ。正解。"}, {"text": "椅子", "is_correct": false, "explanation": "座る家具で、食べる道具と比べることはできない。"}, {"text": "鍋", "is_correct": false, "explanation": "料理を作る器で、箸と比べて食べやすさを言う対象にはならない。"}, {"text": "皿", "is_correct": false, "explanation": "料理を載せる器で、箸と比べて食べやすさを言う対象にはならない。"}], "explanations": {"スプーン": "食べ物をすくって食べる道具のスプーン。「箸よりスプーンのほうが楽です」が成り立つ。正解。", "椅子": "座る家具で、食べる道具と比べることはできない。", "鍋": "料理を作る器で、箸と比べて食べやすさを言う対象にはならない。", "皿": "料理を載せる器で、箸と比べて食べやすさを言う対象にはならない。"}, "sentence_index": 0, "correct_answer": "スプーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スプーンで、髪を乾かしました。", "explanation": "ここは〈ドライヤー〉の動作。食べ物をすくって食べる道具で、髪は乾かせない。"}, {"text": "スプーンで、にんじんを切りました。", "explanation": "ここは〈包丁〉の動作。食べ物をすくって食べる道具で、切る道具ではない。"}, {"text": "スプーンで、書類を留めました。", "explanation": "ここは〈ホッチキス〉の動作。紙をとめる道具で、食べるためのスプーンとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38917, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スプーン", "is_correct": true, "explanation": "食べさせる道具のスプーン。「赤ちゃんにスプーンでおかゆを食べさせた」が成り立つ。正解。"}, {"text": "包丁", "is_correct": false, "explanation": "切る道具で、おかゆを食べさせる道具にはならない。"}, {"text": "栓抜き", "is_correct": false, "explanation": "瓶のふたを開ける道具で、食べさせる道具にはならない。"}, {"text": "砂", "is_correct": false, "explanation": "食べ物ではなく、「砂でおかゆを食べさせた」は成り立たない。"}], "explanations": {"スプーン": "食べさせる道具のスプーン。「赤ちゃんにスプーンでおかゆを食べさせた」が成り立つ。正解。", "包丁": "切る道具で、おかゆを食べさせる道具にはならない。", "栓抜き": "瓶のふたを開ける道具で、食べさせる道具にはならない。", "砂": "食べ物ではなく、「砂でおかゆを食べさせた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "スプーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スプーンで、紙を切りました。", "explanation": "ここは〈はさみ〉の動作。紙を切る道具で、食べるためのスプーンでは切れない。"}, {"text": "スプーンで、小さな部品をつまみました。", "explanation": "ここは〈ピンセット〉の動作。つまむ道具で、すくって食べるスプーンとは違う。"}, {"text": "スプーンで、手紙を書きました。", "explanation": "ここは〈ペン〉の動作。文字を書く道具で、食べるためのスプーンでは書けない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
