INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38918, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「箸」が「うまく持てない」の主語になるので、主格の「が」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "帰着・位置を示す格で、「持てない」の対象としては入らず不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列を示す格で、ここでは「箸と持てない」となり意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格で、「箸から持てない」とは言わないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「箸」が「うまく持てない」の主語になるので、主格の「が」が正しい。", "に": "帰着・位置を示す格で、「持てない」の対象としては入らず不自然。", "と": "相手・並列を示す格で、ここでは「箸と持てない」となり意味が通らない。", "から": "起点を示す格で、「箸から持てない」とは言わないので合わない。"}, "error_tags": {"に": "帰着・位置を示す格で、ここでは合わない", "と": "相手・並列を示す格で、ここでは合わない", "から": "起点を示す格で、ここでは合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
