INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38918, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを はさんで もつ どうぐです。", "primary_collocate": null, "pronunciation": "はし", "ipa": "haɕi", "syllable_count": 2, "sentences": [{"text": "日本では、ごはんを食べるときに箸を使います。", "target_word": "箸", "complexity_tier": "T3", "furigana": "日本[にほん]では、ごはんを食[た]べるときに箸[はし]を使[つか]います。", "sentence_source": "generated"}, {"text": "弟はまだ箸がうまく持てなくて、スプーンで食べている。", "target_word": "箸", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ箸[はし]がうまく持[も]てなくて、スプーンで食[た]べている。", "sentence_source": "generated"}, {"text": "食事の前に、母が人数分の箸をテーブルにならべた。", "target_word": "箸", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]に、母[はは]が人数分[にんずうぶん]の箸[はし]をテーブルにならべた。", "sentence_source": "generated"}, {"text": "旅行のお土産に、きれいな絵の箸を買った。", "target_word": "箸", "complexity_tier": "T3", "furigana": "旅行[りょこう]のお土産[みやげ]に、きれいな絵[え]の箸[はし]を買[か]った。", "sentence_source": "generated"}, {"text": "箸でつかんだ豆が、つるりと落ちてしまった。", "target_word": "箸", "complexity_tier": "T3", "furigana": "箸[はし]でつかんだ豆[まめ]が、つるりと落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "外食のときは、いつも自分の箸を持っていく。", "target_word": "箸", "complexity_tier": "T3", "furigana": "外食[がいしょく]のときは、いつも自分[じぶん]の箸[はし]を持[も]っていく。", "sentence_source": "generated"}, {"text": "箸が長すぎて、小さな子には使いにくそうだった。", "target_word": "箸", "complexity_tier": "T3", "furigana": "箸[はし]が長[なが]すぎて、小[ちい]さな子[こ]には使[つか]いにくそうだった。", "sentence_source": "generated"}, {"text": "卵は箸でよくまぜてから、ごはんにかける。", "target_word": "箸", "complexity_tier": "T3", "furigana": "卵[たまご]は箸[はし]でよくまぜてから、ごはんにかける。", "sentence_source": "generated"}, {"text": "祖父は毎朝、使い慣れた箸で納豆を食べる。", "target_word": "箸", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎朝[まいあさ]、使[つか]い慣[な]れた箸[はし]で納豆[なっとう]を食[た]べる。", "sentence_source": "generated"}, {"text": "私は左手で箸を持つので、右ききの人の隣にすわるとぶつかる。", "target_word": "箸", "complexity_tier": "T3", "furigana": "私[わたし]は左手[ひだりて]で箸[はし]を持[も]つので、右[みぎ]ききの人[ひと]の隣[となり]にすわるとぶつかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "箸", "label": "base"}], "register": "neutral", "sense_fingerprint": "二本一組で、食べ物をはさんで口に運ぶ食事の道具。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: つるりと (Zipf 1.48)','sentence 9 above tier T3: contains vocabulary far above tier T3: すわる (Zipf 1.95)']::text[], 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38918, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "箸", "is_correct": true, "explanation": "食べ物をはさんで口に運ぶ道具で、ごはんを食べる場面に合う。"}, {"text": "傘", "is_correct": false, "explanation": "雨をよける道具で、ごはんを食べる場面では使わない。"}, {"text": "地図", "is_correct": false, "explanation": "道を調べるための紙で、食事の場面では使わない。"}, {"text": "鍵", "is_correct": false, "explanation": "戸を開ける道具で、食事の場面には合わない。"}], "explanations": {"箸": "食べ物をはさんで口に運ぶ道具で、ごはんを食べる場面に合う。", "傘": "雨をよける道具で、ごはんを食べる場面では使わない。", "地図": "道を調べるための紙で、食事の場面では使わない。", "鍵": "戸を開ける道具で、食事の場面には合わない。"}, "sentence_index": 0, "correct_answer": "箸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川に箸をかけて、向こう岸へ渡った。", "explanation": "ここは〈橋〉の意味。箸は食べ物をはさむ道具で、川にかける物ではないので合わない。"}, {"text": "道路の箸に車を止めて、少し待った。", "explanation": "ここは〈端〉の意味。箸は食事の道具で、道路の端を指さないので合わない。"}, {"text": "箸でスープをすくって飲んだ。", "explanation": "ここは〈スプーン〉の意味。箸はものをはさむ道具で、スープをすくう用途には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38918, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箸", "is_correct": true, "explanation": "長さを話題にできる食事の道具で、文の主語として合う。"}, {"text": "豆腐", "is_correct": false, "explanation": "食べ物で、長すぎて使いにくいという話にはならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の現象で、使いにくいという評価の対象にならない。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面で、子どもが使うという文脈に合わない。"}], "explanations": {"箸": "長さを話題にできる食事の道具で、文の主語として合う。", "豆腐": "食べ物で、長すぎて使いにくいという話にはならない。", "夕焼け": "空の現象で、使いにくいという評価の対象にならない。", "天井": "部屋の上の面で、子どもが使うという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "箸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジュースを箸で飲んだら、こぼれてしまった。", "explanation": "ここは〈ストロー〉の場面。箸は食べ物をはさむ道具で、飲み物を飲むには使わないので合わない。"}, {"text": "パンを箸で切った。", "explanation": "ここは〈ナイフ〉の場面。箸は食べ物をはさむ道具で、パンを切る道具ではないので合わない。"}, {"text": "おかずは箸に盛って出すと、見た目が美しい。", "explanation": "ここは〈皿〉の場面。箸は食べ物をはさむ道具で、料理を盛りつける器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38918, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は箸を煮物をつまんだ。", "corrected_sentence": "祖母は箸で煮物をつまんだ。", "error_description": "「箸」は道具を表すので「で」が正しい。「を」は目的語に使う助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38918, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は箸を一枚買った。", "corrected_sentence": "祖父は箸を一膳買った。", "error_description": "箸は二本で一組なので「膳」で数える。「枚」は薄くて平たいものを数える助数詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
