INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38922, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神に約束を必ず守ると示す、古代の儀式です。", "primary_collocate": null, "pronunciation": "うけい", "ipa": "ɯkeː", "syllable_count": 3, "sentences": [{"text": "古代の日本では、約束を必ず守ると神に示す儀式を誓（うけい）と言った。", "target_word": "誓", "complexity_tier": "T3", "furigana": "古代[こだい]の日本[にほん]では、約束[やくそく]を必[かなら]ず守[まも]ると神[かみ]に示[しめ]す儀式[ぎしき]を誓[うけい]（うけい）と言[い]った。", "sentence_source": "generated"}, {"text": "神話の姉と弟は、誓（うけい）によって自分の心が正しいと証明した。", "target_word": "誓", "complexity_tier": "T3", "furigana": "神話[しんわ]の姉[あね]と弟[おとうと]は、誓[うけい]（うけい）によって自分[じぶん]の心[こころ]が正[ただ]しいと証明[しょうめい]した。", "sentence_source": "generated"}, {"text": "この物語では、誓（うけい）を破った者に神の罰がくだる。", "target_word": "誓", "complexity_tier": "T3", "furigana": "この物語[ものがたり]では、誓[うけい]（うけい）を破[やぶ]った者[もの]に神[かみ]の罰[ばつ]がくだる。", "sentence_source": "generated"}, {"text": "二人は川のほとりで誓（うけい）を行い、決して裏切らないと約束した。", "target_word": "誓", "complexity_tier": "T3", "furigana": "二人[ふたり]は川[かわ]のほとりで誓[うけい]（うけい）を行[おこな]い、決[けっ]して裏切[うらぎ]らないと約束[やくそく]した。", "sentence_source": "generated"}, {"text": "昔の人々は、誓（うけい）を立てた以上、命をかけてそれを守った。", "target_word": "誓", "complexity_tier": "T3", "furigana": "昔[むかし]の人々[ひとびと]は、誓[うけい]（うけい）を立[た]てた以上[いじょう]、命[いのち]をかけてそれを守[まも]った。", "sentence_source": "generated"}, {"text": "神の前で誓（うけい）をしたので、王は約束を取り消せなかった。", "target_word": "誓", "complexity_tier": "T3", "furigana": "神[かみ]の前[まえ]で誓[うけい]（うけい）をしたので、王[おう]は約束[やくそく]を取[と]り消[け]せなかった。", "sentence_source": "generated"}, {"text": "弟は誓（うけい）の言葉を口にして、姉の疑いを晴らした。", "target_word": "誓", "complexity_tier": "T3", "furigana": "弟[おとうと]は誓[うけい]（うけい）の言葉[ことば]を口[くち]にして、姉[あね]の疑[うたが]いを晴[は]らした。", "sentence_source": "generated"}, {"text": "歴史の授業で、神話に出てくる誓（うけい）の意味を習った。", "target_word": "誓", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、神話[しんわ]に出[で]てくる誓[うけい]（うけい）の意味[いみ]を習[なら]った。", "sentence_source": "generated"}, {"text": "誓（うけい）とは、神に約束して、それを必ず守ることだ。", "target_word": "誓", "complexity_tier": "T3", "furigana": "誓[うけい]（うけい）とは、神[かみ]に約束[やくそく]して、それを必[かなら]ず守[まも]ることだ。", "sentence_source": "generated"}, {"text": "約束を軽く考える人には、誓（うけい）の重みが分からない。", "target_word": "誓", "complexity_tier": "T3", "furigana": "約束[やくそく]を軽[かる]く考[かんが]える人[ひと]には、誓[うけい]（うけい）の重[おも]みが分[わ]からない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誓", "label": "base"}], "register": "literary", "sense_fingerprint": "古代の神話や儀式で、約束を必ず守ると神に示す「うけい」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38922, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誓", "is_correct": true, "explanation": "神に約束を守ると示す儀式の名で、ここに入ると意味が通る。"}, {"text": "失敗", "is_correct": false, "explanation": "うまくいかないことを表し、儀式の名としては合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指す言葉で、儀式の名ではない。"}, {"text": "食器", "is_correct": false, "explanation": "食べるための道具で、儀式の名ではないので合わない。"}], "explanations": {"誓": "神に約束を守ると示す儀式の名で、ここに入ると意味が通る。", "失敗": "うまくいかないことを表し、儀式の名としては合わない。", "天気": "空模様を指す言葉で、儀式の名ではない。", "食器": "食べるための道具で、儀式の名ではないので合わない。"}, "sentence_index": 0, "correct_answer": "誓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "遊園地の入場券として、誓を三枚もらった。", "explanation": "ここは〈入場券〉の場面。誓は神に示す儀式で、券として配られる物ではないので合わない。"}, {"text": "この規則には、住民を縛る誓（うけい）がある。", "explanation": "ここは〈制約〉の意味。誓は神に示す約束の儀式で、規則の縛りを指さないので合わない。"}, {"text": "食卓に、誓の皿を並べた。", "explanation": "ここは〈皿〉の場面。誓は神に示す儀式で、食卓に並べる器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38922, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誓", "is_correct": true, "explanation": "神に約束を守ると示す言葉として、「の言葉」に続けて意味が通る。"}, {"text": "地図", "is_correct": false, "explanation": "紙の道具で、言葉の前に置いても意味が通らない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物で、言葉に結びつかないので合わない。"}, {"text": "本棚", "is_correct": false, "explanation": "家具で、口にする言葉に結びつかないので合わない。"}], "explanations": {"誓": "神に約束を守ると示す言葉として、「の言葉」に続けて意味が通る。", "地図": "紙の道具で、言葉の前に置いても意味が通らない。", "電車": "乗り物で、言葉に結びつかないので合わない。", "本棚": "家具で、口にする言葉に結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "誓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "神社で、誓（うけい）を買った。", "explanation": "ここは〈お守り〉の場面。誓は約束を守る儀式の意味で、買える物ではないので合わない。"}, {"text": "新しい商品を、大きな誓（うけい）で広く知らせた。", "explanation": "ここは〈広告〉の意味。誓は神との約束の儀式で、商品の宣伝には使わないので合わない。"}, {"text": "店の誓（うけい）を、お客さんに配った。", "explanation": "ここは〈名刺〉の場面。誓は神との約束の儀式で、配れる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38922, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅人は神の前で誓（うけい）を食べ、旅を続けた。", "corrected_sentence": "旅人は神の前で誓（うけい）を立て、旅を続けた。", "error_description": "「誓」には「立てる」が結びつく。「食べる」は飲食の動詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38922, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は神の前で誓（うけい）を立てれ、約束した。", "corrected_sentence": "二人は神の前で誓（うけい）を立てて、約束した。", "error_description": "「立てる」の連用形は「立てて」。「立てれ」は仮定形で、ここでは文を続けられないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
