INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38924, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あれこれ いう こと。", "primary_collocate": "言う", "pronunciation": "どうこう", "ipa": "doːkoː", "syllable_count": 4, "sentences": [{"text": "他人の生き方を、どうこう言うものではない。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "他人[たにん]の生[い]き方[かた]を、どうこう言[い]うものではない。", "sentence_source": "generated"}, {"text": "彼の決めたことに、私がどうこう言う資格はない。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "彼[かれ]の決[き]めたことに、私[わたし]がどうこう言[い]う資格[しかく]はない。", "sentence_source": "generated"}, {"text": "今さら過去をどうこう言っても、何も変わらない。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "今[いま]さら過去[かこ]をどうこう言[い]っても、何[なに]も変[か]わらない。", "sentence_source": "generated"}, {"text": "値段をどうこう言う前に、まず品物を見てください。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "値段[ねだん]をどうこう言[い]う前[まえ]に、まず品物[しなもの]を見[み]てください。", "sentence_source": "generated"}, {"text": "結果が出てから、どうこう言うことにしよう。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "結果[けっか]が出[で]てから、どうこう言[い]うことにしよう。", "sentence_source": "generated"}, {"text": "人の服装をどうこう言うのは、失礼だ。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "人[ひと]の服装[ふくそう]をどうこう言[い]うのは、失礼[しつれい]だ。", "sentence_source": "generated"}, {"text": "彼女は友達の恋愛を、どうこう言わずに見守っていた。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は友達[ともだち]の恋愛[れんあい]を、どうこう言[い]わずに見守[みまも]っていた。", "sentence_source": "generated"}, {"text": "試験の点数をどうこう言うより、次の努力が大切だ。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "試験[しけん]の点数[てんすう]をどうこう言[い]うより、次[つぎ]の努力[どりょく]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "親が子どもの進路をどうこう言うと、反発されることもある。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "親[おや]が子[こ]どもの進路[しんろ]をどうこう言[い]うと、反発[はんぱつ]されることもある。", "sentence_source": "generated"}, {"text": "他人にどうこう言われても、自分の信じた道を進む。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "他人[たにん]にどうこう言[い]われても、自分[じぶん]の信[しん]じた道[みち]を進[すす]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "どうこう", "label": "base"}], "register": "colloquial", "sense_fingerprint": "あれこれと批評や文句を言うさま。「どうこう言う」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38924, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "どうこう", "is_correct": true, "explanation": "「あれこれ言う」の意味で、「言うものではない」に自然につながる。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "熟睡する様子を表し、言うという動作には合わない。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝く様子で、言うという動作には合わない。"}, {"text": "ぺこぺこ", "is_correct": false, "explanation": "空腹や頭を下げる様子で、言うという動作には合わない。"}], "explanations": {"どうこう": "「あれこれ言う」の意味で、「言うものではない」に自然につながる。", "ぐっすり": "熟睡する様子を表し、言うという動作には合わない。", "きらきら": "光が輝く様子で、言うという動作には合わない。", "ぺこぺこ": "空腹や頭を下げる様子で、言うという動作には合わない。"}, "sentence_index": 0, "correct_answer": "どうこう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は、どうこうおいしい。", "explanation": "ここは〈とても〉の意味。どうこうは〈あれこれ言う〉ことで、味の程度を表さないので合わない。"}, {"text": "どうこう、困った。", "explanation": "ここは〈どうしよう〉の場面。どうこうは〈あれこれ言う〉ことで、困ったときの言葉ではないので合わない。"}, {"text": "ちょっと待ってください、どうこう待ってください。", "explanation": "ここは〈ちょっと〉の意味。どうこうは〈あれこれ言う〉ことで、待つ時間の短さを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38924, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "どうこう", "is_correct": true, "explanation": "「あれこれ言う」の意味で、「言わずに見守る」に自然につながる。"}, {"text": "ちらほら", "is_correct": false, "explanation": "少しずつ見えるさまを表し、言うという動作には合わない。"}, {"text": "ひらひら", "is_correct": false, "explanation": "物が軽く揺れるさまを表し、言うという動作には合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "物が光るさまを表し、言うという動作には合わない。"}], "explanations": {"どうこう": "「あれこれ言う」の意味で、「言わずに見守る」に自然につながる。", "ちらほら": "少しずつ見えるさまを表し、言うという動作には合わない。", "ひらひら": "物が軽く揺れるさまを表し、言うという動作には合わない。", "ぴかぴか": "物が光るさまを表し、言うという動作には合わない。"}, "sentence_index": 6, "correct_answer": "どうこう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキは、もうどうこう残っていない。", "explanation": "ここは〈ほとんど〉の意味。どうこうは〈あれこれ言う〉ことで、残りの量を表さないので合わない。"}, {"text": "この川は、どうこう流れが速い。", "explanation": "ここは〈やや〉の意味。どうこうは〈あれこれ言う〉ことで、流れの速さを表さないので合わない。"}, {"text": "彼は昔から、どうこう足が速かった。", "explanation": "ここは〈ずっと〉の意味。どうこうは〈あれこれ言う〉ことで、期間を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38924, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "親は子どもの進路を、どうこう笑わずに見守った。", "corrected_sentence": "親は子どもの進路を、どうこう言わずに見守った。", "error_description": "「どうこう」は「言う」と結びつく。「笑う」は「あれこれ言う」の意味にならないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38924, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩の成績を、どうこう言い資格はない。", "corrected_sentence": "先輩の成績を、どうこう言う資格はない。", "error_description": "「資格」の前は動詞の基本形「言う」が来る。「言い」は連用形なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
