INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38925, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あれこれ。とやかく。多く「どうこう言う」の形で使う。", "primary_collocate": "言う", "pronunciation": "どうこう", "ipa": "doːkoː", "syllable_count": 4, "sentences": [{"text": "相手の反応をどうこう言う前に、自分の説明を見直そう。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "相手[あいて]の反応[はんのう]をどうこう言う前[まえ]に、自分[じぶん]の説明[せつめい]を見直[みなお]そう。", "sentence_source": "generated"}, {"text": "この習慣は、他人がどうこう言えるものではないと思う。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "この習慣[しゅうかん]は、他人[たにん]がどうこう言[い]えるものではないと思[おも]う。", "sentence_source": "generated"}, {"text": "子どもの服装を、祖母がどうこう言うのはいつものことだ。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "子[こ]どもの服装[ふくそう]を、祖母[そぼ]がどうこう言[い]うのはいつものことだ。", "sentence_source": "generated"}, {"text": "他人の意見をどうこう言うのは、控えたほうがいい。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "他人[たにん]の意見[いけん]をどうこう言[い]うのは、控[ひか]えたほうがいい。", "sentence_source": "generated"}, {"text": "決まったルールを、私たちがどうこう言っても変わらない。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "決[き]まったルールを、私[わたし]たちがどうこう言[い]っても変[か]わらない。", "sentence_source": "generated"}, {"text": "彼の態度をどうこう言いたくなる気持ちは、分かる。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "彼[かれ]の態度[たいど]をどうこう言[い]いたくなる気持[きも]ちは、分[わ]かる。", "sentence_source": "generated"}, {"text": "会議では、予算をどうこう言う声が多かった。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、予算[よさん]をどうこう言[い]う声[こえ]が多[おお]かった。", "sentence_source": "generated"}, {"text": "終わったことを、今さらどうこう言わないでほしい。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "終[お]わったことを、今[いま]さらどうこう言[い]わないでほしい。", "sentence_source": "generated"}, {"text": "雨が降ったのは誰のせいでもないし、どうこう言っても仕方がない。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったのは誰[だれ]のせいでもないし、どうこう言[い]っても仕方[しかた]がない。", "sentence_source": "generated"}, {"text": "母は私の成績を、どうこう言わずに励ましてくれた。", "target_word": "どうこう", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の成績[せいせき]を、どうこう言[い]わずに励[はげ]ましてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "どうこう", "label": "base"}], "register": "colloquial", "sense_fingerprint": "あれこれ、とやかくの意味。「どうこう言う」「どうこうできない」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38925, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "どうこう", "is_correct": true, "explanation": "「相手の反応をあれこれ言う」の意味で、「言う」につながるのはこの語だけ。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「よく眠る様子」を表す副詞。「言う」とは結びつかず、空欄に入らない。"}, {"text": "ひらひら", "is_correct": false, "explanation": "「薄いものが揺れる様子」を表す副詞。「相手の反応を言う」とは合わない。"}, {"text": "しんと", "is_correct": false, "explanation": "「静まり返る様子」を表す副詞。「言う」の前に置いても意味が通らない。"}], "explanations": {"どうこう": "「相手の反応をあれこれ言う」の意味で、「言う」につながるのはこの語だけ。", "ぐっすり": "「よく眠る様子」を表す副詞。「言う」とは結びつかず、空欄に入らない。", "ひらひら": "「薄いものが揺れる様子」を表す副詞。「相手の反応を言う」とは合わない。", "しんと": "「静まり返る様子」を表す副詞。「言う」の前に置いても意味が通らない。"}, "sentence_index": 0, "correct_answer": "どうこう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電話に、どうこう出た。", "explanation": "ここは〈すぐに〉（即座に）の意味。どうこうは「あれこれ」で、すばやく行う意味は表さないので合わない。"}, {"text": "どうこう遅れたのか、理由を教えてください。", "explanation": "ここは〈どうして〉（なぜ）の意味。どうこうは理由を尋ねる語ではないので、疑問文には合わない。"}, {"text": "彼の報告書はどうこう立派だった。", "explanation": "ここは〈とても〉（非常に）の意味。どうこうは「あれこれ」で、程度の強さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38925, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "どうこう", "is_correct": true, "explanation": "「予算についてあれこれ言う」の意味で、「言う」を修飾するこの語が入る。"}, {"text": "くるくる", "is_correct": false, "explanation": "「回転する様子」を表す副詞。「予算を言う」の前に置くと意味が通らない。"}, {"text": "ぎらぎら", "is_correct": false, "explanation": "「強く光る様子」を表す副詞。「言う」とは結びつかない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "「軽く柔らかい様子」を表す副詞。「予算の話を言う」には合わない。"}], "explanations": {"どうこう": "「予算についてあれこれ言う」の意味で、「言う」を修飾するこの語が入る。", "くるくる": "「回転する様子」を表す副詞。「予算を言う」の前に置くと意味が通らない。", "ぎらぎら": "「強く光る様子」を表す副詞。「言う」とは結びつかない。", "ふわふわ": "「軽く柔らかい様子」を表す副詞。「予算の話を言う」には合わない。"}, "sentence_index": 6, "correct_answer": "どうこう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は朝からどうこう待っていた。", "explanation": "ここは〈ずっと〉（長い間）の意味。どうこうは「あれこれ」で、時間の長さは表さないので合わない。"}, {"text": "彼はどうこう窓を割った。", "explanation": "ここは〈わざと〉（故意に）の意味。どうこうは「あれこれ」で、意図して行ったことは表さないので合わない。"}, {"text": "子どもはどうこう眠っていた。", "explanation": "ここは〈ぐっすり〉（深く眠る様子）の意味。どうこうは「あれこれ」で、眠りの深さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38925, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私がどうこうを言える立場ではない。", "corrected_sentence": "私がどうこう言える立場ではない。", "error_description": "誤りは「どうこう」の直後に格助詞「を」を付けた点。「どうこう」は副詞なので「を」は付かず、正しくは「どうこう言える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38925, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の遅刻を、先生はどうこう食べなかった。", "corrected_sentence": "彼の遅刻を、先生はどうこう言わなかった。", "error_description": "誤りは「どうこう」と結びつく動詞。「どうこう」は「言う」と組み合わせて使い、「食べる」とは結びつかない。正しくは「どうこう言わなかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「動向」に直接付く格助詞で、「雲の動向を見れば」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「雲の動向に見れば」は文として成り立たず、「見る」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞だが、「動向へ見る」は不自然で、この空欄には入らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す助詞。「動向と見れば」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「動向」に直接付く格助詞で、「雲の動向を見れば」の目的語を示す。", "に": "「雲の動向に見れば」は文として成り立たず、「見る」の目的語にはならない。", "へ": "方向を示す助詞だが、「動向へ見る」は不自然で、この空欄には入らない。", "と": "相手や引用を示す助詞。「動向と見れば」は文として成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「動向」に直接付く格助詞で、「犯人の動向を追って」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「犯人の動向が追って」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞。「犯人の動向で追って」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞。「犯人の動向より追って」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「動向」に直接付く格助詞で、「犯人の動向を追って」の目的語を示す。", "が": "主語を示す助詞。「犯人の動向が追って」は文として成り立たない。", "で": "手段や場所を示す助詞。「犯人の動向で追って」は意味が通らない。", "より": "比較を示す助詞。「犯人の動向より追って」は文として成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが、どちらに動くか、という方向のこと。", "primary_collocate": null, "pronunciation": "どうこう", "ipa": "doːkoː", "syllable_count": 4, "sentences": [{"text": "台風の動向に注意して、外出を決めてください。", "target_word": "動向", "complexity_tier": "T3", "furigana": "台風[たいふう]の動向[どうこう]に注意[ちゅうい]して、外出[がいしゅつ]を決[き]めてください。", "sentence_source": "generated"}, {"text": "雲の動向を見れば、今日雨が降るかどうか分かる。", "target_word": "動向", "complexity_tier": "T3", "furigana": "雲[くも]の動向[どうこう]を見[み]れば、今日[きょう]雨[あめ]が降[ふ]るかどうか分[わ]かる。", "sentence_source": "generated"}, {"text": "渡り鳥の動向を調べるために、観察所が作られた。", "target_word": "動向", "complexity_tier": "T3", "furigana": "渡[わた]り鳥[どり]の動向[どうこう]を調[しら]べるために、観察所[かんさつしょ]が作[つく]られた。", "sentence_source": "generated"}, {"text": "川を流れる落ち葉の動向を見て、水の流れる向きを確かめた。", "target_word": "動向", "complexity_tier": "T3", "furigana": "川[かわ]を流[なが]れる落[お]ち葉[ば]の動向[どうこう]を見[み]て、水[みず]の流[なが]れる向[む]きを確[たし]かめた。", "sentence_source": "generated"}, {"text": "魚の群れの動向は、船の上からでもよく見えた。", "target_word": "動向", "complexity_tier": "T3", "furigana": "魚[さかな]の群[む]れの動向[どうこう]は、船[ふね]の上[うえ]からでもよく見[み]えた。", "sentence_source": "generated"}, {"text": "敵の軍隊の動向を、見張りが毎日報告している。", "target_word": "動向", "complexity_tier": "T3", "furigana": "敵[てき]の軍隊[ぐんたい]の動向[どうこう]を、見張[みは]りが毎日[まいにち]報告[ほうこく]している。", "sentence_source": "generated"}, {"text": "氷山の動向を、衛星の写真で調べている。", "target_word": "動向", "complexity_tier": "T3", "furigana": "氷山[ひょうざん]の動向[どうこう]を、衛星[えいせい]の写真[しゃしん]で調[しら]べている。", "sentence_source": "generated"}, {"text": "犯人の動向を追って、警察は町の中を調べた。", "target_word": "動向", "complexity_tier": "T3", "furigana": "犯人[はんにん]の動向[どうこう]を追[お]って、警察[けいさつ]は町[まち]の中[なか]を調[しら]べた。", "sentence_source": "generated"}, {"text": "動物の動向を記録するために、体に小さな機械をつけた。", "target_word": "動向", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の動向[どうこう]を記録[きろく]するために、体[からだ]に小[ちい]さな機械[きかい]をつけた。", "sentence_source": "generated"}, {"text": "風の動向が変わったので、ヨットの向きも変えた。", "target_word": "動向", "complexity_tier": "T3", "furigana": "風[かぜ]の動向[どうこう]が変[か]わったので、ヨットの向[む]きも変[か]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動向", "label": "base"}], "register": "formal", "sense_fingerprint": "人・動物・雲・台風など、具体的なものがどちらへ動いていくかという動きの方向。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動向", "is_correct": true, "explanation": "台風が動いていく方向を表す名詞で、「台風の○○に注意」の空欄に入る。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色を指す名詞。台風の動きに注意する文脈には合わない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を指す名詞。「台風の気温に注意」は意味が通らない。"}, {"text": "虹", "is_correct": false, "explanation": "雨上がりに空に見える現象。台風に注意する文脈では空欄に入らない。"}], "explanations": {"動向": "台風が動いていく方向を表す名詞で、「台風の○○に注意」の空欄に入る。", "夕焼け": "夕方の空の色を指す名詞。台風の動きに注意する文脈には合わない。", "気温": "空気の温度を指す名詞。「台風の気温に注意」は意味が通らない。", "虹": "雨上がりに空に見える現象。台風に注意する文脈では空欄に入らない。"}, "sentence_index": 0, "correct_answer": "動向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その船は朝の動向に港を出た。", "explanation": "ここは〈時刻〉の意味。動向は動く向きを表し、時刻は表さないので合わない。"}, {"text": "彼女の動向が急に赤くなった。", "explanation": "ここは〈顔色〉の意味。動向は動く向きを表し、顔の色は表さないので合わない。"}, {"text": "彼は英語の動向がとても上手だ。", "explanation": "ここは〈腕前〉（能力）の意味。動向は動きの方向を表し、能力の高さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動向", "is_correct": true, "explanation": "氷山が動いていく方向を表す名詞で、「氷山の○○を調べる」の空欄に入る。"}, {"text": "足音", "is_correct": false, "explanation": "人や動物が歩く音を指す名詞。「氷山の足音を調べる」は意味が通らない。"}, {"text": "香り", "is_correct": false, "explanation": "ものが発するにおいを指す名詞。氷山の調査の文脈には合わない。"}, {"text": "手触り", "is_correct": false, "explanation": "触ったときの感じを指す名詞。氷山を衛星の写真で調べる文脈では空欄に入らない。"}], "explanations": {"動向": "氷山が動いていく方向を表す名詞で、「氷山の○○を調べる」の空欄に入る。", "足音": "人や動物が歩く音を指す名詞。「氷山の足音を調べる」は意味が通らない。", "香り": "ものが発するにおいを指す名詞。氷山の調査の文脈には合わない。", "手触り": "触ったときの感じを指す名詞。氷山を衛星の写真で調べる文脈では空欄に入らない。"}, "sentence_index": 6, "correct_answer": "動向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川の動向が高いので、ボートは出せなかった。", "explanation": "ここは〈水位〉の意味。動向は動く向きを表し、水の高さは表さないので合わない。"}, {"text": "彼女の動向が急に明るくなった。", "explanation": "ここは〈表情〉の意味。動向は動く方向で、顔つきや明るさは表さないので合わない。"}, {"text": "先生は正しい動向で座った。", "explanation": "ここは〈姿勢〉の意味。動向は動く方向で、体の構えは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雲の動向を食べて、傘を持って出かけた。", "corrected_sentence": "雲の動向を見て、傘を持って出かけた。", "error_description": "誤りは「動向」と組み合わせた動詞。「動向」は「見る・追う」と使う。「食べる」とは結びつかないので、正しくは「見て」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38928, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渡り鳥の動向で、望遠鏡で追い続けた。", "corrected_sentence": "渡り鳥の動向を、望遠鏡で追い続けた。", "error_description": "誤りは「動向」に続く助詞。「追う」の目的語を示すのは「を」で、「で」は合わない。正しくは「渡り鳥の動向を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「動向」に直接付く格助詞で、「市場の動向を見ながら」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す助詞。「市場の動向に見ながら」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す助詞。「市場の動向と見ながら」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞。「市場の動向より見ながら」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「動向」に直接付く格助詞で、「市場の動向を見ながら」の目的語を示す。", "に": "位置や相手を示す助詞。「市場の動向に見ながら」は文として成り立たない。", "と": "相手や引用を示す助詞。「市場の動向と見ながら」は意味が通らない。", "より": "比較を示す助詞。「市場の動向より見ながら」は文として成り立たない。"}, "error_tags": {"に": "位置・相手", "と": "相手・引用", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「流行の動向」に続き、主題を示す助詞。空欄の位置に入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「流行の動向を早く変わる」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞。「流行の動向で早く変わる」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "修飾や所属を示す助詞。「流行の動向の早く変わる」は文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「流行の動向」に続き、主題を示す助詞。空欄の位置に入る。", "を": "目的語を示す助詞。「流行の動向を早く変わる」は文として成り立たない。", "で": "手段や場所を示す助詞。「流行の動向で早く変わる」は意味が通らない。", "の": "修飾や所属を示す助詞。「流行の動向の早く変わる」は文として成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "修飾・所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の動きや変化の方向性。特に、社会や時代の全体的な傾向や流れを指すことが多い。", "primary_collocate": null, "pronunciation": "どうこう", "ipa": "doːkoː", "syllable_count": 4, "sentences": [{"text": "経済の動向を知るために、毎日新聞を読んでいる。", "target_word": "動向", "complexity_tier": "T3", "furigana": "経済[けいざい]の動向[どうこう]を知[し]るために、毎日[まいにち]新聞[しんぶん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "会社は、市場の動向を見ながら商品の値段を決める。", "target_word": "動向", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、市場[しじょう]の動向[どうこう]を見[み]ながら商品[しょうひん]の値段[ねだん]を決[き]める。", "sentence_source": "generated"}, {"text": "若者の消費の動向について、調査結果が発表された。", "target_word": "動向", "complexity_tier": "T3", "furigana": "若者[わかもの]の消費[しょうひ]の動向[どうこう]について、調査結果[ちょうさけっか]が発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "政治の動向に関心がある人は、ニュース番組をよく見る。", "target_word": "動向", "complexity_tier": "T3", "furigana": "政治[せいじ]の動向[どうこう]に関心[かんしん]がある人[ひと]は、ニュース番組[ばんぐみ]をよく見[み]る。", "sentence_source": "generated"}, {"text": "業界の動向をつかんでいないと、新しい仕事は取れない。", "target_word": "動向", "complexity_tier": "T3", "furigana": "業界[ぎょうかい]の動向[どうこう]をつかんでいないと、新[あたら]しい仕事[しごと]は取[と]れない。", "sentence_source": "generated"}, {"text": "世界の動向を知るには、海外のニュースも大切だ。", "target_word": "動向", "complexity_tier": "T3", "furigana": "世界[せかい]の動向[どうこう]を知[し]るには、海外[かいがい]のニュースも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "人口の動向を調べると、将来の学校の数が予想できる。", "target_word": "動向", "complexity_tier": "T3", "furigana": "人口[じんこう]の動向[どうこう]を調[しら]べると、将来[しょうらい]の学校[がっこう]の数[かず]が予想[よそう]できる。", "sentence_source": "generated"}, {"text": "流行の動向は早く変わるので、店はいつも情報を集めている。", "target_word": "動向", "complexity_tier": "T3", "furigana": "流行[りゅうこう]の動向[どうこう]は早[はや]く変[か]わるので、店[みせ]はいつも情報[じょうほう]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "専門家は、為替の動向が景気に与える影響を説明した。", "target_word": "動向", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、為替[かわせ]の動向[どうこう]が景気[けいき]に与[あた]える影響[えいきょう]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "先生は、時代の動向を考えて進路を選ぶようにと言った。", "target_word": "動向", "complexity_tier": "T3", "furigana": "先生[せんせい]は、時代[じだい]の動向[どうこう]を考[かんが]えて進路[しんろ]を選[えら]ぶようにと言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動向", "label": "base"}], "register": "formal", "sense_fingerprint": "経済・政治・市場など、社会や時代の全体的な傾向や変化の流れ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1aa3799-c2f0-4bec-92ee-778cd05600f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動向", "is_correct": true, "explanation": "経済の全体的な傾向や流れを表し、「経済の○○を知る」の空欄に入る。"}, {"text": "値段", "is_correct": false, "explanation": "個々の商品の価格を指す名詞。「経済の値段を知る」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "人や動物の重さを指す名詞。「経済の体重を知る」は意味が通らない。"}, {"text": "歯並び", "is_correct": false, "explanation": "歯の並び方を指す名詞。「経済の歯並びを知る」は意味が通らない。"}], "explanations": {"動向": "経済の全体的な傾向や流れを表し、「経済の○○を知る」の空欄に入る。", "値段": "個々の商品の価格を指す名詞。「経済の値段を知る」は意味が通らない。", "体重": "人や動物の重さを指す名詞。「経済の体重を知る」は意味が通らない。", "歯並び": "歯の並び方を指す名詞。「経済の歯並びを知る」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "動向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の動向は、いつも大きな声だ。", "explanation": "ここは〈声量〉の意味。動向は流れや方向を表し、声の大きさは表さないので合わない。"}, {"text": "今日の動向は晴れだ。", "explanation": "ここは〈天気〉の意味。動向は流れや傾向を表すので、天候の状態には合わない。"}, {"text": "その商品は動向が重い。", "explanation": "ここは〈重さ〉の意味。動向は流れの方向を表し、重さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動向", "is_correct": true, "explanation": "人口の全体的な傾向を表し、「人口の○○を調べる」の空欄に入る。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の味を指す名詞。「人口の味を調べる」は意味が通らない。"}, {"text": "色合い", "is_correct": false, "explanation": "色の調子を指す名詞。人口を調べる文脈では空欄に入らない。"}, {"text": "手触り", "is_correct": false, "explanation": "触ったときの感じを指す名詞。「人口の手触りを調べる」は成り立たない。"}], "explanations": {"動向": "人口の全体的な傾向を表し、「人口の○○を調べる」の空欄に入る。", "味": "食べ物の味を指す名詞。「人口の味を調べる」は意味が通らない。", "色合い": "色の調子を指す名詞。人口を調べる文脈では空欄に入らない。", "手触り": "触ったときの感じを指す名詞。「人口の手触りを調べる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "動向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもの動向が伸びた。", "explanation": "ここは〈身長〉の意味。動向は流れの方向を表し、体の高さが伸びる意味は表さないので合わない。"}, {"text": "試合に動向が入った。", "explanation": "ここは〈点〉の意味。動向は流れの方向を表し、得点が入る意味は表さないので合わない。"}, {"text": "花の動向が咲いた。", "explanation": "ここは〈花〉が主語の意味。動向は流れの方向を表し、花が開く意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "為替の動向に調べて、輸出の計画を立てた。", "corrected_sentence": "為替の動向を調べて、輸出の計画を立てた。", "error_description": "誤りは「動向」に続く助詞。「調べる」の目的語を示すのは「を」で、「に」は合わない。正しくは「為替の動向を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38929, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は、客層の動向を味わってから仕入れを決める。", "corrected_sentence": "店長は、客層の動向をつかんでから仕入れを決める。", "error_description": "誤りは「動向」と組み合わせた動詞。「動向」は「つかむ・追う」と使う。「味わう」とは結びつかないので、正しくは「つかんで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a9f23e-6c20-488e-bebc-4a6c45a9faa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「使い捨てにする」の形で、物を一度使って捨てる扱いにする意味。文中の「使い捨てにする生活」に合う。"}, {"text": "が", "is_correct": false, "explanation": "「使い捨てが生活」では動詞が続かず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「使い捨てへ生活」は意味をなさない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「使い捨てから生活」は文の構造に合わない。"}], "correct_answer": "に", "explanations": {"に": "「使い捨てにする」の形で、物を一度使って捨てる扱いにする意味。文中の「使い捨てにする生活」に合う。", "が": "「使い捨てが生活」では動詞が続かず、文が成り立たない。", "へ": "「へ」は方向を表すので、「使い捨てへ生活」は意味をなさない。", "から": "「から」は起点を表すので、「使い捨てから生活」は文の構造に合わない。"}, "error_tags": {"が": "subject", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「使い捨てにして」の形で、社員を使い捨てる扱いにする意味。文中の「使い捨てにしている」に合う。"}, {"text": "が", "is_correct": false, "explanation": "「使い捨てが」では続く動詞がなく、文の構造が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「使い捨ての」は名詞を修飾する形で、「していると」に続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「使い捨てへ」は動作の対象として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「使い捨てにして」の形で、社員を使い捨てる扱いにする意味。文中の「使い捨てにしている」に合う。", "が": "「使い捨てが」では続く動詞がなく、文の構造が成り立たない。", "の": "「使い捨ての」は名詞を修飾する形で、「していると」に続かず不自然。", "へ": "「へ」は方向を表すので、「使い捨てへ」は動作の対象として成り立たない。"}, "error_tags": {"が": "subject", "の": "modifier", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "一度使ったら、もう使わないで捨てること。", "primary_collocate": null, "pronunciation": "つかいすて", "ipa": "tsɯkaisɯte", "syllable_count": 5, "sentences": [{"text": "この店は使い捨ての食器をやめて、洗える皿を使っています。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "このみせはつかいすてのしょっきをやめて、あらえるさらをつかっています。", "sentence_source": "generated"}, {"text": "物を使い捨てにする生活は、ごみを増やす原因になります。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "ものをつかいすてにするせいかつは、ごみをふやすげんいんになります。", "sentence_source": "generated"}, {"text": "服を使い捨てにせず、長く大切に着たい。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "ふくをつかいすてにせず、ながくたいせつにきたい。", "sentence_source": "generated"}, {"text": "資源が少ない国では、使い捨ての考え方は許されない。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "しげんがすくないくにでは、つかいすてのかんがえかたはゆるされない。", "sentence_source": "generated"}, {"text": "彼は新しい物が好きで、何でも使い捨てにしてしまう。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "かれはあたらしいものがすきで、なんでもつかいすてにしてしまう。", "sentence_source": "generated"}, {"text": "使い捨てをやめるために、私は水筒を持ち歩いています。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "つかいすてをやめるために、わたしはすいとうをもちあるいています。", "sentence_source": "generated"}, {"text": "昔の人は物を直して使ったので、使い捨ての習慣はなかった。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "むかしのひとはものをなおしてつかったので、つかいすてのしゅうかんはなかった。", "sentence_source": "generated"}, {"text": "会社は社員を使い捨てにしていると批判された。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "かいしゃはしゃいんをつかいすてにしているとひはんされた。", "sentence_source": "generated"}, {"text": "使い捨てを減らす運動が、町の小学校から始まった。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "つかいすてをへらすうんどうが、まちのしょうがっこうからはじまった。", "sentence_source": "generated"}, {"text": "紙のコップを使い捨てにすると、毎日大量のごみが出る。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "かみのコップをつかいすてにすると、まいにちたいりょうのごみがでる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使い捨て", "label": "基本形"}, {"form": "使い捨ての", "label": "の形"}, {"form": "使い捨てにする", "label": "にする形"}], "register": "標準", "sense_fingerprint": "一度使って捨てる行為・習慣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使い捨て", "is_correct": true, "explanation": "「使い捨ての食器」は一度使って捨てる食器のこと。文脈の「洗える皿を使う」と対比になる。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤の食器」は意味が通らない。洗剤は食器の種類を表さない。"}, {"text": "包装", "is_correct": false, "explanation": "「包装の食器」は種類を表す言い方として不自然で、やめる対象の説明にならない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文の食器」は、食器の性質を表す語として成り立たない。"}], "explanations": {"使い捨て": "「使い捨ての食器」は一度使って捨てる食器のこと。文脈の「洗える皿を使う」と対比になる。", "洗剤": "「洗剤の食器」は意味が通らない。洗剤は食器の種類を表さない。", "包装": "「包装の食器」は種類を表す言い方として不自然で、やめる対象の説明にならない。", "注文": "「注文の食器」は、食器の性質を表す語として成り立たない。"}, "sentence_index": 0, "correct_answer": "使い捨て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このペンは使い捨てなので、インクを入れて何度も書けます。", "explanation": "ここは〈繰り返し使える〉の意味で使われている。使い捨ては一度使って捨てることなので、インクを入れて何度も使う話とは合わない。"}, {"text": "この店は、客が返した食器を洗って、使い捨てにして次の客に出している。", "explanation": "ここは〈洗って再び出す〉の意味で使われている。使い捨ては捨てる前提の言葉なので、洗って次の客に出す話には合わない。"}, {"text": "祖父は壊れた時計を一度使い捨てにしてから、丁寧に直した。", "explanation": "ここは〈修理して使う〉の意味で使われている。使い捨ては直して使うことを含まない語なので、壊れた時計を直す話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使い捨て", "is_correct": true, "explanation": "「使い捨ての習慣」は、物を一度で捨てる習慣のこと。直して使った昔の人の話と対比になる。"}, {"text": "大食い", "is_correct": false, "explanation": "「大食いの習慣」は文として通るが、物を直して使う話題とは無関係で、捨てる習慣を表さない。"}, {"text": "配達", "is_correct": false, "explanation": "「配達の習慣」は、物を捨てることとは関係がなく、文脈に合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "「入浴の習慣」は生活習慣としては成り立つが、物の扱いを述べる文脈には合わない。"}], "explanations": {"使い捨て": "「使い捨ての習慣」は、物を一度で捨てる習慣のこと。直して使った昔の人の話と対比になる。", "大食い": "「大食いの習慣」は文として通るが、物を直して使う話題とは無関係で、捨てる習慣を表さない。", "配達": "「配達の習慣」は、物を捨てることとは関係がなく、文脈に合わない。", "入浴": "「入浴の習慣」は生活習慣としては成り立つが、物の扱いを述べる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "使い捨て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紙コップは使い捨てにしてあるので、洗って何度も使えます。", "explanation": "ここは〈繰り返し使える〉の意味で使われている。使い捨ては一度で捨てることなので、洗って何度も使う話とは合わない。"}, {"text": "この箸は使い捨てなので、一生使い続けるつもりだ。", "explanation": "〈長く使い続ける〉の意味で使われている。使い捨ては一度使って捨てる前提の語なので、長く使い続ける話には合わない。"}, {"text": "この箸は使い捨てなので、来年まで買い足さなくてよい。", "explanation": "〈長持ちする〉の意味で使われている。使い捨ては一回で消費される前提なので、長持ちする話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この容器は使い捨てを、一度使ったら捨ててください。", "corrected_sentence": "この容器は使い捨てなので、一度使ったら捨ててください。", "error_description": "「使い捨て」は名詞で、「なので」で文をつなげられる。「使い捨てを」の「を」は誤り。正しくは「使い捨てなので」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38930, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店では、使い捨てを箸を配っています。", "corrected_sentence": "この店では、使い捨ての箸を配っています。", "error_description": "「使い捨て」が後ろの名詞を修飾するときは「の」が必要。「を」は動詞の目的語に付くので、ここでは誤り。正しくは「使い捨ての箸」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「使い捨ての皿」の形で、「使い捨て」が後ろの「皿」を修飾する。文中の「使い捨ての皿」に合う。"}, {"text": "が", "is_correct": false, "explanation": "「使い捨てが皿」では名詞同士がつながらず、文の構造が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「使い捨てで皿」は手段の意味になり、皿を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すので、「使い捨てを皿」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「使い捨ての皿」の形で、「使い捨て」が後ろの「皿」を修飾する。文中の「使い捨ての皿」に合う。", "が": "「使い捨てが皿」では名詞同士がつながらず、文の構造が成り立たない。", "で": "「使い捨てで皿」は手段の意味になり、皿を修飾できない。", "を": "「を」は目的語を表すので、「使い捨てを皿」は文法的に成り立たない。"}, "error_tags": {"が": "subject", "で": "means", "を": "object"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「使い捨ての傘」の形で、「使い捨て」が「傘」を修飾する。文中の「使い捨ての傘」に合う。"}, {"text": "に", "is_correct": false, "explanation": "「使い捨てに傘」は「にする」の形でしか使えず、傘を修飾できない。"}, {"text": "が", "is_correct": false, "explanation": "「使い捨てが傘」では名詞同士がつながらず、修飾関係が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すので、「使い捨てと傘」では傘を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「使い捨ての傘」の形で、「使い捨て」が「傘」を修飾する。文中の「使い捨ての傘」に合う。", "に": "「使い捨てに傘」は「にする」の形でしか使えず、傘を修飾できない。", "が": "「使い捨てが傘」では名詞同士がつながらず、修飾関係が成立しない。", "と": "「と」は並列や相手を表すので、「使い捨てと傘」では傘を修飾できない。"}, "error_tags": {"に": "attachment", "が": "subject", "と": "pairing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一度使用したら、その後は使わずに捨てることを指す言葉。特に、安価で短期間の使用を前提とした製品に使われる。", "primary_collocate": null, "pronunciation": "つかいすて", "ipa": "tsɯkaisɯte", "syllable_count": 5, "sentences": [{"text": "使い捨てのマスクを毎朝新しいものに替えます。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "つかいすてのマスクをまいあさあたらしいものにかえます。", "sentence_source": "generated"}, {"text": "キャンプには使い捨ての皿とコップが便利です。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "キャンプにはつかいすてのさらとコップがべんりです。", "sentence_source": "generated"}, {"text": "病院では、注射器は使い捨てのものしか使いません。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "びょういんでは、ちゅうしゃきはつかいすてのものしかつかいません。", "sentence_source": "generated"}, {"text": "この使い捨てのカメラは、旅行の記念に買いました。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "このつかいすてのカメラは、りょこうのきねんにかいました。", "sentence_source": "generated"}, {"text": "使い捨てのカイロをポケットに入れて、寒い朝に出かけた。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "つかいすてのカイロをポケットにいれて、さむいあさにでかけた。", "sentence_source": "generated"}, {"text": "使い捨ての手袋をつけてから、料理を始めた。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "つかいすてのてぶくろをつけてから、りょうりをはじめた。", "sentence_source": "generated"}, {"text": "値段が安い使い捨てのライターは、すぐに捨てられる。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "ねだんがやすいつかいすてのライターは、すぐにすてられる。", "sentence_source": "generated"}, {"text": "使い捨ての傘は、風が強いとすぐ壊れてしまう。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "つかいすてのかさは、かぜがつよいとすぐこわれてしまう。", "sentence_source": "generated"}, {"text": "掃除のとき、使い捨ての布を使うと後が楽です。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "そうじのとき、つかいすてのぬのをつかうとあとがらくです。", "sentence_source": "generated"}, {"text": "この箸は使い捨てなので、使ったあとは捨ててください。", "target_word": "使い捨て", "complexity_tier": "T3", "furigana": "このはしはつかいすてなので、つかったあとはすててください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使い捨て", "label": "基本形"}, {"form": "使い捨ての", "label": "の形"}, {"form": "使い捨てで", "label": "で形"}], "register": "標準", "sense_fingerprint": "一回で捨てる前提の安価な製品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使い捨て", "is_correct": true, "explanation": "「使い捨てのマスク」は一度使って捨てるマスク。毎朝替えるという文脈に合う。"}, {"text": "洗浄", "is_correct": false, "explanation": "「洗浄のマスク」は意味が通らない。洗浄はマスクの種類を表さない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送のマスク」は種類を表さず、意味が通らない。"}, {"text": "冷却", "is_correct": false, "explanation": "「冷却のマスク」は種類として成り立たず、文の意味に合わない。"}], "explanations": {"使い捨て": "「使い捨てのマスク」は一度使って捨てるマスク。毎朝替えるという文脈に合う。", "洗浄": "「洗浄のマスク」は意味が通らない。洗浄はマスクの種類を表さない。", "配送": "「配送のマスク」は種類を表さず、意味が通らない。", "冷却": "「冷却のマスク」は種類として成り立たず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "使い捨て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この使い捨てのシャツは旅行の記念に、何年も着ている。", "explanation": "〈長く着る〉の意味で使われている。使い捨ては一度で捨てる前提なので、何年も着る話には合わない。"}, {"text": "この使い捨てのカメラは中古で、前の持ち主の写真がそのまま残っている。", "explanation": "〈中古品〉の意味で使われている。使い捨ては新品を一度で捨てる前提の語なので、中古品の話には合わない。"}, {"text": "この使い捨ての時計は高級品で、何十年も大切に使われている。", "explanation": "〈大切に長く使う〉の意味で使われている。使い捨ては長く使わない前提なので、高級品を大切に使う話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使い捨て", "is_correct": true, "explanation": "「使い捨てのライター」は一度使って捨てるライター。安くて、すぐ捨てられるという文脈に合う。"}, {"text": "電池", "is_correct": false, "explanation": "「電池のライター」は意味が通らない。電池はライターの種類を表さない。"}, {"text": "小包", "is_correct": false, "explanation": "「小包のライター」は成り立たず、文の意味にも合わない。"}, {"text": "読書", "is_correct": false, "explanation": "「読書のライター」は意味が通らず、ライターの種類を表さない。"}], "explanations": {"使い捨て": "「使い捨てのライター」は一度使って捨てるライター。安くて、すぐ捨てられるという文脈に合う。", "電池": "「電池のライター」は意味が通らない。電池はライターの種類を表さない。", "小包": "「小包のライター」は成り立たず、文の意味にも合わない。", "読書": "「読書のライター」は意味が通らず、ライターの種類を表さない。"}, "sentence_index": 6, "correct_answer": "使い捨て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箸は使い捨てなので、洗って何度も使えます。", "explanation": "〈繰り返し使える〉の意味で使われている。使い捨ては一度使って捨てることなので、洗って何度も使う話とは合わない。"}, {"text": "この箸は使い捨てなので、一生使い続けるつもりだ。", "explanation": "〈長く使い続ける〉の意味で使われている。使い捨ては長く使わない前提の語なので、使い続ける話には合わない。"}, {"text": "この箸は使い捨てなので、来年まで買い足さなくてよい。", "explanation": "〈長持ちする〉の意味で使われている。使い捨ては一回で消費される前提なので、長持ちする話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "キャンプには使い捨てに皿を使うと楽です。", "corrected_sentence": "キャンプには使い捨ての皿を使うと楽です。", "error_description": "「使い捨て」の後ろで名詞を修飾するときは「の」が必要。「に」は「使い捨てにする」の形でしか使えないため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38931, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使い捨てを傘は、風が強いとすぐ壊れてしまいます。", "corrected_sentence": "使い捨ての傘は、風が強いとすぐ壊れてしまいます。", "error_description": "「使い捨て」が後ろの「傘」を修飾するときは「の」が必要。「を」は動詞の目的語に付くので、ここでは誤り。正しくは「使い捨ての傘」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38932, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「配布は」の形で、配布を主題として「午前十時から始まる」と説明する。文中の「配布は」に合う。"}, {"text": "を", "is_correct": false, "explanation": "「配布を、午前十時から始まります」は目的語になり、始まるという主題の説明にならない。"}, {"text": "に", "is_correct": false, "explanation": "「配布に始まります」は方向や時点の関係が不自然で、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「配布から、午前十時から始まります」では意味が重複して不自然。"}], "correct_answer": "は", "explanations": {"は": "「配布は」の形で、配布を主題として「午前十時から始まる」と説明する。文中の「配布は」に合う。", "を": "「配布を、午前十時から始まります」は目的語になり、始まるという主題の説明にならない。", "に": "「配布に始まります」は方向や時点の関係が不自然で、文が成り立たない。", "から": "「から」は起点を表すので、「配布から、午前十時から始まります」では意味が重複して不自然。"}, "error_tags": {"を": "object", "に": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38932, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「配布を始めた」の形で、配布を始める対象を表す。文中の「毛布の配布を始めた」に合う。"}, {"text": "が", "is_correct": false, "explanation": "「配布が始めた」は主語になるが、始める動作の対象としては文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「配布に始めた」は方向や時点を表すが、始める対象を表せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「配布と始めた」は並列の形で、動詞「始めた」の対象にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「配布を始めた」の形で、配布を始める対象を表す。文中の「毛布の配布を始めた」に合う。", "が": "「配布が始めた」は主語になるが、始める動作の対象としては文が成り立たない。", "に": "「配布に始めた」は方向や時点を表すが、始める対象を表せず不自然。", "と": "「配布と始めた」は並列の形で、動詞「始めた」の対象にならず不自然。"}, "error_tags": {"が": "subject", "に": "direction", "と": "pairing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38932, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "チラシや品物などを、多くの人に配って渡すこと。", "primary_collocate": null, "pronunciation": "はいふ", "ipa": "haiɸɯ", "syllable_count": 3, "sentences": [{"text": "駅の前で、新しい店のチラシの配布が行われていた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "えきのまえで、あたらしいみせのチラシのはいふがおこなわれていた。", "sentence_source": "generated"}, {"text": "無料の傘の配布は、午前十時から始まります。", "target_word": "配布", "complexity_tier": "T3", "furigana": "むりょうのかさのはいふは、ごぜんじゅうじからはじまります。", "sentence_source": "generated"}, {"text": "先生は、プリントの配布を係の生徒にたのんだ。", "target_word": "配布", "complexity_tier": "T3", "furigana": "せんせいは、プリントのはいふをかかりのせいとにたのんだ。", "sentence_source": "generated"}, {"text": "配布された地図を見ながら、公園を歩いた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "はいふされたちずをみながら、こうえんをあるいた。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、チラシの配布は中止になった。", "target_word": "配布", "complexity_tier": "T3", "furigana": "あめがふってきたので、チラシのはいふはちゅうしになった。", "sentence_source": "generated"}, {"text": "マスクの配布には、たくさんの人が並んだ。", "target_word": "配布", "complexity_tier": "T3", "furigana": "マスクのはいふには、たくさんのひとがならんだ。", "sentence_source": "generated"}, {"text": "配布の仕事は、朝早く起きなければならない。", "target_word": "配布", "complexity_tier": "T3", "furigana": "はいふのしごとは、あさはやくおきなければならない。", "sentence_source": "generated"}, {"text": "地震のあと、市役所は毛布の配布を始めた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "じしんのあと、しやくしょはもうふのはいふをはじめた。", "sentence_source": "generated"}, {"text": "ティッシュの配布をしている人から、一つもらった。", "target_word": "配布", "complexity_tier": "T3", "furigana": "ティッシュのはいふをしているひとから、ひとつもらった。", "sentence_source": "generated"}, {"text": "お祭りの日に、子どもたちへお菓子の配布があった。", "target_word": "配布", "complexity_tier": "T3", "furigana": "おまつりのひに、こどもたちへおかしのはいふがあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配布", "label": "基本形"}, {"form": "配布する", "label": "サ変動詞形"}, {"form": "配布された", "label": "受身過去形"}], "register": "標準", "sense_fingerprint": "チラシや品物を人に配って渡すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38932, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配布", "is_correct": true, "explanation": "「チラシの配布」は、チラシを多くの人に配ること。駅前で行われていたという文脈に合う。"}, {"text": "解体", "is_correct": false, "explanation": "「チラシの解体」は意味が通らない。解体はチラシを配る行為を表さない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「チラシの洗濯」は成り立たず、駅前で行われる活動の説明にならない。"}, {"text": "乾燥", "is_correct": false, "explanation": "「チラシの乾燥」は意味が通らず、配る行為を表さない。"}], "explanations": {"配布": "「チラシの配布」は、チラシを多くの人に配ること。駅前で行われていたという文脈に合う。", "解体": "「チラシの解体」は意味が通らない。解体はチラシを配る行為を表さない。", "洗濯": "「チラシの洗濯」は成り立たず、駅前で行われる活動の説明にならない。", "乾燥": "「チラシの乾燥」は意味が通らず、配る行為を表さない。"}, "sentence_index": 0, "correct_answer": "配布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の人が古い家具を寄付して、図書館の本棚を配布した。", "explanation": "ここは〈寄付〉に近い意味で使われている。配布は多くの人に物を配ることで、本棚を贈る話には合わない。"}, {"text": "ピザを配布して、三十分以内に届けます。", "explanation": "ここは〈配達〉の意味で使われている。配布は多くの人に配る行為で、一人の客に届ける話には合わない。"}, {"text": "祖父は孫に小遣いを配布してくれた。", "explanation": "〈一人に渡す〉の意味で使われている。配布は多くの人に配ることなので、一人の孫に渡す話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38932, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配布", "is_correct": true, "explanation": "「配布の仕事」は物を多くの人に配る仕事。朝早く起きるという文脈に合う。"}, {"text": "水没", "is_correct": false, "explanation": "「水没の仕事」は意味が通らず、仕事の内容を表さない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火の仕事」は成り立たず、仕事の内容を説明できない。"}, {"text": "入浴", "is_correct": false, "explanation": "「入浴の仕事」は意味が通らず、仕事の内容を表さない。"}], "explanations": {"配布": "「配布の仕事」は物を多くの人に配る仕事。朝早く起きるという文脈に合う。", "水没": "「水没の仕事」は意味が通らず、仕事の内容を表さない。", "点火": "「点火の仕事」は成り立たず、仕事の内容を説明できない。", "入浴": "「入浴の仕事」は意味が通らず、仕事の内容を表さない。"}, "sentence_index": 6, "correct_answer": "配布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お祭りの日に、子どもたちはお菓子の配布を一人で食べた。", "explanation": "ここは〈食べ物そのもの〉の意味で使われている。配布は配る行為を表す語で、食べられるものを指さないので、食べる文には合わない。"}, {"text": "お祭りの日に、店はお菓子を一袋百円で配布した。", "explanation": "ここは〈販売〉の意味で使われている。配布は無料で配ることなので、一袋百円で代金を取る話には合わない。"}, {"text": "お祭りの日に、お菓子の配布は昨日届いた。", "explanation": "ここは〈届けられた品物〉の意味で使われている。配布は配る行為を表す語なので、届いた品物を指す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
