INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38933, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「配布は」の形で、配布を主題として「年齢の高い人から順に行われた」と説明する。文中の「配布は」に合う。"}, {"text": "を", "is_correct": false, "explanation": "「配布を、行われた」は目的語になり、行われたという主題の説明にならない。"}, {"text": "に", "is_correct": false, "explanation": "「配布に行われた」は方向や対象を表すが、行われるという主語の説明には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「配布へ行われた」は文の構造が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「配布は」の形で、配布を主題として「年齢の高い人から順に行われた」と説明する。文中の「配布は」に合う。", "を": "「配布を、行われた」は目的語になり、行われたという主題の説明にならない。", "に": "「配布に行われた」は方向や対象を表すが、行われるという主語の説明には合わない。", "へ": "「へ」は方向を表すので、「配布へ行われた」は文の構造が成り立たない。"}, "error_tags": {"を": "object", "に": "direction", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38933, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や情報などを、多くの人にわたすこと。", "primary_collocate": null, "pronunciation": "はいふ", "ipa": "haiɸɯ", "syllable_count": 3, "sentences": [{"text": "会議の資料は、前の日に全員へ配布します。", "target_word": "配布", "complexity_tier": "T3", "furigana": "かいぎのしりょうは、まえのひにぜんいんへはいふします。", "sentence_source": "generated"}, {"text": "このソフトは、インターネットで無料で配布されている。", "target_word": "配布", "complexity_tier": "T3", "furigana": "このソフトは、インターネットでむりょうではいふされている。", "sentence_source": "generated"}, {"text": "新聞の配布は、早朝に販売店の人が行う。", "target_word": "配布", "complexity_tier": "T3", "furigana": "しんぶんのはいふは、そうちょうにはんばいてんのひとがおこなう。", "sentence_source": "generated"}, {"text": "町は、災害の地図を全部の家に配布した。", "target_word": "配布", "complexity_tier": "T3", "furigana": "まちは、さいがいのちずをぜんぶのいえにはいふした。", "sentence_source": "generated"}, {"text": "資料の配布が遅れたので、会議の開始も遅れた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "しりょうのはいふがおくれたので、かいぎのかいしもおくれた。", "sentence_source": "generated"}, {"text": "アンケート用紙の配布と回収は、委員が担当します。", "target_word": "配布", "complexity_tier": "T3", "furigana": "アンケートようしのはいふとかいしゅうは、いいんがたんとうします。", "sentence_source": "generated"}, {"text": "動画の配布を始めたところ、見る人が急に増えた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "どうがのはいふをはじめたところ、みるひとがきゅうにふえた。", "sentence_source": "generated"}, {"text": "ワクチンの配布は、年齢の高い人から順に行われた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "ワクチンのはいふは、ねんれいのたかいひとからじゅんにおこなわれた。", "sentence_source": "generated"}, {"text": "学校では、新入生への教科書の配布が終わった。", "target_word": "配布", "complexity_tier": "T3", "furigana": "がっこうでは、しんにゅうせいへのきょうかしょのはいふがおわった。", "sentence_source": "generated"}, {"text": "配布するお知らせは、百枚コピーしておいた。", "target_word": "配布", "complexity_tier": "T3", "furigana": "はいふするおしらせは、ひゃくまいコピーしておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配布", "label": "基本形"}, {"form": "配布する", "label": "サ変動詞形"}, {"form": "配布された", "label": "受身過去形"}], "register": "標準", "sense_fingerprint": "資料・情報などを多数の人に行き渡らせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38933, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配布", "is_correct": true, "explanation": "「資料を配布します」は、資料を全員に配る意味。前の日に全員へ渡すという文脈に合う。"}, {"text": "集計", "is_correct": false, "explanation": "「集計します」は数を数えてまとめる意味で、全員に資料を渡す話には合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去します」は取り除く意味で、資料を全員に渡す文脈とは逆になる。"}, {"text": "整理", "is_correct": false, "explanation": "「整理します」は片付ける意味で、資料を全員に渡す行為を表さない。"}], "explanations": {"配布": "「資料を配布します」は、資料を全員に配る意味。前の日に全員へ渡すという文脈に合う。", "集計": "「集計します」は数を数えてまとめる意味で、全員に資料を渡す話には合わない。", "撤去": "「撤去します」は取り除く意味で、資料を全員に渡す文脈とは逆になる。", "整理": "「整理します」は片付ける意味で、資料を全員に渡す行為を表さない。"}, "sentence_index": 0, "correct_answer": "配布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町は、災害の地図を全部の家から配布して集めた。", "explanation": "ここは〈回収〉に近い意味で使われている。配布は家々に配る行為で、集める話とは逆になるので合わない。"}, {"text": "町は、災害の地図を全部の家に配布して、一週間だけ貸し出した。", "explanation": "ここは〈期限付きで貸す〉の意味で使われている。配布は相手に渡しきりにする行為なので、返す前提で貸す話には合わない。"}, {"text": "町は、災害の地図を全部の家に配布して、一枚三百円で売った。", "explanation": "ここは〈販売〉の意味で使われている。配布は無料で配る行為なので、代金を取って売る話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38933, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配布", "is_correct": true, "explanation": "「動画の配布を始めた」は、動画を多くの人に配り始める意味。見る人が増えたという文脈に合う。"}, {"text": "削除", "is_correct": false, "explanation": "「動画の削除を始めた」は消すことで、見る人が増える文脈と逆になる。"}, {"text": "乾燥", "is_correct": false, "explanation": "「動画の乾燥」は意味が通らず、見る人が増える文脈とも合わない。"}, {"text": "点検", "is_correct": false, "explanation": "「動画の点検を始めた」は確認作業で、見る人が急に増えたという結果とつながらない。"}], "explanations": {"配布": "「動画の配布を始めた」は、動画を多くの人に配り始める意味。見る人が増えたという文脈に合う。", "削除": "「動画の削除を始めた」は消すことで、見る人が増える文脈と逆になる。", "乾燥": "「動画の乾燥」は意味が通らず、見る人が増える文脈とも合わない。", "点検": "「動画の点検を始めた」は確認作業で、見る人が急に増えたという結果とつながらない。"}, "sentence_index": 6, "correct_answer": "配布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お礼の手紙を、先輩に配布した。", "explanation": "ここは〈送る〉の意味で使われている。配布は多くの人に配る行為で、一人の先輩に手紙を送る話には合わない。"}, {"text": "お知らせを配布して、一人で百枚書き上げた。", "explanation": "ここは〈作る〉の意味で使われている。配布は配る行為を表す語なので、一人で百枚書き上げる話には合わない。"}, {"text": "新入社員を、それぞれの部署に配布した。", "explanation": "ここは〈配属〉の意味で使われている。配布は物や情報を配ることで、人を部署に割り振る話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38933, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボランティアは、毛布の配布で担当した。", "corrected_sentence": "ボランティアは、毛布の配布を担当した。", "error_description": "「担当する」の対象は「を」で示す。「で」は手段を表すので、ここでは誤り。正しくは「毛布の配布を担当した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38933, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "動画は、無料で配布させていた。", "corrected_sentence": "動画は、無料で配布されていた。", "error_description": "「配布する」の受け身の形は「配布される」。「配布させる」は使役の形で、動画が誰かに配らせたという意味になるため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「話すことが禁止されている」で、禁止される行為を「が」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。禁止される行為は「が」で示すので、「話すことへ禁止されている」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "方向・相手の「に」。「話すことに禁止されている」は成り立たず、禁止される行為は「が」で示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「話すことの禁止されている」は述語として文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「話すことが禁止されている」で、禁止される行為を「が」で示す。", "へ": "方向の「へ」。禁止される行為は「が」で示すので、「話すことへ禁止されている」は成り立たない。", "に": "方向・相手の「に」。「話すことに禁止されている」は成り立たず、禁止される行為は「が」で示す。", "の": "連体修飾の「の」。「話すことの禁止されている」は述語として文が成り立たない。"}, "error_tags": {"に": "方向・相手（禁止の主語には使わない）", "の": "連体修飾（名詞句をつなぐだけで文が成り立たない）", "へ": "方向（禁止される行為の示し方として成り立たない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "許可", "is_correct": true, "explanation": "禁止の対義語。〈してもよいと認めること〉で、「走ることが禁止されている」の反対の意味になる。"}, {"text": "水泳", "is_correct": false, "explanation": "スポーツの一種で、禁止と意味が対立する関係にない。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩く行為の名詞で、禁止の反対語としては成り立たない。"}, {"text": "掃除", "is_correct": false, "explanation": "場所をきれいにする行為の名詞で、禁止とは意味の対立関係がない。"}], "correct_answer": "許可", "explanations": {"許可": "禁止の対義語。〈してもよいと認めること〉で、「走ることが禁止されている」の反対の意味になる。", "水泳": "スポーツの一種で、禁止と意味が対立する関係にない。", "散歩": "外を歩く行為の名詞で、禁止の反対語としては成り立たない。", "掃除": "場所をきれいにする行為の名詞で、禁止とは意味の対立関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "許可", "is_correct": true, "explanation": "禁止の対義語。〈してもよいと認めること〉で、「魚をとることを禁止している」の反対の意味になる。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作る行為で、禁止と意味が対立する関係にない。"}, {"text": "登山", "is_correct": false, "explanation": "山に登るスポーツ・活動で、禁止の対義語ではない。"}, {"text": "買い物", "is_correct": false, "explanation": "商品を買う行為で、禁止とは意味の対立関係がない。"}], "correct_answer": "許可", "explanations": {"許可": "禁止の対義語。〈してもよいと認めること〉で、「魚をとることを禁止している」の反対の意味になる。", "料理": "食べ物を作る行為で、禁止と意味が対立する関係にない。", "登山": "山に登るスポーツ・活動で、禁止の対義語ではない。", "買い物": "商品を買う行為で、禁止とは意味の対立関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "してはいけないこと。やめてと決められたこと。", "primary_collocate": null, "pronunciation": "きんし", "ipa": "kiɴɕi", "syllable_count": 3, "sentences": [{"text": "この部屋で食べることは禁止です。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "このへやでたべることはきんしです。", "sentence_source": "generated"}, {"text": "図書館では大きな声で話すことが禁止されている。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "としょかんではおおきなこえではなすことがきんしされている。", "sentence_source": "generated"}, {"text": "ここは車を止めることが禁止されているので、別の場所を探した。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "ここはくるまをとめることがきんしされているので、べつのばしょをさがした。", "sentence_source": "generated"}, {"text": "プールでは、走ることが禁止されています。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "プールでは、はしることがきんしされています。", "sentence_source": "generated"}, {"text": "試験中の辞書の使用は禁止だと、先生が言った。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "しけんちゅうのじしょのしようはきんしだと、せんせいがいった。", "sentence_source": "generated"}, {"text": "母は私に夜遅く出かけることを禁止した。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "はははわたしによるおそくでかけることをきんしした。", "sentence_source": "generated"}, {"text": "禁止されていても、ルールを守らない人がいる。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "きんしされていても、ルールをまもらないひとがいる。", "sentence_source": "generated"}, {"text": "病院の中で携帯電話を使うのは禁止です。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "びょういんのなかでけいたいでんわをつかうのはきんしです。", "sentence_source": "generated"}, {"text": "写真をとることは禁止なので、絵だけ見て帰った。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "しゃしんをとることはきんしなので、えだけみてかえった。", "sentence_source": "generated"}, {"text": "この池では、魚をとることを禁止している。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "このいけでは、さかなをとることをきんししている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁止", "label": "基本形"}, {"form": "禁止する", "label": "サ変動詞形"}, {"form": "禁止された", "label": "受身過去形"}], "register": "標準", "sense_fingerprint": "場所やきまりで、してはいけないと決めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正解。「この部屋で食べることは禁止です」で、室内での飲食を認めないという意味になる。"}, {"text": "使用", "is_correct": false, "explanation": "「使うこと」の意味の名詞。「食べることは使用です」は意味が通らず、禁止の文脈に入らない。"}, {"text": "清掃", "is_correct": false, "explanation": "「掃除」の意味の名詞。食べる行為を述べる文には入らず、禁止の意味にならない。"}, {"text": "返却", "is_correct": false, "explanation": "「返すこと」の意味の名詞。食べることを述べる文には入らず、禁止の意味にならない。"}], "explanations": {"禁止": "正解。「この部屋で食べることは禁止です」で、室内での飲食を認めないという意味になる。", "使用": "「使うこと」の意味の名詞。「食べることは使用です」は意味が通らず、禁止の文脈に入らない。", "清掃": "「掃除」の意味の名詞。食べる行為を述べる文には入らず、禁止の意味にならない。", "返却": "「返すこと」の意味の名詞。食べることを述べる文には入らず、禁止の意味にならない。"}, "sentence_index": 0, "correct_answer": "禁止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "けんかしている二人を禁止した。", "explanation": "ここは〈制止〉の意味。禁止は行為を認めないことを言い、人を止めるなら制止を使う。"}, {"text": "先生は試験の合格を禁止した。", "explanation": "ここは〈合格〉の意味。禁止は行為を認めないことで、試験に受かることを指すなら合格を使う。"}, {"text": "彼は相続の権利を禁止した。", "explanation": "ここは〈放棄〉の意味。禁止は他人の行為を制限する語で、自分の権利を手放すなら放棄を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正解。「禁止されていても」で、決まりがあっても守られないという意味になる。"}, {"text": "規則", "is_correct": false, "explanation": "名詞だが「規則されていても」とは言えず、受身の形が成り立たないので入らない。"}, {"text": "罰則", "is_correct": false, "explanation": "名詞だが「罰則されていても」とは言えず、受身の形が成り立たないので入らない。"}, {"text": "条例", "is_correct": false, "explanation": "名詞だが「条例されていても」とは言えず、受身の形が成り立たないので入らない。"}], "explanations": {"禁止": "正解。「禁止されていても」で、決まりがあっても守られないという意味になる。", "規則": "名詞だが「規則されていても」とは言えず、受身の形が成り立たないので入らない。", "罰則": "名詞だが「罰則されていても」とは言えず、受身の形が成り立たないので入らない。", "条例": "名詞だが「条例されていても」とは言えず、受身の形が成り立たないので入らない。"}, "sentence_index": 6, "correct_answer": "禁止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作業員は、動いている機械の電源を禁止した。", "explanation": "ここは〈停止〉の意味。禁止は行為を認めないことで、動いている機械を止めるなら停止を使う。"}, {"text": "その店は入場者の数を禁止している。", "explanation": "ここは〈制限〉の意味。禁止は行為そのものを認めないことで、人数を一定に抑えるなら制限を使う。"}, {"text": "会議は次回の日程を禁止した。", "explanation": "ここは〈設定〉の意味。禁止は行為を認めないことで、日程を決めて定めるなら設定を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ここでは花火をすることに禁止されています。", "corrected_sentence": "ここでは花火をすることが禁止されています。", "error_description": "「禁止される」の主語は「が」で示す。「に」は誤り。正しくは「花火をすることが禁止されています」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38934, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ここでは大声を出すことは禁止しられています。", "corrected_sentence": "ここでは大声を出すことは禁止されています。", "error_description": "「禁止する」の受身は「禁止される」。「禁止しられる」は誤った形で、サ変動詞の受身は「される」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "許可", "is_correct": true, "explanation": "禁止の対義語。〈してもよいと認めること〉で、「副業は禁止されている」の反対の意味になる。"}, {"text": "通勤", "is_correct": false, "explanation": "職場へ通う行為の名詞で、禁止と意味が対立する関係にない。"}, {"text": "作業", "is_correct": false, "explanation": "仕事として手を動かす行為の名詞で、禁止の対義語ではない。"}, {"text": "報告", "is_correct": false, "explanation": "知らせる行為の名詞で、禁止とは意味の対立関係がない。"}], "correct_answer": "許可", "explanations": {"許可": "禁止の対義語。〈してもよいと認めること〉で、「副業は禁止されている」の反対の意味になる。", "通勤": "職場へ通う行為の名詞で、禁止と意味が対立する関係にない。", "作業": "仕事として手を動かす行為の名詞で、禁止の対義語ではない。", "報告": "知らせる行為の名詞で、禁止とは意味の対立関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「輸入を禁止した」の「を」。禁止する行為の対象を示すので正しい。"}, {"text": "の", "is_correct": false, "explanation": "「輸入の禁止した」は文が成り立たず、「禁止した」の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、禁止の対象を示す形としては合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、禁止の対象を示せず文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「輸入を禁止した」の「を」。禁止する行為の対象を示すので正しい。", "の": "「輸入の禁止した」は文が成り立たず、「禁止した」の目的語を示せない。", "へ": "「へ」は方向を表すので、禁止の対象を示す形としては合わない。", "から": "「から」は起点を表すので、禁止の対象を示せず文に合わない。"}, "error_tags": {"の": "連体修飾（「輸入の禁止した」は文が成り立たない）", "へ": "方向（禁止の対象は「を」で示す）", "から": "起点（禁止の対象を示せない）"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "許可", "is_correct": true, "explanation": "禁止の対義語。〈してもよいと認めること〉で、「道路のごみが減った決まり」の反対の意味になる。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作る行為で、禁止と意味が対立する関係にない。"}, {"text": "登山", "is_correct": false, "explanation": "山に登るスポーツ・活動で、禁止の対義語ではない。"}, {"text": "買い物", "is_correct": false, "explanation": "商品を買う行為で、禁止とは意味の対立関係がない。"}], "correct_answer": "許可", "explanations": {"許可": "禁止の対義語。〈してもよいと認めること〉で、「道路のごみが減った決まり」の反対の意味になる。", "料理": "食べ物を作る行為で、禁止と意味が対立する関係にない。", "登山": "山に登るスポーツ・活動で、禁止の対義語ではない。", "買い物": "商品を買う行為で、禁止とは意味の対立関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "法律や規則などで、ある行為をすることを認めないこと。", "primary_collocate": null, "pronunciation": "きんし", "ipa": "kiɴɕi", "syllable_count": 3, "sentences": [{"text": "日本では、二十歳未満の人の飲酒は法律で禁止されている。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "にほんでは、はたちみまんのひとのいんしゅはほうりつできんしされている。", "sentence_source": "generated"}, {"text": "この地域では、ドローンを飛ばすことが条例で禁止された。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "このちいきでは、ドローンをとばすことがじょうれいできんしされた。", "sentence_source": "generated"}, {"text": "政府は、その薬の販売を禁止する決定をした。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "せいふは、そのくすりのはんばいをきんしするけっていをした。", "sentence_source": "generated"}, {"text": "会社の規則で、社員の副業は禁止されている。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "かいしゃのきそくで、しゃいんのふくぎょうはきんしされている。", "sentence_source": "generated"}, {"text": "動物の売買を禁止する法律が、来年から施行される。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "どうぶつのばいばいをきんしするほうりつが、らいねんからしこうされる。", "sentence_source": "generated"}, {"text": "運転中のスマートフォンの使用は、法律で禁止です。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "うんてんちゅうのスマートフォンのしようは、ほうりつできんしです。", "sentence_source": "generated"}, {"text": "スポーツ大会では、薬を使うことが禁止されている。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "スポーツたいかいでは、くすりをつかうことがきんしされている。", "sentence_source": "generated"}, {"text": "国は、危険な物質の輸入を禁止した。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "くには、きけんなぶっしつのゆにゅうをきんしした。", "sentence_source": "generated"}, {"text": "火の使用が禁止になった山では、バーベキューもできない。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "ひのしようがきんしになったやまでは、バーベキューもできない。", "sentence_source": "generated"}, {"text": "禁止の決まりができてから、道路のごみが減った。", "target_word": "禁止", "complexity_tier": "T3", "furigana": "きんしのきまりができてから、どうろのごみがへった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁止", "label": "基本形"}, {"form": "禁止する", "label": "サ変動詞形"}, {"form": "禁止された", "label": "受身過去形"}], "register": "標準", "sense_fingerprint": "法律・規則で行為を認めないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正解。「法律で禁止されている」で、法律が行為を認めないという意味になる。"}, {"text": "罰金", "is_correct": false, "explanation": "「免許」は許可証の名詞。「法律で免許されている」は「許可されている」の意味になり、禁止の文脈に入らない。"}, {"text": "免許", "is_correct": false, "explanation": "許可証の名詞。「法律で免許されている」とは言えず、禁止の意味にならない。"}, {"text": "義務", "is_correct": false, "explanation": "しなければならないことの名詞。「法律で義務されている」とは言えず、禁止の意味にならない。"}], "explanations": {"禁止": "正解。「法律で禁止されている」で、法律が行為を認めないという意味になる。", "罰金": "「免許」は許可証の名詞。「法律で免許されている」は「許可されている」の意味になり、禁止の文脈に入らない。", "免許": "許可証の名詞。「法律で免許されている」とは言えず、禁止の意味にならない。", "義務": "しなければならないことの名詞。「法律で義務されている」とは言えず、禁止の意味にならない。"}, "sentence_index": 0, "correct_answer": "禁止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は故郷に校舎を禁止した。", "explanation": "ここは〈寄付〉の意味。禁止は行為を認めないことで、建物を贈るなら寄付を使う。"}, {"text": "天気を禁止した。", "explanation": "ここは〈記録〉の意味。禁止は行為を認める語ではなく、天気を書き残すなら記録を使う。"}, {"text": "ゴミを禁止した。", "explanation": "ここは〈撤去〉の意味。禁止は行為を認めない語で、ゴミを取り除くなら撤去を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正解。「使うことが禁止されている」で、薬の使用を認めないという意味になる。"}, {"text": "通路", "is_correct": false, "explanation": "場所を指す名詞。「使うことが通路されている」とは言えず、受身として成り立たない。"}, {"text": "名簿", "is_correct": false, "explanation": "記録の名詞。「使うことが名簿されている」とは言えず、禁止の意味にならない。"}, {"text": "看板", "is_correct": false, "explanation": "掲示物の名詞。「使うことが看板されている」とは言えず、禁止の意味にならない。"}], "explanations": {"禁止": "正解。「使うことが禁止されている」で、薬の使用を認めないという意味になる。", "通路": "場所を指す名詞。「使うことが通路されている」とは言えず、受身として成り立たない。", "名簿": "記録の名詞。「使うことが名簿されている」とは言えず、禁止の意味にならない。", "看板": "掲示物の名詞。「使うことが看板されている」とは言えず、禁止の意味にならない。"}, "sentence_index": 6, "correct_answer": "禁止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "価格を禁止している。", "explanation": "ここは〈規制〉の意味。禁止は行為そのものを認めないことで、価格を一定の範囲に抑えるなら規制を使う。"}, {"text": "家族は母の誕生日を禁止した。", "explanation": "ここは〈祝う〉の意味。禁止は行為を認めないことで、喜んで祝うなら祝うを使う。"}, {"text": "その問題を禁止した。", "explanation": "ここは〈解消〉の意味。禁止は行為を認めない語で、問題をなくすなら解消を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "入口に禁止な張り紙がある。", "corrected_sentence": "入口に禁止の張り紙がある。", "error_description": "名詞「禁止」が後ろの名詞を修飾するには「の」を使う（禁止の張り紙）。「な」は形容動詞の語尾で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38935, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校では、ゲームを持ち込むことは禁止しられている。", "corrected_sentence": "学校では、ゲームを持ち込むことは禁止されている。", "error_description": "サ変動詞「禁止する」の受身は「禁止される」。「禁止しられる」は誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「傘を持参しなかった」で、持って行かなかった物として傘を示す。"}, {"text": "に", "is_correct": false, "explanation": "方向・相手の「に」。「傘に持参しなかった」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「傘が持参しなかった」は主語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「傘と持参しなかった」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「傘を持参しなかった」で、持って行かなかった物として傘を示す。", "に": "方向・相手の「に」。「傘に持参しなかった」は成り立たない。", "が": "主語の「が」。「傘が持参しなかった」は主語として不自然。", "と": "並列の「と」。「傘と持参しなかった」は意味が通らない。"}, "error_tags": {"に": "方向・相手（「傘に持参しなかった」は成り立たない）", "が": "主語（「傘が持参しなかった」は主語として不自然）", "と": "並列（「傘と持参しなかった」は意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「水筒を持参した」で、持って行った物として水筒を示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「水筒の持参した」は名詞を修飾するだけで、述語として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。持参の対象は「を」で示すため、「水筒へ持参した」は誤り。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる意味になり、持参する物を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「水筒を持参した」で、持って行った物として水筒を示す。", "の": "連体修飾の「の」。「水筒の持参した」は名詞を修飾するだけで、述語として文が成り立たない。", "へ": "方向の「へ」。持参の対象は「を」で示すため、「水筒へ持参した」は誤り。", "より": "比較の「より」。比べる意味になり、持参する物を示せない。"}, "error_tags": {"の": "連体修飾（「水筒の持参した」は文が成り立たない）", "へ": "方向（持参の対象は「を」で示す）", "より": "比較（比べる意味になり、持参とは結びつかない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分で何かを持って行くこと。", "primary_collocate": null, "pronunciation": "じさん", "ipa": "dʑisaɴ", "syllable_count": 3, "sentences": [{"text": "遠足にはお弁当を持参してください。", "target_word": "持参", "complexity_tier": "T3", "furigana": "えんそくにはおべんとうをじさんしてください。", "sentence_source": "generated"}, {"text": "傘を持参しなかったので、帰りに雨でぬれてしまった。", "target_word": "持参", "complexity_tier": "T3", "furigana": "かさをじさんしなかったので、かえりにあめでぬれてしまった。", "sentence_source": "generated"}, {"text": "プールには、水着とタオルの持参が必要です。", "target_word": "持参", "complexity_tier": "T3", "furigana": "プールには、みずぎとタオルのじさんがひつようです。", "sentence_source": "generated"}, {"text": "会議には、自分のノートパソコンを持参する決まりだ。", "target_word": "持参", "complexity_tier": "T3", "furigana": "かいぎには、じぶんのノートパソコンをじさんするきまりだ。", "sentence_source": "generated"}, {"text": "買い物のときは、袋を持参すると少し安くなる。", "target_word": "持参", "complexity_tier": "T3", "furigana": "かいもののときは、ふくろをじさんするとすこしやすくなる。", "sentence_source": "generated"}, {"text": "筆記用具は各自で持参することになっている。", "target_word": "持参", "complexity_tier": "T3", "furigana": "ひっきようぐはかくじでじさんすることになっている。", "sentence_source": "generated"}, {"text": "友達の家へ、お土産を持参して行った。", "target_word": "持参", "complexity_tier": "T3", "furigana": "ともだちのいえへ、おみやげをじさんしていった。", "sentence_source": "generated"}, {"text": "お茶は店にないので、水筒を持参した。", "target_word": "持参", "complexity_tier": "T3", "furigana": "おちゃはみせにないので、すいとうをじさんした。", "sentence_source": "generated"}, {"text": "持参した地図を広げて、道を調べた。", "target_word": "持参", "complexity_tier": "T3", "furigana": "じさんしたちずをひろげて、みちをしらべた。", "sentence_source": "generated"}, {"text": "パーティーに飲み物を持参する人が多かった。", "target_word": "持参", "complexity_tier": "T3", "furigana": "パーティーにのみものをじさんするひとがおおかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "持参", "label": "基本形"}, {"form": "持参する", "label": "サ変動詞形"}, {"form": "持参した", "label": "過去形"}], "register": "標準", "sense_fingerprint": "自分の物を自分で持って行くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持参", "is_correct": true, "explanation": "正解。「お弁当を持参してください」で、自分で持ってくることを指示する。"}, {"text": "欠席", "is_correct": false, "explanation": "行事を休むことの名詞。「お弁当を欠席してください」は意味が通らない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で知らせる行為の名詞。「お弁当を放送してください」は意味が通らない。"}, {"text": "乾杯", "is_correct": false, "explanation": "杯を上げて祝う行為の名詞。「お弁当を乾杯してください」は意味が通らない。"}], "explanations": {"持参": "正解。「お弁当を持参してください」で、自分で持ってくることを指示する。", "欠席": "行事を休むことの名詞。「お弁当を欠席してください」は意味が通らない。", "放送": "電波で知らせる行為の名詞。「お弁当を放送してください」は意味が通らない。", "乾杯": "杯を上げて祝う行為の名詞。「お弁当を乾杯してください」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "持参"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅館を持参した。", "explanation": "ここは〈手配〉の意味。持参は自分の物を持って行くことで、宿を予約して整えるなら手配を使う。"}, {"text": "友人を持参した。", "explanation": "ここは〈同伴〉の意味。持参は物を持って行くことで、人と一緒に行くなら同伴を使う。"}, {"text": "英単語を持参した。", "explanation": "ここは〈暗記〉の意味。持参は物を運ぶことで、言葉を覚えるなら暗記を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持参", "is_correct": true, "explanation": "正解。「お土産を持参して行った」で、自分で持って行ったという意味になる。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作る行為の名詞。「お土産を作曲して行った」は意味が通らない。"}, {"text": "解説", "is_correct": false, "explanation": "説明する行為の名詞。「お土産を解説して行った」は意味が通らない。"}, {"text": "改札", "is_correct": false, "explanation": "切符を確認する場所・行為の名詞。「お土産を改札して行った」は意味が通らない。"}], "explanations": {"持参": "正解。「お土産を持参して行った」で、自分で持って行ったという意味になる。", "作曲": "曲を作る行為の名詞。「お土産を作曲して行った」は意味が通らない。", "解説": "説明する行為の名詞。「お土産を解説して行った」は意味が通らない。", "改札": "切符を確認する場所・行為の名詞。「お土産を改札して行った」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "持参"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社員を持参した。", "explanation": "ここは〈解雇〉の意味。持参は物を持って行くことで、雇用をやめるなら解雇を使う。"}, {"text": "会話を持参した。", "explanation": "ここは〈通訳〉の意味。持参は物を運ぶことで、言葉を別の言語に置き換えるなら通訳を使う。"}, {"text": "自分の行いを持参した。", "explanation": "ここは〈反省〉の意味。持参は物を持って行くことで、自分の行動を振り返るなら反省を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宿題のプリントに持参してください。", "corrected_sentence": "宿題のプリントを持参してください。", "error_description": "「持参する」の目的語は「を」で示す。「に」は誤り。正しくは「プリントを持参してください」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38936, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "かばんを持参しで、図書館へ行った。", "corrected_sentence": "かばんを持参して、図書館へ行った。", "error_description": "「持参して」の「て」は連用形の接続。「しで」は濁音化した誤り。正しくは「持参して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「保険証を持参しないと」で、持って行かない物として保険証を示す。"}, {"text": "に", "is_correct": false, "explanation": "方向・相手の「に」。「保険証に持参しない」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「保険証が持参しない」は主語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「保険証と持参しない」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「保険証を持参しないと」で、持って行かない物として保険証を示す。", "に": "方向・相手の「に」。「保険証に持参しない」は成り立たない。", "が": "主語の「が」。「保険証が持参しない」は主語として不自然。", "と": "並列の「と」。「保険証と持参しない」は意味が通らない。"}, "error_tags": {"に": "方向・相手（「保険証に持参しない」は成り立たない）", "が": "主語（「保険証が持参しない」は主語として不自然）", "と": "並列（「保険証と持参しない」は意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要な物を自分で用意して、どこかへ持って行くこと。", "primary_collocate": null, "pronunciation": "じさん", "ipa": "dʑisaɴ", "syllable_count": 3, "sentences": [{"text": "入学式には、上ばきを用意して持参してください。", "target_word": "持参", "complexity_tier": "T3", "furigana": "にゅうがくしきには、うわばきをよういしてじさんしてください。", "sentence_source": "generated"}, {"text": "受付で保険証を持参しないと、診察が受けられません。", "target_word": "持参", "complexity_tier": "T3", "furigana": "うけつけでほけんしょうをじさんしないと、しんさつがうけられません。", "sentence_source": "generated"}, {"text": "講習会では、ペンと辞書を持参するよう言われた。", "target_word": "持参", "complexity_tier": "T3", "furigana": "こうしゅうかいでは、ペンとじしょをじさんするようわれた。", "sentence_source": "generated"}, {"text": "キャンプ場では、寝袋は持参しなければならない。", "target_word": "持参", "complexity_tier": "T3", "furigana": "キャンプじょうでは、ねぶくろはじさんしなければならない。", "sentence_source": "generated"}, {"text": "面接の日、必要な書類を忘れずに持参した。", "target_word": "持参", "complexity_tier": "T3", "furigana": "めんせつのひ、ひつようなしょるいをわすれずにじさんした。", "sentence_source": "generated"}, {"text": "印鑑を持参するのを忘れて、家へ取りに戻った。", "target_word": "持参", "complexity_tier": "T3", "furigana": "いんかんをじさんするのをわすれて、いえへとりにもどった。", "sentence_source": "generated"}, {"text": "この教室では、飲み物の持参は自由です。", "target_word": "持参", "complexity_tier": "T3", "furigana": "このきょうしつでは、のみもののじさんはじゆうです。", "sentence_source": "generated"}, {"text": "料理教室には、エプロンを必ず持参してください。", "target_word": "持参", "complexity_tier": "T3", "furigana": "りょうりきょうしつには、エプロンをかならずじさんしてください。", "sentence_source": "generated"}, {"text": "お客さんは、自分でお皿を持参して、店で料理を入れてもらう。", "target_word": "持参", "complexity_tier": "T3", "furigana": "おきゃくさんは、じぶんでおさらをじさんして、みせでりょうりをいれてもらう。", "sentence_source": "generated"}, {"text": "試験のとき、時計を持参する人も多い。", "target_word": "持参", "complexity_tier": "T3", "furigana": "しけんのとき、とけいをじさんするひともおおい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "持参", "label": "基本形"}, {"form": "持参する", "label": "サ変動詞形"}, {"form": "持参した", "label": "過去形"}], "register": "標準", "sense_fingerprint": "必要な物を準備して目的地へ持って行くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持参", "is_correct": true, "explanation": "正解。「上ばきを用意して持参してください」で、用意したものを持ってくることを指示する。"}, {"text": "欠席", "is_correct": false, "explanation": "行事を休むことの名詞。「用意して欠席してください」は意味が通らない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で知らせる行為の名詞。「用意して放送してください」は意味が通らない。"}, {"text": "乾杯", "is_correct": false, "explanation": "杯を上げて祝う行為の名詞。「用意して乾杯してください」は意味が通らない。"}], "explanations": {"持参": "正解。「上ばきを用意して持参してください」で、用意したものを持ってくることを指示する。", "欠席": "行事を休むことの名詞。「用意して欠席してください」は意味が通らない。", "放送": "電波で知らせる行為の名詞。「用意して放送してください」は意味が通らない。", "乾杯": "杯を上げて祝う行為の名詞。「用意して乾杯してください」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "持参"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車に持参した。", "explanation": "ここは〈乗車〉の意味。持参は物を持って行くことで、電車に乗り込むなら乗車を使う。"}, {"text": "新郎新婦を持参した。", "explanation": "ここは〈祝福〉の意味。持参は物を持って行くことで、相手の門出を喜び祝うなら祝福を使う。"}, {"text": "毎朝、グラウンドを持参した。", "explanation": "ここは〈練習〉の意味。持参は物を持って行くことで、体を鍛えるなら練習を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持参", "is_correct": true, "explanation": "正解。「飲み物の持参は自由です」で、飲み物を自分で持ってくることは任意だという意味になる。"}, {"text": "解説", "is_correct": false, "explanation": "説明する行為の名詞。「飲み物の解説は自由です」は意味が通らない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作る行為の名詞。「飲み物の作曲は自由です」は意味が通らない。"}, {"text": "改札", "is_correct": false, "explanation": "切符を確認する場所・行為の名詞。「飲み物の改札は自由です」は意味が通らない。"}], "explanations": {"持参": "正解。「飲み物の持参は自由です」で、飲み物を自分で持ってくることは任意だという意味になる。", "解説": "説明する行為の名詞。「飲み物の解説は自由です」は意味が通らない。", "作曲": "曲を作る行為の名詞。「飲み物の作曲は自由です」は意味が通らない。", "改札": "切符を確認する場所・行為の名詞。「飲み物の改札は自由です」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "持参"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋を持参した。", "explanation": "ここは〈装飾〉の意味。持参は物を持って行くことで、場所を飾るなら装飾を使う。"}, {"text": "迷惑を持参した。", "explanation": "ここは〈謝罪〉の意味。持参は物を運ぶことで、詫びの気持ちを伝えるなら謝罪を使う。"}, {"text": "先生の恩を持参した。", "explanation": "ここは〈感謝〉の意味。持参は物を持って行くことで、礼を述べて気持ちを表すなら感謝を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お守りに持参しておくと安心だ。", "corrected_sentence": "お守りを持参しておくと安心だ。", "error_description": "「持参する」の目的語は「を」で示す。「に」は誤り。正しくは「お守りを持参しておくと安心だ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38937, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験会場には、受験票を持参ること。", "corrected_sentence": "試験会場には、受験票を持参すること。", "error_description": "「持参する」の名詞化は「持参すること」。「持参ること」は「す」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38940, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "道具・手段を表す『で』なので、ストローを使って水を飲む意味になり、ここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "『ストローへ』は方向を表すので、飲み物を飲む手段の意味にならず、文として不自然なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "『ストローに』は方向・着点を表すので、ストローを使って水を飲むという手段の意味にならず合わない。"}, {"text": "を", "is_correct": false, "explanation": "『ストローを』とすると『水を』と対象が二つ並び、ストローを道具として使う意味が出ないので合わない。"}], "correct_answer": "で", "explanations": {"で": "道具・手段を表す『で』なので、ストローを使って水を飲む意味になり、ここに入る。", "へ": "『ストローへ』は方向を表すので、飲み物を飲む手段の意味にならず、文として不自然なので合わない。", "に": "『ストローに』は方向・着点を表すので、ストローを使って水を飲むという手段の意味にならず合わない。", "を": "『ストローを』とすると『水を』と対象が二つ並び、ストローを道具として使う意味が出ないので合わない。"}, "error_tags": {"へ": "方向", "に": "方向・着点", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
