INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38940, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飲み物を飲むときに使う、細い筒のことです。", "primary_collocate": null, "pronunciation": "すとろー", "ipa": "sɯtoɾoː", "syllable_count": 4, "sentences": [{"text": "冷たいジュースをストローで飲みます。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "冷[つめ]たいジュースをストローで飲[の]みます。", "sentence_source": "generated"}, {"text": "赤ちゃんはまだコップが使えないので、ストローで水を飲みます。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんはまだコップが使[つか]えないので、ストローで水[みず]を飲[の]みます。", "sentence_source": "generated"}, {"text": "店員さんが、アイスコーヒーにストローを付けてくれました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "店員[てんいん]さんが、アイスコーヒーにストローを付[つ]けてくれました。", "sentence_source": "generated"}, {"text": "ストローが短すぎて、深いコップの底まで届きません。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローが短[みじか]すぎて、深[ふか]いコップの底[そこ]まで届[とど]きません。", "sentence_source": "generated"}, {"text": "弟はストローに息を吹き込んで、ジュースの中で泡を作りました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "弟[おとうと]はストローに息[いき]を吹[ふ]き込[こ]んで、ジュースの中[なか]で泡[あわ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "このカフェでは、紙のストローを使っています。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "このカフェでは、紙[かみ]のストローを使[つか]っています。", "sentence_source": "generated"}, {"text": "ストローの袋を破って、ミルクティーに差しました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローの袋[ふくろ]を破[やぶ]って、ミルクティーに差[さ]しました。", "sentence_source": "generated"}, {"text": "風邪で口が開けにくいので、ストローでスープを少しずつ飲みました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "風邪[かぜ]で口[くち]が開[あ]けにくいので、ストローでスープを少[すこ]しずつ飲[の]みました。", "sentence_source": "generated"}, {"text": "ストローを使うと、冷たい飲み物でも歯にしみにくくなります。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローを使[つか]うと、冷[つめ]たい飲[の]み物[もの]でも歯[は]にしみにくくなります。", "sentence_source": "generated"}, {"text": "ストローが曲がるタイプなので、寝たままでも飲めます。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローが曲[ま]がるタイプなので、寝[ね]たままでも飲[の]めます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ストロー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "飲み物を飲むための細い筒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38940, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ストロー", "is_correct": true, "explanation": "飲み物を飲むための細い筒なので、ここに入る。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は食材を切る刃物で、ジュースを飲むときには使わないので合わない。"}, {"text": "缶切り", "is_correct": false, "explanation": "缶切りは缶を開ける道具で、ジュースを飲むときには使わないので合わない。"}, {"text": "箸", "is_correct": false, "explanation": "箸は食べ物を挟む道具で、ジュースを飲むときには使わないので合わない。"}], "explanations": {"ストロー": "飲み物を飲むための細い筒なので、ここに入る。", "包丁": "包丁は食材を切る刃物で、ジュースを飲むときには使わないので合わない。", "缶切り": "缶切りは缶を開ける道具で、ジュースを飲むときには使わないので合わない。", "箸": "箸は食べ物を挟む道具で、ジュースを飲むときには使わないので合わない。"}, "sentence_index": 0, "correct_answer": "ストロー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラーメンの麺を、ストローで食べました。", "explanation": "ここは〈箸〉で麺を食べる場面。ストローは液体を吸う細い筒なので、麺を食べるのには合わない。"}, {"text": "氷を、ストローで砕きました。", "explanation": "ここは〈アイスピック〉で氷を砕く場面。ストローは飲み物用の細い筒で、氷を砕く道具ではないので合わない。"}, {"text": "汗をかいたので、ストローで顔をふきました。", "explanation": "ここは〈タオル〉で顔をふく場面。ストローは飲み物を吸う道具なので、顔をふくのには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38940, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ストロー", "is_correct": true, "explanation": "袋に入った細い飲み物用の筒なので、ここに入る。"}, {"text": "皿", "is_correct": false, "explanation": "皿は料理を盛る器で、ミルクティーに差すものではないので合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は料理用の器で、袋を破ってミルクティーに差すものではないので合わない。"}, {"text": "まな板", "is_correct": false, "explanation": "まな板は食材を切る台で、ミルクティーに差すものではないので合わない。"}], "explanations": {"ストロー": "袋に入った細い飲み物用の筒なので、ここに入る。", "皿": "皿は料理を盛る器で、ミルクティーに差すものではないので合わない。", "鍋": "鍋は料理用の器で、袋を破ってミルクティーに差すものではないので合わない。", "まな板": "まな板は食材を切る台で、ミルクティーに差すものではないので合わない。"}, "sentence_index": 6, "correct_answer": "ストロー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ベランダの掃除に、ストローで水をまきました。", "explanation": "ここは〈ホース〉の意味。ストローは飲み物を吸う細い筒で、大量の水をまく道具としては合わない。"}, {"text": "ケーキを食べたあと、ストローで歯の間を掃除しました。", "explanation": "ここは〈爪楊枝〉で歯の間をつつく場面。ストローは飲み物用の筒で、歯の掃除には使わないので合わない。"}, {"text": "布の穴に、ストローで糸を通しました。", "explanation": "ここは〈針〉で糸を通す場面。ストローは飲み物を吸う筒で、糸を通す道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38940, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お客さんは、ストローにアイスティーを飲みます。", "corrected_sentence": "お客さんは、ストローでアイスティーを飲みます。", "error_description": "飲む道具を表す『ストローで』が正しいのに『ストローに』と誤っている。『に』は方向・着点を表すので、飲み物を飲む手段としては使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38940, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝たままでも、曲がるストローで食べられます。", "corrected_sentence": "寝たままでも、曲がるストローで飲めます。", "error_description": "ストローと組み合わせる動詞が誤っている。ストローは飲み物を飲むための道具なので『飲める』が正しく、『食べられる』は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す『は』で、「細いストローは」の主題になるのでここに入る。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すので、「細いストローを」では主題にならず、「タピオカを」と重なって合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、主題の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列・共同を表すので、「細いストローと」では主題にならず合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す『は』で、「細いストローは」の主題になるのでここに入る。", "を": "『を』は目的語を示すので、「細いストローを」では主題にならず、「タピオカを」と重なって合わない。", "へ": "『へ』は方向を表すので、主題の位置には合わない。", "と": "『と』は並列・共同を表すので、「細いストローと」では主題にならず合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す『は』で、「使い終わったストローは」の主題になるのでここに入る。"}, {"text": "に", "is_correct": false, "explanation": "『に』は着点を表すので、主題にはならず、「ストローに」では文の成り立ちが変わって合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表すので、ここでは比較の意味がなく合わない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表すので、ここでは主題の役割にはならず合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す『は』で、「使い終わったストローは」の主題になるのでここに入る。", "に": "『に』は着点を表すので、主題にはならず、「ストローに」では文の成り立ちが変わって合わない。", "より": "『より』は比較を表すので、ここでは比較の意味がなく合わない。", "から": "『から』は起点を表すので、ここでは主題の役割にはならず合わない。"}, "error_tags": {"に": "方向・着点", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飲み物を吸い上げるために使われる細い管状の道具。", "primary_collocate": null, "pronunciation": "すとろー", "ipa": "sɯtoɾoː", "syllable_count": 4, "sentences": [{"text": "ストローで吸うと、ジュースが管の中を上がってきます。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローで吸[す]うと、ジュースが管[くだ]の中[なか]を上[あ]がってきます。", "sentence_source": "generated"}, {"text": "細いストローは、タピオカを吸うには向いていません。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "細[ほそ]いストローは、タピオカを吸[す]うには向[む]いていません。", "sentence_source": "generated"}, {"text": "太いストローを買ったので、タピオカドリンクが飲みやすくなりました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "太[ふと]いストローを買[か]ったので、タピオカドリンクが飲[の]みやすくなりました。", "sentence_source": "generated"}, {"text": "ストローをさしたまま、パックの牛乳を飲みました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローをさしたまま、パックの牛乳[ぎゅうにゅう]を飲[の]みました。", "sentence_source": "generated"}, {"text": "環境のために、プラスチックのストローをやめる店が増えています。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "環境[かんきょう]のために、プラスチックのストローをやめる店[みせ]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "ストローの先を指で押さえて、水を持ち上げる実験をしました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローの先[さき]を指[ゆび]で押[お]さえて、水[みず]を持[も]ち上[あ]げる実験[じっけん]をしました。", "sentence_source": "generated"}, {"text": "ストローが折れ曲がっていて、飲み物がうまく吸えません。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "ストローが折[お]れ曲[ま]がっていて、飲[の]み物[もの]がうまく吸[す]えません。", "sentence_source": "generated"}, {"text": "使い終わったストローは、燃えるごみの箱に捨ててください。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わったストローは、燃[も]えるごみの箱[はこ]に捨[す]ててください。", "sentence_source": "generated"}, {"text": "会計のとき、店員さんに「ストローはいりません」と伝えました。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "会計[かいけい]のとき、店員[てんいん]さんに「ストローはいりません」と伝[つた]えました。", "sentence_source": "generated"}, {"text": "竹で作ったストローは、洗って何度も使えます。", "target_word": "ストロー", "complexity_tier": "T3", "furigana": "竹[たけ]で作[つく]ったストローは、洗[あら]って何度[なんど]も使[つか]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ストロー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "飲み物を吸い上げる管状の道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ストロー", "is_correct": true, "explanation": "飲み物を吸い上げる管なので、ここに入る。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は料理器具で、吸って飲む道具ではないので合わない。"}, {"text": "栓", "is_correct": false, "explanation": "栓は瓶の口をふさぐもので、吸い上げる道具ではないので合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は料理を盛る器で、飲み物を吸い上げるものではないので合わない。"}], "explanations": {"ストロー": "飲み物を吸い上げる管なので、ここに入る。", "鍋": "鍋は料理器具で、吸って飲む道具ではないので合わない。", "栓": "栓は瓶の口をふさぐもので、吸い上げる道具ではないので合わない。", "皿": "皿は料理を盛る器で、飲み物を吸い上げるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "ストロー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪を、ストローで乾かしました。", "explanation": "ここは〈ドライヤー〉で髪を乾かす場面。ストローは飲み物を吸う管で、髪を乾かす道具ではないので合わない。"}, {"text": "ノートに、ストローで文字を書きました。", "explanation": "ここは〈ペン〉で文字を書く場面。ストローは飲み物用の管で、文字を書く道具ではないので合わない。"}, {"text": "パンを、ストローで切りました。", "explanation": "ここは〈ナイフ〉でパンを切る場面。ストローは飲み物を吸う管で、切る道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ストロー", "is_correct": true, "explanation": "飲み物を吸うための細い管なので、ここに入る。"}, {"text": "箸", "is_correct": false, "explanation": "箸は食べ物を挟む道具で、飲み物を吸う管ではないので合わない。"}, {"text": "缶切り", "is_correct": false, "explanation": "缶切りは缶を開ける道具で、飲み物を吸う管ではないので合わない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は食材を切る刃物で、飲み物を吸う管ではないので合わない。"}], "explanations": {"ストロー": "飲み物を吸うための細い管なので、ここに入る。", "箸": "箸は食べ物を挟む道具で、飲み物を吸う管ではないので合わない。", "缶切り": "缶切りは缶を開ける道具で、飲み物を吸う管ではないので合わない。", "包丁": "包丁は食材を切る刃物で、飲み物を吸う管ではないので合わない。"}, "sentence_index": 6, "correct_answer": "ストロー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "絵の具を、ストローから絞り出しました。", "explanation": "ここは〈チューブ〉から絵の具を絞り出す場面。ストローは飲み物用の細い筒で、絵の具を絞り出す容器ではないので合わない。"}, {"text": "おにぎりを、ストローで包みました。", "explanation": "ここは〈ラップ〉で包む場面。ストローは飲み物を吸う筒で、食べ物を包むものではないので合わない。"}, {"text": "書類を、ストローで留めました。", "explanation": "ここは〈ホッチキス〉で書類を留める場面。ストローは飲み物用の筒で、書類を留める道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "タピオカを吸うには、太いストローを向いています。", "corrected_sentence": "タピオカを吸うには、太いストローが向いています。", "error_description": "『向く』と結びつく格助詞が誤っている。正しくは『が』で、『を』は他動詞の目的語に使うので『向く』には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38941, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "竹のストローは、洗えば何度でも飲めます。", "corrected_sentence": "竹のストローは、洗えば何度でも使えます。", "error_description": "『ストロー』と組み合わせる動詞が誤っている。『使える』が正しく、『飲める』ではストローが飲まれる対象になってしまい意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「汁が」は「ついて」の主語。付着したものが草の汁であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。「つく」は自動詞なので「汁を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。ここでは汁が主語のため、「で」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「汁とついて」では付く対象の関係が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「汁が」は「ついて」の主語。付着したものが草の汁であることを示す。", "を": "「を」は他動詞の目的語を示す。「つく」は自動詞なので「汁を」は取らない。", "で": "「で」は場所や手段を示す。ここでは汁が主語のため、「で」では文が成り立たない。", "と": "「と」は相手や並列を示す。「汁とついて」では付く対象の関係が成り立たない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離れる", "is_correct": true, "explanation": "「付く」の対義語。付いた状態が解けて、くっついていないことを表す。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す動詞で、付着の反対の関係にはならない。"}, {"text": "進む", "is_correct": false, "explanation": "前へ移動する動詞で、付着と反対の関係にはならない。"}, {"text": "光る", "is_correct": false, "explanation": "発光を表す動詞で、付着と反対の関係にはならない。"}], "correct_answer": "離れる", "explanations": {"離れる": "「付く」の対義語。付いた状態が解けて、くっついていないことを表す。", "眠る": "睡眠を表す動詞で、付着の反対の関係にはならない。", "進む": "前へ移動する動詞で、付着と反対の関係にはならない。", "光る": "発光を表す動詞で、付着と反対の関係にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離れる", "is_correct": true, "explanation": "「付く」の対義語。接触や付着がなくなることを表す。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動詞で、付着の反対の関係にはならない。"}, {"text": "冷める", "is_correct": false, "explanation": "温度が下がる意味の動詞で、付着と反対の関係にはならない。"}, {"text": "呼ぶ", "is_correct": false, "explanation": "声をかける意味の動詞で、付着と反対の関係にはならない。"}], "correct_answer": "離れる", "explanations": {"離れる": "「付く」の対義語。接触や付着がなくなることを表す。", "歩く": "移動の動詞で、付着の反対の関係にはならない。", "冷める": "温度が下がる意味の動詞で、付着と反対の関係にはならない。", "呼ぶ": "声をかける意味の動詞で、付着と反対の関係にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが、別のものにくっつくこと。", "primary_collocate": null, "pronunciation": "つく", "ipa": "tsɯkɯ", "syllable_count": 2, "sentences": [{"text": "子どもの顔にご飯粒がついていた。", "target_word": "ついて", "complexity_tier": "T3", "furigana": "子[こ]どもの顔[かお]にご飯粒[はんつぶ]がついていた。", "sentence_source": "generated"}, {"text": "ズボンに草の汁がついて、なかなか落ちない。", "target_word": "ついて", "complexity_tier": "T3", "furigana": "ズボンに草[くさ]の汁[しる]がついて、なかなか落[お]ちない。", "sentence_source": "generated"}, {"text": "このシールは、紙にもガラスにもよくつく。", "target_word": "つく", "complexity_tier": "T3", "furigana": "このシールは、紙[かみ]にもガラスにもよくつく。", "sentence_source": "generated"}, {"text": "壁のペンキが手につきました。", "target_word": "つきました", "complexity_tier": "T3", "furigana": "壁[かべ]のペンキが手[て]につきました。", "sentence_source": "generated"}, {"text": "雨の日は、靴に泥がつきやすい。", "target_word": "つき", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、靴[くつ]に泥[どろ]がつきやすい。", "sentence_source": "generated"}, {"text": "磁石に砂鉄がたくさんついている。", "target_word": "ついている", "complexity_tier": "T3", "furigana": "磁石[じしゃく]に砂鉄[さてつ]がたくさんついている。", "sentence_source": "generated"}, {"text": "散歩のあと、足に砂がついたまま家に上がった。", "target_word": "ついた", "complexity_tier": "T3", "furigana": "散歩[さんぽ]のあと、足[あし]に砂[すな]がついたまま家[いえ]に上[あ]がった。", "sentence_source": "generated"}, {"text": "接着剤が弱くて、部品がつかなかった。", "target_word": "つかなかった", "complexity_tier": "T3", "furigana": "接着剤[せっちゃくざい]が弱[よわ]くて、部品[ぶひん]がつかなかった。", "sentence_source": "generated"}, {"text": "紙に指紋がつかないよう、端を持ってください。", "target_word": "つかない", "complexity_tier": "T3", "furigana": "紙[かみ]に指紋[しもん]がつかないよう、端[はし]を持[も]ってください。", "sentence_source": "generated"}, {"text": "机にお茶がつくと、すぐにしみになる。", "target_word": "つく", "complexity_tier": "T3", "furigana": "机[つくえ]にお茶[ちゃ]がつくと、すぐにしみになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つく", "label": "基本形"}, {"form": "つきます", "label": "丁寧形"}, {"form": "ついた", "label": "過去形"}, {"form": "つかない", "label": "否定形"}, {"form": "ついて", "label": "て形"}], "register": "標準", "sense_fingerprint": "あるものが別のものの表面にくっつく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 飯粒 (Zipf 1.72)','sentence 5 above tier T2: contains vocabulary far above tier T2: 砂鉄 (Zipf 2.28)']::text[], 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ついて", "is_correct": true, "explanation": "「ついていた」の「て形」。付いた状態が続いていたことを表し、「いた」に続く形として正しい。"}, {"text": "つく", "is_correct": false, "explanation": "基本形なので「いた」に直接続かず、「つくいた」は文法的に成り立たない。"}, {"text": "つきます", "is_correct": false, "explanation": "丁寧形で「いた」へは接続しない。「つきますいた」は成り立たず、この位置には入らない。"}, {"text": "つかない", "is_correct": false, "explanation": "否定形なので、ご飯粒が付いていたという内容と逆になり、「いた」にも続かない。"}], "explanations": {"ついて": "「ついていた」の「て形」。付いた状態が続いていたことを表し、「いた」に続く形として正しい。", "つく": "基本形なので「いた」に直接続かず、「つくいた」は文法的に成り立たない。", "つきます": "丁寧形で「いた」へは接続しない。「つきますいた」は成り立たず、この位置には入らない。", "つかない": "否定形なので、ご飯粒が付いていたという内容と逆になり、「いた」にも続かない。"}, "sentence_index": 0, "correct_answer": "ついて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で新しい企画に予算が付いて、準備が始まった。", "explanation": "ここは〈付く〉を「割り当てられる」の意味で使っている。「くっつく」の意味では、予算の割り当てには使わない。"}, {"text": "彼は最後まで迷ったが、結局は多数派に付いた。", "explanation": "ここは〈付く〉を「味方になる」の意味で使っている。「くっつく」の意味では、立場や味方の選択には使わない。"}, {"text": "その法案には、与党の強い支持が付いた。", "explanation": "ここは〈付く〉を「支持を得る」の意味で使っている。「くっつく」の意味では、支持や賛成には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ついた", "is_correct": true, "explanation": "「ついたまま」は付いた状態のままの意味で、「〜たまま」に続く過去形として正しい。"}, {"text": "つきます", "is_correct": false, "explanation": "丁寧形は「まま」に続かず、文が成り立たない。"}, {"text": "つき", "is_correct": false, "explanation": "連用形は「まま」に直接続かず、「つきまま」は不自然で成り立たない。"}, {"text": "つけた", "is_correct": false, "explanation": "他動詞「付ける」の形で、砂が主語になると文法的に合わない。"}], "explanations": {"ついた": "「ついたまま」は付いた状態のままの意味で、「〜たまま」に続く過去形として正しい。", "つきます": "丁寧形は「まま」に続かず、文が成り立たない。", "つき": "連用形は「まま」に直接続かず、「つきまま」は不自然で成り立たない。", "つけた": "他動詞「付ける」の形で、砂が主語になると文法的に合わない。"}, "sentence_index": 6, "correct_answer": "ついた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅に着いたら、連絡してください。", "explanation": "ここは「着く（到着する）」の意味。「付く」は物がくっつく意味なので、場所への到着には合わない。"}, {"text": "母は、入院した弟に付いて、一晩中病院にいた。", "explanation": "ここは〈付く〉を「付き添う」の意味で使っている。「くっつく」の意味では、人の看病や世話には使わない。"}, {"text": "子どもは、友だちに付いて遊びに行った。", "explanation": "ここは〈付く〉を「後について行く」の意味で使っている。「くっつく」の意味では、人について移動する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このテープは、どんな面をもよくつく。", "corrected_sentence": "このテープは、どんな面にもよくつく。", "error_description": "「つく」は自動詞で、接着する先は「に」で示す。「面を」は誤りで、正しくは「面にも」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ついて", "is_correct": true, "explanation": "「て形」。「ついて、」と後ろの「なかなか落ちない」へ続ける形で、ここでは正しい。"}, {"text": "つく", "is_correct": false, "explanation": "基本形で言い切りになり、「て」で接続する位置には合わない。"}, {"text": "つけた", "is_correct": false, "explanation": "他動詞「付ける」の過去形で、汁が主語の文では成り立たない。"}, {"text": "つかない", "is_correct": false, "explanation": "否定形で、汁が付いていないことになり、ズボンに付いたという状況と矛盾する。"}], "correct_form": "ついて", "base_form": "つく", "form_label": "て形", "sentence_index": 1, "explanations": {"ついて": "「て形」。「ついて、」と後ろの「なかなか落ちない」へ続ける形で、ここでは正しい。", "つく": "基本形で言い切りになり、「て」で接続する位置には合わない。", "つけた": "他動詞「付ける」の過去形で、汁が主語の文では成り立たない。", "つかない": "否定形で、汁が付いていないことになり、ズボンに付いたという状況と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38942, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泥が靴につくまま、部屋に入った。", "corrected_sentence": "泥が靴についたまま、部屋に入った。", "error_description": "「ついたまま」は「付いた状態のまま」の形。「つくまま」は「ついたまま」が正しく、過去の「た」が抜けている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "つかなかった", "is_correct": true, "explanation": "否定の過去形。付かなかったという出来事を表し、文末に合う。"}, {"text": "つきません", "is_correct": false, "explanation": "丁寧な否定形で、文末の普通体「つかなかった」とは文体が合わない。"}, {"text": "つかなくて", "is_correct": false, "explanation": "否定のて形で、文を言い切らず「〜て、」と続く形なので、ここで文を終えられない。"}, {"text": "つかなければ", "is_correct": false, "explanation": "仮定の条件形で、文を条件節にしてしまい、過去の事実を言い切る文に合わない。"}], "correct_form": "つかなかった", "base_form": "つく", "form_label": "否定の過去形", "sentence_index": 7, "explanations": {"つかなかった": "否定の過去形。付かなかったという出来事を表し、文末に合う。", "つきません": "丁寧な否定形で、文末の普通体「つかなかった」とは文体が合わない。", "つかなくて": "否定のて形で、文を言い切らず「〜て、」と続く形なので、ここで文を終えられない。", "つかなければ": "仮定の条件形で、文を条件節にしてしまい、過去の事実を言い切る文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離れる", "is_correct": true, "explanation": "「離れる」は物がくっついた状態から別れることを表し、「つく」と対義関係にある。"}, {"text": "歩く", "is_correct": false, "explanation": "歩くは移動の動作で、「つく」の対義語ではない。"}, {"text": "感じる", "is_correct": false, "explanation": "感じるは知覚の動詞で、「つく」の対義語ではない。"}, {"text": "選ぶ", "is_correct": false, "explanation": "選ぶは選択の動詞で、「つく」の対義語ではない。"}], "correct_answer": "離れる", "explanations": {"離れる": "「離れる」は物がくっついた状態から別れることを表し、「つく」と対義関係にある。", "歩く": "歩くは移動の動作で、「つく」の対義語ではない。", "感じる": "感じるは知覚の動詞で、「つく」の対義語ではない。", "選ぶ": "選ぶは選択の動詞で、「つく」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「葉っぱがついた」の「が」。付着する主体を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を表すため、「葉っぱとついた」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、付着の主体にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「葉っぱからついた」は付着の主体として不自然。"}], "correct_answer": "が", "explanations": {"が": "「葉っぱがついた」の「が」。付着する主体を示す。", "と": "「と」は並列や共同を表すため、「葉っぱとついた」は意味が通らない。", "より": "「より」は比較を表すので、付着の主体にはならない。", "から": "「から」は起点を示すため、「葉っぱからついた」は付着の主体として不自然。"}, "error_tags": {"と": "並列・共同", "より": "比較", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離れる", "is_correct": true, "explanation": "「離れる」は物がくっついた状態から別れることを表し、「つく」と対義関係にある。"}, {"text": "寝る", "is_correct": false, "explanation": "寝るは休む動作で、「つく」の対義語ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、「つく」の対義語ではない。"}, {"text": "話す", "is_correct": false, "explanation": "話すは言葉を発する動作で、「つく」の対義語ではない。"}], "correct_answer": "離れる", "explanations": {"離れる": "「離れる」は物がくっついた状態から別れることを表し、「つく」と対義関係にある。", "寝る": "寝るは休む動作で、「つく」の対義語ではない。", "洗う": "洗うは汚れを落とす動作で、「つく」の対義語ではない。", "話す": "話すは言葉を発する動作で、「つく」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物と物とが離れずに、くっついた状態になる。", "primary_collocate": null, "pronunciation": "つく", "ipa": "tsɯkɯ", "syllable_count": 2, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "ついて", "complexity_tier": "T3", "furigana": "革[かわ]の匂[にお]いが漂[ただよ]う暗闇[くらやみ]の奥底[おくそこ]で、長[なが]き眠[ねむ]りについていたそれを引[ひ]きずり出[だ]した瞬間[しゅんかん]、埃[ほこり]っぽい記憶[きおく]の粒子[りゅうし]が舞[ま]い上[あ]がる。", "sentence_source": "mined"}, {"text": "服に泥がついたので、すぐに洗った。", "target_word": "ついた", "complexity_tier": "T3", "furigana": "服[ふく]に泥[どろ]がついたので、すぐに洗[あら]った。", "sentence_source": "generated"}, {"text": "靴の裏にガムがついて、歩きにくかった。", "target_word": "ついて", "complexity_tier": "T3", "furigana": "靴[くつ]の裏[うら]にガムがついて、歩[ある]きにくかった。", "sentence_source": "generated"}, {"text": "手にインクがつかないように、手袋をはめる。", "target_word": "つかない", "complexity_tier": "T3", "furigana": "手[て]にインクがつかないように、手袋[てぶくろ]をはめる。", "sentence_source": "generated"}, {"text": "このテープは水に濡れても、壁にしっかりつく。", "target_word": "つく", "complexity_tier": "T3", "furigana": "このテープは水[みず]に濡[ぬ]れても、壁[かべ]にしっかりつく。", "sentence_source": "generated"}, {"text": "犬の毛がセーターにつくので、毎日ブラシをかける。", "target_word": "つく", "complexity_tier": "T3", "furigana": "犬[いぬ]の毛[け]がセーターにつくので、毎日[まいにち]ブラシをかける。", "sentence_source": "generated"}, {"text": "袖に糸くずがついているよ、と友達が教えてくれた。", "target_word": "ついている", "complexity_tier": "T3", "furigana": "袖[そで]に糸[いと]くずがついているよ、と友達[ともだち]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "髪に葉っぱがついたまま、彼は教室に入ってきた。", "target_word": "ついた", "complexity_tier": "T3", "furigana": "髪[かみ]に葉[は]っぱがついたまま、彼[かれ]は教室[きょうしつ]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "のりが弱いと、紙がうまくつかない。", "target_word": "つかない", "complexity_tier": "T3", "furigana": "のりが弱[よわ]いと、紙[かみ]がうまくつかない。", "sentence_source": "generated"}, {"text": "白いシャツにコーヒーがつきました。", "target_word": "つきました", "complexity_tier": "T3", "furigana": "白[しろ]いシャツにコーヒーがつきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つく", "label": "基本形"}, {"form": "つきます", "label": "丁寧形"}, {"form": "ついた", "label": "過去形"}, {"form": "つかない", "label": "否定形"}, {"form": "ついて", "label": "て形"}], "register": "標準", "sense_fingerprint": "汚れやものが表面に離れずくっつく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 奥底 (Zipf 3.21), 長き (Zipf 3.3), 引きずり出し (Zipf 2.55), 埃 (Zipf 3.54), 舞い上がる (Zipf 2.61)']::text[], 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ついて", "is_correct": true, "explanation": "「ついていた」の「て形」。付いた状態が続いていたことを表し、「いた」に続く形として正しい。"}, {"text": "つく", "is_correct": false, "explanation": "基本形なので「いた」に直接続かず、「つくいた」は文法的に成り立たない。"}, {"text": "つけて", "is_correct": false, "explanation": "他動詞「付ける」の形で、ガムが主語の文には合わない。「つけていた」は成り立たない。"}, {"text": "つきます", "is_correct": false, "explanation": "丁寧形で「いた」へは接続しない。「つきますいた」は成り立たず、この位置には入らない。"}], "explanations": {"ついて": "「ついていた」の「て形」。付いた状態が続いていたことを表し、「いた」に続く形として正しい。", "つく": "基本形なので「いた」に直接続かず、「つくいた」は文法的に成り立たない。", "つけて": "他動詞「付ける」の形で、ガムが主語の文には合わない。「つけていた」は成り立たない。", "つきます": "丁寧形で「いた」へは接続しない。「つきますいた」は成り立たず、この位置には入らない。"}, "sentence_index": 0, "correct_answer": "ついて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この中古車には、思ったより高い値がついた。", "explanation": "ここは〈値がつく〉（値段が決まる）の意味。くっつく意味では、価格の決定には使わない。"}, {"text": "長かった会議に、ようやく区切りがついた。", "explanation": "ここは〈区切りがつく〉（決着する）の意味。くっつく意味では、会議の決着には使わない。"}, {"text": "赤ちゃんは、すぐに眠りについた。", "explanation": "ここは〈眠りにつく〉（寝入る）の意味。くっつく意味では、人が眠る場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ついている", "is_correct": true, "explanation": "「糸くずがついている」の形。物が表面にくっついた状態を表し、文脈に合う。"}, {"text": "つけて", "is_correct": false, "explanation": "「つける」は他動詞で、「糸くずがつけて」は主語と合わない。"}, {"text": "つけ", "is_correct": false, "explanation": "「つける」の命令形で、「糸くずがつけよ」は文として成り立たない。"}, {"text": "つくまい", "is_correct": false, "explanation": "否定の意志の形で、「糸くずがつくまい」は友達の発言の内容と合わない。"}], "explanations": {"ついている": "「糸くずがついている」の形。物が表面にくっついた状態を表し、文脈に合う。", "つけて": "「つける」は他動詞で、「糸くずがつけて」は主語と合わない。", "つけ": "「つける」の命令形で、「糸くずがつけよ」は文として成り立たない。", "つくまい": "否定の意志の形で、「糸くずがつくまい」は友達の発言の内容と合わない。"}, "sentence_index": 6, "correct_answer": "ついている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は友だちの前で、大きくついて笑った。", "explanation": "ここは〈笑う〉の意味。つくは物がくっつく意味で、笑う動作には使わない。"}, {"text": "夜になって、部屋の電気がついた。", "explanation": "ここは〈点く〉（明かりがともる）の意味。くっつく意味では、明かりがともる場面には使わない。"}, {"text": "この古い時計には、思いがけない高い値段がついた。", "explanation": "ここは〈値がつく〉（値段が決まる）の意味。くっつく意味では、値段の決定には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業服を油がついたので、すぐに拭いた。", "corrected_sentence": "作業服に油がついたので、すぐに拭いた。", "error_description": "「つく」は付着先を「に」で表す。「を」は目的語になるので誤り。正しくは「作業服に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ついた", "is_correct": true, "explanation": "「泥がついた」の過去形。「ついたので」と続き、文の内容に合う。"}, {"text": "つけた", "is_correct": false, "explanation": "他動詞「付ける」の過去形で、泥が主語の文では成り立たない。"}, {"text": "つかない", "is_correct": false, "explanation": "否定形なので「泥がつかなかった」という逆の意味になり、文の内容と合わない。"}, {"text": "つきます", "is_correct": false, "explanation": "丁寧形で、普通体の「洗った」と文体が合わない。"}], "correct_form": "ついた", "base_form": "つく", "form_label": "過去形", "sentence_index": 1, "explanations": {"ついた": "「泥がついた」の過去形。「ついたので」と続き、文の内容に合う。", "つけた": "他動詞「付ける」の過去形で、泥が主語の文では成り立たない。", "つかない": "否定形なので「泥がつかなかった」という逆の意味になり、文の内容と合わない。", "つきます": "丁寧形で、普通体の「洗った」と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38943, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨粒が窓ガラスをついている。", "corrected_sentence": "雨粒が窓ガラスについている。", "error_description": "「つく」は付着先を「に」で表す。「を」は目的語を示すため誤り。正しくは「窓ガラスに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ついた", "is_correct": true, "explanation": "「葉っぱがついたまま」の過去形。髪に付いた状態を表し、文に合う。"}, {"text": "つかなかった", "is_correct": false, "explanation": "過去否定形で、「葉っぱがつかなかった」は文の内容と逆になる。"}, {"text": "つきません", "is_correct": false, "explanation": "丁寧な否定形で、文末の普通体「入ってきた」と合わない。"}, {"text": "つかず", "is_correct": false, "explanation": "否定の連用形で、「つかずまま」は意味が逆になり、文の形にも合わない。"}], "correct_form": "ついた", "base_form": "つく", "form_label": "過去形", "sentence_index": 7, "explanations": {"ついた": "「葉っぱがついたまま」の過去形。髪に付いた状態を表し、文に合う。", "つかなかった": "過去否定形で、「葉っぱがつかなかった」は文の内容と逆になる。", "つきません": "丁寧な否定形で、文末の普通体「入ってきた」と合わない。", "つかず": "否定の連用形で、「つかずまま」は意味が逆になり、文の形にも合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
