INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38944, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "今まで使っていたものを、別のものに変えること。", "primary_collocate": null, "pronunciation": "きりかえ", "ipa": "kiɾikae", "syllable_count": 4, "sentences": [{"text": "古い電話から新しい電話への切り替えは、思ったより簡単だった。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "ふるいでんわからあたらしいでんわへのきりかえは、おもったよりかんたんだった。", "sentence_source": "generated"}, {"text": "電気会社の切り替えをすると、毎月の料金が安くなる。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "でんきがいしゃのきりかえをすると、まいつきのりょうきんがやすくなる。", "sentence_source": "generated"}, {"text": "ガスの切り替えのために、業者が家に来た。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "ガスのきりかえのために、ぎょうしゃがいえにきた。", "sentence_source": "generated"}, {"text": "契約の切り替えは、来月の末までに済ませてください。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "けいやくのきりかえは、らいげつのすえまでにすませてください。", "sentence_source": "generated"}, {"text": "新しいシステムへの切り替えで、仕事が楽になった。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "あたらしいシステムへのきりかえで、しごとがらくになった。", "sentence_source": "generated"}, {"text": "古いパソコンから新しいものへの切り替えに、一日かかった。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "ふるいパソコンからあたらしいものへのきりかえに、いちにちかかった。", "sentence_source": "generated"}, {"text": "インターネットの切り替えは、手続きが少し面倒だった。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "インターネットのきりかえは、てつづきがすこしめんどうだった。", "sentence_source": "generated"}, {"text": "冬タイヤへの切り替えを、雪が降る前にしておこう。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "ふゆタイヤへのきりかえを、ゆきがふるまえにしておこう。", "sentence_source": "generated"}, {"text": "紙の書類から電子データへの切り替えが進んでいる。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "かみのしょるいからでんしデータへのきりかえがすすんでいる。", "sentence_source": "generated"}, {"text": "銀行の切り替えをしたとき、通帳もすべて新しくなった。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "ぎんこうのきりかえをしたとき、つうちょうもすべてあたらしくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切り替え", "label": "基本形"}, {"form": "切り替える", "label": "動詞形"}, {"form": "切り替えた", "label": "過去形"}], "register": "標準", "sense_fingerprint": "使っていた契約・機器・方式を別のものに替えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38944, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切り替え", "is_correct": true, "explanation": "古い電話を新しい電話に替えることを指すので、文の意味に合う。"}, {"text": "修理", "is_correct": false, "explanation": "壊れた物を直すことで、別の電話に替える意味ではない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べることで、物を別の物に替えることは表さない。"}, {"text": "解約", "is_correct": false, "explanation": "契約をやめる意味で、電話を新しくすることとは合わない。"}], "explanations": {"切り替え": "古い電話を新しい電話に替えることを指すので、文の意味に合う。", "修理": "壊れた物を直すことで、別の電話に替える意味ではない。", "点検": "状態を調べることで、物を別の物に替えることは表さない。", "解約": "契約をやめる意味で、電話を新しくすることとは合わない。"}, "sentence_index": 0, "correct_answer": "切り替え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古いメールを切り替えて、一覧から消した。", "explanation": "ここは〈消去〉の意味。切り替えは別のものに替えることで、不要な物を消す意味は表さない。"}, {"text": "雨が降ってきたので、彼は切り替えて傘を開いた。", "explanation": "ここは〈広げる〉の意味。切り替えは別のものに替えることで、傘を開く動作は表さない。"}, {"text": "大雨で壊れた屋根を、業者が切り替えて直した。", "explanation": "ここは〈修理〉の意味。切り替えは別の方式や機器に移すことで、壊れた物を直す意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38944, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切り替え", "is_correct": true, "explanation": "インターネット回線を別の回線に替えることを指すので、手続きが面倒だったという文に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に訳すことで、回線には使わない。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取ることで、回線を替える意味ではない。"}, {"text": "録音", "is_correct": false, "explanation": "音を記録することで、回線の変更とは合わない。"}], "explanations": {"切り替え": "インターネット回線を別の回線に替えることを指すので、手続きが面倒だったという文に合う。", "翻訳": "言葉を別の言語に訳すことで、回線には使わない。", "掃除": "汚れを取ることで、回線を替える意味ではない。", "録音": "音を記録することで、回線の変更とは合わない。"}, "sentence_index": 6, "correct_answer": "切り替え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達の顔を見て、切り替えてすぐに気づいた。", "explanation": "ここは〈気づく〉の意味。切り替えは使う方式や機器を別のものに替えることで、相手の様子を察する意味は表さない。"}, {"text": "眠る前に、彼は切り替えて深く呼吸した。", "explanation": "ここは〈呼吸する〉の意味。切り替えは別のものに替えることで、息を吸う意味は表さない。"}, {"text": "原稿の誤字を切り替えて、すべて直した。", "explanation": "ここは〈修正〉の意味。切り替えは別の方式や機器に移すことで、誤りを直す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38944, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水道会社の切り替えが、来週までに済ませる予定だ。", "corrected_sentence": "水道会社の切り替えを、来週までに済ませる予定だ。", "error_description": "『済ませる』の目的語は『を』で示す。『が』に変えると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38944, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月から、電気の契約を切り替えた予定だ。", "corrected_sentence": "来月から、電気の契約を切り替える予定だ。", "error_description": "未来の予定には辞書形『切り替える』を使う。『切り替えた』は過去形で、予定の文に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38945, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『切り替えが上手』で、上手さの主語を示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "『切り替えを上手な人』では形容詞が続かず、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "『切り替えで上手な』では手段になり、人の様子を表さない。"}, {"text": "と", "is_correct": false, "explanation": "『切り替えと上手な』では並列になり、上手さの主語にならない。"}], "correct_answer": "が", "explanations": {"が": "『切り替えが上手』で、上手さの主語を示すので正しい。", "を": "『切り替えを上手な人』では形容詞が続かず、不自然になる。", "で": "『切り替えで上手な』では手段になり、人の様子を表さない。", "と": "『切り替えと上手な』では並列になり、上手さの主語にならない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
