INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38945, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある状態や物を、別の状態や物に変えること。", "primary_collocate": null, "pronunciation": "きりかえ", "ipa": "kiɾikae", "syllable_count": 4, "sentences": [{"text": "テレビの画面の切り替えが速くて、目が疲れた。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "テレビのがめんのきりかえがはやくて、めがつかれた。", "sentence_source": "generated"}, {"text": "仕事と休みの気持ちの切り替えが上手な人はうらやましい。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "しごととやすみのきもちのきりかえがじょうずなひとはうらやましい。", "sentence_source": "generated"}, {"text": "夏から冬の服への切り替えは、十月に行います。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "なつからふゆのふくへのきりかえは、じゅうがつにおこないます。", "sentence_source": "generated"}, {"text": "信号が青に変わる切り替えの時間は、とても短い。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "しんごうがあおにかわるきりかえのじかんは、とてもみじかい。", "sentence_source": "generated"}, {"text": "スイッチの切り替えで、暖房と冷房を選べる。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "スイッチのきりかえで、だんぼうとれいぼうをえらべる。", "sentence_source": "generated"}, {"text": "気持ちの切り替えができず、昨日の失敗を考え続けた。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "きもちのきりかえができず、きのうのしっぱいをかんがえつづけた。", "sentence_source": "generated"}, {"text": "昼と夜の照明の切り替えは、自動で行われる。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "ひるとよるのしょうめいのきりかえは、じどうでおこなわれる。", "sentence_source": "generated"}, {"text": "カメラの設定の切り替えは、横のボタンで行います。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "カメラのせっていのきりかえは、よこのボタンでおこないます。", "sentence_source": "generated"}, {"text": "試合の前半と後半で、守りから攻めへの切り替えが早かった。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "しあいのぜんはんとこうはんで、まもりからせめへのきりかえがはやかった。", "sentence_source": "generated"}, {"text": "季節の切り替えのころは、体調をくずしやすい。", "target_word": "切り替え", "complexity_tier": "T3", "furigana": "きせつのきりかえのころは、たいちょうをくずしやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切り替え", "label": "基本形"}, {"form": "切り替える", "label": "動詞形"}, {"form": "切り替えた", "label": "過去形"}], "register": "標準", "sense_fingerprint": "状態・設定・気持ちなどを別の状態に変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48135081-0778-49c0-84f5-a0ee11a09eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38945, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切り替え", "is_correct": true, "explanation": "画面が別の映像に変わることを指すので、速くて目が疲れたという文に合う。"}, {"text": "録画", "is_correct": false, "explanation": "映像を記録することで、画面が変わる意味ではない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れた物を直すことで、画面の変化の速さとは合わない。"}, {"text": "通知", "is_correct": false, "explanation": "知らせることで、画面が変わる意味ではない。"}], "explanations": {"切り替え": "画面が別の映像に変わることを指すので、速くて目が疲れたという文に合う。", "録画": "映像を記録することで、画面が変わる意味ではない。", "修理": "壊れた物を直すことで、画面の変化の速さとは合わない。", "通知": "知らせることで、画面が変わる意味ではない。"}, "sentence_index": 0, "correct_answer": "切り替え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "休み時間に、彼は切り替えて本を読んだ。", "explanation": "ここは〈読む〉の意味。切り替えは状態や物を別のものに変えることで、本を読むこと自体は表さない。"}, {"text": "窓辺の花を切り替えて、水をたっぷりやった。", "explanation": "ここは〈水やり〉の意味。切り替えは別の状態に変えることで、植物に水を与える意味は表さない。"}, {"text": "体調の切り替えが進み、もう元気になった。", "explanation": "ここは〈回復〉の意味。切り替えは意図して別の状態に替えることで、病気から治っていく過程には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38945, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切り替え", "is_correct": true, "explanation": "照明が昼と夜で別の状態に替わることを指すので、自動で行われるという文に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に訳すことで、照明には使わない。"}, {"text": "録音", "is_correct": false, "explanation": "音を記録することで、照明の状態を替える意味ではない。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取ることで、照明の状態を替える意味ではない。"}], "explanations": {"切り替え": "照明が昼と夜で別の状態に替わることを指すので、自動で行われるという文に合う。", "翻訳": "言葉を別の言語に訳すことで、照明には使わない。", "録音": "音を記録することで、照明の状態を替える意味ではない。", "掃除": "汚れを取ることで、照明の状態を替える意味ではない。"}, "sentence_index": 6, "correct_answer": "切り替え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きなケーキを二つに切り替えて、友達と分けた。", "explanation": "ここは〈切り分ける〉の意味。切り替えは状態や物を別のものに変えることで、一つの物を分けて複数にする意味は表さない。"}, {"text": "テストの答案を切り替えて、点数をつけた。", "explanation": "ここは〈採点〉の意味。切り替えは状態や物を別のものに変えることで、答案に点数をつける意味は表さない。"}, {"text": "書きかけの文章の誤りを切り替えて直した。", "explanation": "ここは〈修正〉の意味。切り替えは状態を替えることで、誤りを直す意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38945, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の照明の切り替えに、リモコンで行える。", "corrected_sentence": "夜の照明の切り替えを、リモコンで行える。", "error_description": "『行える』の対象は『を』で示す。『に』は『行える』の目的語にならず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38945, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の照明を、明日から切り替えた予定だ。", "corrected_sentence": "会社の照明を、明日から切り替える予定だ。", "error_description": "未来の予定には辞書形『切り替える』を使う。『切り替えた』は過去形で、予定の文に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72034a05-99b6-42e0-8b48-1bb464131ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
