INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38948, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「製品の箱」と名詞を修飾する所属・所有の「の」で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "主語（この文は「箱には」で話題を示す）"}, {"text": "へ", "is_correct": false, "explanation": "方向（ここは所属を示す形にならない）"}, {"text": "より", "is_correct": false, "explanation": "比較（比べる文ではない）"}], "correct_answer": "の", "explanations": {"の": "「製品の箱」と名詞を修飾する所属・所有の「の」で、ここに入る。", "が": "主語（この文は「箱には」で話題を示す）", "へ": "方向（ここは所属を示す形にならない）", "より": "比較（比べる文ではない）"}, "error_tags": {"が": "主語（この文は「箱には」で話題を示す）", "へ": "方向（ここは所属を示す形にならない）", "より": "比較（比べる文ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38948, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お店で買えるものや、工場で作られたものです。", "primary_collocate": null, "pronunciation": "せいひん", "ipa": "seːçiɴ", "syllable_count": 4, "sentences": [{"text": "この工場では、毎日たくさんの製品が作られています。", "target_word": "製品", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、毎日[まいにち]たくさんの製品[せいひん]が作[つく]られています。", "sentence_source": "generated"}, {"text": "新しい製品は、来月から店に並びます。", "target_word": "製品", "complexity_tier": "T3", "furigana": "新[あたら]しい製品[せいひん]は、来月[らいげつ]から店[みせ]に並[なら]びます。", "sentence_source": "generated"}, {"text": "この製品は安いので、よく売れています。", "target_word": "製品", "complexity_tier": "T3", "furigana": "この製品[せいひん]は安[やす]いので、よく売[う]れています。", "sentence_source": "generated"}, {"text": "製品に問題があったので、店に返しました。", "target_word": "製品", "complexity_tier": "T3", "furigana": "製品[せいひん]に問題[もんだい]があったので、店[みせ]に返[かえ]しました。", "sentence_source": "generated"}, {"text": "日本の製品は丈夫だと言われています。", "target_word": "製品", "complexity_tier": "T3", "furigana": "日本[にほん]の製品[せいひん]は丈夫[じょうぶ]だと言[い]われています。", "sentence_source": "generated"}, {"text": "この会社の製品は、世界中で使われています。", "target_word": "製品", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の製品[せいひん]は、世界中[せかいじゅう]で使[つか]われています。", "sentence_source": "generated"}, {"text": "買った製品がこわれたので、店に電話しました。", "target_word": "製品", "complexity_tier": "T3", "furigana": "買[か]った製品[せいひん]がこわれたので、店[みせ]に電話[でんわ]しました。", "sentence_source": "generated"}, {"text": "製品の箱には、使い方が書いてあります。", "target_word": "製品", "complexity_tier": "T3", "furigana": "製品[せいひん]の箱[はこ]には、使[つか]い方[かた]が書[か]いてあります。", "sentence_source": "generated"}, {"text": "彼は自分の会社で作った製品を、毎日チェックしています。", "target_word": "製品", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の会社[かいしゃ]で作[つく]った製品[せいひん]を、毎日[まいにち]チェックしています。", "sentence_source": "generated"}, {"text": "古いものより、新しい製品のほうが軽くて便利です。", "target_word": "製品", "complexity_tier": "T3", "furigana": "古[ふる]いものより、新[あたら]しい製品[せいひん]のほうが軽[かる]くて便利[べんり]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "製品", "label": "基本形"}], "register": "neutral (丁寧)", "sense_fingerprint": "店で売られる、工場で作られた品物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38948, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "製品", "is_correct": true, "explanation": "工場で毎日作られ、店に並ぶ品物なので、ここに入る語。"}, {"text": "魚", "is_correct": false, "explanation": "魚は工場で作るものではなく獲るものなので、「たくさんの魚が作られています」とは続かない。"}, {"text": "空", "is_correct": false, "explanation": "空は作られるものではないので、「たくさんの空が作られています」は成り立たない。"}, {"text": "石", "is_correct": false, "explanation": "石は自然にあるもので、工場で作られる品物ではないので合わない。"}], "explanations": {"製品": "工場で毎日作られ、店に並ぶ品物なので、ここに入る語。", "魚": "魚は工場で作るものではなく獲るものなので、「たくさんの魚が作られています」とは続かない。", "空": "空は作られるものではないので、「たくさんの空が作られています」は成り立たない。", "石": "石は自然にあるもので、工場で作られる品物ではないので合わない。"}, "sentence_index": 0, "correct_answer": "製品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は絵の製品を十枚描きました。", "explanation": "ここは〈作品〉の意味。絵は描いて仕上げる作品を指し、工場で作って店で売る製品とは言わない。"}, {"text": "この畑では、米の製品を毎年育てています。", "explanation": "ここは〈作物〉の意味。畑で育てて収穫するものを指し、工場で作る品物には使わない。"}, {"text": "二と三の製品は、六です。", "explanation": "ここは〈積〉の意味。掛け算の答えは製品ではなく積と言うので、製品は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38948, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "製品", "is_correct": true, "explanation": "店で買った品物で、こわれるのは製品なので、ここに入る語。"}, {"text": "雲", "is_correct": false, "explanation": "雲は買えるものではないので、「買った雲」は成り立たない。"}, {"text": "犬", "is_correct": false, "explanation": "犬は生き物で、こわれる品物ではないので合わない。"}, {"text": "星", "is_correct": false, "explanation": "星は買えるものではなく、こわれる品物でもないので合わない。"}], "explanations": {"製品": "店で買った品物で、こわれるのは製品なので、ここに入る語。", "雲": "雲は買えるものではないので、「買った雲」は成り立たない。", "犬": "犬は生き物で、こわれる品物ではないので合わない。", "星": "星は買えるものではなく、こわれる品物でもないので合わない。"}, "sentence_index": 6, "correct_answer": "製品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食は、新鮮な製品をたくさん使って作りました。", "explanation": "ここは〈材料〉の意味。料理に使う食材には製品とは言わない。"}, {"text": "この山では、金の製品が採れます。", "explanation": "ここは〈鉱物〉の意味。山から採れるのは鉱物や資源で、工場で作る製品とは合わない。"}, {"text": "彼の努力の製品が、大会で表れました。", "explanation": "ここは〈成果〉の意味。努力の結果は製品ではなく成果と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38948, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この製品を、一年の保証がついています。", "corrected_sentence": "この製品には、一年の保証がついています。", "error_description": "正しくは「製品には」。「〜がついている」は「〜に」で持ち主を示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38948, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "完成した製品が、倉庫に運び入れます。", "corrected_sentence": "完成した製品を、倉庫に運び入れます。", "error_description": "正しくは「製品を」。「運び入れる」は目的語を「を」で示すので、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
