INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38954, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「条件で」は手段・条件を表し、「同じ条件で実施された」と自然に続く。"}, {"text": "の", "is_correct": false, "explanation": "「条件の」は名詞を修飾するだけで、「条件の実施された」では文の述語が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は「条件から実施された」と続けると、条件を出発点にする意味になってしまう。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「条件より実施された」と続かず、意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「条件で」は手段・条件を表し、「同じ条件で実施された」と自然に続く。", "の": "「条件の」は名詞を修飾するだけで、「条件の実施された」では文の述語が成り立たない。", "から": "起点を表す「から」は「条件から実施された」と続けると、条件を出発点にする意味になってしまう。", "より": "比較の「より」は「条件より実施された」と続かず、意味が通らない。"}, "error_tags": {"の": "連体修飾", "から": "起点・出どころ", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38954, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "決めたことを、本当に行うこと。", "primary_collocate": null, "pronunciation": "じっし", "ipa": "dʑiɕːi", "syllable_count": 3, "sentences": [{"text": "来月から、市内の小学校で新しい給食のメニューを実施する予定だ。", "target_word": "実施", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、市内[しない]の小学校[しょうがっこう]で新[あたら]しい給食[きゅうしょく]のメニューを実施[じっし]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "雨のため、予定していた運動会の実施は来週に延期された。", "target_word": "実施", "complexity_tier": "T3", "furigana": "雨[あめ]のため、予定[よてい]していた運動会[うんどうかい]の実施[じっし]は来週[らいしゅう]に延期[えんき]された。", "sentence_source": "generated"}, {"text": "会議で決まった節電対策は、四月一日から実施されます。", "target_word": "実施", "complexity_tier": "T3", "furigana": "会議[かいぎ]で決[き]まった節電対策[せつでんたいさく]は、四月一日[しがつついたち]から実施[じっし]されます。", "sentence_source": "generated"}, {"text": "計画を立てるだけでなく、実施しなければ意味がない。", "target_word": "実施", "complexity_tier": "T3", "furigana": "計画[けいかく]を立[た]てるだけでなく、実施[じっし]しなければ意味[いみ]がない。", "sentence_source": "generated"}, {"text": "避難訓練は毎年九月に実施している。", "target_word": "実施", "complexity_tier": "T3", "furigana": "避難訓練[ひなんくんれん]は毎年[まいとし]九月[くがつ]に実施[じっし]している。", "sentence_source": "generated"}, {"text": "アンケートを実施したところ、八割の人が賛成した。", "target_word": "実施", "complexity_tier": "T3", "furigana": "アンケートを実施[じっし]したところ、八割[はちわり]の人[ひと]が賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "費用が足りず、旅行の実施は難しくなった。", "target_word": "実施", "complexity_tier": "T3", "furigana": "費用[ひよう]が足[た]りず、旅行[りょこう]の実施[じっし]は難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "試験は午前九時に始まり、全員が同じ条件で実施された。", "target_word": "実施", "complexity_tier": "T3", "furigana": "試験[しけん]は午前九時[ごぜんくじ]に始[はじ]まり、全員[ぜんいん]が同[おな]じ条件[じょうけん]で実施[じっし]された。", "sentence_source": "generated"}, {"text": "社長の指示どおりに、新しい規則をすぐ実施した。", "target_word": "実施", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の指示[しじ]どおりに、新[あたら]しい規則[きそく]をすぐ実施[じっし]した。", "sentence_source": "generated"}, {"text": "工事の実施について、近所の人たちに説明があった。", "target_word": "実施", "complexity_tier": "T3", "furigana": "工事[こうじ]の実施[じっし]について、近所[きんじょ]の人[ひと]たちに説明[せつめい]があった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実施する", "label": "辞書形"}, {"form": "実施した", "label": "過去形"}, {"form": "実施される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "実施=決まった予定や取り決めを実際に行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38954, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実施", "is_correct": true, "explanation": "ここは「決めたことを行う」の意味。決まったメニューを実際に出す話に合う。"}, {"text": "食材", "is_correct": false, "explanation": "料理の材料を指す語で、「メニューを食材する」とは言えない。"}, {"text": "栄養", "is_correct": false, "explanation": "体に取る成分の意味で、行為の動詞にならない。「メニューを栄養する」は不自然。"}, {"text": "人数", "is_correct": false, "explanation": "数を表す語で、「メニューを人数する」とは続かない。"}], "explanations": {"実施": "ここは「決めたことを行う」の意味。決まったメニューを実際に出す話に合う。", "食材": "料理の材料を指す語で、「メニューを食材する」とは言えない。", "栄養": "体に取る成分の意味で、行為の動詞にならない。「メニューを栄養する」は不自然。", "人数": "数を表す語で、「メニューを人数する」とは続かない。"}, "sentence_index": 0, "correct_answer": "実施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "運転は教科書より実施で身につく。", "explanation": "ここは〈実地〉（現場で体験する）の意味。実施は決めたことを行う意味なので、身につく経験の話には合わない。"}, {"text": "会場でピアノを実施してもらった。", "explanation": "ここは〈演奏〉の意味。音楽を奏でる行為には「実施」を使わないので、この文は不自然。"}, {"text": "台風で壊れた屋根を、すぐ実施してもらった。", "explanation": "ここは〈修理〉の意味。壊れた物を直す行為には「実施」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38954, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実施", "is_correct": true, "explanation": "ここは「決めた旅行を行う」の意味。費用不足で旅行を行えない話に合う。"}, {"text": "パンフレット", "is_correct": false, "explanation": "案内の冊子で、「旅行のパンフレットは難しくなった」とは言えず、行うかどうかの話にならない。"}, {"text": "絵葉書", "is_correct": false, "explanation": "旅先から送る葉書で、旅行を行うことの難しさとは結びつかない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝るための道具で、旅行を行う困難さを表さない。"}], "explanations": {"実施": "ここは「決めた旅行を行う」の意味。費用不足で旅行を行えない話に合う。", "パンフレット": "案内の冊子で、「旅行のパンフレットは難しくなった」とは言えず、行うかどうかの話にならない。", "絵葉書": "旅先から送る葉書で、旅行を行うことの難しさとは結びつかない。", "寝袋": "寝るための道具で、旅行を行う困難さを表さない。"}, "sentence_index": 6, "correct_answer": "実施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学んだ知識を実施して、自信がついた。", "explanation": "ここは〈実践〉（学んだことを現場で試す）の意味。「実施」は決めた計画を行う意味なので、知識の活用には合わない。"}, {"text": "休日は家族のために料理を実施した。", "explanation": "ここは〈料理〉の意味。食事を作る行為を「実施」とは言わない。"}, {"text": "整備士は毎朝、機械を実施している。", "explanation": "ここは〈点検〉（状態を調べること）の意味。機械を調べる行為には「実施」は使わず、点検を行うという言い方に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38954, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その計画は来月から実施を移される。", "corrected_sentence": "その計画は来月から実施に移される。", "error_description": "「実施に移す」と「に」で続けるのが正しい。「実施を移される」は「を」が誤りで、目的語のように扱えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38954, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は今年度、住民への調査を実施れた。", "corrected_sentence": "市は今年度、住民への調査を実施した。", "error_description": "「実施した」が過去形。「実施れた」は「する」の活用の誤りで、正しい形は「した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
