INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38955, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「計画を実施している」の「を」で、計画が実施の対象になる。"}, {"text": "に", "is_correct": false, "explanation": "「計画に実施している」は到達点を示すが、実施の対象としては成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「計画の実施している」は名詞修飾で、述語の「実施している」に結べない。"}, {"text": "から", "is_correct": false, "explanation": "「計画から実施している」は起点を示すため、計画を対象として実施する意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「計画を実施している」の「を」で、計画が実施の対象になる。", "に": "「計画に実施している」は到達点を示すが、実施の対象としては成り立たない。", "の": "「計画の実施している」は名詞修飾で、述語の「実施している」に結べない。", "から": "「計画から実施している」は起点を示すため、計画を対象として実施する意味にならない。"}, "error_tags": {"に": "到達・方向", "の": "連体修飾", "から": "起点・出どころ"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38955, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "計画や法律など、決めたことを実際に行うこと。", "primary_collocate": null, "pronunciation": "じっし", "ipa": "dʑiɕːi", "syllable_count": 3, "sentences": [{"text": "新しい法律は来年の一月から実施される。", "target_word": "実施", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]は来年[らいねん]の一月[いちがつ]から実施[じっし]される。", "sentence_source": "generated"}, {"text": "政府は景気を回復させるため、減税の実施を決めた。", "target_word": "実施", "complexity_tier": "T3", "furigana": "政府[せいふ]は景気[けいき]を回復[かいふく]させるため、減税[げんぜい]の実施[じっし]を決[き]めた。", "sentence_source": "generated"}, {"text": "会社は計画どおりに、新製品の販売を実施した。", "target_word": "実施", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は計画[けいかく]どおりに、新製品[しんせいひん]の販売[はんばい]を実施[じっし]した。", "sentence_source": "generated"}, {"text": "その条例が実施されてから、道のごみが減った。", "target_word": "実施", "complexity_tier": "T3", "furigana": "その条例[じょうれい]が実施[じっし]されてから、道[みち]のごみが減[へ]った。", "sentence_source": "generated"}, {"text": "年度末までに、全部署で研修を実施する方針だ。", "target_word": "実施", "complexity_tier": "T3", "furigana": "年度末[ねんどまつ]までに、全部署[ぜんぶしょ]で研修[けんしゅう]を実施[じっし]する方針[ほうしん]だ。", "sentence_source": "generated"}, {"text": "準備に時間がかかり、計画の実施が三か月遅れた。", "target_word": "実施", "complexity_tier": "T3", "furigana": "準備[じゅんび]に時間[じかん]がかかり、計画[けいかく]の実施[じっし]が三[さん]か月[げつ]遅[おく]れた。", "sentence_source": "generated"}, {"text": "議会で可決された制度は、すぐに実施に移された。", "target_word": "実施", "complexity_tier": "T3", "furigana": "議会[ぎかい]で可決[かけつ]された制度[せいど]は、すぐに実施[じっし]に移[うつ]された。", "sentence_source": "generated"}, {"text": "市は大雪に備えて、除雪の計画を実施している。", "target_word": "実施", "complexity_tier": "T3", "furigana": "市[し]は大雪[おおゆき]に備[そな]えて、除雪[じょせつ]の計画[けいかく]を実施[じっし]している。", "sentence_source": "generated"}, {"text": "規則の実施を前に、社員への説明会が開かれた。", "target_word": "実施", "complexity_tier": "T3", "furigana": "規則[きそく]の実施[じっし]を前[まえ]に、社員[しゃいん]への説明会[せつめいかい]が開[ひら]かれた。", "sentence_source": "generated"}, {"text": "法律の実施には、多くの予算が必要だ。", "target_word": "実施", "complexity_tier": "T3", "furigana": "法律[ほうりつ]の実施[じっし]には、多[おお]くの予算[よさん]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実施する", "label": "辞書形"}, {"form": "実施した", "label": "過去形"}, {"form": "実施される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "実施=計画・法律・制度を実際に行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38955, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実施", "is_correct": true, "explanation": "ここは「決まった法律を行う」の意味。法律を来年から実際に行う話に合う。"}, {"text": "予算", "is_correct": false, "explanation": "お金の枠を表す語で、「予算される」とは言えず、開始時期の話にならない。"}, {"text": "期限", "is_correct": false, "explanation": "締め切りの意味で、「期限される」と続けられない。"}, {"text": "税金", "is_correct": false, "explanation": "税の支払いを指す語で、「税金される」は成り立たない。"}], "explanations": {"実施": "ここは「決まった法律を行う」の意味。法律を来年から実際に行う話に合う。", "予算": "お金の枠を表す語で、「予算される」とは言えず、開始時期の話にならない。", "期限": "締め切りの意味で、「期限される」と続けられない。", "税金": "税の支払いを指す語で、「税金される」は成り立たない。"}, "sentence_index": 0, "correct_answer": "実施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎朝、車を実施して畑へ行く。", "explanation": "ここは〈運転〉の意味。車を動かす行為には「実施」は使わず、この文は不自然。"}, {"text": "犬を連れて実施した。", "explanation": "ここは〈散歩〉の意味。犬と歩く行為を「実施」とは言わない。"}, {"text": "新人は一か月、工場で実施を受けた。", "explanation": "ここは〈実習〉の意味。現場で学ぶ研修を「実施」とは言わず、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38955, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実施", "is_correct": true, "explanation": "ここは「決まった制度を行う」の意味。可決された制度を実際に動かす段階に移る話に合う。"}, {"text": "提案", "is_correct": false, "explanation": "案を出す行為で、制度を動かす段階を指さない。「提案に移された」とは言えない。"}, {"text": "修正", "is_correct": false, "explanation": "直す行為で、可決後に動かす段階の話にならない。"}, {"text": "予測", "is_correct": false, "explanation": "先の見通しを立てる語で、「予測に移された」では段階の移行にならない。"}], "explanations": {"実施": "ここは「決まった制度を行う」の意味。可決された制度を実際に動かす段階に移る話に合う。", "提案": "案を出す行為で、制度を動かす段階を指さない。「提案に移された」とは言えない。", "修正": "直す行為で、可決後に動かす段階の話にならない。", "予測": "先の見通しを立てる語で、「予測に移された」では段階の移行にならない。"}, "sentence_index": 6, "correct_answer": "実施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は夜おそくまで答案を実施した。", "explanation": "ここは〈採点〉の意味。答案に点をつける行為には「実施」は使わない。"}, {"text": "家族のために洗濯を実施した。", "explanation": "ここは〈洗濯〉の意味。衣類を洗う家事を「実施」とは言わない。"}, {"text": "庭の距離を実施した。", "explanation": "ここは〈実測〉（実際に測る）の意味。測る行為には「実施」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38955, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は来春から、新しい制度を実施す予定だ。", "corrected_sentence": "市は来春から、新しい制度を実施する予定だ。", "error_description": "「実施する予定」と辞書形の「する」を続ける。「実施す」は活用として成り立たず、「する」の形が崩れている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38955, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画は秋に一斉に実施すれる。", "corrected_sentence": "その計画は秋に一斉に実施される。", "error_description": "「実施される」が正しい受身形。「実施すれる」は「する」の受身として成り立たない活用の誤りで、「される」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
