INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38956, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いちばんたいせつなところ", "primary_collocate": null, "pronunciation": "ちゅうかく", "ipa": "tɕɯːkaku", "syllable_count": 4, "sentences": [{"text": "この計画の中核は、みんなで話し合うことです。", "target_word": "中核", "complexity_tier": "T3", "furigana": "この計画[けいかく]の中核[ちゅうかく]は、みんなで話[はな]し合[あ]うことです。", "sentence_source": "generated"}, {"text": "チームの中核として、彼女は毎日遅くまで働いています。", "target_word": "中核", "complexity_tier": "T3", "furigana": "チームの中核[ちゅうかく]として、彼女[かのじょ]は毎日[まいにち]遅[おそ]くまで働[はたら]いています。", "sentence_source": "generated"}, {"text": "話の中核を先に書くと、読む人が分かりやすいです。", "target_word": "中核", "complexity_tier": "T3", "furigana": "話[はなし]の中核[ちゅうかく]を先[さき]に書[か]くと、読[よ]む人[ひと]が分[わ]かりやすいです。", "sentence_source": "generated"}, {"text": "この活動の中核は、地域の人と一緒に行う清掃です。", "target_word": "中核", "complexity_tier": "T3", "furigana": "この活動[かつどう]の中核[ちゅうかく]は、地域[ちいき]の人[ひと]と一緒[いっしょ]に行[おこな]う清掃[せいそう]です。", "sentence_source": "generated"}, {"text": "問題の中核がわからないまま、会議が終わりました。", "target_word": "中核", "complexity_tier": "T3", "furigana": "問題[もんだい]の中核[ちゅうかく]がわからないまま、会議[かいぎ]が終[お]わりました。", "sentence_source": "generated"}, {"text": "この店の中核は、祖母から教わった味です。", "target_word": "中核", "complexity_tier": "T3", "furigana": "この店[みせ]の中核[ちゅうかく]は、祖母[そぼ]から教[おそ]わった味[あじ]です。", "sentence_source": "generated"}, {"text": "彼は会社の中核を担う大切な人です。", "target_word": "中核", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]の中核[ちゅうかく]を担[にな]う大切[たいせつ]な人[ひと]です。", "sentence_source": "generated"}, {"text": "文章の中核をまとめてから、細かい説明を書きます。", "target_word": "中核", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]の中核[ちゅうかく]をまとめてから、細[こま]かい説明[せつめい]を書[か]きます。", "sentence_source": "generated"}, {"text": "中核となる考えが決まれば、あとは簡単です。", "target_word": "中核", "complexity_tier": "T3", "furigana": "中核[ちゅうかく]となる考[かんが]えが決[き]まれば、あとは簡単[かんたん]です。", "sentence_source": "generated"}, {"text": "練習の中核は、基本の動きを何度も繰り返すことです。", "target_word": "中核", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の中核[ちゅうかく]は、基本[きほん]の動[うご]きを何度[なんど]も繰[く]り返[かえ]すことです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中核", "label": "基本形"}], "register": "中立", "sense_fingerprint": "いちばん大切な部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38956, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中核", "is_correct": true, "explanation": "『いちばん大切なところ』の意味で、計画の要を表すので合う"}, {"text": "雨天", "is_correct": false, "explanation": "雨の降っている天気の意味で、計画の大切な部分にはならないので合わない"}, {"text": "服装", "is_correct": false, "explanation": "身につけるものの意味で、計画の大切な部分にはならないので合わない"}, {"text": "注射", "is_correct": false, "explanation": "体に薬液を入れる医療行為の意味で、計画の部分を表せないので合わない"}], "explanations": {"中核": "『いちばん大切なところ』の意味で、計画の要を表すので合う", "雨天": "雨の降っている天気の意味で、計画の大切な部分にはならないので合わない", "服装": "身につけるものの意味で、計画の大切な部分にはならないので合わない", "注射": "体に薬液を入れる医療行為の意味で、計画の部分を表せないので合わない"}, "sentence_index": 0, "correct_answer": "中核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉛筆の中核が折れてしまいました。", "explanation": "ここは〈芯〉の意味。『中核』は比喩的に大切な部分を指し、物の芯には使わない"}, {"text": "この品の中核は、三千円です。", "explanation": "ここは〈値段〉の意味。『中核』は物事の大切な部分を指し、金額は表さない"}, {"text": "この箱の中核には、古い手紙が入っていました。", "explanation": "ここは〈中身〉の意味。『中核』は物事の大切な部分を指し、箱の中身は表さない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38956, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中核", "is_correct": true, "explanation": "『いちばん大切なところ』の意味で、会社の重要な役割を表すので合う"}, {"text": "季節", "is_correct": false, "explanation": "一年を区切る時期の意味で、役割を担う対象にならないので合わない"}, {"text": "食器", "is_correct": false, "explanation": "食べ物を盛る器の意味で、役割を担う対象にならないので合わない"}, {"text": "遠足", "is_correct": false, "explanation": "校外での行事の意味で、会社の役割を表せないので合わない"}], "explanations": {"中核": "『いちばん大切なところ』の意味で、会社の重要な役割を表すので合う", "季節": "一年を区切る時期の意味で、役割を担う対象にならないので合わない", "食器": "食べ物を盛る器の意味で、役割を担う対象にならないので合わない", "遠足": "校外での行事の意味で、会社の役割を表せないので合わない"}, "sentence_index": 6, "correct_answer": "中核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は中核なので、新品より安く買えました。", "explanation": "ここは〈中古〉の意味（一度使われたもの）。『中核』は大切な部分で、車の使用状態は表さない"}, {"text": "試合は中核で一気に点が入った。", "explanation": "ここは〈中盤〉の意味（試合の途中の時期）。『中核』は重要な部分で、時期は表せない"}, {"text": "木の中核が、雨で腐ってしまいました。", "explanation": "ここは〈木の芯〉の意味。『中核』は比喩的に大切な部分を指し、木の芯は表さない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38956, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この事業の中核を、地元の若者の育成です。", "corrected_sentence": "この事業の中核は、地元の若者の育成です。", "error_description": "『中核』に続く助詞が『を』になっている。『です』の文の主題を示すには『は』が正しく、『を』では文が成り立たない", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38956, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の経済の中核に担うのは、観光業です。", "corrected_sentence": "町の経済の中核を担うのは、観光業です。", "error_description": "『担う』の目的語を示すには『中核を』が正しい。『中核に』では『担う』の対象にならず、文が成り立たない", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
