INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38957, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語。『失う』の対象を示す正しい形"}, {"text": "が", "is_correct": false, "explanation": "主語。『中核が失えば』では失う対象がなく、文が成り立たない"}, {"text": "に", "is_correct": false, "explanation": "位置・相手。『中核に失えば』では失う対象にならない"}, {"text": "で", "is_correct": false, "explanation": "手段・場所。『中核で失えば』は不自然"}], "correct_answer": "を", "explanations": {"を": "目的語。『失う』の対象を示す正しい形", "が": "主語。『中核が失えば』では失う対象がなく、文が成り立たない", "に": "位置・相手。『中核に失えば』では失う対象にならない", "で": "手段・場所。『中核で失えば』は不自然"}, "error_tags": {"が": "主格（主語）", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38957, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の中心となる重要な部分。", "primary_collocate": null, "pronunciation": "ちゅうかく", "ipa": "tɕɯːkaku", "syllable_count": 4, "sentences": [{"text": "研究の中核を成すのは、長年の観察データです。", "target_word": "中核", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の中核[ちゅうかく]を成[な]すのは、長年[ながねん]の観察[かんさつ]データです。", "sentence_source": "generated"}, {"text": "新しい制度の中核には、公平さという考えがあります。", "target_word": "中核", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]の中核[ちゅうかく]には、公平[こうへい]さという考[かんが]えがあります。", "sentence_source": "generated"}, {"text": "彼は事業の中核を担う部署に配属された。", "target_word": "中核", "complexity_tier": "T3", "furigana": "彼[かれ]は事業[じぎょう]の中核[ちゅうかく]を担[にな]う部署[ぶしょ]に配属[はいぞく]された。", "sentence_source": "generated"}, {"text": "議論の中核が見えてきたので、結論を出しやすくなった。", "target_word": "中核", "complexity_tier": "T3", "furigana": "議論[ぎろん]の中核[ちゅうかく]が見[み]えてきたので、結論[けつろん]を出[だ]しやすくなった。", "sentence_source": "generated"}, {"text": "この技術は、製品の中核となる部分に使われている。", "target_word": "中核", "complexity_tier": "T3", "furigana": "この技術[ぎじゅつ]は、製品[せいひん]の中核[ちゅうかく]となる部分[ぶぶん]に使[つか]われている。", "sentence_source": "generated"}, {"text": "理論の中核をなす仮説が、実験で確かめられた。", "target_word": "中核", "complexity_tier": "T3", "furigana": "理論[りろん]の中核[ちゅうかく]をなす仮説[かせつ]が、実験[じっけん]で確[たし]かめられた。", "sentence_source": "generated"}, {"text": "町の経済の中核は、昔から農業だった。", "target_word": "中核", "complexity_tier": "T3", "furigana": "町[まち]の経済[けいざい]の中核[ちゅうかく]は、昔[むかし]から農業[のうぎょう]だった。", "sentence_source": "generated"}, {"text": "組織の中核を失えば、活動は続けられない。", "target_word": "中核", "complexity_tier": "T3", "furigana": "組織[そしき]の中核[ちゅうかく]を失[うしな]えば、活動[かつどう]は続[つづ]けられない。", "sentence_source": "generated"}, {"text": "報告書の中核にあたる章を、最初に読んでください。", "target_word": "中核", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]の中核[ちゅうかく]にあたる章[しょう]を、最初[さいしょ]に読[よ]んでください。", "sentence_source": "generated"}, {"text": "改革の中核が示されないと、反対する人は納得しない。", "target_word": "中核", "complexity_tier": "T3", "furigana": "改革[かいかく]の中核[ちゅうかく]が示[しめ]されないと、反対[はんたい]する人[ひと]は納得[なっとく]しない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中核", "label": "基本形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "物事の中心となる重要部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38957, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中核", "is_correct": true, "explanation": "『物事の中心となる重要な部分』の意味で、研究の要を表すので合う"}, {"text": "食卓", "is_correct": false, "explanation": "食事をする台の意味で、研究を成す対象にならないので合わない"}, {"text": "寝袋", "is_correct": false, "explanation": "寝るための袋の意味で、研究を成す対象にならないので合わない"}, {"text": "花束", "is_correct": false, "explanation": "花をまとめたものの意味で、研究を成す対象にならないので合わない"}], "explanations": {"中核": "『物事の中心となる重要な部分』の意味で、研究の要を表すので合う", "食卓": "食事をする台の意味で、研究を成す対象にならないので合わない", "寝袋": "寝るための袋の意味で、研究を成す対象にならないので合わない", "花束": "花をまとめたものの意味で、研究を成す対象にならないので合わない"}, "sentence_index": 0, "correct_answer": "中核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布の中核には、古いお札が入っていました。", "explanation": "ここは〈中身〉の意味。『中核』は重要な部分を表し、財布の中身は表さない"}, {"text": "このカメラは中核なので、新品より安く買えました。", "explanation": "ここは〈中古〉の意味（一度使われたもの）。『中核』は重要な部分で、物の状態は表さない"}, {"text": "この荷物の中核は、十キロもある。", "explanation": "ここは〈重さ〉の意味。『中核』は大切な部分を表し、物の重さは表さない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38957, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中核", "is_correct": true, "explanation": "『物事の中心となる重要な部分』の意味で、経済の要を表すので合う"}, {"text": "天候", "is_correct": false, "explanation": "空模様の意味で、経済の一部を担う対象にならないので合わない"}, {"text": "花粉", "is_correct": false, "explanation": "植物の雄しべから出る粉の意味で、経済の説明にならないので合わない"}, {"text": "寝室", "is_correct": false, "explanation": "寝るための部屋の意味で、経済の一部を表せないので合わない"}], "explanations": {"中核": "『物事の中心となる重要な部分』の意味で、経済の要を表すので合う", "天候": "空模様の意味で、経済の一部を担う対象にならないので合わない", "花粉": "植物の雄しべから出る粉の意味で、経済の説明にならないので合わない", "寝室": "寝るための部屋の意味で、経済の一部を表せないので合わない"}, "sentence_index": 6, "correct_answer": "中核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の中核に旅行します。", "explanation": "ここは〈中旬〉の意味（月の真ん中あたり）。『中核』は重要な部分で、時期は表さない"}, {"text": "窓の中核を少し広げてください。", "explanation": "ここは〈間隔〉の意味（物と物の隙間）。『中核』は重要な部分を指し、隙間の広さは表せない"}, {"text": "顕微鏡で細胞の中核を観察しました。", "explanation": "ここは〈核〉（細胞の中心にある器官）の意味。『中核』は比喩的に大切な部分を指し、細胞の器官は表せない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38957, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この改革の中核で担うのは、若い世代です。", "corrected_sentence": "この改革の中核を担うのは、若い世代です。", "error_description": "『中核』に続く助詞が『で』になっている。『担う』は目的語を取るため『を』が正しく、『で』では担う対象が示せない", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38957, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この組織の中核を、若い人材を集める計画です。", "corrected_sentence": "この組織の中核に、若い人材を集める計画です。", "error_description": "『中核』に続く助詞が『を』になっている。『集める』の場所を示すには『に』が正しく、『を』では文が成り立たない", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "場所（地位）を自分のものにする動詞「占める」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置を示すため、「地位に占めています」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「地位が占めています」では地位が主語になり、占める対象がなくなる。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示すため、「地位と占めています」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "場所（地位）を自分のものにする動詞「占める」の目的語を示す。", "に": "位置を示すため、「地位に占めています」は意味が通らない。", "が": "主語を示すため、「地位が占めています」では地位が主語になり、占める対象がなくなる。", "と": "相手や引用を示すため、「地位と占めています」は成り立たない。"}, "error_tags": {"に": "位置", "が": "主語", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "場所（ベンチ）を取る動詞「占める」の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「ベンチへ占めて」は取る対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示すため、「ベンチと占めて」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示すため、「ベンチの占めて」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "場所（ベンチ）を取る動詞「占める」の目的語を示す。", "へ": "方向を示すため、「ベンチへ占めて」は取る対象にならない。", "と": "相手や引用を示すため、「ベンチと占めて」は文として成り立たない。", "の": "修飾を示すため、「ベンチの占めて」では動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "と": "相手・引用", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所や役割を、しっかりと自分のものにする。", "primary_collocate": null, "pronunciation": "しめる", "ipa": "ɕimeɾɯ", "syllable_count": 3, "sentences": [{"text": "大きな机が部屋の真ん中を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "大[おお]きな机[つくえ]が部屋[へや]の真[ま]ん中[なか]を占[し]めています。", "sentence_source": "generated"}, {"text": "彼は会社で大切な地位を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]で大切[たいせつ]な地位[ちい]を占[し]めています。", "sentence_source": "generated"}, {"text": "山田さんは、いつも前の席を占めて授業を受けます。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "山田[やまだ]さんは、いつも前[まえ]の席[せき]を占[し]めて授業[じゅぎょう]を受[う]けます。", "sentence_source": "generated"}, {"text": "大きな荷物が、車の後ろの席を占めていました。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "大[おお]きな荷物[にもつ]が、車[くるま]の後[うし]ろの席[せき]を占[し]めていました。", "sentence_source": "generated"}, {"text": "その歌手の新曲は、人気ランキングの一位を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "その歌手[かしゅ]の新曲[しんきょく]は、人気[にんき]ランキングの一位[いちい]を占[し]めています。", "sentence_source": "generated"}, {"text": "母は家族の中で大切な位置を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "母[はは]は家族[かぞく]の中[なか]で大切[たいせつ]な位置[いち]を占[し]めています。", "sentence_source": "generated"}, {"text": "彼のチームは、リーグで首位を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "彼[かれ]のチームは、リーグで首位[しゅい]を占[し]めています。", "sentence_source": "generated"}, {"text": "昼になると、観光客が公園のベンチを占めてしまいます。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "昼[ひる]になると、観光客[かんこうきゃく]が公園[こうえん]のベンチを占[し]めてしまいます。", "sentence_source": "generated"}, {"text": "音楽は、私の生活で大きな位置を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "音楽[おんがく]は、私[わたし]の生活[せいかつ]で大[おお]きな位置[いち]を占[し]めています。", "sentence_source": "generated"}, {"text": "大きな木が庭の中央を占めているので、日当たりが悪いです。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "大[おお]きな木[き]が庭[にわ]の中央[ちゅうおう]を占[し]めているので、日当[ひあ]たりが悪[わる]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "占める", "label": "辞書形"}, {"form": "占めない", "label": "否定形"}, {"form": "占めます", "label": "丁寧形"}, {"form": "占めて", "label": "て形"}, {"form": "占めた", "label": "た形"}, {"form": "占めれば", "label": "仮定形"}, {"form": "占められる", "label": "受身・可能形"}], "register": "neutral (丁寧)", "sense_fingerprint": "場所・席・地位などを自分のものとして確保する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形に「います」が続いて「占めています」となり、場所を占めている状態を表す。"}, {"text": "占めた", "is_correct": false, "explanation": "た形に「います」は続かず、「占めたいます」は成り立たない。"}, {"text": "占めれば", "is_correct": false, "explanation": "仮定形は「〜れば」に続く文が必要で、この文は完結しない。"}, {"text": "占めない", "is_correct": false, "explanation": "否定形は「ていない」の形を作れず、「占めないています」となる。"}], "explanations": {"占めて": "て形に「います」が続いて「占めています」となり、場所を占めている状態を表す。", "占めた": "た形に「います」は続かず、「占めたいます」は成り立たない。", "占めれば": "仮定形は「〜れば」に続く文が必要で、この文は完結しない。", "占めない": "否定形は「ていない」の形を作れず、「占めないています」となる。"}, "sentence_index": 0, "correct_answer": "占めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓を占めました。", "explanation": "ここは〈閉める〉の意味。占めるは場所や役割を取る意味で、窓を閉める意味はない。"}, {"text": "先生が生徒にプリントを占めました。", "explanation": "ここは〈配る〉の意味。占めるは場所を取る意味で、物を人に分ける意味はない。"}, {"text": "母は毎朝、家族のために朝ご飯を占めます。", "explanation": "ここは〈作る〉の意味。占めるは場所や役割を取る意味で、料理を作る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形に「います」が続いて「占めています」となり、首位を占めている状態を表す。"}, {"text": "占めます", "is_correct": false, "explanation": "丁寧形に「います」は続かず、「占めますいます」となる。"}, {"text": "占める", "is_correct": false, "explanation": "辞書形に「います」は続かず、「占めるいます」となる。"}, {"text": "占められ", "is_correct": false, "explanation": "受身の語幹で、「占められいます」となり文が成り立たない。"}], "explanations": {"占めて": "て形に「います」が続いて「占めています」となり、首位を占めている状態を表す。", "占めます": "丁寧形に「います」は続かず、「占めますいます」となる。", "占める": "辞書形に「います」は続かず、「占めるいます」となる。", "占められ": "受身の語幹で、「占められいます」となり文が成り立たない。"}, "sentence_index": 6, "correct_answer": "占めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はネクタイをきつく占めました。", "explanation": "ここは〈締める〉の意味。同じ読みでも、占めるは場所や役割を取る意味で、ネクタイを締める意味はない。"}, {"text": "店はパンを占めています。", "explanation": "ここは〈売る〉の意味。占めるは場所や役割を取る意味で、商品を売る意味では使わない。"}, {"text": "クラスをふたつに占めました。", "explanation": "ここは〈分ける〉の意味。占めるは場所や役割を自分のものにする意味で、集団を二つに分ける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな本棚が壁の一面が占めています。", "corrected_sentence": "大きな本棚が壁の一面を占めています。", "error_description": "正しくは「壁の一面を占めています」。「占める」は場所を対象として取るので「を」を使い、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形（〜ています）。「地位を占めています」の一部で、現在の状態を表す。"}, {"text": "占めない", "is_correct": false, "explanation": "否定形なので、地位を持っている状況と矛盾する。"}, {"text": "占めれば", "is_correct": false, "explanation": "仮定形は「〜れば」が続かず、文が完結しない。"}, {"text": "占められる", "is_correct": false, "explanation": "受身・可能形になり、「占めています」の形を表さない。"}], "correct_form": "占めて", "base_form": "占める", "form_label": "て形", "sentence_index": 1, "explanations": {"占めて": "て形（〜ています）。「地位を占めています」の一部で、現在の状態を表す。", "占めない": "否定形なので、地位を持っている状況と矛盾する。", "占めれば": "仮定形は「〜れば」が続かず、文が完結しない。", "占められる": "受身・可能形になり、「占めています」の形を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38958, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昼のバスで、観光客が前の席を占めるてしまいます。", "corrected_sentence": "昼のバスで、観光客が前の席を占めてしまいます。", "error_description": "辞書形の「占める」の後に「て」は続かない。正しくは て形の「占めて」で、「しまいます」につながる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形。「占めてしまいます」の一部で、「しまう」に続く形。"}, {"text": "占めた", "is_correct": false, "explanation": "た形は「しまいます」に続かず、「占めたしまいます」となる。"}, {"text": "占めます", "is_correct": false, "explanation": "丁寧形は「しまいます」と続かず、文法的に成り立たない。"}, {"text": "占める", "is_correct": false, "explanation": "辞書形は「占めるしまいます」となり、文法的に成り立たない。"}], "correct_form": "占めて", "base_form": "占める", "form_label": "て形", "sentence_index": 7, "explanations": {"占めて": "て形。「占めてしまいます」の一部で、「しまう」に続く形。", "占めた": "た形は「しまいます」に続かず、「占めたしまいます」となる。", "占めます": "丁寧形は「しまいます」と続かず、文法的に成り立たない。", "占める": "辞書形は「占めるしまいます」となり、文法的に成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "割合（七割）を示す「占める」の目的語を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所（「七割で占めています」は成り立たない）"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示すため、「七割と占めています」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「七割へ占めています」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "割合（七割）を示す「占める」の目的語を示す。", "で": "手段・場所（「七割で占めています」は成り立たない）", "と": "相手や引用を示すため、「七割と占めています」は文として成り立たない。", "へ": "方向を示すため、「七割へ占めています」は意味が通らない。"}, "error_tags": {"で": "手段・場所（「七割で占めています」は成り立たない）", "が": "主語", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "割合（過半数）を示す「占める」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「過半数が占めました」では割合が主語になり、目的語が消える。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すため、「過半数で占めました」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「過半数から占めました」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "割合（過半数）を示す「占める」の目的語を示す。", "が": "主語を示すため、「過半数が占めました」では割合が主語になり、目的語が消える。", "で": "手段や場所を示すため、「過半数で占めました」は意味が通らない。", "から": "起点を示すため、「過半数から占めました」は文として成り立たない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある範囲内で、特定の位置や割合を確保すること。", "primary_collocate": null, "pronunciation": "しめる", "ipa": "ɕimeɾɯ", "syllable_count": 3, "sentences": [{"text": "学生は、このクラスの半分を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "学生[がくせい]は、このクラスの半分[はんぶん]を占[し]めています。", "sentence_source": "generated"}, {"text": "輸入品が、店の商品の七割を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "輸入品[ゆにゅうひん]が、店[みせ]の商品[しょうひん]の七割[ななわり]を占[し]めています。", "sentence_source": "generated"}, {"text": "水田は、この町の面積の三分の一を占めます。", "target_word": "占めます", "complexity_tier": "T3", "furigana": "水田[すいでん]は、この町[まち]の面積[めんせき]の三分[さんぶん]の一[いち]を占[し]めます。", "sentence_source": "generated"}, {"text": "お年寄りが人口の三割を占める町もあります。", "target_word": "占める", "complexity_tier": "T3", "furigana": "お年寄[としよ]りが人口[じんこう]の三割[さんわり]を占[し]める町[まち]もあります。", "sentence_source": "generated"}, {"text": "家賃が収入の四割を占めているので、生活が苦しいです。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "家賃[やちん]が収入[しゅうにゅう]の四割[よんわり]を占[し]めているので、生活[せいかつ]が苦[くる]しいです。", "sentence_source": "generated"}, {"text": "女性の社員が、全体の六割を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "女性[じょせい]の社員[しゃいん]が、全体[ぜんたい]の六割[ろくわり]を占[し]めています。", "sentence_source": "generated"}, {"text": "米は、日本の農業生産の大きな割合を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "米[こめ]は、日本[にほん]の農業[のうぎょう]生産[せいさん]の大[おお]きな割合[わりあい]を占[し]めています。", "sentence_source": "generated"}, {"text": "調査では、賛成の人が過半数を占めました。", "target_word": "占めました", "complexity_tier": "T3", "furigana": "調査[ちょうさ]では、賛成[さんせい]の人[ひと]が過半数[かはんすう]を占[し]めました。", "sentence_source": "generated"}, {"text": "水は、人の体の約六割を占めています。", "target_word": "占めて", "complexity_tier": "T3", "furigana": "水[みず]は、人[ひと]の体[からだ]の約[やく]六割[ろくわり]を占[し]めています。", "sentence_source": "generated"}, {"text": "外国人の観光客は、客全体の二割を占めました。", "target_word": "占めました", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の観光客[かんこうきゃく]は、客[きゃく]全体[ぜんたい]の二割[にわり]を占[し]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "占める", "label": "辞書形"}, {"form": "占めない", "label": "否定形"}, {"form": "占めます", "label": "丁寧形"}, {"form": "占めて", "label": "て形"}, {"form": "占めた", "label": "た形"}, {"form": "占めれば", "label": "仮定形"}, {"form": "占められる", "label": "受身・可能形"}], "register": "neutral (丁寧)", "sense_fingerprint": "全体の中で一定の割合・比率を構成する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形に「います」が続いて「半分を占めています」となり、割合を表す。"}, {"text": "占めた", "is_correct": false, "explanation": "た形に「います」は続かず、「占めたいます」は成り立たない。"}, {"text": "占めれば", "is_correct": false, "explanation": "仮定形は「〜れば」に続く文が必要で、この文は完結しない。"}, {"text": "占めない", "is_correct": false, "explanation": "否定形は「ていない」の形を作れず、「占めないています」となる。"}], "explanations": {"占めて": "て形に「います」が続いて「半分を占めています」となり、割合を表す。", "占めた": "た形に「います」は続かず、「占めたいます」は成り立たない。", "占めれば": "仮定形は「〜れば」に続く文が必要で、この文は完結しない。", "占めない": "否定形は「ていない」の形を作れず、「占めないています」となる。"}, "sentence_index": 0, "correct_answer": "占めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "写真を占めました。", "explanation": "ここは〈撮る〉の意味。占めるは割合を示す意味で、写真を撮る意味では使わない。"}, {"text": "係の人が教室の生徒を占めました。", "explanation": "ここは〈数える〉の意味。占めるは割合を示すので、人を数える意味では使わない。"}, {"text": "先生はクラスを二つに占めました。", "explanation": "ここは〈分ける〉の意味。占めるは割合を示す意味で、集団を分ける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形に「います」が続いて「割合を占めています」となり、割合を表す。"}, {"text": "占めます", "is_correct": false, "explanation": "丁寧形に「います」は続かず、「占めますいます」となる。"}, {"text": "占める", "is_correct": false, "explanation": "辞書形に「います」は続かず、「占めるいます」となる。"}, {"text": "占められ", "is_correct": false, "explanation": "受身の語幹で、「占められいます」となり文が成り立たない。"}], "explanations": {"占めて": "て形に「います」が続いて「割合を占めています」となり、割合を表す。", "占めます": "丁寧形に「います」は続かず、「占めますいます」となる。", "占める": "辞書形に「います」は続かず、「占めるいます」となる。", "占められ": "受身の語幹で、「占められいます」となり文が成り立たない。"}, "sentence_index": 6, "correct_answer": "占めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "売り上げが目標を占めました。", "explanation": "ここは〈超える〉の意味。占めるは割合を示す意味で、目標を上回る意味では使わない。"}, {"text": "会費を三人で占めました。", "explanation": "ここは〈分ける〉の意味。占めるは割合を示す意味で、費用を分担する意味はない。"}, {"text": "窓ガラスを占めました。", "explanation": "ここは〈壊す〉の意味。占めるは割合を示す意味で、物を壊す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "男子は、このチームの半分が占めています。", "corrected_sentence": "男子は、このチームの半分を占めています。", "error_description": "正しくは「半分を占めています」。割合を表す「占める」は対象を「を」で示すので、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "占めて", "is_correct": true, "explanation": "て形（〜ています）。「七割を占めています」の一部。"}, {"text": "占めない", "is_correct": false, "explanation": "否定形は現在の状態と矛盾し、割合を表さない。"}, {"text": "占めれば", "is_correct": false, "explanation": "仮定形は「〜れば」が続かず、文が完結しない。"}, {"text": "占めた", "is_correct": false, "explanation": "た形に「います」は続かず、「占めたいます」となる。"}], "correct_form": "占めて", "base_form": "占める", "form_label": "て形", "sentence_index": 1, "explanations": {"占めて": "て形（〜ています）。「七割を占めています」の一部。", "占めない": "否定形は現在の状態と矛盾し、割合を表さない。", "占めれば": "仮定形は「〜れば」が続かず、文が完結しない。", "占めた": "た形に「います」は続かず、「占めたいます」となる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38959, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "野菜は、家庭の食費の大きな割合を占めたています。", "corrected_sentence": "野菜は、家庭の食費の大きな割合を占めています。", "error_description": "「占めて」の後に余分な「た」が入っている。正しくは「占めている」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "占めました", "is_correct": true, "explanation": "丁寧な過去形。調査で過半数を占めた出来事を表す。"}, {"text": "占めて", "is_correct": false, "explanation": "て形は文を完結させず、過去の丁寧形を表さない。"}, {"text": "占める", "is_correct": false, "explanation": "辞書形は現在の表現で、過去の出来事を表さない。"}, {"text": "占めません", "is_correct": false, "explanation": "丁寧否定形になり、賛成の人が過半数を占めた事実と矛盾する。"}], "correct_form": "占めました", "base_form": "占める", "form_label": "丁寧な過去形", "sentence_index": 7, "explanations": {"占めました": "丁寧な過去形。調査で過半数を占めた出来事を表す。", "占めて": "て形は文を完結させず、過去の丁寧形を表さない。", "占める": "辞書形は現在の表現で、過去の出来事を表さない。", "占めません": "丁寧否定形になり、賛成の人が過半数を占めた事実と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「上がる」の主語になる語に付く助詞。実効が効果の出る主語になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すため、「実効と上がる」の形では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は向かう先に付くが、実効は向かう先にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「実効より上がる」の形にならない。"}], "correct_answer": "が", "explanations": {"が": "「上がる」の主語になる語に付く助詞。実効が効果の出る主語になる。", "と": "「と」は並列や相手を表すため、「実効と上がる」の形では文が成り立たない。", "へ": "方向を表す「へ」は向かう先に付くが、実効は向かう先にはならない。", "より": "比較の「より」は「実効より上がる」の形にならない。"}, "error_tags": {"と": "accompaniment", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「実効の〜ある案」の形で、実効を後ろの「ある」に結び付ける「の」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「実効を〜ある案」とは続かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示すため、「実効に〜ある案」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「実効で〜ある案」は不自然で成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「実効の〜ある案」の形で、実効を後ろの「ある」に結び付ける「の」。", "を": "「を」は目的語を示すため、「実効を〜ある案」とは続かない。", "に": "「に」は場所や対象を示すため、「実効に〜ある案」では文が成り立たない。", "で": "「で」は場所や手段を示すため、「実効で〜ある案」は不自然で成り立たない。"}, "error_tags": {"を": "object", "に": "target", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実効とは、決めたことが本当に役に立つことです。", "primary_collocate": null, "pronunciation": "じっこう", "ipa": "dʑikkoː", "syllable_count": 4, "sentences": [{"text": "話し合って決めた計画に実効がなければ、意味がない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]って決[き]めた計画[けいかく]に実効[じっこう]がなければ、意味[いみ]がない。", "sentence_source": "generated"}, {"text": "この対策は、実効が上がるまで時間がかかりそうだ。", "target_word": "実効", "complexity_tier": "T3", "furigana": "この対策[たいさく]は、実効[じっこう]が上[あ]がるまで時間[じかん]がかかりそうだ。", "sentence_source": "generated"}, {"text": "立派なスローガンでも、実効のある行動が伴わなければ人は動かない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "立派[りっぱ]なスローガンでも、実効[じっこう]のある行動[こうどう]が伴[ともな]わなければ人[ひと]は動[うご]かない。", "sentence_source": "generated"}, {"text": "節電のルールを作っても、実効が伴わなければ電気代は減らない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "節電[せつでん]のルールを作[つく]っても、実効[じっこう]が伴[ともな]わなければ電気代[でんきだい]は減[へ]らない。", "sentence_source": "generated"}, {"text": "先生に教わった勉強法は実効があって、成績が上がった。", "target_word": "実効", "complexity_tier": "T3", "furigana": "先生[せんせい]に教[おそ]わった勉強法[べんきょうほう]は実効[じっこう]があって、成績[せいせき]が上[あ]がった。", "sentence_source": "generated"}, {"text": "会議で決めたことに実効を持たせるには、毎日の確認が欠かせない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "会議[かいぎ]で決[き]めたことに実効[じっこう]を持[も]たせるには、毎日[まいにち]の確認[かくにん]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "書類だけ整えても、実効がなければ何も変わらない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "書類[しょるい]だけ整[ととの]えても、実効[じっこう]がなければ何[なに]も変[か]わらない。", "sentence_source": "generated"}, {"text": "実効のある案を出すために、現場の声を聞いた。", "target_word": "実効", "complexity_tier": "T3", "furigana": "実効[じっこう]のある案[あん]を出[だ]すために、現場[げんば]の声[こえ]を聞[き]いた。", "sentence_source": "generated"}, {"text": "新しい計画の実効を疑う声が、会議で出た。", "target_word": "実効", "complexity_tier": "T3", "furigana": "新[あたら]しい計画[けいかく]の実効[じっこう]を疑[うたが]う声[こえ]が、会議[かいぎ]で出[で]た。", "sentence_source": "generated"}, {"text": "実効を求める社長は、飾りの多い計画を嫌う。", "target_word": "実効", "complexity_tier": "T3", "furigana": "実効[じっこう]を求[もと]める社長[しゃちょう]は、飾[かざ]りの多[おお]い計画[けいかく]を嫌[きら]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実効", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "決めた計画や方法が実際に役に立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実効", "is_correct": true, "explanation": "「決めた計画が役に立つ効き目」の意味で、この空欄に入るのは実効だけ。"}, {"text": "寛容", "is_correct": false, "explanation": "心が広く相手を許すこと。計画の役立ち具合を表さないので、文が成り立たない。"}, {"text": "哀愁", "is_correct": false, "explanation": "しみじみとした悲しみの気持ち。計画の効き目を表す場所には入らない。"}, {"text": "重宝", "is_correct": false, "explanation": "便利で役に立つ品物を指す。計画が役に立つかどうかを言う文脈に合わない。"}], "explanations": {"実効": "「決めた計画が役に立つ効き目」の意味で、この空欄に入るのは実効だけ。", "寛容": "心が広く相手を許すこと。計画の役立ち具合を表さないので、文が成り立たない。", "哀愁": "しみじみとした悲しみの気持ち。計画の効き目を表す場所には入らない。", "重宝": "便利で役に立つ品物を指す。計画が役に立つかどうかを言う文脈に合わない。"}, "sentence_index": 0, "correct_answer": "実効"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は十年の実効を持つベテラン社員で、仕事を任せられる。", "explanation": "ここは〈実績〉（これまでに積んだ成果）の語で「実績を持つ」と言う。実効は規則や方法が効き目を持つことなので、人の経歴には使わない。"}, {"text": "決めた案を実効に移すため、担当者を決めた。", "explanation": "ここは〈実行〉（計画をやること）の語で「実行に移す」と言う。実効は効き目を表すので「移す」とは言えない。"}, {"text": "この切符は今日まで実効だ。", "explanation": "ここは〈有効〉（期限内で使える）の語。実効は規則や方法が実際に効くことなので、切符の使用可否には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実効", "is_correct": true, "explanation": "規則や対策が効き目を持つかどうかを表す「実効」が、ここでは唯一自然に入る。"}, {"text": "憂い", "is_correct": false, "explanation": "心配や悲しみの気持ち。「書類だけ整えても憂いがなければ」では文として意味をなさない。"}, {"text": "寛大", "is_correct": false, "explanation": "心が広く相手を許す様子。書類の整備と結びつかず、文が成り立たない。"}, {"text": "郷愁", "is_correct": false, "explanation": "故郷を懐かしむ気持ち。書類を整える文脈には入らない。"}], "explanations": {"実効": "規則や対策が効き目を持つかどうかを表す「実効」が、ここでは唯一自然に入る。", "憂い": "心配や悲しみの気持ち。「書類だけ整えても憂いがなければ」では文として意味をなさない。", "寛大": "心が広く相手を許す様子。書類の整備と結びつかず、文が成り立たない。", "郷愁": "故郷を懐かしむ気持ち。書類を整える文脈には入らない。"}, "sentence_index": 6, "correct_answer": "実効"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の長年の実効をたたえ、表彰した。", "explanation": "ここは〈功績〉（立派な働きや手柄）の語。実効は規則や方法の効き目なので、人の働きをたたえる文には使わない。"}, {"text": "卒業式で実効がこみ上げてきた。", "explanation": "ここは〈感慨〉（しみじみとした思い）の語。実効は効き目なので、感情がこみ上げるとは言えない。"}, {"text": "試合の実効に浸った。", "explanation": "ここは〈余韻〉（後に残る感じ）の語で「余韻に浸る」と言う。実効は効き目なので、浸る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい手順は実効を上がったので、現場は続けている。", "corrected_sentence": "新しい手順は実効が上がったので、現場は続けている。", "error_description": "「上がる」は「〜が上がる」の形で使うため、実効に付く「を」は誤り。正しくは「実効が上がる」（効果が出る）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38960, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実効が伴うなければ、計画は続かない。", "corrected_sentence": "実効が伴わなければ、計画は続かない。", "error_description": "「伴う」を否定にすると「伴わない」になるため、「伴うなければ」は誤り。正しくは未然形「伴わ」を使って「伴わなければ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「高める」は目的語に「を」を取るため、「実効を高める」となる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すため、「実効と高める」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "向かう先を表す「へ」は、「実効へ高める」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「実効より高める」の形にならない。"}], "correct_answer": "を", "explanations": {"を": "「高める」は目的語に「を」を取るため、「実効を高める」となる。", "と": "「と」は並列や相手を表すため、「実効と高める」とは続かない。", "へ": "向かう先を表す「へ」は、「実効へ高める」では文が成り立たない。", "より": "比較の「より」は「実効より高める」の形にならない。"}, "error_tags": {"と": "accompaniment", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「疑わしい」の主語を示す「が」。「実効が疑わしい」と続く。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象を示すが、「実効に疑わしい」は不自然で成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「実効で疑わしい」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、「実効から疑わしい」の形では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「疑わしい」の主語を示す「が」。「実効が疑わしい」と続く。", "に": "「に」は対象を示すが、「実効に疑わしい」は不自然で成り立たない。", "で": "「で」は場所や手段を示すため、「実効で疑わしい」は文として成り立たない。", "から": "起点を表す「から」は、「実効から疑わしい」の形では意味が通らない。"}, "error_tags": {"に": "target", "で": "means", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実効は、規則や法律などが実際に持つ効果や、期待通りに働く力を意味します。", "primary_collocate": null, "pronunciation": "じっこう", "ipa": "dʑikkoː", "syllable_count": 4, "sentences": [{"text": "その法律は、罰則がなければ実効が弱い。", "target_word": "実効", "complexity_tier": "T3", "furigana": "その法律[ほうりつ]は、罰則[ばっそく]がなければ実効[じっこう]が弱[よわ]い。", "sentence_source": "generated"}, {"text": "新しい規則の実効を高めるため、監督する人を増やした。", "target_word": "実効", "complexity_tier": "T3", "furigana": "新[あたら]しい規則[きそく]の実効[じっこう]を高[たか]めるため、監督[かんとく]する人[ひと]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "条約を結んでも、守らせる仕組みがなければ実効は期待できない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "条約[じょうやく]を結[むす]んでも、守[まも]らせる仕組[しく]みがなければ実効[じっこう]は期待[きたい]できない。", "sentence_source": "generated"}, {"text": "実効のある法律にするには、細かい決まりが必要だ。", "target_word": "実効", "complexity_tier": "T3", "furigana": "実効[じっこう]のある法律[ほうりつ]にするには、細[こま]かい決[き]まりが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "禁止の規則は作られたが、実効が伴わず、ごみは減らなかった。", "target_word": "実効", "complexity_tier": "T3", "furigana": "禁止[きんし]の規則[きそく]は作[つく]られたが、実効[じっこう]が伴[ともな]わず、ごみは減[へ]らなかった。", "sentence_source": "generated"}, {"text": "裁判所の決定に実効を持たせるため、役所が協力した。", "target_word": "実効", "complexity_tier": "T3", "furigana": "裁判所[さいばんしょ]の決定[けってい]に実効[じっこう]を持[も]たせるため、役所[やくしょ]が協力[きょうりょく]した。", "sentence_source": "generated"}, {"text": "この規制は実効が乏しく、違反する店がなくならない。", "target_word": "実効", "complexity_tier": "T3", "furigana": "この規制[きせい]は実効[じっこう]が乏[とぼ]しく、違反[いはん]する店[みせ]がなくならない。", "sentence_source": "generated"}, {"text": "実効が疑わしい法律は、やがて誰も守らなくなる。", "target_word": "実効", "complexity_tier": "T3", "furigana": "実効[じっこう]が疑[うたが]わしい法律[ほうりつ]は、やがて誰[だれ]も守[まも]らなくなる。", "sentence_source": "generated"}, {"text": "専門家は、新しい条例の実効を慎重に見ている。", "target_word": "実効", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、新[あたら]しい条例[じょうれい]の実効[じっこう]を慎重[しんちょう]に見[み]ている。", "sentence_source": "generated"}, {"text": "罰金を重くしたことで、交通規則の実効が上がった。", "target_word": "実効", "complexity_tier": "T3", "furigana": "罰金[ばっきん]を重[おも]くしたことで、交通規則[こうつうきそく]の実効[じっこう]が上[あ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実効", "label": "基本形"}], "register": "formal", "sense_fingerprint": "規則や法律が現実に発揮する効果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実効", "is_correct": true, "explanation": "法律や規則が実際に持つ効果を表す「実効」が、ここでは唯一自然に入る。"}, {"text": "誠実", "is_correct": false, "explanation": "真心を持って誠意を尽くすこと。法律の効き目を言う文脈には入らない。"}, {"text": "哀愁", "is_correct": false, "explanation": "しみじみとした悲しみの気持ち。罰則と結びつかず、文として不自然。"}, {"text": "感慨", "is_correct": false, "explanation": "深く感じ入る気持ち。法律の効果を言う文では意味が通らない。"}], "explanations": {"実効": "法律や規則が実際に持つ効果を表す「実効」が、ここでは唯一自然に入る。", "誠実": "真心を持って誠意を尽くすこと。法律の効き目を言う文脈には入らない。", "哀愁": "しみじみとした悲しみの気持ち。罰則と結びつかず、文として不自然。", "感慨": "深く感じ入る気持ち。法律の効果を言う文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "実効"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は実効が豊富で、取引先も多い。", "explanation": "ここは〈実績〉（これまでの成果の積み重ね）の語で、会社の経歴には「実績が豊富」と言う。実効は規則や法律の効き目なので、会社の経歴には使わない。"}, {"text": "裁判所は被告に実効を言い渡した。", "explanation": "ここは〈判決〉の語で「判決を言い渡す」と言う。実効は効き目なので言い渡すことはできない。"}, {"text": "違反した店には実効を科すことになった。", "explanation": "ここは〈罰則〉（違反への処罰）の語で「罰則を科す」と言う。実効は効き目を表すので科すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実効", "is_correct": true, "explanation": "この規制が効き目を持つかどうかを表す「実効」が、「乏しく」と結び付く唯一の語。"}, {"text": "容姿", "is_correct": false, "explanation": "人の見た目を指す語。規制の効き目について述べる文には入らない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝るための場所を指す語。規制の文脈では意味が通らない。"}, {"text": "郷愁", "is_correct": false, "explanation": "故郷を懐かしむ気持ち。規制が乏しいという文とは結び付かない。"}], "explanations": {"実効": "この規制が効き目を持つかどうかを表す「実効」が、「乏しく」と結び付く唯一の語。", "容姿": "人の見た目を指す語。規制の効き目について述べる文には入らない。", "寝床": "寝るための場所を指す語。規制の文脈では意味が通らない。", "郷愁": "故郷を懐かしむ気持ち。規制が乏しいという文とは結び付かない。"}, "sentence_index": 6, "correct_answer": "実効"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は新しい実効を打つ前に、住民の意見を集めた。", "explanation": "ここは〈施策〉（政策として行う手だて）の語で「施策を打つ」と言う。実効は効き目なので打つものではない。"}, {"text": "その国は違反した企業に実効を加えた。", "explanation": "ここは〈制裁〉（罰としての不利益）の語で「制裁を加える」と言う。実効は効き目を表すので加えることはできない。"}, {"text": "警察は違反者に実効を科した。", "explanation": "ここは〈処罰〉の語で「処罰を科す」と言う。実効は効き目なので科すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "罰則を強めたことで、規則の実効を上がった。", "corrected_sentence": "罰則を強めたことで、規則の実効が上がった。", "error_description": "「上がる」は「〜が上がる」の形で使うため、実効に付く「を」は誤り。正しくは「実効が上がる」（効き目が高まる）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38961, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この規制は実効を乏しく、違反する店が増えた。", "corrected_sentence": "この規制は実効が乏しく、違反する店が増えた。", "error_description": "「乏しい」は「〜が乏しい」の形で使うため、実効に付く「を」は誤り。正しくは「実効が乏しい」（効き目が少ない）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「症状を呈する」の「を」で、呈するの目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「症状に呈していた」は動作の対象として不自然で、呈するの目的語には使わない。"}, {"text": "で", "is_correct": false, "explanation": "「症状で呈していた」は手段や場所の意味になり、目的語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「症状と呈していた」は並列の「と」になり、目的語を示す文にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「症状を呈する」の「を」で、呈するの目的語を示す。", "に": "「症状に呈していた」は動作の対象として不自然で、呈するの目的語には使わない。", "で": "「症状で呈していた」は手段や場所の意味になり、目的語を示せない。", "と": "「症状と呈していた」は並列の「と」になり、目的語を示す文にならない。"}, "error_tags": {"に": "対象・方向", "で": "手段・場所", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「光景を呈する」の「を」で、呈するの目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「光景へ呈していた」は方向の意味になり、目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「光景から呈していた」は起点の意味になり、目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「光景より呈していた」は比較の意味になり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「光景を呈する」の「を」で、呈するの目的語を示す。", "へ": "「光景へ呈していた」は方向の意味になり、目的語を示せない。", "から": "「光景から呈していた」は起点の意味になり、目的語を示せない。", "より": "「光景より呈していた」は比較の意味になり、目的語を示せない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "外に現れること。見える形になること。", "primary_collocate": null, "pronunciation": "ていする", "ipa": "teisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この液体は熱すると、赤い色を呈する。", "target_word": "呈する", "complexity_tier": "T3", "furigana": "この液体[えきたい]は熱[ねっ]すると、赤[あか]い色[いろ]を呈[てい]する。", "sentence_source": "generated"}, {"text": "患者は高い熱と発疹という症状を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "患者[かんじゃ]は高[たか]い熱[ねつ]と発疹[ほっしん]という症状[しょうじょう]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "古い建物は、近くで見ると崩れかけた無残な姿を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]は、近[ちか]くで見[み]ると崩[くず]れかけた無残[むざん]な姿[すがた]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "秋になると、山全体が燃えるような紅葉の景色を呈する。", "target_word": "呈する", "complexity_tier": "T3", "furigana": "秋[あき]になると、山全体[やまぜんたい]が燃[も]えるような紅葉[こうよう]の景色[けしき]を呈[てい]する。", "sentence_source": "generated"}, {"text": "雪解けの川は茶色く濁った様子を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "雪解[ゆきど]けの川[かわ]は茶色[ちゃいろ]く濁[にご]った様子[ようす]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "火山が噴火し、空は夕方のような不気味な色を呈した。", "target_word": "呈した", "complexity_tier": "T3", "furigana": "火山[かざん]が噴火[ふんか]し、空[そら]は夕方[ゆうがた]のような不気味[ぶきみ]な色[いろ]を呈[てい]した。", "sentence_source": "generated"}, {"text": "会議室は、対立があったとは思えないほど落ち着いた雰囲気を呈していた。", "target_word": "呈していた", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]は、対立[たいりつ]があったとは思[おも]えないほど落[お]ち着[つ]いた雰囲気[ふんいき]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "地震の後、町は瓦礫の山という悲惨な光景を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "地震[じしん]の後[あと]、町[まち]は瓦礫[がれき]の山[やま]という悲惨[ひさん]な光景[こうけい]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "土が乾くと、畑は白っぽい色を呈する。", "target_word": "呈する", "complexity_tier": "T3", "furigana": "土[つち]が乾[かわ]くと、畑[はたけ]は白[しろ]っぽい色[いろ]を呈[てい]する。", "sentence_source": "generated"}, {"text": "病気が進むと、顔色が青白く、やつれた姿を呈する場合がある。", "target_word": "呈する", "complexity_tier": "T3", "furigana": "病気[びょうき]が進[すす]むと、顔色[かおいろ]が青白[あおじろ]く、やつれた姿[すがた]を呈[てい]する場合[ばあい]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈する", "label": "辞書形"}, {"form": "呈した", "label": "過去形"}, {"form": "呈している", "label": "継続形"}], "register": "formal", "sense_fingerprint": "呈する=色・姿・症状などが外に見える形で現れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呈する", "is_correct": true, "explanation": "正解。「熱すると、赤い色を呈する」で、熱によって色が外に現れることを表す。"}, {"text": "壊す", "is_correct": false, "explanation": "「色を壊す」は成立せず、色が現れるという文意に合わない。"}, {"text": "噛む", "is_correct": false, "explanation": "「色を噛む」は意味をなさず、色が現れる場面には使えない。"}, {"text": "踏む", "is_correct": false, "explanation": "「色を踏む」は不自然で、色の出現を表す文脈に合わない。"}], "explanations": {"呈する": "正解。「熱すると、赤い色を呈する」で、熱によって色が外に現れることを表す。", "壊す": "「色を壊す」は成立せず、色が現れるという文意に合わない。", "噛む": "「色を噛む」は意味をなさず、色が現れる場面には使えない。", "踏む": "「色を踏む」は不自然で、色の出現を表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "呈する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大会で優勝し、チームは一番の座を呈した。", "explanation": "〈獲得〉の意味と取り違えやすいが、呈するは状態が外に現れる意味で、地位や座を手に入れる意味では使わない。"}, {"text": "彼は夕食の前に、窓を呈した。", "explanation": "〈開ける〉の意味。窓を開ける動作には「呈する」は使わず、この文は誤り。"}, {"text": "彼は喜びを言葉で呈した。", "explanation": "〈表す〉の意味と取り違えやすいが、「言葉で呈する」とは言わず、感情を表現する場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呈していた", "is_correct": true, "explanation": "正解。「雰囲気を呈していた」で、落ち着いた様子が外に現れていたことを表す。"}, {"text": "縫っていた", "is_correct": false, "explanation": "「雰囲気を縫っていた」は意味をなさず、この文脈に合わない。"}, {"text": "干していた", "is_correct": false, "explanation": "「雰囲気を干していた」は不自然で、雰囲気の出現を表す文脈に合わない。"}, {"text": "煮ていた", "is_correct": false, "explanation": "「雰囲気を煮ていた」は成立せず、文脈に合わない。"}], "explanations": {"呈していた": "正解。「雰囲気を呈していた」で、落ち着いた様子が外に現れていたことを表す。", "縫っていた": "「雰囲気を縫っていた」は意味をなさず、この文脈に合わない。", "干していた": "「雰囲気を干していた」は不自然で、雰囲気の出現を表す文脈に合わない。", "煮ていた": "「雰囲気を煮ていた」は成立せず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "呈していた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その政策は国民に安心を呈した。", "explanation": "〈生む〉の意味と取り違えやすいが、呈するは外に現れる様子を表し、安心をもたらす意味では使わない。"}, {"text": "彼女は三つの専門資格を呈している。", "explanation": "〈持つ〉の意味と取り違えやすいが、呈するは外に現れる様子を表す語で、資格を所持する意味では使わない。"}, {"text": "彼は大きな夢を呈している。", "explanation": "〈抱く〉の意味。呈するは外に現れる形を指すので、心に持つ夢には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋の終わり、山あいの村は一面の黄金色の景色に呈していた。", "corrected_sentence": "秋の終わり、山あいの村は一面の黄金色の景色を呈していた。", "error_description": "「呈する」の目的語（景色）には「を」を付ける。「に」は誤り。正しくは「景色を呈していた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "呈して", "is_correct": true, "explanation": "正解。「呈していた」の「て」形で、「いた」に続く形。"}, {"text": "呈し", "is_correct": false, "explanation": "連用形のみでは「いた」に続かず、「呈しいた」となって文が成立しない。"}, {"text": "呈する", "is_correct": false, "explanation": "辞書形は「いた」に直接続かず、「呈するいた」となって誤り。"}, {"text": "呈した", "is_correct": false, "explanation": "過去形を「いた」と続けると「呈したいた」となり、文法的に成立しない。"}], "correct_form": "呈して", "base_form": "呈する", "form_label": "て形", "sentence_index": 1, "explanations": {"呈して": "正解。「呈していた」の「て」形で、「いた」に続く形。", "呈し": "連用形のみでは「いた」に続かず、「呈しいた」となって文が成立しない。", "呈する": "辞書形は「いた」に直接続かず、「呈するいた」となって誤り。", "呈した": "過去形を「いた」と続けると「呈したいた」となり、文法的に成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38962, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕暮れの港は、静かな青い光を呈せていた。", "corrected_sentence": "夕暮れの港は、静かな青い光を呈していた。", "error_description": "サ変動詞「呈する」の連用形は「呈し」で、「呈せ」は誤り。正しくは「呈していた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "呈して", "is_correct": true, "explanation": "正解。「呈していた」の「て」形で、「いた」に続く形。"}, {"text": "呈しない", "is_correct": false, "explanation": "否定形は「いた」に続かず、「呈しないいた」となって成立しない。"}, {"text": "呈しよう", "is_correct": false, "explanation": "意志形は「いた」に続かず、「呈しようていた」を含めても文法的に成立しない。"}, {"text": "呈せず", "is_correct": false, "explanation": "「ず」形は「いた」に続かず、文が成立しない。"}], "correct_form": "呈して", "base_form": "呈する", "form_label": "て形", "sentence_index": 7, "explanations": {"呈して": "正解。「呈していた」の「て」形で、「いた」に続く形。", "呈しない": "否定形は「いた」に続かず、「呈しないいた」となって成立しない。", "呈しよう": "意志形は「いた」に続かず、「呈しようていた」を含めても文法的に成立しない。", "呈せず": "「ず」形は「いた」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「様相を呈する」の「を」で、呈するの目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「様相に呈していた」は対象の意味として不自然で、目的語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「様相で呈していた」は手段の意味になり、目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「様相へ呈していた」は方向の意味になり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「様相を呈する」の「を」で、呈するの目的語を示す。", "に": "「様相に呈していた」は対象の意味として不自然で、目的語を示せない。", "で": "「様相で呈していた」は手段の意味になり、目的語を示せない。", "へ": "「様相へ呈していた」は方向の意味になり、目的語を示せない。"}, "error_tags": {"に": "対象・結果", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「混乱を呈する」の「を」で、呈するの目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「混乱と呈していた」は並列の意味になり、目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「混乱より呈していた」は比較の意味になり、目的語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「混乱の呈していた」は連体修飾の形になり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「混乱を呈する」の「を」で、呈するの目的語を示す。", "と": "「混乱と呈していた」は並列の意味になり、目的語を示せない。", "より": "「混乱より呈していた」は比較の意味になり、目的語を示せない。", "の": "「混乱の呈していた」は連体修飾の形になり、目的語を示せない。"}, "error_tags": {"と": "並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の状態や形が外に現れること。", "primary_collocate": "様相", "pronunciation": "ていする", "ipa": "teisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "年末の商店街は買い物客で、活況を呈している。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "年末[ねんまつ]の商店街[しょうてんがい]は買[か]い物客[ものきゃく]で、活況[かっきょう]を呈[てい]している。", "sentence_source": "generated"}, {"text": "選挙が近づき、町は混乱した様相を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "選挙[せんきょ]が近[ちか]づき、町[まち]は混乱[こんらん]した様相[ようそう]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "新しい規則をめぐる議論は、泥沼の様相を呈してきた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "新[あたら]しい規則[きそく]をめぐる議論[ぎろん]は、泥沼[どろぬま]の様相[ようそう]を呈[てい]してきた。", "sentence_source": "generated"}, {"text": "連休の観光地は、どこも人であふれ、賑わいを呈する。", "target_word": "呈する", "complexity_tier": "T3", "furigana": "連休[れんきゅう]の観光地[かんこうち]は、どこも人[ひと]であふれ、賑[にぎ]わいを呈[てい]する。", "sentence_source": "generated"}, {"text": "景気が回復し、株式市場は活況を呈した。", "target_word": "呈した", "complexity_tier": "T3", "furigana": "景気[けいき]が回復[かいふく]し、株式市場[かぶしきしじょう]は活況[かっきょう]を呈[てい]した。", "sentence_source": "generated"}, {"text": "事故の直後、駅は大混乱の様相を呈した。", "target_word": "呈した", "complexity_tier": "T3", "furigana": "事故[じこ]の直後[ちょくご]、駅[えき]は大混乱[だいこんらん]の様相[ようそう]を呈[てい]した。", "sentence_source": "generated"}, {"text": "両チームの試合は、終盤になって激戦の様相を呈する。", "target_word": "呈する", "complexity_tier": "T3", "furigana": "両[りょう]チームの試合[しあい]は、終盤[しゅうばん]になって激戦[げきせん]の様相[ようそう]を呈[てい]する。", "sentence_source": "generated"}, {"text": "台風の影響で、空港は欠航が相次ぎ、混乱を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、空港[くうこう]は欠航[けっこう]が相次[あいつ]ぎ、混乱[こんらん]を呈[てい]していた。", "sentence_source": "generated"}, {"text": "交渉は行き詰まり、会議は険悪な雰囲気を呈してきた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "交渉[こうしょう]は行[い]き詰[づ]まり、会議[かいぎ]は険悪[けんあく]な雰囲気[ふんいき]を呈[てい]してきた。", "sentence_source": "generated"}, {"text": "祭りの夜、神社の周りは華やかな景色を呈していた。", "target_word": "呈して", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、神社[じんじゃ]の周[まわ]りは華[はな]やかな景色[けしき]を呈[てい]していた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈する", "label": "辞書形"}, {"form": "呈した", "label": "過去形"}, {"form": "呈している", "label": "継続形"}], "register": "formal", "sense_fingerprint": "呈する=物事の状態・様子(活況・混乱など)が外に現れる", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呈して", "is_correct": true, "explanation": "正解。「活況を呈している」で、活気のある状態が外に現れていることを表す。"}, {"text": "抱いて", "is_correct": false, "explanation": "「活況を抱いている」は不自然で、状態が現れる文脈に合わない。"}, {"text": "担いで", "is_correct": false, "explanation": "「活況を担いでいる」は成立せず、文脈に合わない。"}, {"text": "刻んで", "is_correct": false, "explanation": "「活況を刻んでいる」は意味をなさず、文脈に合わない。"}], "explanations": {"呈して": "正解。「活況を呈している」で、活気のある状態が外に現れていることを表す。", "抱いて": "「活況を抱いている」は不自然で、状態が現れる文脈に合わない。", "担いで": "「活況を担いでいる」は成立せず、文脈に合わない。", "刻んで": "「活況を刻んでいる」は意味をなさず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "呈して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨が屋根の瓦を呈した。", "explanation": "〈落とす〉の意味。瓦を落とす行為には「呈する」は使わず、この文は誤り。"}, {"text": "その薬は患者に安らぎを呈した。", "explanation": "〈もたらす〉の意味と取り違えやすいが、呈するは状態が外に現れる意味で、効果を与える意味では使わない。"}, {"text": "新作の発表会は大勢の観客を呈した。", "explanation": "〈集める〉の意味。呈するは物事の状態を表す語で、人を集める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呈する", "is_correct": true, "explanation": "正解。「激戦の様相を呈する」で、試合の状況が外に現れることを表す。"}, {"text": "研ぐ", "is_correct": false, "explanation": "「様相を研ぐ」は成立せず、文脈に合わない。"}, {"text": "炊く", "is_correct": false, "explanation": "「様相を炊く」は意味をなさず、文脈に合わない。"}, {"text": "縫う", "is_correct": false, "explanation": "「様相を縫う」は成立せず、状況が現れる文脈に合わない。"}], "explanations": {"呈する": "正解。「激戦の様相を呈する」で、試合の状況が外に現れることを表す。", "研ぐ": "「様相を研ぐ」は成立せず、文脈に合わない。", "炊く": "「様相を炊く」は意味をなさず、文脈に合わない。", "縫う": "「様相を縫う」は成立せず、状況が現れる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "呈する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は毎年、盛大な式典を呈している。", "explanation": "〈行う〉の意味と取り違えやすいが、呈するは状態が外に現れる意味で、式典を開く意味では使わない。"}, {"text": "町は大規模な祭りを呈した。", "explanation": "〈催す〉の意味と取り違えやすいが、呈するは催しを開く意味を持たず、状況の出現を表す。"}, {"text": "彼女は議長を呈した。", "explanation": "〈務める〉の意味。呈するは役割を担う意味ではなく、状態が外に現れる意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨のあと、川べりの道は泥だらけの様相が呈していた。", "corrected_sentence": "大雨のあと、川べりの道は泥だらけの様相を呈していた。", "error_description": "「呈する」の目的語（様相）には「を」を付ける。「が」は誤り。正しくは「様相を呈していた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "呈して", "is_correct": true, "explanation": "正解。「呈していた」の「て」形で、「いた」に続く形。"}, {"text": "呈し", "is_correct": false, "explanation": "連用形のみでは「いた」に続かず、「呈しいた」となって成立しない。"}, {"text": "呈する", "is_correct": false, "explanation": "辞書形は「いた」に直接続かず、「呈するいた」となって誤り。"}, {"text": "呈した", "is_correct": false, "explanation": "過去形を「いた」と続けると「呈したいた」となり、文法的に成立しない。"}], "correct_form": "呈して", "base_form": "呈する", "form_label": "て形", "sentence_index": 1, "explanations": {"呈して": "正解。「呈していた」の「て」形で、「いた」に続く形。", "呈し": "連用形のみでは「いた」に続かず、「呈しいた」となって成立しない。", "呈する": "辞書形は「いた」に直接続かず、「呈するいた」となって誤り。", "呈した": "過去形を「いた」と続けると「呈したいた」となり、文法的に成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38963, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏祭りの夜、広場は賑やかな様相呈していた。", "corrected_sentence": "夏祭りの夜、広場は賑やかな様相を呈していた。", "error_description": "「呈する」の目的語（様相）に付く「を」が抜けている。正しくは「様相を呈していた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "呈して", "is_correct": true, "explanation": "正解。「呈していた」の「て」形で、「いた」に続く形。"}, {"text": "呈しない", "is_correct": false, "explanation": "否定形は「いた」に続かず、「呈しないいた」となって成立しない。"}, {"text": "呈しよう", "is_correct": false, "explanation": "意志形は「いた」に続かず、文法的に成立しない。"}, {"text": "呈せず", "is_correct": false, "explanation": "「ず」形は「いた」に続かず、文が成立しない。"}], "correct_form": "呈して", "base_form": "呈する", "form_label": "て形", "sentence_index": 7, "explanations": {"呈して": "正解。「呈していた」の「て」形で、「いた」に続く形。", "呈しない": "否定形は「いた」に続かず、「呈しないいた」となって成立しない。", "呈しよう": "意志形は「いた」に続かず、文法的に成立しない。", "呈せず": "「ず」形は「いた」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「欧州を旅行する」の「を」で、旅行する対象の地域を示す。正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「欧州が旅行する」だと欧州が主語になり、旅行の対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "「欧州に旅行する」は動作の対象を示せず、文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「欧州と旅行する」は一緒に旅行する相手の意味になり、地域を示せない。"}], "correct_answer": "を", "explanations": {"を": "「欧州を旅行する」の「を」で、旅行する対象の地域を示す。正しい助詞。", "が": "「欧州が旅行する」だと欧州が主語になり、旅行の対象にならない。", "に": "「欧州に旅行する」は動作の対象を示せず、文として不自然。", "と": "「欧州と旅行する」は一緒に旅行する相手の意味になり、地域を示せない。"}, "error_tags": {"が": "主語", "に": "位置・時", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「欧州から来た先生」の「から」で、来る動作の出発点を示す。正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「欧州を来た先生」は動作の対象を示すが、来る動作の起点にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「欧州で来た先生」は場所の意味になり、来る動作の出発点を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「欧州の来た先生」は連体修飾として不自然で、来る動作の起点にならない。"}], "correct_answer": "から", "explanations": {"から": "「欧州から来た先生」の「から」で、来る動作の出発点を示す。正しい助詞。", "を": "「欧州を来た先生」は動作の対象を示すが、来る動作の起点にならず不自然。", "で": "「欧州で来た先生」は場所の意味になり、来る動作の出発点を示せない。", "の": "「欧州の来た先生」は連体修飾として不自然で、来る動作の起点にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ヨーロッパの こと。", "primary_collocate": null, "pronunciation": "おうしゅう", "ipa": "oːɕɯː", "syllable_count": 4, "sentences": [{"text": "欧州へ行く飛行機は、毎日この空港から出ている。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]へ行[い]く飛行機[ひこうき]は、毎日[まいにち]この空港[くうこう]から出[で]ている。", "sentence_source": "generated"}, {"text": "彼女は夏休みに欧州を旅行する予定だ。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は夏休[なつやす]みに欧州[おうしゅう]を旅行[りょこう]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "欧州の国々は、地図の上ではとても近い。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]の国々[くにぐに]は、地図[ちず]の上[うえ]ではとても近[ちか]い。", "sentence_source": "generated"}, {"text": "兄は大学を出てから、欧州で五年間働いた。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]を出[で]てから、欧州[おうしゅう]で五年間[ごねんかん]働[はたら]いた。", "sentence_source": "generated"}, {"text": "欧州にはまだ行ったことがないので、来年は行きたい。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]にはまだ行[い]ったことがないので、来年[らいねん]は行[い]きたい。", "sentence_source": "generated"}, {"text": "この料理は欧州で生まれ、世界中に広まった。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "この料理[りょうり]は欧州[おうしゅう]で生[う]まれ、世界中[せかいじゅう]に広[ひろ]まった。", "sentence_source": "generated"}, {"text": "欧州の冬は寒いので、厚いコートを持っていく。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]の冬[ふゆ]は寒[さむ]いので、厚[あつ]いコートを持[も]っていく。", "sentence_source": "generated"}, {"text": "欧州から来た先生が、授業で自分の国の話をした。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]から来[き]た先生[せんせい]が、授業[じゅぎょう]で自分[じぶん]の国[くに]の話[はなし]をした。", "sentence_source": "generated"}, {"text": "父は仕事で、アジアと欧州を行き来している。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]で、アジアと欧州[おうしゅう]を行[い]き来[き]している。", "sentence_source": "generated"}, {"text": "欧州の古い町を歩くと、昔の建物がたくさん残っている。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]の古[ふる]い町[まち]を歩[ある]くと、昔[むかし]の建物[たてもの]がたくさん残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欧州", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ヨーロッパという地域を指す呼び方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欧州", "is_correct": true, "explanation": "「欧州へ行く」で行き先の地域を示し、飛行機の行き先として文脈に合う。"}, {"text": "切符", "is_correct": false, "explanation": "行き先の地域を表さない名詞で、「切符へ行く」は意味が通らない。"}, {"text": "乗客", "is_correct": false, "explanation": "人を指す語で、「乗客へ行く飛行機」は成り立たない。"}, {"text": "荷物", "is_correct": false, "explanation": "行き先にはならない物で、「荷物へ行く飛行機」は不自然。"}], "explanations": {"欧州": "「欧州へ行く」で行き先の地域を示し、飛行機の行き先として文脈に合う。", "切符": "行き先の地域を表さない名詞で、「切符へ行く」は意味が通らない。", "乗客": "人を指す語で、「乗客へ行く飛行機」は成り立たない。", "荷物": "行き先にはならない物で、「荷物へ行く飛行機」は不自然。"}, "sentence_index": 0, "correct_answer": "欧州"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欧州の首相が、日本に来て会議を開いた。", "explanation": "ここは〈国〉の意味。欧州は複数の国をまとめた地域名なので、一人の首相がいるという文とは合わない。"}, {"text": "欧州の王様が、教室で子どもたちに絵本を読んだ。", "explanation": "ここは〈王族〉の意味。欧州は地域名で、一人の王様として教室で本を読む文とは合わない。"}, {"text": "欧州が笑って、部屋の皆に手を振った。", "explanation": "ここは〈人〉の意味。欧州は地域名で、笑ったり手を振ったりする人のようには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欧州", "is_correct": true, "explanation": "「欧州の冬」で地域を示し、寒い冬の話の主語として文脈に合う。"}, {"text": "週末", "is_correct": false, "explanation": "時間の語で、「週末の冬」は意味が通らない。"}, {"text": "試験", "is_correct": false, "explanation": "学習の場面の語で、冬の気候を表す文には合わない。"}, {"text": "給料", "is_correct": false, "explanation": "お金に関する語で、冬の気候を表す文とは合わない。"}], "explanations": {"欧州": "「欧州の冬」で地域を示し、寒い冬の話の主語として文脈に合う。", "週末": "時間の語で、「週末の冬」は意味が通らない。", "試験": "学習の場面の語で、冬の気候を表す文には合わない。", "給料": "お金に関する語で、冬の気候を表す文とは合わない。"}, "sentence_index": 6, "correct_answer": "欧州"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "欧州が一人で、三時間会議に出席した。", "explanation": "ここは〈人〉の意味。欧州は地域名で、会議に出席する個人のようには使わない。"}, {"text": "欧州を読んで、宿題の答えを書いた。", "explanation": "ここは〈文章〉の意味。欧州は地域名で、読んで答えを書く対象にはならない。"}, {"text": "欧州が明日、雨を降らせて、運動会を中止にした。", "explanation": "ここは〈天候〉の意味。欧州は地域名で、雨を降らせる主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は欧州を大学で経済を学んでいる。", "corrected_sentence": "兄は欧州の大学で経済を学んでいる。", "error_description": "「欧州の大学」は所属を表す「の」。「欧州を大学で」と「を」を使うと、欧州が目的語になり意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38964, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は欧州が留学した経験がある。", "corrected_sentence": "祖父は欧州へ留学した経験がある。", "error_description": "「欧州が留学した」だと欧州が主語になってしまう。留学先の方向を示す「へ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「欧州の主な国」の「の」で、所属を示す。欧州の中の国々という関係を表す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「欧州が主な国」だと欧州が主語になり、直後の「の」と文の構造が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「欧州を主な国」は目的語になり、所属の関係を示せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「欧州に主な国」は位置を示すが、所属の関係を表さず不自然。"}], "correct_answer": "の", "explanations": {"の": "「欧州の主な国」の「の」で、所属を示す。欧州の中の国々という関係を表す正しい助詞。", "が": "「欧州が主な国」だと欧州が主語になり、直後の「の」と文の構造が崩れる。", "を": "「欧州を主な国」は目的語になり、所属の関係を示せず不自然。", "に": "「欧州に主な国」は位置を示すが、所属の関係を表さず不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「欧州の歴史」の「の」で、歴史の範囲が欧州であることを示す。正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「欧州を歴史を学ぶ」は目的語が二つ重なり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「欧州へ歴史を学ぶ授業」は方向の意味になり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「欧州より歴史」は所属の関係を示せず不自然。"}], "correct_answer": "の", "explanations": {"の": "「欧州の歴史」の「の」で、歴史の範囲が欧州であることを示す。正しい助詞。", "を": "「欧州を歴史を学ぶ」は目的語が二つ重なり不自然。", "へ": "「欧州へ歴史を学ぶ授業」は方向の意味になり、不自然。", "より": "比較の助詞で、「欧州より歴史」は所属の関係を示せず不自然。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "欧州。ヨーロッパのこと。", "primary_collocate": null, "pronunciation": "おうしゅう", "ipa": "oːɕɯː", "syllable_count": 4, "sentences": [{"text": "今年は欧州の経済が少しずつ回復している。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "今年[ことし]は欧州[おうしゅう]の経済[けいざい]が少[すこ]しずつ回復[かいふく]している。", "sentence_source": "generated"}, {"text": "欧州の主な国の首脳が、今日会議を開く。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]の主[おも]な国[くに]の首脳[しゅのう]が、今日[きょう]会議[かいぎ]を開[ひら]く。", "sentence_source": "generated"}, {"text": "この車は欧州で人気があり、よく売れている。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "この車[くるま]は欧州[おうしゅう]で人気[にんき]があり、よく売[う]れている。", "sentence_source": "generated"}, {"text": "欧州の大学に留学する学生が増えている。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]の大学[だいがく]に留学[りゅうがく]する学生[がくせい]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "欧州各地で、大雨による被害が出た。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]各地[かくち]で、大雨[おおあめ]による被害[ひがい]が出[で]た。", "sentence_source": "generated"}, {"text": "日本から欧州までは、飛行機で十二時間ほどかかる。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "日本[にほん]から欧州[おうしゅう]までは、飛行機[ひこうき]で十二時間[じゅうにじかん]ほどかかる。", "sentence_source": "generated"}, {"text": "欧州で作られたワインを、店で買ってきた。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]で作[つく]られたワインを、店[みせ]で買[か]ってきた。", "sentence_source": "generated"}, {"text": "欧州の歴史を学ぶ授業が、来週から始まる。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]の歴史[れきし]を学[まな]ぶ授業[じゅぎょう]が、来週[らいしゅう]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "彼は欧州の言葉を三つも話せる。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "彼[かれ]は欧州[おうしゅう]の言葉[ことば]を三[みっ]つも話[はな]せる。", "sentence_source": "generated"}, {"text": "欧州に住む友達から、写真つきの手紙が届いた。", "target_word": "欧州", "complexity_tier": "T3", "furigana": "欧州[おうしゅう]に住[す]む友達[ともだち]から、写真[しゃしん]つきの手紙[てがみ]が届[とど]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欧州", "label": "基本形"}], "register": "formal", "sense_fingerprint": "ニュースや文章で使われる、ヨーロッパを表す漢語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欧州", "is_correct": true, "explanation": "「欧州の経済」で地域を示し、ヨーロッパの経済が回復しているという文脈に合う。"}, {"text": "週末", "is_correct": false, "explanation": "時間の語で、「週末の経済」は意味が通らない。"}, {"text": "試験", "is_correct": false, "explanation": "学習の場面の語で、経済の話題とは合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "学校の課題を表す語で、経済が回復するという文には合わない。"}], "explanations": {"欧州": "「欧州の経済」で地域を示し、ヨーロッパの経済が回復しているという文脈に合う。", "週末": "時間の語で、「週末の経済」は意味が通らない。", "試験": "学習の場面の語で、経済の話題とは合わない。", "宿題": "学校の課題を表す語で、経済が回復するという文には合わない。"}, "sentence_index": 0, "correct_answer": "欧州"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欧州の大統領が、来月東京で記者会見を開く。", "explanation": "欧州は地域名で、大統領のような国家元首とは結びつかない。"}, {"text": "欧州の女王が、来月市民に新しい計画を説明した。", "explanation": "ここは〈王族〉の意味。欧州は地域名で、女王として計画を説明する主体にはならない。"}, {"text": "欧州が明日、雨を降らせて、遠足を中止にした。", "explanation": "ここは〈天候〉の意味。欧州は地域名で、雨を降らせる主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欧州", "is_correct": true, "explanation": "「欧州で作られたワイン」で産地を示し、店で買ったワインの話として文脈に合う。"}, {"text": "夢", "is_correct": false, "explanation": "抽象的な語で、ワインの産地や作られた場所を表さず、文が成り立たない。"}, {"text": "朝食", "is_correct": false, "explanation": "食事の時間を表す語で、ワインの産地を示せない。"}, {"text": "演劇", "is_correct": false, "explanation": "舞台芸術の語で、ワインの作られた場所を示す文には合わない。"}], "explanations": {"欧州": "「欧州で作られたワイン」で産地を示し、店で買ったワインの話として文脈に合う。", "夢": "抽象的な語で、ワインの産地や作られた場所を表さず、文が成り立たない。", "朝食": "食事の時間を表す語で、ワインの産地を示せない。", "演劇": "舞台芸術の語で、ワインの作られた場所を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "欧州"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "欧州が昨日、会社に電話をかけてきた。", "explanation": "ここは〈人〉の意味。欧州は地域名で、電話をかける人のようには使わない。"}, {"text": "欧州が一人で、三時間会議に出席した。", "explanation": "欧州は地域名で、人のように会議に出席する主体にはならない。"}, {"text": "欧州を読んで、宿題の答えを書いた。", "explanation": "ここは〈文章〉の意味。欧州は地域名で、読んで答えを書く対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "欧州を企業が、新しい工場を建てる計画を発表した。", "corrected_sentence": "欧州の企業が、新しい工場を建てる計画を発表した。", "error_description": "「欧州の企業」は所属を表す「の」が正しい。「欧州を企業が」では欧州が目的語になり、文の流れが不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38965, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は欧州が帰国して、会議に出席した。", "corrected_sentence": "彼は欧州から帰国して、会議に出席した。", "error_description": "「欧州が帰国」は欧州を主語にしてしまう誤り。出発地を示す「から」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
