INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38966, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「学校同士の連合により」の「に」で、「により」の一部として連合に続く。"}, {"text": "を", "is_correct": false, "explanation": "「連合を、より大きな大会が実現した」は連合を目的語に取る動詞がなく不自然。"}, {"text": "と", "is_correct": false, "explanation": "「学校同士の連合と、より」は文法的に成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「学校同士の連合へ、より」は方向の意味になり、「により」の形にならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「学校同士の連合により」の「に」で、「により」の一部として連合に続く。", "を": "「連合を、より大きな大会が実現した」は連合を目的語に取る動詞がなく不自然。", "と": "「学校同士の連合と、より」は文法的に成立しない。", "へ": "「学校同士の連合へ、より」は方向の意味になり、「により」の形にならない。"}, "error_tags": {"を": "目的", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38966, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものが一緒になること。", "primary_collocate": null, "pronunciation": "れんごう", "ipa": "ɾeŋɡoː", "syllable_count": 4, "sentences": [{"text": "小さな会社が三つ連合して、新しい事業を始めた。", "target_word": "連合", "complexity_tier": "T3", "furigana": "小[ちい]さな会社[かいしゃ]が三[みっ]つ連合[れんごう]して、新[あたら]しい事業[じぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "弱いチームでも、連合すれば強い相手に勝てるかもしれない。", "target_word": "連合", "complexity_tier": "T3", "furigana": "弱[よわ]いチームでも、連合[れんごう]すれば強[つよ]い相手[あいて]に勝[か]てるかもしれない。", "sentence_source": "generated"}, {"text": "各国は貿易の問題で連合し、共同で声明を出した。", "target_word": "連合", "complexity_tier": "T3", "furigana": "各国[かっこく]は貿易[ぼうえき]の問題[もんだい]で連合[れんごう]し、共同[きょうどう]で声明[せいめい]を出[だ]した。", "sentence_source": "generated"}, {"text": "二つの町が連合して、一つの祭りを開くことになった。", "target_word": "連合", "complexity_tier": "T3", "furigana": "二[ふた]つの町[まち]が連合[れんごう]して、一[ひと]つの祭[まつ]りを開[ひら]くことになった。", "sentence_source": "generated"}, {"text": "野党が連合したので、与党は苦しい立場になった。", "target_word": "連合", "complexity_tier": "T3", "furigana": "野党[やとう]が連合[れんごう]したので、与党[よとう]は苦[くる]しい立場[たちば]になった。", "sentence_source": "generated"}, {"text": "単独では無理でも、他の店と連合すれば広告費を減らせる。", "target_word": "連合", "complexity_tier": "T3", "furigana": "単独[たんどく]では無理[むり]でも、他[ほか]の店[みせ]と連合[れんごう]すれば広告費[こうこくひ]を減[へ]らせる。", "sentence_source": "generated"}, {"text": "小さな農家が連合して、野菜を共同で売り始めた。", "target_word": "連合", "complexity_tier": "T3", "furigana": "小[ちい]さな農家[のうか]が連合[れんごう]して、野菜[やさい]を共同[きょうどう]で売[う]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "学校同士の連合により、大きな大会が実現した。", "target_word": "連合", "complexity_tier": "T3", "furigana": "学校同士[がっこうどうし]の連合[れんごう]により、大[おお]きな大会[たいかい]が実現[じつげん]した。", "sentence_source": "generated"}, {"text": "弱点を補い合うため、同業の団体が連合することにした。", "target_word": "連合", "complexity_tier": "T3", "furigana": "弱点[じゃくてん]を補[おぎな]い合[あ]うため、同業[どうぎょう]の団体[だんたい]が連合[れんごう]することにした。", "sentence_source": "generated"}, {"text": "三つの村は連合して、川の水を分け合う約束をした。", "target_word": "連合", "complexity_tier": "T3", "furigana": "三[みっ]つの村[むら]は連合[れんごう]して、川[かわ]の水[みず]を分[わ]け合[あ]う約束[やくそく]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連合する", "label": "辞書形"}, {"form": "連合した", "label": "過去形"}, {"form": "連合して", "label": "て形"}], "register": "formal", "sense_fingerprint": "連合=複数の団体・国・組織が力を合わせて一緒になること(動作)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 補い合う (Zipf 1.56)']::text[], '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38966, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連合", "is_correct": true, "explanation": "正解。「三つ連合して」で、三つの会社が力を合わせて一緒になることを表す。"}, {"text": "回避", "is_correct": false, "explanation": "「三つ回避して」は意味をなさず、一緒になる動作の文脈に合わない。"}, {"text": "解釈", "is_correct": false, "explanation": "「三つ解釈して」は成立せず、会社が一緒になる文脈に合わない。"}, {"text": "誤解", "is_correct": false, "explanation": "「三つ誤解して」は意味をなさず、文脈に合わない。"}], "explanations": {"連合": "正解。「三つ連合して」で、三つの会社が力を合わせて一緒になることを表す。", "回避": "「三つ回避して」は意味をなさず、一緒になる動作の文脈に合わない。", "解釈": "「三つ解釈して」は成立せず、会社が一緒になる文脈に合わない。", "誤解": "「三つ誤解して」は意味をなさず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "連合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "観客が会場に連合した。", "explanation": "〈集まる〉の意味と取り違えやすいが、連合は団体や国などが力を合わせる意味で、個人の観客には使わない。"}, {"text": "二台の車が連合して、大きな事故を起こした。", "explanation": "〈衝突〉の意味と取り違えやすいが、連合は一緒になる意味で、ぶつかる意味では使わない。"}, {"text": "二つの川は下流で連合する。", "explanation": "〈合流〉と取り違えやすいが、連合は団体などの結びつきに使い、川の流れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38966, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連合", "is_correct": true, "explanation": "正解。「小さな農家が連合して」で、農家が力を合わせて一緒になることを表す。"}, {"text": "点火", "is_correct": false, "explanation": "「小さな農家が点火して」は成立せず、文脈に合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "「小さな農家が採掘して」は意味が合わず、文脈に合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "「小さな農家が撮影して」は文脈に合わず、一緒になる動作を表さない。"}], "explanations": {"連合": "正解。「小さな農家が連合して」で、農家が力を合わせて一緒になることを表す。", "点火": "「小さな農家が点火して」は成立せず、文脈に合わない。", "採掘": "「小さな農家が採掘して」は意味が合わず、文脈に合わない。", "撮影": "「小さな農家が撮影して」は文脈に合わず、一緒になる動作を表さない。"}, "sentence_index": 6, "correct_answer": "連合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三つの村は水の利用について協定を連合した。", "explanation": "〈結ぶ〉の意味と取り違えやすいが、連合は団体が力を合わせる意味で、協定を結ぶ動作の言い方ではない。"}, {"text": "三つの村は川の水を三つに連合した。", "explanation": "〈分ける〉の意味と取り違えやすいが、連合は一緒になる意味で、分割には使わない。"}, {"text": "村人たちは食べ物を一つの広場に連合した。", "explanation": "〈持ち寄る〉の意味。連合は団体の結びつきを表し、人が物を集める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38966, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大手の二社が地方の三社に連合して、販売網を広げた。", "corrected_sentence": "大手の二社が地方の三社と連合して、販売網を広げた。", "error_description": "「連合する」の相手は「と」で示す。「に」は誤り。正しくは「三社と連合して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38966, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三つの団体は連合ずに、会議を開いた。", "corrected_sentence": "三つの団体は連合せずに、会議を開いた。", "error_description": "サ変動詞「連合する」の未然形に「ず」を付けるには「連合せず」となる。「連合ず」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「連合に加わる」の「に」で、加わる先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「連合を、十の団体が加わっている」は加わる先を示せず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「その連合がは」は助詞が重なり成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「連合の、十の団体が加わっている」は連体修飾の形になり、加わる先を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「連合に加わる」の「に」で、加わる先を示す。", "を": "「連合を、十の団体が加わっている」は加わる先を示せず、不自然。", "が": "「その連合がは」は助詞が重なり成立しない。", "の": "「連合の、十の団体が加わっている」は連体修飾の形になり、加わる先を示せない。"}, "error_tags": {"を": "対象", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「部族の連合が広い土地を治めていた」の「が」で、連合が主語であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「部族の連合を広い土地を治めていた」は目的語が二つ重なり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「部族の連合へ広い土地を治めていた」は方向の意味になり、主語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「部族の連合から広い土地を治めていた」は起点の意味になり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「部族の連合が広い土地を治めていた」の「が」で、連合が主語であることを示す。", "を": "「部族の連合を広い土地を治めていた」は目的語が二つ重なり不自然。", "へ": "「部族の連合へ広い土地を治めていた」は方向の意味になり、主語を示せない。", "から": "「部族の連合から広い土地を治めていた」は起点の意味になり、主語を示せない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数のものが結びついて一つのまとまりになること。また、そのまとまり。", "primary_collocate": null, "pronunciation": "れんごう", "ipa": "ɾeŋɡoː", "syllable_count": 4, "sentences": [{"text": "労働者たちは連合を作り、会社と賃金の話し合いをした。", "target_word": "連合", "complexity_tier": "T3", "furigana": "労働者[ろうどうしゃ]たちは連合[れんごう]を作[つく]り、会社[かいしゃ]と賃金[ちんぎん]の話[はな]し合[あ]いをした。", "sentence_source": "generated"}, {"text": "その連合には、十の団体が加わっている。", "target_word": "連合", "complexity_tier": "T3", "furigana": "その連合[れんごう]には、十[じゅう]の団体[だんたい]が加[くわ]わっている。", "sentence_source": "generated"}, {"text": "連合の代表が、記者会見で今後の方針を話した。", "target_word": "連合", "complexity_tier": "T3", "furigana": "連合[れんごう]の代表[だいひょう]が、記者会見[きしゃかいけん]で今後[こんご]の方針[ほうしん]を話[はな]した。", "sentence_source": "generated"}, {"text": "小さな国々は連合を組んで、大国に対抗しようとした。", "target_word": "連合", "complexity_tier": "T3", "furigana": "小[ちい]さな国々[くにぐに]は連合[れんごう]を組[く]んで、大国[たいこく]に対抗[たいこう]しようとした。", "sentence_source": "generated"}, {"text": "農家の連合が、新しい販売所を駅前に開いた。", "target_word": "連合", "complexity_tier": "T3", "furigana": "農家[のうか]の連合[れんごう]が、新[あたら]しい販売所[はんばいじょ]を駅前[えきまえ]に開[ひら]いた。", "sentence_source": "generated"}, {"text": "この連合は、五つの大学が協力してできたものだ。", "target_word": "連合", "complexity_tier": "T3", "furigana": "この連合[れんごう]は、五[いつ]つの大学[だいがく]が協力[きょうりょく]してできたものだ。", "sentence_source": "generated"}, {"text": "連合に入れば、会員同士で情報を共有できる。", "target_word": "連合", "complexity_tier": "T3", "furigana": "連合[れんごう]に入[はい]れば、会員同士[かいいんどうし]で情報[じょうほう]を共有[きょうゆう]できる。", "sentence_source": "generated"}, {"text": "古い時代、部族の連合が広い土地を治めていた。", "target_word": "連合", "complexity_tier": "T3", "furigana": "古[ふる]い時代[じだい]、部族[ぶぞく]の連合[れんごう]が広[ひろ]い土地[とち]を治[おさ]めていた。", "sentence_source": "generated"}, {"text": "連合から抜けたいと言う団体が出てきた。", "target_word": "連合", "complexity_tier": "T3", "furigana": "連合[れんごう]から抜[ぬ]けたいと言[い]う団体[だんたい]が出[で]てきた。", "sentence_source": "generated"}, {"text": "連合の会議は、毎月第一月曜日に開かれる。", "target_word": "連合", "complexity_tier": "T3", "furigana": "連合[れんごう]の会議[かいぎ]は、毎月[まいつき]第一月曜日[だいいちげつようび]に開[ひら]かれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連合する", "label": "辞書形"}, {"form": "連合した", "label": "過去形"}, {"form": "連合の", "label": "連体修飾"}], "register": "formal", "sense_fingerprint": "連合=複数が結びついてできた団体・組織(まとまりそのもの)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連合", "is_correct": true, "explanation": "正解。「連合を作り」で、団体や組織としてのまとまりを表す。"}, {"text": "回避", "is_correct": false, "explanation": "「回避を作り」は成立せず、組織を指す文脈に合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "「欠席を作り」は意味をなさず、組織を作る文脈に合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "「撮影を作り」は文脈に合わず、組織を作る動作と結びつかない。"}], "explanations": {"連合": "正解。「連合を作り」で、団体や組織としてのまとまりを表す。", "回避": "「回避を作り」は成立せず、組織を指す文脈に合わない。", "欠席": "「欠席を作り」は意味をなさず、組織を作る文脈に合わない。", "撮影": "「撮影を作り」は文脈に合わず、組織を作る動作と結びつかない。"}, "sentence_index": 0, "correct_answer": "連合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が三日間の連合で降り続いた。", "explanation": "〈連続〉の意味と取り違えやすいが、連合はまとまりを表す語で、途切れずに続く意味では使わない。"}, {"text": "選手たちは強い連合を見せた。", "explanation": "〈団結〉と取り違えやすいが、連合は団体そのものを指し、人の結束の強さは表せない。"}, {"text": "夫婦は長い年月で連合を深めた。", "explanation": "〈絆〉の意味と取り違えやすいが、連合は個人の結びつきには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連合", "is_correct": true, "explanation": "正解。「連合に入れば」で、団体や組織としての連合に加わることを表す。"}, {"text": "清掃", "is_correct": false, "explanation": "「清掃に入れば」は組織に加わる意味にならず、文脈に合わない。"}, {"text": "解剖", "is_correct": false, "explanation": "「解剖に入れば」は意味をなさず、組織への加入を表さない。"}, {"text": "採掘", "is_correct": false, "explanation": "「採掘に入れば」は組織に加わる意味にならず、文脈に合わない。"}], "explanations": {"連合": "正解。「連合に入れば」で、団体や組織としての連合に加わることを表す。", "清掃": "「清掃に入れば」は組織に加わる意味にならず、文脈に合わない。", "解剖": "「解剖に入れば」は意味をなさず、組織への加入を表さない。", "採掘": "「採掘に入れば」は組織に加わる意味にならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "連合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長年の研究の連合が、この一冊の本だ。", "explanation": "〈結晶〉の意味と取り違えやすいが、連合は団体やまとまりを指し、研究の成果には使わない。"}, {"text": "資料は種類ごとに連合された。", "explanation": "〈分類〉の意味と取り違えやすいが、連合は結びつけてまとまりを作る意味で、分ける作業には使わない。"}, {"text": "部屋を連合した。", "explanation": "〈整理〉の意味。連合は団体の結びつきを表し、物を片付ける動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域の農家が連合を開き、共同で出荷を始めた。", "corrected_sentence": "地域の農家が連合を組み、共同で出荷を始めた。", "error_description": "「連合を組む」が正しい。「開く」は連合と結びつかない。正しくは「連合を組み」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38967, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その団体は連合しずに、会議を開いた。", "corrected_sentence": "その団体は連合せずに、会議を開いた。", "error_description": "サ変動詞「連合する」に「ず」を付けるには「連合せず」となる。「連合しず」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "洗う動作の対象（目的語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置を示すため、「食器に洗う」は動作の対象にならない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「食器が洗う」では食器が動作主になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「食器へ洗う」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "洗う動作の対象（目的語）を示す。", "に": "位置を示すため、「食器に洗う」は動作の対象にならない。", "が": "主語を示すため、「食器が洗う」では食器が動作主になる。", "へ": "方向を示すため、「食器へ洗う」は文として成り立たない。"}, "error_tags": {"に": "位置", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「食器が多い」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すため、「食器を多い」は形容詞の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すため、「食器と多い」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「食器から多い」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「食器が多い」の主語を示す。", "を": "目的語を示すため、「食器を多い」は形容詞の主語にならない。", "と": "相手や並列を示すため、「食器と多い」は文として成り立たない。", "から": "起点を示すため、「食器から多い」は意味が通らない。"}, "error_tags": {"を": "目的語", "と": "相手・引用", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ご飯を食べるときに使うおさらやコップやはしなど。", "primary_collocate": null, "pronunciation": "しょっき", "ipa": "ɕokkʲi", "syllable_count": 3, "sentences": [{"text": "食べたあとで、食器を台所に運びます。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食[た]べたあとで、食器[しょっき]を台所[だいどころ]に運[はこ]びます。", "sentence_source": "generated"}, {"text": "食器を洗うのは、私の仕事です。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食器[しょっき]を洗[あら]うのは、私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "新しい食器を買って、食卓が明るくなりました。", "target_word": "食器", "complexity_tier": "T3", "furigana": "新[あたら]しい食器[しょっき]を買[か]って、食卓[しょくたく]が明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "食器はこの棚にしまってください。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食器[しょっき]はこの棚[たな]にしまってください。", "sentence_source": "generated"}, {"text": "子ども用の食器は、割れにくい材料でできています。", "target_word": "食器", "complexity_tier": "T3", "furigana": "子[こ]ども用[よう]の食器[しょっき]は、割[わ]れにくい材料[ざいりょう]でできています。", "sentence_source": "generated"}, {"text": "友だちが来るので、きれいな食器を出しました。", "target_word": "食器", "complexity_tier": "T3", "furigana": "友[とも]だちが来[く]るので、きれいな食器[しょっき]を出[だ]しました。", "sentence_source": "generated"}, {"text": "食器をテーブルに並べるのを、手伝ってくれますか。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食器[しょっき]をテーブルに並[なら]べるのを、手伝[てつだ]ってくれますか。", "sentence_source": "generated"}, {"text": "食器が多いので、洗うのに時間がかかります。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食器[しょっき]が多[おお]いので、洗[あら]うのに時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "引っ越しのとき、食器は新聞紙で包みました。", "target_word": "食器", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのとき、食器[しょっき]は新聞紙[しんぶんし]で包[つつ]みました。", "sentence_source": "generated"}, {"text": "祖母は、古い食器を大切に使っています。", "target_word": "食器", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、古[ふる]い食器[しょっき]を大切[たいせつ]に使[つか]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食器", "label": "基本形"}], "register": "neutral (丁寧)", "sense_fingerprint": "食事で使う皿・コップ・箸などの道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食器", "is_correct": true, "explanation": "食事で使う皿やコップなどの道具で、食後に台所へ運ぶ対象になる。"}, {"text": "食堂", "is_correct": false, "explanation": "食事をする場所を指し、台所へ運ぶ物ではない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表し、物として運ぶことはできない。"}, {"text": "食事", "is_correct": false, "explanation": "食べることや料理を指し、食後に台所へ運ぶ対象として成り立たない。"}], "explanations": {"食器": "食事で使う皿やコップなどの道具で、食後に台所へ運ぶ対象になる。", "食堂": "食事をする場所を指し、台所へ運ぶ物ではない。", "食欲": "食べたい気持ちを表し、物として運ぶことはできない。", "食事": "食べることや料理を指し、食後に台所へ運ぶ対象として成り立たない。"}, "sentence_index": 0, "correct_answer": "食器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食器の期限を、必ず確かめてください。", "explanation": "ここは〈食品〉の意味。食器は皿やコップなどの道具で、期限を確かめる対象ではない。"}, {"text": "食器を、塩とこしょうで味付けしてください。", "explanation": "ここは〈食材〉の意味。食器は道具で、味付けする食べ物ではない。"}, {"text": "食器は、冷たいうちに食べてください。", "explanation": "ここは〈食べ物〉の意味。食器は食べられるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食器", "is_correct": true, "explanation": "皿やコップなどの道具で、テーブルに並べる対象になる。"}, {"text": "食卓", "is_correct": false, "explanation": "食事をする台を指し、テーブルに並べる物ではない。"}, {"text": "食道", "is_correct": false, "explanation": "食べ物の通り道である体の部分で、並べる物ではない。"}, {"text": "食中毒", "is_correct": false, "explanation": "食べ物が原因の病気で、テーブルに並べる物ではない。"}], "explanations": {"食器": "皿やコップなどの道具で、テーブルに並べる対象になる。", "食卓": "食事をする台を指し、テーブルに並べる物ではない。", "食道": "食べ物の通り道である体の部分で、並べる物ではない。", "食中毒": "食べ物が原因の病気で、テーブルに並べる物ではない。"}, "sentence_index": 6, "correct_answer": "食器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は古い食器で、野菜を切っています。", "explanation": "ここは〈包丁〉の意味。食器は食事で使う皿やコップなどで、野菜を切る道具ではない。"}, {"text": "母は大きな食器を毛布の代わりにして、毎晩寝ました。", "explanation": "ここは〈寝具〉の意味。食器は食事に使う皿や椀などで、寝るための毛布の代わりにはならない。"}, {"text": "父は食器で、毎日服を洗っています。", "explanation": "ここは〈洗濯機〉の意味。食器は洗濯のための道具ではなく、服を洗う機械でもない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕食のあと、食器に拭いてください。", "corrected_sentence": "夕食のあと、食器を拭いてください。", "error_description": "「拭く」の対象は目的語として「を」で示す。「に」は誤りで、正しくは「食器を拭いてください」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38970, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎晩、食器を育ててから寝ます。", "corrected_sentence": "毎晩、食器を洗ってから寝ます。", "error_description": "「育てる」は植物や子どもなどに使い、食器には使わない。食器には「洗う」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38971, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「作られている」の主語を示す。「食器が作られている」は食器が作られるものとして自然。"}, {"text": "を", "is_correct": false, "explanation": "「作られている」は受身なので、食器は主語として「が」で示す。「食器を作られている」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や動作の相手を示す。「食器に作られている」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「作られている」と結びつかず、「食器へ作られている」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「作られている」の主語を示す。「食器が作られている」は食器が作られるものとして自然。", "を": "「作られている」は受身なので、食器は主語として「が」で示す。「食器を作られている」は不自然。", "に": "「に」は場所や動作の相手を示す。「食器に作られている」は意味が通らない。", "へ": "方向を示す「へ」は「作られている」と結びつかず、「食器へ作られている」は不自然。"}, "error_tags": {"を": "目的語", "に": "動作の相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
