INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38971, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食事の際に用いる器具や容器の総称。皿、椀、箸、杯などを含む。", "primary_collocate": null, "pronunciation": "しょっき", "ipa": "ɕokkʲi", "syllable_count": 3, "sentences": [{"text": "食器には、皿や茶わん、箸などがある。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食器[しょっき]には、皿[さら]や茶[ちゃ]わん、箸[はし]などがある。", "sentence_source": "generated"}, {"text": "この地方では、伝統的な技法で食器が作られている。", "target_word": "食器", "complexity_tier": "T3", "furigana": "この地方[ちほう]では、伝統的[でんとうてき]な技法[ぎほう]で食器[しょっき]が作[つく]られている。", "sentence_source": "generated"}, {"text": "食堂の食器は、毎日業務用の機械で洗っている。", "target_word": "食器", "complexity_tier": "T3", "furigana": "食堂[しょくどう]の食器[しょっき]は、毎日[まいにち]業務用[ぎょうむよう]の機械[きかい]で洗[あら]っている。", "sentence_source": "generated"}, {"text": "陶器の食器は割れやすいので、扱いに注意が必要だ。", "target_word": "食器", "complexity_tier": "T3", "furigana": "陶器[とうき]の食器[しょっき]は割[わ]れやすいので、扱[あつか]いに注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "博物館には、江戸時代の食器が展示されている。", "target_word": "食器", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、江戸[えど]時代[じだい]の食器[しょっき]が展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "素材によっては、電子レンジに入れられない食器もある。", "target_word": "食器", "complexity_tier": "T3", "furigana": "素材[そざい]によっては、電子[でんし]レンジに入[い]れられない食器[しょっき]もある。", "sentence_source": "generated"}, {"text": "旅館では、季節に合わせて食器を替えて料理を出す。", "target_word": "食器", "complexity_tier": "T3", "furigana": "旅館[りょかん]では、季節[きせつ]に合[あ]わせて食器[しょっき]を替[か]えて料理[りょうり]を出[だ]す。", "sentence_source": "generated"}, {"text": "この洗剤は、食器の油汚れを落とすために使われる。", "target_word": "食器", "complexity_tier": "T3", "furigana": "この洗剤[せんざい]は、食器[しょっき]の油[あぶら]汚[よご]れを落[お]とすために使[つか]われる。", "sentence_source": "generated"}, {"text": "国によって、食事に使う食器の種類は違う。", "target_word": "食器", "complexity_tier": "T3", "furigana": "国[くに]によって、食事[しょくじ]に使[つか]う食器[しょっき]の種類[しゅるい]は違[ちが]う。", "sentence_source": "generated"}, {"text": "割れた食器は、ごみの分別ルールに従って捨てる。", "target_word": "食器", "complexity_tier": "T3", "furigana": "割[わ]れた食器[しょっき]は、ごみの分別[ぶんべつ]ルールに従[したが]って捨[す]てる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食器", "label": "基本形"}], "register": "formal (常体・書き言葉)", "sense_fingerprint": "食事に用いる器具・容器の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 茶わん (Zipf 1.64)']::text[], '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38971, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食器", "is_correct": true, "explanation": "食事に使う皿や茶わんなどの総称で、「食器には、皿や茶わん、箸などがある」と文意が合う。"}, {"text": "食材", "is_correct": false, "explanation": "料理の材料を指す語で、皿や茶わんを含まないので「食材には、皿や茶わん、箸などがある」は合わない。"}, {"text": "調味料", "is_correct": false, "explanation": "味付けに使う物を指す語で、皿や箸のような道具を含まないので合わない。"}, {"text": "家電", "is_correct": false, "explanation": "電気で動く機械を指す語で、皿や茶わんとは別の物なので合わない。"}], "explanations": {"食器": "食事に使う皿や茶わんなどの総称で、「食器には、皿や茶わん、箸などがある」と文意が合う。", "食材": "料理の材料を指す語で、皿や茶わんを含まないので「食材には、皿や茶わん、箸などがある」は合わない。", "調味料": "味付けに使う物を指す語で、皿や箸のような道具を含まないので合わない。", "家電": "電気で動く機械を指す語で、皿や茶わんとは別の物なので合わない。"}, "sentence_index": 0, "correct_answer": "食器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このケーキの食器は、卵と小麦粉と砂糖だ。", "explanation": "ここは〈材料〉の意味。食器は食事に使う器具や容器のことで、料理の原料を指す材料とは違うので合わない。"}, {"text": "野菜を炒めるため、食器を鍋で強く熱した。", "explanation": "ここは〈調理器具〉の意味。食器は食べるときに使う皿や椀などで、鍋のように加熱して調理する道具は指さないので合わない。"}, {"text": "この店は食器を囲める大きな席があり、家族連れに人気だ。", "explanation": "ここは〈食卓〉の意味。食卓は家族などが囲んで食事をする台のことで、皿や箸などの食器とは別物なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38971, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食器", "is_correct": true, "explanation": "季節に合わせて替える器として皿や茶わんを指し、「旅館では、季節に合わせて食器を替えて料理を出す」と文脈に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "布団などの寝るための道具で、料理を出す場面には合わない。"}, {"text": "文房具", "is_correct": false, "explanation": "書いたり描いたりする道具で、料理を出す文脈には合わない。"}, {"text": "工具", "is_correct": false, "explanation": "作業に使う道具で、料理を出す文脈には合わない。"}], "explanations": {"食器": "季節に合わせて替える器として皿や茶わんを指し、「旅館では、季節に合わせて食器を替えて料理を出す」と文脈に合う。", "寝具": "布団などの寝るための道具で、料理を出す場面には合わない。", "文房具": "書いたり描いたりする道具で、料理を出す文脈には合わない。", "工具": "作業に使う道具で、料理を出す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "食器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リビングの食器は、ソファとテーブルとテレビだ。", "explanation": "ここは〈家具〉の意味。ソファやテーブルは部屋に置く家具で、食事の道具である食器とは違うので合わない。"}, {"text": "朝の食器を済ませてから、学校へ行った。", "explanation": "ここは〈食事〉の意味。「食事を済ませる」は言えるが、食器を済ませるとは言わないので合わない。"}, {"text": "彼は食器が大きく、小さな失敗は気にしない。", "explanation": "ここは「器が大きい」の〈度量〉の意味。食器は食事に使う道具で、人の度量には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38971, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店では、手作りの食器が一つずつ丁寧に包んで売っている。", "corrected_sentence": "この店では、手作りの食器を一つずつ丁寧に包んで売っている。", "error_description": "「包んで売る」の目的語は「食器を」で示す。「食器が」とすると目的語が欠け、文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38971, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜、食器を洗えときは水を止めて節約する。", "corrected_sentence": "夜、食器を洗うときは水を止めて節約する。", "error_description": "「洗う」の連体形（「とき」の前）は「洗う」。「洗えとき」は活用形の誤りで、正しくは「洗うとき」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「川に流出」で、流れ出る先の川を示す。山の土が川へ出ていくという文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "「流出」は自動詞なので目的語の「を」は取らない。「土を川に流出」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」を入れると「山の土が川が流出しました」となり、主語が二つになって文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は「川と流出しました」となり、流れ出る先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「川に流出」で、流れ出る先の川を示す。山の土が川へ出ていくという文意に合う。", "を": "「流出」は自動詞なので目的語の「を」は取らない。「土を川に流出」は不自然。", "が": "「が」を入れると「山の土が川が流出しました」となり、主語が二つになって文が成り立たない。", "と": "並列の「と」は「川と流出しました」となり、流れ出る先を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流入", "is_correct": true, "explanation": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。"}, {"text": "流派", "is_correct": false, "explanation": "芸道などの流儀の集まりを指し、流出の反対の意味を持たない。"}, {"text": "流氷", "is_correct": false, "explanation": "海に浮かぶ氷の塊を指し、流出と対になる語ではない。"}, {"text": "流木", "is_correct": false, "explanation": "流れてきた木材を指し、流出の反対の意味を持たない。"}], "correct_answer": "流入", "explanations": {"流入": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。", "流派": "芸道などの流儀の集まりを指し、流出の反対の意味を持たない。", "流氷": "海に浮かぶ氷の塊を指し、流出と対になる語ではない。", "流木": "流れてきた木材を指し、流出の反対の意味を持たない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「流出を防ぐ」で、防ぐ対象の流出を示す。文意が合う。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す「に」だと「流出に防ぐ」となり、防ぐ対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「防ぐ」に合わず、「流出へ防ぐ」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」だと「流出より防ぐ」となり、防ぐ対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「流出を防ぐ」で、防ぐ対象の流出を示す。文意が合う。", "に": "場所を示す「に」だと「流出に防ぐ」となり、防ぐ対象を示せない。", "へ": "方向を示す「へ」は「防ぐ」に合わず、「流出へ防ぐ」は不自然。", "より": "比較を示す「より」だと「流出より防ぐ」となり、防ぐ対象にならない。"}, "error_tags": {"に": "位置", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流入", "is_correct": true, "explanation": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。"}, {"text": "流星", "is_correct": false, "explanation": "夜空を流れる光を指し、流出の対義語ではない。"}, {"text": "流儀", "is_correct": false, "explanation": "やり方や作法を表し、流出とは対義の関係にない。"}, {"text": "流域", "is_correct": false, "explanation": "川の流れが及ぶ地域を指し、流出の対義語ではない。"}], "correct_answer": "流入", "explanations": {"流入": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。", "流星": "夜空を流れる光を指し、流出の対義語ではない。", "流儀": "やり方や作法を表し、流出とは対義の関係にない。", "流域": "川の流れが及ぶ地域を指し、流出の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水やものが、外にこぼれ出ること。", "primary_collocate": null, "pronunciation": "りゅうしゅつ", "ipa": "ɾʲɯːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "船から油が流出して、海がよごれました。", "target_word": "流出", "complexity_tier": "T3", "furigana": "船[ふね]から油[あぶら]が流出[りゅうしゅつ]して、海[うみ]がよごれました。", "sentence_source": "generated"}, {"text": "大雨のあと、山の土が川に流出しました。", "target_word": "流出", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあと、山[やま]の土[つち]が川[かわ]に流出[りゅうしゅつ]しました。", "sentence_source": "generated"}, {"text": "タンクがこわれて、水の流出が止まりません。", "target_word": "流出", "complexity_tier": "T3", "furigana": "タンクがこわれて、水[みず]の流出[りゅうしゅつ]が止[と]まりません。", "sentence_source": "generated"}, {"text": "雨で畑の土が流出しないように、木を植えます。", "target_word": "流出", "complexity_tier": "T3", "furigana": "雨[あめ]で畑[はたけ]の土[つち]が流出[りゅうしゅつ]しないように、木[き]を植[う]えます。", "sentence_source": "generated"}, {"text": "パイプに穴があいて、水が流出しています。", "target_word": "流出", "complexity_tier": "T3", "furigana": "パイプに穴[あな]があいて、水[みず]が流出[りゅうしゅつ]しています。", "sentence_source": "generated"}, {"text": "流出した油を、みんなで集めました。", "target_word": "流出", "complexity_tier": "T3", "furigana": "流出[りゅうしゅつ]した油[あぶら]を、みんなで集[あつ]めました。", "sentence_source": "generated"}, {"text": "川の近くの工場から、薬品が流出したそうです。", "target_word": "流出", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くの工場[こうじょう]から、薬品[やくひん]が流出[りゅうしゅつ]したそうです。", "sentence_source": "generated"}, {"text": "海への油の流出を防ぐために、船は検査を受けます。", "target_word": "流出", "complexity_tier": "T3", "furigana": "海[うみ]への油[あぶら]の流出[りゅうしゅつ]を防[ふせ]ぐために、船[ふね]は検査[けんさ]を受[う]けます。", "sentence_source": "generated"}, {"text": "ふたが外れて、タンクの水が流出しました。", "target_word": "流出", "complexity_tier": "T3", "furigana": "ふたが外[はず]れて、タンクの水[みず]が流出[りゅうしゅつ]しました。", "sentence_source": "generated"}, {"text": "雨が強いと、土の流出が心配です。", "target_word": "流出", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]いと、土[つち]の流出[りゅうしゅつ]が心配[しんぱい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流出", "label": "基本形"}, {"form": "流出する", "label": "動詞形"}, {"form": "流出した", "label": "た形"}, {"form": "流出して", "label": "て形"}], "register": "neutral (丁寧)", "sense_fingerprint": "水・油・土などが外へ流れ出ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: よごれ (Zipf 2.32)']::text[], '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "油が外にこぼれ出て海が汚れるという文脈に合う。"}, {"text": "流氷", "is_correct": false, "explanation": "海に浮かぶ氷の塊を指す語で、油の漏れには合わず「流氷して」とも言えない。"}, {"text": "流派", "is_correct": false, "explanation": "芸道などの流儀の集まりを指す語で、物理的な漏れを表さない。"}, {"text": "流木", "is_correct": false, "explanation": "川や海を流れる木材を指す語で、油の動きには当てはまらない。"}], "explanations": {"流出": "油が外にこぼれ出て海が汚れるという文脈に合う。", "流氷": "海に浮かぶ氷の塊を指す語で、油の漏れには合わず「流氷して」とも言えない。", "流派": "芸道などの流儀の集まりを指す語で、物理的な漏れを表さない。", "流木": "川や海を流れる木材を指す語で、油の動きには当てはまらない。"}, "sentence_index": 0, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この髪型は今年、若者の間で流出している。", "explanation": "ここは〈流行〉の意味。人気や評判が広がることを表す。流出は中身が外へこぼれ出ることなので、髪型の流行には合わない。"}, {"text": "夏の夜、涼しい風が窓から部屋へ流出して、部屋が涼しくなった。", "explanation": "ここは〈流入〉の意味。外から中へ入ってくることを表す。流出は内から外へ出ることなので、外から部屋へ入る風には合わない。"}, {"text": "この商品は、来月から全国の店に流出する予定だ。", "explanation": "ここは〈流通〉の意味。商品が店などに広く出回ることを表す。流出は外へこぼれ出ることなので、店に出回る意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "工場から薬品が外に漏れ出たという文脈に合う。"}, {"text": "流星", "is_correct": false, "explanation": "夜空を流れる光を指す語で、薬品が漏れる動きには合わない。"}, {"text": "流儀", "is_correct": false, "explanation": "やり方や作法を指す語で、薬品の動きを表さないので合わない。"}, {"text": "流域", "is_correct": false, "explanation": "川の流れが及ぶ地域を指す語で、薬品が漏れる動作には合わない。"}], "explanations": {"流出": "工場から薬品が外に漏れ出たという文脈に合う。", "流星": "夜空を流れる光を指す語で、薬品が漏れる動きには合わない。", "流儀": "やり方や作法を指す語で、薬品の動きを表さないので合わない。", "流域": "川の流れが及ぶ地域を指す語で、薬品が漏れる動作には合わない。"}, "sentence_index": 6, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "嵐で漁船が流出し、数日間海をさまよった。", "explanation": "ここは〈漂流〉の意味。船や人が海上を当てもなく流される場合に使う。流出は中身がこぼれ出る意味で、船そのものには合わない。"}, {"text": "大雨で川が流出して、町が水につかった。", "explanation": "ここは〈氾濫〉の意味。川があふれて周囲に広がる現象を指す。流出は中身が外へ出ることなので、川があふれる場合には合わない。"}, {"text": "囚人が刑務所から流出した。", "explanation": "ここは〈脱出〉の意味。人が閉じ込められた場所から逃げ出す場合に使う。流出は液体や情報などに使うので、人には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パイプの穴から水を流出しないよう、テープで止めた。", "corrected_sentence": "パイプの穴から水が流出しないよう、テープで止めた。", "error_description": "「流出する」は自動詞なので、流れ出るもの（水）は「が」で示す。「水を流出しない」の「を」は誤りで、正しくは「水が流出しない」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38974, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の排水が川に流出ないよう、タンクを毎月点検する。", "corrected_sentence": "工場の排水が川に流出しないよう、タンクを毎月点検する。", "error_description": "「流出」は名詞なので、動詞として使うには「する」が必要。「流出ない」は「する」が抜けた誤りで、正しくは「流出しない」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "流れ出るガスを主語として示す。「ガスが流出した」で文意が合う。"}, {"text": "を", "is_correct": false, "explanation": "「流出」は自動詞なので目的語の「を」は取らない。「ガスを流出した」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」だと「ガスへ流出した」となり、主語が立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」だと「ガスと流出した」となり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "流れ出るガスを主語として示す。「ガスが流出した」で文意が合う。", "を": "「流出」は自動詞なので目的語の「を」は取らない。「ガスを流出した」は不自然。", "へ": "方向を示す「へ」だと「ガスへ流出した」となり、主語が立たない。", "と": "並列の「と」だと「ガスと流出した」となり、主語を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流入", "is_correct": true, "explanation": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。"}, {"text": "流派", "is_correct": false, "explanation": "流儀や学派を表し、流出の対義語ではない。"}, {"text": "流木", "is_correct": false, "explanation": "流れてきた木材を指し、流出の対義語ではない。"}, {"text": "流域", "is_correct": false, "explanation": "川の流れが及ぶ地域を指し、流出の対義語ではない。"}], "correct_answer": "流入", "explanations": {"流入": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。", "流派": "流儀や学派を表し、流出の対義語ではない。", "流木": "流れてきた木材を指し、流出の対義語ではない。", "流域": "川の流れが及ぶ地域を指し、流出の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "流れ出る放射性物質を主語として示す。「放射性物質が流出する事故」で文意が合う。"}, {"text": "を", "is_correct": false, "explanation": "「流出する」は自動詞なので目的語の「を」は取らない。「放射性物質を流出する」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」だと「物質より流出する」となり、主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "方向を示す「に」だと「物質に流出する」となり、行き先を示す文になって不自然。"}], "correct_answer": "が", "explanations": {"が": "流れ出る放射性物質を主語として示す。「放射性物質が流出する事故」で文意が合う。", "を": "「流出する」は自動詞なので目的語の「を」は取らない。「放射性物質を流出する」は不自然。", "より": "比較を示す「より」だと「物質より流出する」となり、主語にならない。", "に": "方向を示す「に」だと「物質に流出する」となり、行き先を示す文になって不自然。"}, "error_tags": {"を": "目的語", "より": "比較", "に": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流入", "is_correct": true, "explanation": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。"}, {"text": "流星", "is_correct": false, "explanation": "夜空を流れる光を指し、流出の対義語ではない。"}, {"text": "流儀", "is_correct": false, "explanation": "やり方や作法を表し、流出の対義語ではない。"}, {"text": "流氷", "is_correct": false, "explanation": "海に浮かぶ氷を指し、流出の対義語ではない。"}], "correct_answer": "流入", "explanations": {"流入": "流出の対義語。外から中へ入り込む意味で、中から外へ出る流出と反対の関係にある。", "流星": "夜空を流れる光を指し、流出の対義語ではない。", "流儀": "やり方や作法を表し、流出の対義語ではない。", "流氷": "海に浮かぶ氷を指し、流出の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "液体や気体、または情報などが、内部から外部へと漏れ出ること。また、その漏れ出たもの。", "primary_collocate": null, "pronunciation": "りゅうしゅつ", "ipa": "ɾʲɯːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "会社の顧客情報が流出し、大きな問題になった。", "target_word": "流出", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の顧客[こきゃく]情報[じょうほう]が流出[りゅうしゅつ]し、大[おお]きな問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "ガス管の事故で、有毒なガスが流出した。", "target_word": "流出", "complexity_tier": "T3", "furigana": "ガス管[かん]の事故[じこ]で、有毒[ゆうどく]なガスが流出[りゅうしゅつ]した。", "sentence_source": "generated"}, {"text": "個人情報の流出を防ぐために、パスワードを変更する。", "target_word": "流出", "complexity_tier": "T3", "furigana": "個人[こじん]情報[じょうほう]の流出[りゅうしゅつ]を防[ふせ]ぐために、パスワードを変更[へんこう]する。", "sentence_source": "generated"}, {"text": "工場から化学物質が川へ流出し、魚が死んだ。", "target_word": "流出", "complexity_tier": "T3", "furigana": "工場[こうじょう]から化学[かがく]物質[ぶっしつ]が川[かわ]へ流出[りゅうしゅつ]し、魚[さかな]が死[し]んだ。", "sentence_source": "generated"}, {"text": "試験問題が流出したため、試験は中止された。", "target_word": "流出", "complexity_tier": "T3", "furigana": "試験[しけん]問題[もんだい]が流出[りゅうしゅつ]したため、試験[しけん]は中止[ちゅうし]された。", "sentence_source": "generated"}, {"text": "内部資料が外部に流出した原因を調べている。", "target_word": "流出", "complexity_tier": "T3", "furigana": "内部[ないぶ]資料[しりょう]が外部[がいぶ]に流出[りゅうしゅつ]した原因[げんいん]を調[しら]べている。", "sentence_source": "generated"}, {"text": "流出した画像は、すでにネット上に広がっていた。", "target_word": "流出", "complexity_tier": "T3", "furigana": "流出[りゅうしゅつ]した画像[がぞう]は、すでにネット上[じょう]に広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "原子力発電所から放射性物質が流出する事故が起きた。", "target_word": "流出", "complexity_tier": "T3", "furigana": "原子力[げんしりょく]発電所[はつでんしょ]から放射性[ほうしゃせい]物質[ぶっしつ]が流出[りゅうしゅつ]する事故[じこ]が起[お]きた。", "sentence_source": "generated"}, {"text": "データの流出が分かった時点で、会社は謝罪した。", "target_word": "流出", "complexity_tier": "T3", "furigana": "データの流出[りゅうしゅつ]が分[わ]かった時点[じてん]で、会社[かいしゃ]は謝罪[しゃざい]した。", "sentence_source": "generated"}, {"text": "冷却用のガスが流出しないよう、定期的に点検する。", "target_word": "流出", "complexity_tier": "T3", "furigana": "冷却用[れいきゃくよう]のガスが流出[りゅうしゅつ]しないよう、定期的[ていきてき]に点検[てんけん]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流出", "label": "基本形"}, {"form": "流出する", "label": "動詞形"}, {"form": "流出した", "label": "た形"}, {"form": "流出して", "label": "て形"}], "register": "formal (常体・書き言葉)", "sense_fingerprint": "液体・気体・情報などが内部から外部へ漏れ出ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "情報が外部へ漏れることを表し、顧客情報が問題になったという文脈に合う。"}, {"text": "流派", "is_correct": false, "explanation": "流儀や学派を表す語で、情報が漏れる意味には合わない。"}, {"text": "流木", "is_correct": false, "explanation": "流れてきた木材を指す語で、情報には当てはまらない。"}, {"text": "流域", "is_correct": false, "explanation": "川の流れが及ぶ地域を指す語で、情報の漏れには合わない。"}], "explanations": {"流出": "情報が外部へ漏れることを表し、顧客情報が問題になったという文脈に合う。", "流派": "流儀や学派を表す語で、情報が漏れる意味には合わない。", "流木": "流れてきた木材を指す語で、情報には当てはまらない。", "流域": "川の流れが及ぶ地域を指す語で、情報の漏れには合わない。"}, "sentence_index": 0, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兵士が包囲網から流出した。", "explanation": "ここは〈脱出〉の意味。人が囲まれた場所から逃れる場合に使う。流出は液体や情報などに使うので、人には合わない。"}, {"text": "遭難したボートが流出し、そのまま沖へ消えた。", "explanation": "ここは〈漂流〉の意味。船や人が海上を当てもなく流される場合に使う。流出は中身が外へ出ることなので、船そのものには合わない。"}, {"text": "豪雨で湖が流出し、道路が冠水した。", "explanation": "ここは〈氾濫〉の意味。水があふれて周囲に広がる現象を指す。流出は中身が外へ出ることなので、湖があふれる場合には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "外部に漏れ出た画像を指し、ネット上に広がったという文脈に合う。"}, {"text": "流星", "is_correct": false, "explanation": "夜空の光を指す語で、画像には当てはまらない。"}, {"text": "流儀", "is_correct": false, "explanation": "やり方を表す語で、画像を指さないので合わない。"}, {"text": "流氷", "is_correct": false, "explanation": "海に浮かぶ氷を指す語で、画像とは無関係。"}], "explanations": {"流出": "外部に漏れ出た画像を指し、ネット上に広がったという文脈に合う。", "流星": "夜空の光を指す語で、画像には当てはまらない。", "流儀": "やり方を表す語で、画像を指さないので合わない。", "流氷": "海に浮かぶ氷を指す語で、画像とは無関係。"}, "sentence_index": 6, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火事が町じゅうに流出し、夜空が明るくなった。", "explanation": "ここは〈広がる〉の意味。火事などが広い範囲に及ぶことを表す。流出は内から外へ出ることなので、町全体に広がる意味には合わない。"}, {"text": "囚人が刑務所から流出した。", "explanation": "ここは〈脱走〉の意味。人が閉じ込められた場所から逃げ出す場合に使う。流出は液体や情報などに使うので、人には合わない。"}, {"text": "この服の色は今年、若者の間で流出している。", "explanation": "ここは〈流行〉の意味。人気や評判が広がることを表す。流出は中身が外へ漏れることなので、流行の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "データの流出に防ぐため、社員はパスワードを毎月変えている。", "corrected_sentence": "データの流出を防ぐため、社員はパスワードを毎月変えている。", "error_description": "「防ぐ」の対象は「を」で示す。「流出に」の「に」は誤りで、正しくは「流出を防ぐ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38975, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ネット上に流出しった画像は、すぐに削除しなければならない。", "corrected_sentence": "ネット上に流出した画像は、すぐに削除しなければならない。", "error_description": "「流出」の過去の形は「流出した」。「流出しった」は活用形の誤りで、正しくは「流出した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「研究と並行して」で、二つのことを同時に進める形になる。"}, {"text": "で", "is_correct": false, "explanation": "「研究で並行して」は手段の「で」が不自然で、並行の相手を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、並行の相手を示す形にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、同時に進むことを表せない。"}], "correct_answer": "と", "explanations": {"と": "正解。「研究と並行して」で、二つのことを同時に進める形になる。", "で": "「研究で並行して」は手段の「で」が不自然で、並行の相手を示せない。", "から": "起点の「から」は、並行の相手を示す形にならない。", "より": "比較の「より」は、同時に進むことを表せない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのことが、同じときに進むことです。", "primary_collocate": null, "pronunciation": "へいこう", "ipa": "heːkoː", "syllable_count": 4, "sentences": [{"text": "私は仕事と勉強を並行して進めている。", "target_word": "並行", "complexity_tier": "T3", "furigana": "私[わたし]は仕事[しごと]と勉強[べんきょう]を並行[へいこう]して進[すす]めている。", "sentence_source": "generated"}, {"text": "料理は、肉を焼きながらスープも作るように並行して行う。", "target_word": "並行", "complexity_tier": "T3", "furigana": "料理[りょうり]は、肉[にく]を焼[や]きながらスープも作[つく]るように並行[へいこう]して行[おこな]う。", "sentence_source": "generated"}, {"text": "二つの工事を並行して進めたので、予定より早く終わった。", "target_word": "並行", "complexity_tier": "T3", "furigana": "二[ふた]つの工事[こうじ]を並行[へいこう]して進[すす]めたので、予定[よてい]より早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "彼女は大学の授業と並行して、週末にアルバイトもしている。", "target_word": "並行", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]の授業[じゅぎょう]と並行[へいこう]して、週末[しゅうまつ]にアルバイトもしている。", "sentence_source": "generated"}, {"text": "話し合いと並行して、準備も進めておいてください。", "target_word": "並行", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いと並行[へいこう]して、準備[じゅんび]も進[すす]めておいてください。", "sentence_source": "generated"}, {"text": "二つの計画が並行して動いているため、毎日とても忙しい。", "target_word": "並行", "complexity_tier": "T3", "furigana": "二[ふた]つの計画[けいかく]が並行[へいこう]して動[うご]いているため、毎日[まいにち]とても忙[いそが]しい。", "sentence_source": "generated"}, {"text": "一人で並行して三つの仕事をするのは、さすがに無理だ。", "target_word": "並行", "complexity_tier": "T3", "furigana": "一人[ひとり]で並行[へいこう]して三[みっ]つの仕事[しごと]をするのは、さすがに無理[むり]だ。", "sentence_source": "generated"}, {"text": "研究と並行して、論文も書き進めた。", "target_word": "並行", "complexity_tier": "T3", "furigana": "研究[けんきゅう]と並行[へいこう]して、論文[ろんぶん]も書[か]き進[すす]めた。", "sentence_source": "generated"}, {"text": "事業を並行して行うと、時間が足りなくなる。", "target_word": "並行", "complexity_tier": "T3", "furigana": "事業[じぎょう]を並行[へいこう]して行[おこな]うと、時間[じかん]が足[た]りなくなる。", "sentence_source": "generated"}, {"text": "道路の工事と並行して、水道の工事も始まった。", "target_word": "並行", "complexity_tier": "T3", "furigana": "道路[どうろ]の工事[こうじ]と並行[へいこう]して、水道[すいどう]の工事[こうじ]も始[はじ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "並行する", "label": "辞書形"}, {"form": "並行して", "label": "て形"}, {"form": "並行した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "並行=二つのことを同じ時期に進めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "並行", "is_correct": true, "explanation": "正解。「〜を並行して進める」の形で、二つの作業を同時に進める意味になる。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめる意味。「進めている」と矛盾するので合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりや組織をまとめて解く意味。仕事や勉強には使えない。"}, {"text": "撤回", "is_correct": false, "explanation": "出した申し出や主張を取り消す意味。作業の進め方には使わない。"}], "explanations": {"並行": "正解。「〜を並行して進める」の形で、二つの作業を同時に進める意味になる。", "中断": "途中でやめる意味。「進めている」と矛盾するので合わない。", "解散": "集まりや組織をまとめて解く意味。仕事や勉強には使えない。", "撤回": "出した申し出や主張を取り消す意味。作業の進め方には使わない。"}, "sentence_index": 0, "correct_answer": "並行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は寝室と書斎を並行している。", "explanation": "ここは〈兼ねる〉の意味。一つの部屋が二つの役割を果たすことは兼ねると言い、並行は同時に進むことで役割の兼用は表さない。"}, {"text": "兄と並行して暮らしている。", "explanation": "ここは〈一緒に〉の意味。家族と共に生活することは一緒にと言い、並行とは言わない。"}, {"text": "この薬は痛み止めと並行しないでください。", "explanation": "ここは〈併用〉の意味。薬を一緒に使うことは併用と言い、並行とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "並行", "is_correct": true, "explanation": "正解。「一人で並行して」の形で、三つの仕事を同時に進めることを表す。"}, {"text": "反発", "is_correct": false, "explanation": "押し返す、逆らう意味。仕事を同時に進める文脈には合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "途中で投げ出す意味。「三つの仕事をする」と矛盾する。"}, {"text": "脱退", "is_correct": false, "explanation": "組織から抜ける意味。仕事を重ねて進める文脈には合わない。"}], "explanations": {"並行": "正解。「一人で並行して」の形で、三つの仕事を同時に進めることを表す。", "反発": "押し返す、逆らう意味。仕事を同時に進める文脈には合わない。", "放棄": "途中で投げ出す意味。「三つの仕事をする」と矛盾する。", "脱退": "組織から抜ける意味。仕事を重ねて進める文脈には合わない。"}, "sentence_index": 6, "correct_answer": "並行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は先生と並行して美術館へ行った。", "explanation": "ここは〈同行〉の意味。人と一緒に出かけることは同行と言い、並行とは言わない。"}, {"text": "この町では、人と野生動物が並行して暮らしている。", "explanation": "ここは〈共存〉の意味。異なるものがともに生きることは共存と言い、並行とは言わない。"}, {"text": "二つの会社は並行して一つになり、新会社が生まれた。", "explanation": "ここは〈合併〉の意味。一つにまとまることは合併で、並行しても一つにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は大学の課題と勉強を並行で進めた。", "corrected_sentence": "私は大学の課題と勉強を並行して進めた。", "error_description": "「並行で」は誤り。正しくは「並行して」。「〜を並行して進める」の形で、「で」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38976, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勉強に並行して仕事も続けている。", "corrected_sentence": "勉強と並行して仕事も続けている。", "error_description": "「勉強に」は誤り。「並行」は「〜と並行して」で使うので、「に」ではなく「と」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放する", "is_correct": true, "explanation": "『拘束する（自由に動けなくする）』の対義語。国語辞典でも対義語として挙がる。"}, {"text": "保護する", "is_correct": false, "explanation": "守り助ける意味で、動きを奪う拘束の対義とは言えない。"}, {"text": "歓迎する", "is_correct": false, "explanation": "受け入れて喜ぶ意味で、拘束とは対になる関係にない。"}, {"text": "放置する", "is_correct": false, "explanation": "そのまま放っておく意味で、拘束の対義語ではない。"}], "correct_answer": "解放する", "explanations": {"解放する": "『拘束する（自由に動けなくする）』の対義語。国語辞典でも対義語として挙がる。", "保護する": "守り助ける意味で、動きを奪う拘束の対義とは言えない。", "歓迎する": "受け入れて喜ぶ意味で、拘束とは対になる関係にない。", "放置する": "そのまま放っておく意味で、拘束の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『患者を拘束する』で、拘束する動作の対象を示す『を』。正しい。"}, {"text": "に", "is_correct": false, "explanation": "『患者に拘束する』は動作の対象を示せず、文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は拘束の対象にはならず、『患者へ拘束する』は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "共同を示す『と』は対象を取らず、『患者と拘束する』は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『患者を拘束する』で、拘束する動作の対象を示す『を』。正しい。", "に": "『患者に拘束する』は動作の対象を示せず、文として不自然。", "へ": "方向を示す『へ』は拘束の対象にはならず、『患者へ拘束する』は成立しない。", "と": "共同を示す『と』は対象を取らず、『患者と拘束する』は意味が通らない。"}, "error_tags": {"に": "対象の誤り", "へ": "方向の誤り", "と": "共同の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "『拘束（自由に動けなくすること）』の対義語。国語辞典でも対義語として挙がる。"}, {"text": "監視", "is_correct": false, "explanation": "見張る意味で、拘束と対になる関係ではない。"}, {"text": "観察", "is_correct": false, "explanation": "注意深く見る意味で、拘束とは対義の関係にない。"}, {"text": "支援", "is_correct": false, "explanation": "助ける意味で、動きを奪う拘束の対義語とは言えない。"}], "correct_answer": "解放", "explanations": {"解放": "『拘束（自由に動けなくすること）』の対義語。国語辞典でも対義語として挙がる。", "監視": "見張る意味で、拘束と対になる関係ではない。", "観察": "注意深く見る意味で、拘束とは対義の関係にない。", "支援": "助ける意味で、動きを奪う拘束の対義語とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを自由にできないようにすること。", "primary_collocate": null, "pronunciation": "こうそく", "ipa": "koːsokɯ", "syllable_count": 4, "sentences": [{"text": "警察は逃げた男をその場で拘束した。", "target_word": "拘束した", "complexity_tier": "T3", "furigana": "警察[けいさつ]は逃[に]げた男[おとこ]をその場[ば]で拘束[こうそく]した。", "sentence_source": "generated"}, {"text": "人質は手足を縛られ、三時間も拘束された。", "target_word": "拘束された", "complexity_tier": "T3", "furigana": "人質[ひとじち]は手足[てあし]を縛[しば]られ、三時間[さんじかん]も拘束[こうそく]された。", "sentence_source": "generated"}, {"text": "犯人は逃げないよう、椅子に拘束されていた。", "target_word": "拘束されていた", "complexity_tier": "T3", "furigana": "犯人[はんにん]は逃[に]げないよう、椅子[いす]に拘束[こうそく]されていた。", "sentence_source": "generated"}, {"text": "子どもを部屋に拘束するのは、してはいけないことだ。", "target_word": "拘束する", "complexity_tier": "T3", "furigana": "子[こ]どもを部屋[へや]に拘束[こうそく]するのは、してはいけないことだ。", "sentence_source": "generated"}, {"text": "彼は暴れたので、警備員に体を拘束された。", "target_word": "拘束された", "complexity_tier": "T3", "furigana": "彼[かれ]は暴[あば]れたので、警備員[けいびいん]に体[からだ]を拘束[こうそく]された。", "sentence_source": "generated"}, {"text": "自由を奪う拘束は、どんな理由でも問題になる。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "自由[じゆう]を奪[うば]う拘束[こうそく]は、どんな理由[りゆう]でも問題[もんだい]になる。", "sentence_source": "generated"}, {"text": "拘束が長引いたため、家族はとても心配した。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "拘束[こうそく]が長引[ながび]いたため、家族[かぞく]はとても心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "病院で患者を拘束することは、特別な場合だけ認められている。", "target_word": "拘束する", "complexity_tier": "T3", "furigana": "病院[びょういん]で患者[かんじゃ]を拘束[こうそく]することは、特別[とくべつ]な場合[ばあい]だけ認[みと]められている。", "sentence_source": "generated"}, {"text": "暴れた容疑者は、手錠をかけられて拘束された。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "暴[あば]れた容疑者[ようぎしゃ]は、手錠[てじょう]をかけられて拘束[こうそく]された。", "sentence_source": "generated"}, {"text": "拘束を解かれた男は、ほっとした顔で外に出た。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "拘束[こうそく]を解[と]かれた男[おとこ]は、ほっとした顔[かお]で外[そと]に出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拘束する", "label": "辞書形"}, {"form": "拘束した", "label": "過去形"}, {"form": "拘束された", "label": "受身過去形"}], "register": "標準", "sense_fingerprint": "人や動物の体や行動を押さえて、自由に動けなくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拘束した", "is_correct": true, "explanation": "過去形の述語で文を締めており、『警察は男を拘束した』として成立する。"}, {"text": "拘束を", "is_correct": false, "explanation": "名詞のままでは述語にならず、『その場で拘束を。』は文として成立しない。"}, {"text": "拘束し", "is_correct": false, "explanation": "連用形のままでは述語にならず、『その場で拘束し。』は文が途中で切れている。"}, {"text": "拘束された", "is_correct": false, "explanation": "受身にすると主語が『警察』と合わず、『男をその場で拘束された』と目的語の扱いが崩れる。"}], "explanations": {"拘束した": "過去形の述語で文を締めており、『警察は男を拘束した』として成立する。", "拘束を": "名詞のままでは述語にならず、『その場で拘束を。』は文として成立しない。", "拘束し": "連用形のままでは述語にならず、『その場で拘束し。』は文が途中で切れている。", "拘束された": "受身にすると主語が『警察』と合わず、『男をその場で拘束された』と目的語の扱いが崩れる。"}, "sentence_index": 0, "correct_answer": "拘束した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ネジで板を拘束した。", "explanation": "ここは〈固定〉の意味。拘束は人や動物の体や行動を押さえる時に使い、板のような物には〈固定〉を使うので合わない。"}, {"text": "父は貯金箱の硬貨を拘束して、大切に守った。", "explanation": "ここは〈保管〉の意味。拘束は人や動物の行動を押さえる時に使い、お金を大切にしまう時は保管と言うので合わない。"}, {"text": "迷子の子どもを警察が拘束した。", "explanation": "ここは〈保護〉の意味。迷子の子どもは押さえるのではなく守る対象なので、拘束ではなく保護と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拘束", "is_correct": true, "explanation": "名詞として主語になり、『拘束が長引いた』と文が成立する。"}, {"text": "拘束して", "is_correct": false, "explanation": "て形は名詞の位置に入らず、『拘束して長引いた』は文として成立しない。"}, {"text": "拘束され", "is_correct": false, "explanation": "受身の連用形では主語にならず、『拘束され長引いた』と続かない。"}, {"text": "拘束する", "is_correct": false, "explanation": "動詞の終止形は名詞の位置に入らず、『拘束する長引いた』は不自然で成立しない。"}], "explanations": {"拘束": "名詞として主語になり、『拘束が長引いた』と文が成立する。", "拘束して": "て形は名詞の位置に入らず、『拘束して長引いた』は文として成立しない。", "拘束され": "受身の連用形では主語にならず、『拘束され長引いた』と続かない。", "拘束する": "動詞の終止形は名詞の位置に入らず、『拘束する長引いた』は不自然で成立しない。"}, "sentence_index": 6, "correct_answer": "拘束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この法律は、工場の排水を拘束するために作られた。", "explanation": "ここは〈規制〉の意味。排水のような物質には拘束を使わず、規制と言うので合わない。"}, {"text": "彼は怒りを拘束して、冷静に話した。", "explanation": "ここは〈抑制〉の意味。感情は拘束ではなく『抑える・抑制する』と言うので合わない。"}, {"text": "防犯カメラで店の入り口を拘束していた。", "explanation": "ここは〈監視〉の意味。カメラは人を押さえるのではなく見張るので、拘束ではなく監視と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼を拘束が解けたのは、夜になってからだった。", "corrected_sentence": "彼の拘束が解けたのは、夜になってからだった。", "error_description": "誤った形は『彼を拘束』（を）。正しい形は『彼の拘束』（の）。『拘束が解ける』の主体は彼なので、名詞を修飾する『の』が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38978, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犯人は手錠をかけられ、朝まで拘束れた。", "corrected_sentence": "犯人は手錠をかけられ、朝まで拘束された。", "error_description": "誤った形は『拘束れた』。正しい形は『拘束された』（受身）。『さ』が抜けており、『される』の活用が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『行動を拘束する』で、拘束の対象を示す『を』。正しい。"}, {"text": "に", "is_correct": false, "explanation": "『行動に拘束する』は対象を示せず、文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す『で』は拘束の対象を示せず、『行動で拘束する』は意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は拘束の対象にならず、『行動へ拘束する』は成立しない。"}], "correct_answer": "を", "explanations": {"を": "『行動を拘束する』で、拘束の対象を示す『を』。正しい。", "に": "『行動に拘束する』は対象を示せず、文として不自然。", "で": "手段や場所を示す『で』は拘束の対象を示せず、『行動で拘束する』は意味が合わない。", "へ": "方向を示す『へ』は拘束の対象にならず、『行動へ拘束する』は成立しない。"}, "error_tags": {"に": "対象の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自由", "is_correct": true, "explanation": "行動を制限する『拘束』の対義語として、類語辞典でも対義語に挙がる。"}, {"text": "規制", "is_correct": false, "explanation": "制限する意味で、拘束の類義語であり対義語ではない。"}, {"text": "制約", "is_correct": false, "explanation": "しばる意味で、拘束の類義語であり対義語ではない。"}, {"text": "監督", "is_correct": false, "explanation": "見て導く意味で、拘束と対になる関係にはない。"}], "correct_answer": "自由", "explanations": {"自由": "行動を制限する『拘束』の対義語として、類語辞典でも対義語に挙がる。", "規制": "制限する意味で、拘束の類義語であり対義語ではない。", "制約": "しばる意味で、拘束の類義語であり対義語ではない。", "監督": "見て導く意味で、拘束と対になる関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『期待に拘束される』で、拘束の原因を示す『に』。正しい。"}, {"text": "を", "is_correct": false, "explanation": "『期待を拘束される』は受身の形と合わず、文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同を示す『と』は拘束の原因を示せず、『期待と拘束される』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は拘束の原因にならず、『期待へ拘束される』は成立しない。"}], "correct_answer": "に", "explanations": {"に": "『期待に拘束される』で、拘束の原因を示す『に』。正しい。", "を": "『期待を拘束される』は受身の形と合わず、文として不自然。", "と": "共同を示す『と』は拘束の原因を示せず、『期待と拘束される』は意味が通らない。", "へ": "方向を示す『へ』は拘束の原因にならず、『期待へ拘束される』は成立しない。"}, "error_tags": {"を": "対象の誤り", "と": "共同の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自由な行動や状態を制限すること。また、その制限。", "primary_collocate": null, "pronunciation": "こうそく", "ipa": "koːsokɯ", "syllable_count": 4, "sentences": [{"text": "この仕事は時間の拘束が長くて、夜まで帰れない。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "この仕事[しごと]は時間[じかん]の拘束[こうそく]が長[なが]くて、夜[よる]まで帰[かえ]れない。", "sentence_source": "generated"}, {"text": "規則で社員の行動を拘束するのは、限度がある。", "target_word": "拘束する", "complexity_tier": "T3", "furigana": "規則[きそく]で社員[しゃいん]の行動[こうどう]を拘束[こうそく]するのは、限度[げんど]がある。", "sentence_source": "generated"}, {"text": "彼は何にも拘束されない生き方を選んだ。", "target_word": "拘束されない", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]にも拘束[こうそく]されない生[い]き方[かた]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "拘束時間が短い仕事を探している。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "拘束[こうそく]時間[じかん]が短[みじか]い仕事[しごと]を探[さが]している。", "sentence_source": "generated"}, {"text": "古い習慣の拘束から逃れて、自由に暮らしたい。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "古[ふる]い習慣[しゅうかん]の拘束[こうそく]から逃[のが]れて、自由[じゆう]に暮[く]らしたい。", "sentence_source": "generated"}, {"text": "契約に、住む場所を拘束する条件はなかった。", "target_word": "拘束する", "complexity_tier": "T3", "furigana": "契約[けいやく]に、住[す]む場所[ばしょ]を拘束[こうそく]する条件[じょうけん]はなかった。", "sentence_source": "generated"}, {"text": "法律は、人の行動を必要以上に拘束してはならない。", "target_word": "拘束して", "complexity_tier": "T3", "furigana": "法律[ほうりつ]は、人[ひと]の行動[こうどう]を必要以上[ひつよういじょう]に拘束[こうそく]してはならない。", "sentence_source": "generated"}, {"text": "親の期待に拘束されて、本当にやりたいことが言えなかった。", "target_word": "拘束されて", "complexity_tier": "T3", "furigana": "親[おや]の期待[きたい]に拘束[こうそく]されて、本当[ほんとう]にやりたいことが言[い]えなかった。", "sentence_source": "generated"}, {"text": "拘束の少ない働き方が若い人に人気だ。", "target_word": "拘束", "complexity_tier": "T3", "furigana": "拘束[こうそく]の少[すく]ない働[はたら]き方[かた]が若[わか]い人[ひと]に人気[にんき]だ。", "sentence_source": "generated"}, {"text": "時間に拘束されずに、旅行を楽しんだ。", "target_word": "拘束されず", "complexity_tier": "T3", "furigana": "時間[じかん]に拘束[こうそく]されずに、旅行[りょこう]を楽[たの]しんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拘束する", "label": "辞書形"}, {"form": "拘束して", "label": "て形"}, {"form": "拘束される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "時間・規則・立場などで行動の自由を制限すること、またその制限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拘束", "is_correct": true, "explanation": "名詞として『時間の拘束』となり、『時間の拘束が長くて』と文が成立する。"}, {"text": "拘束され", "is_correct": false, "explanation": "受身の連用形は『時間の』の後に続かず、『時間の拘束されが長くて』は成立しない。"}, {"text": "拘束させ", "is_correct": false, "explanation": "使役の連用形は名詞の位置に入らず、『時間の拘束させが長くて』は不自然で成立しない。"}, {"text": "拘束しよう", "is_correct": false, "explanation": "意向形は名詞を修飾できず、『時間の拘束しよう長くて』は成立しない。"}], "explanations": {"拘束": "名詞として『時間の拘束』となり、『時間の拘束が長くて』と文が成立する。", "拘束され": "受身の連用形は『時間の』の後に続かず、『時間の拘束されが長くて』は成立しない。", "拘束させ": "使役の連用形は名詞の位置に入らず、『時間の拘束させが長くて』は不自然で成立しない。", "拘束しよう": "意向形は名詞を修飾できず、『時間の拘束しよう長くて』は成立しない。"}, "sentence_index": 0, "correct_answer": "拘束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大人は子どもの手を拘束して、道を渡った。", "explanation": "ここは〈握る〉の意味。拘束は人の行動や状態を制限する時に使い、子どもの手を握るだけなら『握る』と言うので合わない。"}, {"text": "車の速度を拘束する。", "explanation": "ここは〈速度の上限を定める〉の意味。速度を抑える場合は『規制する』と言い、人の行動を縛る拘束とは合わない。"}, {"text": "警察の存在が犯罪を拘束する。", "explanation": "ここは〈抑止〉の意味。犯罪を防ぐ意味で、人の行動を押さえる拘束とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拘束して", "is_correct": true, "explanation": "『拘束してはならない』の形で、後ろの『はならない』と続く正しい形。"}, {"text": "拘束し", "is_correct": false, "explanation": "連用形のままでは『はならない』と続かず、文として成立しない。"}, {"text": "拘束する", "is_correct": false, "explanation": "終止形では『はならない』に接続せず、『拘束するはならない』は成立しない。"}, {"text": "拘束した", "is_correct": false, "explanation": "過去形では『はならない』に続かず、禁止の文として成立しない。"}], "explanations": {"拘束して": "『拘束してはならない』の形で、後ろの『はならない』と続く正しい形。", "拘束し": "連用形のままでは『はならない』と続かず、文として成立しない。", "拘束する": "終止形では『はならない』に接続せず、『拘束するはならない』は成立しない。", "拘束した": "過去形では『はならない』に続かず、禁止の文として成立しない。"}, "sentence_index": 6, "correct_answer": "拘束して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場は夜間、機械の運転を拘束した。", "explanation": "ここは〈停止〉の意味。機械の運転は止めるのであり、拘束は人や動物の行動を押さえる時に使うので合わない。"}, {"text": "図書館は誰でも無料で資料を拘束している。", "explanation": "ここは〈提供〉の意味。資料は貸し出して提供するのであり、拘束とは言わないので合わない。"}, {"text": "友人は飲み物を拘束して、ゆっくり味わった。", "explanation": "ここは〈保持〉の意味。飲み物は手に持つ・味わうもので、人の行動を押さえる拘束とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事が生活を拘束されている。", "corrected_sentence": "仕事が生活を拘束している。", "error_description": "誤った形は受身の『拘束されている』。正しい形は能動の『拘束している』。『仕事』が生活を縛る側なので能動形が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38979, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "期待を拘束されて、本音を言えなかった。", "corrected_sentence": "期待に拘束されて、本音を言えなかった。", "error_description": "誤った形は『期待を』（を）。正しい形は『期待に』（に）。『拘束される』は『〜に拘束される』の形で、拘束する側を『に』で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『窓は東南を向いている』で、向く対象を示す『を』。正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す『で』は向く対象にならず、『東南で向いている』は成立しない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』は向く対象にならず、『東南から向いている』は不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同を示す『と』は向く対象にならず、『東南と向いている』は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『窓は東南を向いている』で、向く対象を示す『を』。正しい。", "で": "手段や場所を示す『で』は向く対象にならず、『東南で向いている』は成立しない。", "から": "起点を示す『から』は向く対象にならず、『東南から向いている』は不自然。", "と": "共同を示す『と』は向く対象にならず、『東南と向いている』は意味が通らない。"}, "error_tags": {"で": "手段の誤り", "から": "起点の誤り", "と": "共同の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "西北", "is_correct": true, "explanation": "東南の正反対の方角で、対義語として辞典にも挙がる。"}, {"text": "北東", "is_correct": false, "explanation": "東南から九十度ずれた方角で、対義の関係にはない。"}, {"text": "北", "is_correct": false, "explanation": "東南から大きく離れた方角で、対義語ではない。"}, {"text": "南西", "is_correct": false, "explanation": "東南から九十度ずれた方角で、対義の関係にはない。"}], "correct_answer": "西北", "explanations": {"西北": "東南の正反対の方角で、対義語として辞典にも挙がる。", "北東": "東南から九十度ずれた方角で、対義の関係にはない。", "北": "東南から大きく離れた方角で、対義語ではない。", "南西": "東南から九十度ずれた方角で、対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『東南の空』で、空を修飾する『の』。正しい。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す『に』は『東南に空』と続かず、『東南に空に』は助詞が重なる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は『東南へ空に』と続かず、文として成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す『より』は『東南より空に』と続かず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "『東南の空』で、空を修飾する『の』。正しい。", "に": "位置を示す『に』は『東南に空』と続かず、『東南に空に』は助詞が重なる。", "へ": "方向を示す『へ』は『東南へ空に』と続かず、文として成立しない。", "より": "比較を示す『より』は『東南より空に』と続かず、意味が通らない。"}, "error_tags": {"に": "位置の誤り", "へ": "方向の誤り", "より": "比較の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "西北", "is_correct": true, "explanation": "東南の正反対の方角で、対義語として辞典にも挙がる。"}, {"text": "西南", "is_correct": false, "explanation": "南西と同じ方角を表す語で、対義語ではない。"}, {"text": "南", "is_correct": false, "explanation": "東南の構成要素のひとつで、対義語ではない。"}, {"text": "東", "is_correct": false, "explanation": "東南の構成要素のひとつで、対義語ではない。"}], "correct_answer": "西北", "explanations": {"西北": "東南の正反対の方角で、対義語として辞典にも挙がる。", "西南": "南西と同じ方角を表す語で、対義語ではない。", "南": "東南の構成要素のひとつで、対義語ではない。", "東": "東南の構成要素のひとつで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "東と南の間の方角のこと。", "primary_collocate": null, "pronunciation": "とうなん", "ipa": "toːnaɴ", "syllable_count": 4, "sentences": [{"text": "台風は東南の方角へ進んでいる。", "target_word": "東南", "complexity_tier": "T3", "furigana": "台風[たいふう]は東南[とうなん]の方角[ほうがく]へ進[すす]んでいる。", "sentence_source": "generated"}, {"text": "私の部屋の窓は東南を向いている。", "target_word": "東南", "complexity_tier": "T3", "furigana": "私[わたし]の部屋[へや]の窓[まど]は東南[とうなん]を向[む]いている。", "sentence_source": "generated"}, {"text": "駅から見て、公園は東南にある。", "target_word": "東南", "complexity_tier": "T3", "furigana": "駅[えき]から見[み]て、公園[こうえん]は東南[とうなん]にある。", "sentence_source": "generated"}, {"text": "東南の風が吹くと、あたたかくなる。", "target_word": "東南", "complexity_tier": "T3", "furigana": "東南[とうなん]の風[かぜ]が吹[ふ]くと、あたたかくなる。", "sentence_source": "generated"}, {"text": "地図で東南を指しながら説明した。", "target_word": "東南", "complexity_tier": "T3", "furigana": "地図[ちず]で東南[とうなん]を指[さ]しながら説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この家は東南に庭があるので、朝から日が入る。", "target_word": "東南", "complexity_tier": "T3", "furigana": "この家[いえ]は東南[とうなん]に庭[にわ]があるので、朝[あさ]から日[ひ]が入[はい]る。", "sentence_source": "generated"}, {"text": "船は東南へ向かって、ゆっくり進んだ。", "target_word": "東南", "complexity_tier": "T3", "furigana": "船[ふね]は東南[とうなん]へ向[む]かって、ゆっくり進[すす]んだ。", "sentence_source": "generated"}, {"text": "東南の空に、大きな雲が見えた。", "target_word": "東南", "complexity_tier": "T3", "furigana": "東南[とうなん]の空[そら]に、大[おお]きな雲[くも]が見[み]えた。", "sentence_source": "generated"}, {"text": "町の東南にあたる場所に、小さな神社がある。", "target_word": "東南", "complexity_tier": "T3", "furigana": "町[まち]の東南[とうなん]にあたる場所[ばしょ]に、小[ちい]さな神社[じんじゃ]がある。", "sentence_source": "generated"}, {"text": "東南に歩いていくと、海に出ます。", "target_word": "東南", "complexity_tier": "T3", "furigana": "東南[とうなん]に歩[ある]いていくと、海[うみ]に出[で]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "東南", "label": "基本形"}], "register": "標準", "sense_fingerprint": "東と南の中間にあたる方角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "東南", "is_correct": true, "explanation": "『台風は東南の方角へ』と、方角を表す名詞として文が成立する。"}, {"text": "東南の", "is_correct": false, "explanation": "『の』が続くと『東南の方角の』となり、『台風は東南のの方角へ』と文が崩れる。"}, {"text": "東南に", "is_correct": false, "explanation": "『に』が続くと『台風は東南にの方角へ』となり、助詞が重なって成立しない。"}, {"text": "東南を", "is_correct": false, "explanation": "『を』が続くと『台風は東南をの方角へ』となり、助詞が重なって成立しない。"}], "explanations": {"東南": "『台風は東南の方角へ』と、方角を表す名詞として文が成立する。", "東南の": "『の』が続くと『東南の方角の』となり、『台風は東南のの方角へ』と文が崩れる。", "東南に": "『に』が続くと『台風は東南にの方角へ』となり、助詞が重なって成立しない。", "東南を": "『を』が続くと『台風は東南をの方角へ』となり、助詞が重なって成立しない。"}, "sentence_index": 0, "correct_answer": "東南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "東南アジアへ旅行して、屋台の料理を楽しんだ。", "explanation": "ここは〈地域名〉の意味（東南アジア）。方角としての東南ではなく地域の名前なので、教える義項とは合わない。"}, {"text": "夏休みに東南本線で仙台へ向かった。", "explanation": "ここは〈東北本線〉の取り違え。仙台へ向かう路線は東北本線で、東南本線という路線はないので合わない。"}, {"text": "東南環状線に乗って、大阪城へ向かった。", "explanation": "ここは〈大阪環状線〉の取り違え。大阪城へ向かう環状線は大阪環状線で、東南環状線という路線はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "東南", "is_correct": true, "explanation": "『船は東南へ向かって』と、方角を表す名詞として文が成立する。"}, {"text": "東南は", "is_correct": false, "explanation": "『は』が続くと『船は東南はへ向かって』となり、助詞が重なって成立しない。"}, {"text": "東南が", "is_correct": false, "explanation": "『が』が続くと『船は東南がへ向かって』となり、助詞が重なって成立しない。"}, {"text": "東南で", "is_correct": false, "explanation": "『で』が続くと『船は東南でへ向かって』となり、助詞が重なって成立しない。"}], "explanations": {"東南": "『船は東南へ向かって』と、方角を表す名詞として文が成立する。", "東南は": "『は』が続くと『船は東南はへ向かって』となり、助詞が重なって成立しない。", "東南が": "『が』が続くと『船は東南がへ向かって』となり、助詞が重なって成立しない。", "東南で": "『で』が続くと『船は東南でへ向かって』となり、助詞が重なって成立しない。"}, "sentence_index": 6, "correct_answer": "東南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "東南新幹線に乗って、仙台へ向かった。", "explanation": "ここは『東北新幹線』という路線名の一部。東北を東南と誤っており、東南新幹線という路線はないので合わない。"}, {"text": "東南諸島へ船で向かった。", "explanation": "ここは『南西諸島』に近い呼び方の誤り。東南諸島という呼び方はなく、方角の意味としても合わない。"}, {"text": "東南戦争は明治時代に起きた。", "explanation": "ここは『西南戦争』という名称の一部。東南戦争という出来事はなく、方角の意味としても合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船は東南で向かって、夕方に着いた。", "corrected_sentence": "船は東南へ向かって、夕方に着いた。", "error_description": "誤った形は『東南で』（で）。正しい形は『東南へ』（へ）。『向かう』は方向を『へ』で示すので、『で』は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38980, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "東南を見える島が、火山島だ。", "corrected_sentence": "東南に見える島が、火山島だ。", "error_description": "誤った形は『東南を』（を）。正しい形は『東南に』（に）。『見える』は見える方向を『に』で示すので、『を』は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は動作の場所を表す。「国内でしか売っていない」という限定に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表す。「国内がしか売っていない」は主語の形にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表す。「国内をしか売っていない」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「国内へしか売っていない」は方向の意味にならず不自然。"}], "correct_answer": "で", "explanations": {"で": "「で」は動作の場所を表す。「国内でしか売っていない」という限定に合う。", "が": "「が」は主語を表す。「国内がしか売っていない」は主語の形にならず不自然。", "を": "「を」は動作の対象を表す。「国内をしか売っていない」は文が成り立たない。", "へ": "「へ」は方向を表す。「国内へしか売っていない」は方向の意味にならず不自然。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "海外", "is_correct": true, "explanation": "「国内」の対義語。国の外を指し、「国内」と対になる語。"}, {"text": "地方", "is_correct": false, "explanation": "国内の中の一地域を指す語で、「国内」の反対ではない。"}, {"text": "郊外", "is_correct": false, "explanation": "都市の外側の地域を指す語で、「国内」とは対にならない。"}, {"text": "屋外", "is_correct": false, "explanation": "建物の外を指す語で、屋内の対義語。「国内」とは対にならない。"}], "correct_answer": "海外", "explanations": {"海外": "「国内」の対義語。国の外を指し、「国内」と対になる語。", "地方": "国内の中の一地域を指す語で、「国内」の反対ではない。", "郊外": "都市の外側の地域を指す語で、「国内」とは対にならない。", "屋外": "建物の外を指す語で、屋内の対義語。「国内」とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は動作の場所を表す。国内で過ごすという場所の指定に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点を表す。「国内に過ごす」は過ごす場所として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共にする相手を表す。「国内と過ごす」は場所として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表す。「国内へ過ごす」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「で」は動作の場所を表す。国内で過ごすという場所の指定に合う。", "に": "「に」は到達点を表す。「国内に過ごす」は過ごす場所として不自然。", "と": "「と」は共にする相手を表す。「国内と過ごす」は場所として成り立たない。", "へ": "「へ」は移動の方向を表す。「国内へ過ごす」は意味が通らない。"}, "error_tags": {"に": "到達・存在の場所", "と": "共にする相手", "へ": "移動の方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "海外", "is_correct": true, "explanation": "「国内」の対義語。国の外を指し、「国内」と対になる語。"}, {"text": "世界", "is_correct": false, "explanation": "地球全体を指す語で、「国内」の反対語ではない。"}, {"text": "沿岸", "is_correct": false, "explanation": "海に沿った陸地を指す語で、「国内」とは対にならない。"}, {"text": "港町", "is_correct": false, "explanation": "港のある町を指す語で、「国内」の反対語ではない。"}], "correct_answer": "海外", "explanations": {"海外": "「国内」の対義語。国の外を指し、「国内」と対になる語。", "世界": "地球全体を指す語で、「国内」の反対語ではない。", "沿岸": "海に沿った陸地を指す語で、「国内」とは対にならない。", "港町": "港のある町を指す語で、「国内」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国の、中や内側のこと。", "primary_collocate": null, "pronunciation": "こくない", "ipa": "kokɯnai", "syllable_count": 4, "sentences": [{"text": "国内の旅行は、海外より安く行ける。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]の旅行[りょこう]は、海外[かいがい]より安[やす]く行[い]ける。", "sentence_source": "generated"}, {"text": "この商品は国内でしか売っていない。", "target_word": "国内", "complexity_tier": "T3", "furigana": "この商品[しょうひん]は国内[こくない]でしか売[う]っていない。", "sentence_source": "generated"}, {"text": "国内にいる間に、パスポートを作っておこう。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]にいる間[あいだ]に、パスポートを作[つく]っておこう。", "sentence_source": "generated"}, {"text": "彼は国内の有名な大学を卒業した。", "target_word": "国内", "complexity_tier": "T3", "furigana": "彼[かれ]は国内[こくない]の有名[ゆうめい]な大学[だいがく]を卒業[そつぎょう]した。", "sentence_source": "generated"}, {"text": "台風のせいで、国内の多くの空港が閉まった。", "target_word": "国内", "complexity_tier": "T3", "furigana": "台風[たいふう]のせいで、国内[こくない]の多[おお]くの空港[くうこう]が閉[し]まった。", "sentence_source": "generated"}, {"text": "国内の景気がよくなって、仕事が増えた。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]の景気[けいき]がよくなって、仕事[しごと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "国内で作った野菜を食べるようにしている。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]で作[つく]った野菜[やさい]を食[た]べるようにしている。", "sentence_source": "generated"}, {"text": "夏休みは海外ではなく、国内で過ごすつもりだ。", "target_word": "国内", "complexity_tier": "T3", "furigana": "夏休[なつやす]みは海外[かいがい]ではなく、国内[こくない]で過[す]ごすつもりだ。", "sentence_source": "generated"}, {"text": "国内のニュースより、海外のニュースに興味がある。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]のニュースより、海外[かいがい]のニュースに興味[きょうみ]がある。", "sentence_source": "generated"}, {"text": "国内の川の中で、この川は二番目に長い。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]の川[かわ]の中[なか]で、この川[かわ]は二番目[にばんめ]に長[なが]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国内", "label": "基本形"}, {"form": "国内の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "自分の国の中。海外に対して、国の内側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内", "is_correct": true, "explanation": "「国内」は国の中という意味。「海外より安く行ける」という対比に合う。"}, {"text": "機内", "is_correct": false, "explanation": "「機内」は飛行機の中のこと。「機内の旅行」では海外との対比にならず、意味が通らない。"}, {"text": "空港", "is_correct": false, "explanation": "「空港」は施設の名前。「空港の旅行」は旅行の範囲として成り立たない。"}, {"text": "駅前", "is_correct": false, "explanation": "「駅前」は駅の周辺を指す。「駅前の旅行」は海外との比較文に合わない。"}], "explanations": {"国内": "「国内」は国の中という意味。「海外より安く行ける」という対比に合う。", "機内": "「機内」は飛行機の中のこと。「機内の旅行」では海外との対比にならず、意味が通らない。", "空港": "「空港」は施設の名前。「空港の旅行」は旅行の範囲として成り立たない。", "駅前": "「駅前」は駅の周辺を指す。「駅前の旅行」は海外との比較文に合わない。"}, "sentence_index": 0, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "グラスの国内に、水滴がたくさんついていた。", "explanation": "ここは〈中〉の意味。グラスの中の水滴を指す場面で、国内は国の内部を指す語なので、器の中には使えない。"}, {"text": "寒い日は、国内で体を動かすようにしている。", "explanation": "ここは〈室内〉の意味。屋内で体を動かす場面で、国内は国の範囲を指すので合わない。"}, {"text": "三日国内に返事をください。", "explanation": "ここは〈以内〉の意味。期限は「三日以内に」と言うので、国内では期限を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内", "is_correct": true, "explanation": "「国内」は国の中という意味。国内で作った野菜という生産の場所に合う。"}, {"text": "売店", "is_correct": false, "explanation": "「売店」は商品を売る店。「売店で作った野菜」は生産の場所として不自然。"}, {"text": "船室", "is_correct": false, "explanation": "「船室」は船の中の部屋。「船室で作った野菜」は生産の場所として合わない。"}, {"text": "祭壇", "is_correct": false, "explanation": "「祭壇」は供え物を置く台。野菜を作る場所ではないので文が成り立たない。"}], "explanations": {"国内": "「国内」は国の中という意味。国内で作った野菜という生産の場所に合う。", "売店": "「売店」は商品を売る店。「売店で作った野菜」は生産の場所として不自然。", "船室": "「船室」は船の中の部屋。「船室で作った野菜」は生産の場所として合わない。", "祭壇": "「祭壇」は供え物を置く台。野菜を作る場所ではないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国内の水分が足りないと、頭が痛くなる。", "explanation": "ここは〈体内〉の意味。体の中の状態を指す語で、国内は国の範囲なので体の中には使えない。"}, {"text": "国内に出るには、パスポートが要る。", "explanation": "ここは〈国外〉の意味。国の外へ出る話なので〈国外〉が合い、国内は出ていく先にならない。"}, {"text": "予算の国内で買い物をしよう。", "explanation": "ここは〈範囲内〉の意味。予算の枠を表す語で、国内は国の内側を指すので予算には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この果物は国内をしか手に入らない。", "corrected_sentence": "この果物は国内でしか手に入らない。", "error_description": "「手に入る」の場所は「で」で表す。「を」は動作の対象に使うので、「国内でしか」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38982, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国内を生産された米が店に並んだ。", "corrected_sentence": "国内で生産された米が店に並んだ。", "error_description": "「生産された」の場所は「で」で表す。「を」は誤り（正しくは「で」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は名詞をつなぐ。「国内の法律」と法律を修飾する形に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表す。「国内が法律は」となり、修飾の形が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。「国内を法律」では名詞の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「国内へ法律は」は方向の意味にならず、文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「の」は名詞をつなぐ。「国内の法律」と法律を修飾する形に合う。", "が": "「が」は主語を表す。「国内が法律は」となり、修飾の形が崩れる。", "を": "「を」は目的語を表す。「国内を法律」では名詞の関係が成り立たない。", "へ": "「へ」は方向を表す。「国内へ法律は」は方向の意味にならず、文が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "海外", "is_correct": true, "explanation": "「国内」の対義語。国の外を指し、「国内」と対になる語。"}, {"text": "山間", "is_correct": false, "explanation": "山あいの地域を指す語で、「国内」の反対ではない。"}, {"text": "離島", "is_correct": false, "explanation": "海に囲まれた島を指す語で、「国内」とは対にならない。"}, {"text": "辺境", "is_correct": false, "explanation": "国や地域の端の地域を指す語で、「国内」の反対語ではない。"}], "correct_answer": "海外", "explanations": {"海外": "「国内」の対義語。国の外を指し、「国内」と対になる語。", "山間": "山あいの地域を指す語で、「国内」の反対ではない。", "離島": "海に囲まれた島を指す語で、「国内」とは対にならない。", "辺境": "国や地域の端の地域を指す語で、「国内」の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は名詞をつなぐ。「国内の問題」と問題を修飾する形に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「国内へ問題」は名詞の関係として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。「国内を問題が多く」では名詞がつながらず成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表す。「国内と問題が多く」は並列としても意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「の」は名詞をつなぐ。「国内の問題」と問題を修飾する形に合う。", "へ": "「へ」は方向を表す。「国内へ問題」は名詞の関係として成り立たない。", "を": "「を」は目的語を表す。「国内を問題が多く」では名詞がつながらず成り立たない。", "と": "「と」は並列を表す。「国内と問題が多く」は並列としても意味が通らない。"}, "error_tags": {"へ": "方向", "を": "目的語", "と": "並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "海外", "is_correct": true, "explanation": "「国内」の対義語。国の外を指し、「国内」と対になる語。"}, {"text": "郷土", "is_correct": false, "explanation": "故郷の土地を指す語で、「国内」の反対語ではない。"}, {"text": "城下", "is_correct": false, "explanation": "城の周りの町を指す語で、「国内」とは対にならない。"}, {"text": "田園", "is_correct": false, "explanation": "田畑の広がる地域を指す語で、「国内」の反対語ではない。"}], "correct_answer": "海外", "explanations": {"海外": "「国内」の対義語。国の外を指し、「国内」と対になる語。", "郷土": "故郷の土地を指す語で、「国内」の反対語ではない。", "城下": "城の周りの町を指す語で、「国内」とは対にならない。", "田園": "田畑の広がる地域を指す語で、「国内」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その国の内部。国家の領域内。", "primary_collocate": null, "pronunciation": "こくない", "ipa": "kokɯnai", "syllable_count": 4, "sentences": [{"text": "外国人が国内で働くには、許可が必要だ。", "target_word": "国内", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]が国内[こくない]で働[はたら]くには、許可[きょか]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "国内の法律は、全員が守らなければならない。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]の法律[ほうりつ]は、全員[ぜんいん]が守[まも]らなければならない。", "sentence_source": "generated"}, {"text": "戦争が終わり、国内はやっと落ち着いた。", "target_word": "国内", "complexity_tier": "T3", "furigana": "戦争[せんそう]が終[お]わり、国内[こくない]はやっと落[お]ち着[つ]いた。", "sentence_source": "generated"}, {"text": "この薬は、国内では使うことが認められていない。", "target_word": "国内", "complexity_tier": "T3", "furigana": "この薬[くすり]は、国内[こくない]では使[つか]うことが認[みと]められていない。", "sentence_source": "generated"}, {"text": "国内の治安を守るのは、警察の仕事だ。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]の治安[ちあん]を守[まも]るのは、警察[けいさつ]の仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "海外から戻り、国内の空港で荷物の検査を受けた。", "target_word": "国内", "complexity_tier": "T3", "furigana": "海外[かいがい]から戻[もど]り、国内[こくない]の空港[くうこう]で荷物[にもつ]の検査[けんさ]を受[う]けた。", "sentence_source": "generated"}, {"text": "大雪で、国内の交通が止まってしまった。", "target_word": "国内", "complexity_tier": "T3", "furigana": "大雪[おおゆき]で、国内[こくない]の交通[こうつう]が止[と]まってしまった。", "sentence_source": "generated"}, {"text": "その国では国内の問題が多く、外交に力を入れられない。", "target_word": "国内", "complexity_tier": "T3", "furigana": "その国[くに]では国内[こくない]の問題[もんだい]が多[おお]く、外交[がいこう]に力[ちから]を入[い]れられない。", "sentence_source": "generated"}, {"text": "国内で起きた事件を、海外の新聞も伝えた。", "target_word": "国内", "complexity_tier": "T3", "furigana": "国内[こくない]で起[お]きた事件[じけん]を、海外[かいがい]の新聞[しんぶん]も伝[つた]えた。", "sentence_source": "generated"}, {"text": "輸入が増え、国内の工場は苦しくなった。", "target_word": "国内", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]が増[ふ]え、国内[こくない]の工場[こうじょう]は苦[くる]しくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国内", "label": "基本形"}, {"form": "国内の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "ある国家の領域の内部。法律や政治、治安が及ぶ範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内", "is_correct": true, "explanation": "「国内」は国の範囲という意味。外国人が国の中で働くには許可が要る、という文に合う。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室」は寝るための部屋。外国人が寝室で働くのは不自然で、許可の話にもならない。"}, {"text": "祭壇", "is_correct": false, "explanation": "「祭壇」は供え物を置く台。働く場所として成り立たない。"}, {"text": "水槽", "is_correct": false, "explanation": "「水槽」は水を入れる容器。働く場所として不自然で、許可の文脈に合わない。"}], "explanations": {"国内": "「国内」は国の範囲という意味。外国人が国の中で働くには許可が要る、という文に合う。", "寝室": "「寝室」は寝るための部屋。外国人が寝室で働くのは不自然で、許可の話にもならない。", "祭壇": "「祭壇」は供え物を置く台。働く場所として成り立たない。", "水槽": "「水槽」は水を入れる容器。働く場所として不自然で、許可の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "密輸品が国内を越えて運ばれた。", "explanation": "ここは〈国境〉の意味。国内は国の内側なので、越えるという動きとは合わない。"}, {"text": "国内の異物を取り除く手術が、無事に終わった。", "explanation": "ここは〈体内〉の意味。体の中の状態を指す語で、国の範囲を指す国内は使えない。"}, {"text": "結果は来週国内に知らせます。", "explanation": "ここは〈以内〉の意味。期限は「来週以内に」と言うので、国内では期限を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内", "is_correct": true, "explanation": "「国内」は国の範囲という意味。大雪で交通が止まる地域の広さを示すので合う。"}, {"text": "浴槽", "is_correct": false, "explanation": "「浴槽」は湯を入れる容器。「浴槽の交通」は意味が通らない。"}, {"text": "本棚", "is_correct": false, "explanation": "「本棚」は本を並べる家具。交通を修飾する語として成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫」は食品を冷やす箱。交通の範囲を表す語として不自然。"}], "explanations": {"国内": "「国内」は国の範囲という意味。大雪で交通が止まる地域の広さを示すので合う。", "浴槽": "「浴槽」は湯を入れる容器。「浴槽の交通」は意味が通らない。", "本棚": "「本棚」は本を並べる家具。交通を修飾する語として成り立たない。", "冷蔵庫": "「冷蔵庫」は食品を冷やす箱。交通の範囲を表す語として不自然。"}, "sentence_index": 6, "correct_answer": "国内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国内の温度が上がり、乗客が汗をかいた。", "explanation": "ここは〈機内〉の意味。飛行機の中の温度を指す語で、国内は国の範囲なので合わない。"}, {"text": "窓を開けて、国内の空気を入れ替えた。", "explanation": "ここは〈室内〉の意味。空気の入れ替えは部屋の中の話で、国内は国の範囲を指すので合わない。"}, {"text": "国内の水を捨ててください。", "explanation": "ここは〈容器内〉の意味。容器の中の水を指す場面で、国内は国の範囲なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国では、国内を安全を守るため法律が作られた。", "corrected_sentence": "この国では、国内の安全を守るため法律が作られた。", "error_description": "「安全」を修飾するには「の」が必要。「を」は動詞の目的語に使うので、「国内の安全」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38983, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国内を発生した地震で、道路が通れなくなった。", "corrected_sentence": "国内で発生した地震で、道路が通れなくなった。", "error_description": "「発生する」は自動詞で、目的語の「を」は取らない。場所は「で」で表すので、「国内で発生した」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は名詞をつなぐ。公衆の意見と意見を修飾する形に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。「公衆を意見」では名詞の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「公衆へ意見」は修飾の形にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表す。「公衆より意見」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「の」は名詞をつなぐ。公衆の意見と意見を修飾する形に合う。", "を": "「を」は目的語を表す。「公衆を意見」では名詞の関係が成り立たない。", "へ": "「へ」は方向を表す。「公衆へ意見」は修飾の形にならない。", "より": "「より」は比較の基準を表す。「公衆より意見」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較の基準"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「が」は主語を表す。公衆が使うという主語の関係に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。「公衆を使う場所」では人を使う形になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や到達点を表す。「公衆に使う場所」は文の関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「公衆から使う場所」は主語の関係として不自然。"}], "correct_answer": "が", "explanations": {"が": "「が」は主語を表す。公衆が使うという主語の関係に合う。", "を": "「を」は目的語を表す。「公衆を使う場所」では人を使う形になり、文が成り立たない。", "に": "「に」は相手や到達点を表す。「公衆に使う場所」は文の関係が成り立たない。", "から": "「から」は起点を表す。「公衆から使う場所」は主語の関係として不自然。"}, "error_tags": {"に": "相手・到達点", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みんな。よのなかの ひとたち。", "primary_collocate": null, "pronunciation": "こうしゅう", "ipa": "koːɕɯː", "syllable_count": 4, "sentences": [{"text": "公衆の前で大声を出すのは、はずかしい。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の前[まえ]で大声[おおごえ]を出[だ]すのは、はずかしい。", "sentence_source": "generated"}, {"text": "公衆の意見を聞いて、新しい公園を作った。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の意見[いけん]を聞[き]いて、新[あたら]しい公園[こうえん]を作[つく]った。", "sentence_source": "generated"}, {"text": "市長は公衆に向かって、やさしく話しかけた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "市長[しちょう]は公衆[こうしゅう]に向[む]かって、やさしく話[はな]しかけた。", "sentence_source": "generated"}, {"text": "公衆の安全を守るため、道に柵を立てた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の安全[あんぜん]を守[まも]るため、道[みち]に柵[さく]を立[た]てた。", "sentence_source": "generated"}, {"text": "公衆の目があるところでは、静かにしましょう。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の目[め]があるところでは、静[しず]かにしましょう。", "sentence_source": "generated"}, {"text": "公衆の健康のために、駅の中は禁煙になった。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の健康[けんこう]のために、駅[えき]の中[なか]は禁煙[きんえん]になった。", "sentence_source": "generated"}, {"text": "新しい決まりは、公衆に広く知らされた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "新[あたら]しい決[き]まりは、公衆[こうしゅう]に広[ひろ]く知[し]らされた。", "sentence_source": "generated"}, {"text": "公衆が使う場所は、みんなできれいに使おう。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]が使[つか]う場所[ばしょ]は、みんなできれいに使[つか]おう。", "sentence_source": "generated"}, {"text": "公衆の集まる広場で、お祭りが開かれた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の集[あつ]まる広場[ひろば]で、お祭[まつ]りが開[ひら]かれた。", "sentence_source": "generated"}, {"text": "公衆のためになる仕事がしたくて、市役所に入った。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]のためになる仕事[しごと]がしたくて、市役所[しやくしょ]に入[はい]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公衆", "label": "基本形"}, {"form": "公衆の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "特定でない、世の中の大勢の人たち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公衆", "is_correct": true, "explanation": "「公衆」は不特定多数の人々。人前で大声を出す場面の「人前」の意味に合う。"}, {"text": "鏡台", "is_correct": false, "explanation": "「鏡台」は化粧用の台。「鏡台の前で大声を出す」は場面として不自然。"}, {"text": "窓辺", "is_correct": false, "explanation": "「窓辺」は窓の近く。「窓辺の前で」は意味が通らない。"}, {"text": "戸棚", "is_correct": false, "explanation": "「戸棚」は物を入れる棚。「戸棚の前で大声を出す」は不自然で、はずかしさの場面に合わない。"}], "explanations": {"公衆": "「公衆」は不特定多数の人々。人前で大声を出す場面の「人前」の意味に合う。", "鏡台": "「鏡台」は化粧用の台。「鏡台の前で大声を出す」は場面として不自然。", "窓辺": "「窓辺」は窓の近く。「窓辺の前で」は意味が通らない。", "戸棚": "「戸棚」は物を入れる棚。「戸棚の前で大声を出す」は不自然で、はずかしさの場面に合わない。"}, "sentence_index": 0, "correct_answer": "公衆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公用の車の代わりに、公衆の車を使って出張に行った。", "explanation": "ここは〈公用〉の意味。会社や役所の仕事で使う車を指す語で、公衆は不特定多数の人なので車の持ち主にならない。"}, {"text": "私の公衆は、毎朝早く起きる。", "explanation": "ここは〈家族〉の意味。身内の特定の相手を指す語で、公衆は不特定多数の人なので私の身内には使えない。"}, {"text": "公衆の捜査が進んで、犯人が捕まった。", "explanation": "ここは〈公安〉の意味。警察などが行う安全を守るための捜査を指す語で、公衆は捜査の主体にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公衆", "is_correct": true, "explanation": "「公衆」は一般の人々。決まりを広く知らせる相手として合う。"}, {"text": "天井", "is_correct": false, "explanation": "「天井」は部屋の上の面。決まりを知らせる相手にはならない。"}, {"text": "石畳", "is_correct": false, "explanation": "「石畳」は地面に敷いた石。知らされる対象として不自然。"}, {"text": "植木鉢", "is_correct": false, "explanation": "「植木鉢」は植物を植える容器。知らせる相手にはならない。"}], "explanations": {"公衆": "「公衆」は一般の人々。決まりを広く知らせる相手として合う。", "天井": "「天井」は部屋の上の面。決まりを知らせる相手にはならない。", "石畳": "「石畳」は地面に敷いた石。知らされる対象として不自然。", "植木鉢": "「植木鉢」は植物を植える容器。知らせる相手にはならない。"}, "sentence_index": 6, "correct_answer": "公衆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公衆として、市民のために働く。", "explanation": "ここは〈公僕〉の意味。公務員の立場を表す語で、公衆は一般の人々を指すので立場の名前にならない。"}, {"text": "公衆の友人と、遊園地に行った。", "explanation": "ここは〈友人〉の意味。親しい特定の相手を指す語で、公衆は不特定多数の人なので友人には使えない。"}, {"text": "公衆の資格を取って、看護の仕事を始めた。", "explanation": "ここは〈公認〉の意味。公的に認められた資格を指す語で、公衆は資格の種類ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公衆に前で、大きな声で話すのは控えよう。", "corrected_sentence": "公衆の前で、大きな声で話すのは控えよう。", "error_description": "「前」を修飾するには「の」が必要。「に」は到着点を表すので、「公衆の前で」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38984, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公衆を集まる広場で、体操の会が開かれた。", "corrected_sentence": "公衆が集まる広場で、体操の会が開かれた。", "error_description": "「集まる」は自動詞なので、主語の「公衆」には「が」を使う。「を」は誤り（正しくは「が」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は向かう先を表す。「公衆に向けて」の向かう相手に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。「公衆を向けて」は動作の対象として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表す。「公衆が向けて」は主語の形として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共にする相手を表す。「公衆と向けて」は向きの表現にならない。"}], "correct_answer": "に", "explanations": {"に": "「に」は向かう先を表す。「公衆に向けて」の向かう相手に合う。", "を": "「を」は目的語を表す。「公衆を向けて」は動作の対象として成り立たない。", "が": "「が」は主語を表す。「公衆が向けて」は主語の形として不自然。", "と": "「と」は共にする相手を表す。「公衆と向けて」は向きの表現にならない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "共にする相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は名詞をつなぐ。公衆の反応と反応を修飾する形に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「公衆で反応を見て」は反応の主体にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表す。「公衆より反応を見て」は文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「公衆へ反応を見て」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「の」は名詞をつなぐ。公衆の反応と反応を修飾する形に合う。", "で": "「で」は場所や手段を表す。「公衆で反応を見て」は反応の主体にならない。", "より": "「より」は比較の基準を表す。「公衆より反応を見て」は文の流れに合わない。", "へ": "「へ」は方向を表す。「公衆へ反応を見て」は意味が通らない。"}, "error_tags": {"で": "場所・手段", "より": "比較の基準", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "社会一般の人々。世間の人々。", "primary_collocate": null, "pronunciation": "こうしゅう", "ipa": "koːɕɯː", "syllable_count": 4, "sentences": [{"text": "公衆の利益を考えて、道路を広げることが決まった。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の利益[りえき]を考[かんが]えて、道路[どうろ]を広[ひろ]げることが決[き]まった。", "sentence_source": "generated"}, {"text": "政府は公衆に向けて、感染への注意をよびかけた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "政府[せいふ]は公衆[こうしゅう]に向[む]けて、感染[かんせん]への注意[ちゅうい]をよびかけた。", "sentence_source": "generated"}, {"text": "公衆の信頼を失った会社は、客が減った。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の信頼[しんらい]を失[うしな]った会社[かいしゃ]は、客[きゃく]が減[へ]った。", "sentence_source": "generated"}, {"text": "公衆の面前で人をしかるのは、よくない。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の面前[めんぜん]で人[ひと]をしかるのは、よくない。", "sentence_source": "generated"}, {"text": "博物館は、広く公衆に開かれている。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]は、広[ひろ]く公衆[こうしゅう]に開[ひら]かれている。", "sentence_source": "generated"}, {"text": "この図書館は公衆が自由に使える。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は公衆[こうしゅう]が自由[じゆう]に使[つか]える。", "sentence_source": "generated"}, {"text": "公衆の関心が高い事件なので、新聞が大きく伝えた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の関心[かんしん]が高[たか]い事件[じけん]なので、新聞[しんぶん]が大[おお]きく伝[つた]えた。", "sentence_source": "generated"}, {"text": "公衆の反応を見てから、値段を決めるつもりだ。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の反応[はんのう]を見[み]てから、値段[ねだん]を決[き]めるつもりだ。", "sentence_source": "generated"}, {"text": "記者は公衆が知るべき事実を、正しく伝えた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "記者[きしゃ]は公衆[こうしゅう]が知[し]るべき事実[じじつ]を、正[ただ]しく伝[つた]えた。", "sentence_source": "generated"}, {"text": "公衆の健康を守る法律が、新しく作られた。", "target_word": "公衆", "complexity_tier": "T3", "furigana": "公衆[こうしゅう]の健康[けんこう]を守[まも]る法律[ほうりつ]が、新[あたら]しく作[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公衆", "label": "基本形"}, {"form": "公衆の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "社会全体を成す不特定多数の人々。世間一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: よびかけ (Zipf 1.99)']::text[], '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公衆", "is_correct": true, "explanation": "「公衆」は社会の人々を指し、利益を考える対象として合う。"}, {"text": "金庫", "is_correct": false, "explanation": "「金庫」は物を入れる箱。「金庫の利益」は意味が通らない。"}, {"text": "花瓶", "is_correct": false, "explanation": "「花瓶」は花を生ける容器。利益を考える対象にはならない。"}, {"text": "電池", "is_correct": false, "explanation": "「電池」は電気を蓄える部品。「電池の利益」は文として成り立たない。"}], "explanations": {"公衆": "「公衆」は社会の人々を指し、利益を考える対象として合う。", "金庫": "「金庫」は物を入れる箱。「金庫の利益」は意味が通らない。", "花瓶": "「花瓶」は花を生ける容器。利益を考える対象にはならない。", "電池": "「電池」は電気を蓄える部品。「電池の利益」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "公衆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の公衆に、新しい服を買ってあげた。", "explanation": "ここは〈家族〉の意味。身内の相手を指す語で、公衆は不特定多数なので身内には使えない。"}, {"text": "公衆で海外に出張する。", "explanation": "ここは〈公務〉の意味。仕事としての出張を表す語で、公衆は一般の人々を指すので出張の主体にならない。"}, {"text": "公衆の日程が決まり、会場を押さえた。", "explanation": "ここは〈公演〉の意味。舞台などの催しを指す語で、公衆は人々を指すので日程の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公衆", "is_correct": true, "explanation": "「公衆」は世間の人々を指し、関心を持つ主体として合う。"}, {"text": "陶器", "is_correct": false, "explanation": "「陶器」は焼き物。「陶器の関心」は主語として成り立たない。"}, {"text": "湯呑み", "is_correct": false, "explanation": "「湯呑み」はお茶を飲む器。関心を持つ相手にはならない。"}, {"text": "寝袋", "is_correct": false, "explanation": "「寝袋」は寝るための袋。「寝袋の関心」は意味が通らない。"}], "explanations": {"公衆": "「公衆」は世間の人々を指し、関心を持つ主体として合う。", "陶器": "「陶器」は焼き物。「陶器の関心」は主語として成り立たない。", "湯呑み": "「湯呑み」はお茶を飲む器。関心を持つ相手にはならない。", "寝袋": "「寝袋」は寝るための袋。「寝袋の関心」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "公衆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題の公衆を、先生に見せた。", "explanation": "公衆は人々を指す語で、答案の意味にはならない。宿題の答案の代わりには使えない。"}, {"text": "公衆によって、選挙が始まった。", "explanation": "ここは〈公示〉の意味。役所が決まりを人々に知らせることを指す語で、公衆は知らせの主体にならない。"}, {"text": "公衆の入り口に、花が咲いた。", "explanation": "ここは〈公園〉の意味。場所を指す語で、公衆は人々を指すので入り口の位置にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公衆を関心が高い話題なので、番組で取り上げた。", "corrected_sentence": "公衆の関心が高い話題なので、番組で取り上げた。", "error_description": "「関心」を修飾するには「の」が必要。「を」は動作の対象に使うので、「公衆の関心」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38985, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公衆を参加する催しを、毎月開いている。", "corrected_sentence": "公衆が参加する催しを、毎月開いている。", "error_description": "「参加する」の主語には「が」を使う。「を」は誤り（正しくは「が」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「光が交錯して」で、光と影が入り混じる主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「光を交錯して」は他動詞の形にならず、交錯は主語を取る。"}, {"text": "で", "is_correct": false, "explanation": "「光で交錯して」は手段の意味になり、入り混じる状態に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、交錯の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「光が交錯して」で、光と影が入り混じる主語を示す。", "を": "「光を交錯して」は他動詞の形にならず、交錯は主語を取る。", "で": "「光で交錯して」は手段の意味になり、入り混じる状態に合わない。", "より": "比較の「より」では、交錯の主語を示せない。"}, "error_tags": {"を": "目的語", "で": "手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「二つの道が交錯する」で、道が入り混じる主語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では、道の入り混じりを示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、道が交わる状態を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「道に交錯する」は対象を示す形として不自然。"}], "correct_answer": "が", "explanations": {"が": "正解。「二つの道が交錯する」で、道が入り混じる主語を示す。", "へ": "方向の「へ」では、道の入り混じりを示せない。", "から": "起点の「から」は、道が交わる状態を表せない。", "に": "「道に交錯する」は対象を示す形として不自然。"}, "error_tags": {"へ": "方向", "から": "起点", "に": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つ以上のものが、互いにまじり合うこと。", "primary_collocate": null, "pronunciation": "こうさく", "ipa": "koːsakɯ", "syllable_count": 4, "sentences": [{"text": "試験の前夜は、期待と不安が交錯して眠れなかった。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "試験[しけん]の前夜[ぜんや]は、期待[きたい]と不安[ふあん]が交錯[こうさく]して眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "森の中では、木の影と光が交錯して美しい模様を作っていた。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]では、木[き]の影[かげ]と光[ひかり]が交錯[こうさく]して美[うつく]しい模様[もよう]を作[つく]っていた。", "sentence_source": "generated"}, {"text": "駅前では、人の流れが交錯して、まっすぐ歩けない。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "駅前[えきまえ]では、人[ひと]の流[なが]れが交錯[こうさく]して、まっすぐ歩[ある]けない。", "sentence_source": "generated"}, {"text": "彼の話には、事実とうわさが交錯していて、よく分からなかった。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]には、事実[じじつ]とうわさが交錯[こうさく]していて、よく分[わ]からなかった。", "sentence_source": "generated"}, {"text": "喜びと悲しみが交錯する中で、卒業式が終わった。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "喜[よろこ]びと悲[かな]しみが交錯[こうさく]する中[なか]で、卒業式[そつぎょうしき]が終[お]わった。", "sentence_source": "generated"}, {"text": "会場では、いろいろな言葉が交錯していた。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "会場[かいじょう]では、いろいろな言葉[ことば]が交錯[こうさく]していた。", "sentence_source": "generated"}, {"text": "夕暮れの空に、飛行機の白い線が交錯していた。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "夕暮[ゆうぐ]れの空[そら]に、飛行機[ひこうき]の白[しろ]い線[せん]が交錯[こうさく]していた。", "sentence_source": "generated"}, {"text": "二つの道が交錯する場所に、小さな店がある。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "二[ふた]つの道[みち]が交錯[こうさく]する場所[ばしょ]に、小[ちい]さな店[みせ]がある。", "sentence_source": "generated"}, {"text": "別れの場面では、感謝と寂しさが交錯した。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "別[わか]れの場面[ばめん]では、感謝[かんしゃ]と寂[さび]しさが交錯[こうさく]した。", "sentence_source": "generated"}, {"text": "窓の外では、雨音と風の音が交錯していた。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]では、雨音[あまおと]と風[かぜ]の音[おと]が交錯[こうさく]していた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交錯する", "label": "辞書形"}, {"form": "交錯した", "label": "過去形"}, {"form": "交錯して", "label": "て形"}], "register": "formal", "sense_fingerprint": "交錯=感情や光・人の流れなど二つ以上のものが入りまじること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交錯", "is_correct": true, "explanation": "正解。「期待と不安が交錯して」で、二つの感情が入り混じる状態を表す。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解く意味。感情には使わない。"}, {"text": "放棄", "is_correct": false, "explanation": "権利や責任を投げ出す意味。感情の状態には合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "取り消す意味。感情が入り混じる状態には使わない。"}], "explanations": {"交錯": "正解。「期待と不安が交錯して」で、二つの感情が入り混じる状態を表す。", "解散": "集まりを解く意味。感情には使わない。", "放棄": "権利や責任を投げ出す意味。感情の状態には合わない。", "撤回": "取り消す意味。感情が入り混じる状態には使わない。"}, "sentence_index": 0, "correct_answer": "交錯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女とは大学時代から交錯している。", "explanation": "ここは〈交際〉の意味。人と親しく付き合うことは交際と言い、入り混じるという交錯は合わない。"}, {"text": "価格について、彼と交錯を続けた。", "explanation": "ここは〈交渉〉の意味。条件を話し合って決めることは交渉と言い、交錯は入り混じる意味で使う。"}, {"text": "国会は大きな交錯に陥った。", "explanation": "ここは〈混乱〉の意味。秩序が乱れることは混乱と言い、入り混じるという交錯は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交錯", "is_correct": true, "explanation": "正解。「白い線が交錯していた」で、飛行機雲が入り混じって見える様子を表す。"}, {"text": "反発", "is_correct": false, "explanation": "押し返す意味。線の状態には合わない。"}, {"text": "脱退", "is_correct": false, "explanation": "組織から抜ける意味。線には使わない。"}, {"text": "失効", "is_correct": false, "explanation": "効力がなくなる意味。線の状態には合わない。"}], "explanations": {"交錯": "正解。「白い線が交錯していた」で、飛行機雲が入り混じって見える様子を表す。", "反発": "押し返す意味。線の状態には合わない。", "脱退": "組織から抜ける意味。線には使わない。", "失効": "効力がなくなる意味。線の状態には合わない。"}, "sentence_index": 6, "correct_answer": "交錯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二台の車が交錯して、大きな音がした。", "explanation": "ここは〈衝突〉の意味。ぶつかることは衝突と言い、入り混じるという交錯は合わない。"}, {"text": "夜勤は二人で交錯して、朝まで見張った。", "explanation": "ここは〈交代〉の意味。役目を入れ替わって受け持つことは交代と言い、交錯は入り混じる意味で使う。"}, {"text": "二つの地域が交錯して、一つの自治体になった。", "explanation": "ここは〈合併〉の意味。一つにまとまることは合併と言い、入り混じる意味の交錯は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記憶と夢を交錯して、朝まで眠れなかった。", "corrected_sentence": "記憶と夢が交錯して、朝まで眠れなかった。", "error_description": "「を」は誤り。正しくは「が」。交錯は自動詞なので、入り混じる主体に「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38986, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホームでは、人の声と電車の音が交錯しいた。", "corrected_sentence": "ホームでは、人の声と電車の音が交錯していた。", "error_description": "「交錯しいた」は誤り。「し」の後に「て」が必要で、正しくは「交錯していた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「証言が交錯して」で、複数の証言が入り混じる主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「証言を交錯して」は他動詞の形にならず、交錯は主語を取る。"}, {"text": "で", "is_correct": false, "explanation": "「証言で交錯して」は手段の意味になり、入り混じる状態に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、交錯の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「証言が交錯して」で、複数の証言が入り混じる主語を示す。", "を": "「証言を交錯して」は他動詞の形にならず、交錯は主語を取る。", "で": "「証言で交錯して」は手段の意味になり、入り混じる状態に合わない。", "より": "比較の「より」では、交錯の主語を示せない。"}, "error_tags": {"を": "目的語", "で": "手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「文化が交錯して」で、さまざまな文化が入り混じる主語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では、文化の入り混じりを示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、文化が混じる状態を表せない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では、交錯の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「文化が交錯して」で、さまざまな文化が入り混じる主語を示す。", "へ": "方向の「へ」では、文化の入り混じりを示せない。", "から": "起点の「から」は、文化が混じる状態を表せない。", "の": "連体の「の」では、交錯の主語にならない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の物事が互いに入り混じること。", "primary_collocate": null, "pronunciation": "こうさく", "ipa": "koːsakɯ", "syllable_count": 4, "sentences": [{"text": "会議では、賛成と反対の意見が交錯して、結論が出なかった。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、賛成[さんせい]と反対[はんたい]の意見[いけん]が交錯[こうさく]して、結論[けつろん]が出[で]なかった。", "sentence_source": "generated"}, {"text": "事件の現場では、いくつもの証言が交錯していた。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "事件[じけん]の現場[げんば]では、いくつもの証言[しょうげん]が交錯[こうさく]していた。", "sentence_source": "generated"}, {"text": "古い町並みには、昔と今の風景が交錯している。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "古[ふる]い町並[まちな]みには、昔[むかし]と今[いま]の風景[ふうけい]が交錯[こうさく]している。", "sentence_source": "generated"}, {"text": "彼女の心の中で、迷いと決意が交錯した。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の心[こころ]の中[なか]で、迷[まよ]いと決意[けつい]が交錯[こうさく]した。", "sentence_source": "generated"}, {"text": "ニュースには、正しい情報と間違った情報が交錯している。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "ニュースには、正[ただ]しい情報[じょうほう]と間違[まちが]った情報[じょうほう]が交錯[こうさく]している。", "sentence_source": "generated"}, {"text": "夜の街では、車のライトとネオンが交錯して眩しい。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "夜[よる]の街[まち]では、車[くるま]のライトとネオンが交錯[こうさく]して眩[まぶ]しい。", "sentence_source": "generated"}, {"text": "物語では、二人の過去と現在が交錯して描かれる。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "物語[ものがたり]では、二人[ふたり]の過去[かこ]と現在[げんざい]が交錯[こうさく]して描[えが]かれる。", "sentence_source": "generated"}, {"text": "大都市では、さまざまな文化が交錯して新しいものが生まれる。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "大都市[だいとし]では、さまざまな文化[ぶんか]が交錯[こうさく]して新[あたら]しいものが生[う]まれる。", "sentence_source": "generated"}, {"text": "怒りと後悔が交錯して、彼は何も言えなかった。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "怒[いか]りと後悔[こうかい]が交錯[こうさく]して、彼[かれ]は何[なに]も言[い]えなかった。", "sentence_source": "generated"}, {"text": "利害が交錯する交渉は、まとめるのが難しい。", "target_word": "交錯", "complexity_tier": "T3", "furigana": "利害[りがい]が交錯[こうさく]する交渉[こうしょう]は、まとめるのが難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交錯する", "label": "辞書形"}, {"form": "交錯した", "label": "過去形"}, {"form": "交錯して", "label": "て形"}], "register": "formal", "sense_fingerprint": "交錯=意見・情報・利害など複数の物事が入り混じること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交錯", "is_correct": true, "explanation": "正解。「意見が交錯して」で、賛成と反対が入り混じる状態を表す。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解く意味。意見の状態には合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "投げ出す意味。意見が入り混じる状態には使わない。"}, {"text": "撤回", "is_correct": false, "explanation": "取り消す意味。意見が入り混じる文脈には合わない。"}], "explanations": {"交錯": "正解。「意見が交錯して」で、賛成と反対が入り混じる状態を表す。", "解散": "集まりを解く意味。意見の状態には合わない。", "放棄": "投げ出す意味。意見が入り混じる状態には使わない。", "撤回": "取り消す意味。意見が入り混じる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "交錯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隣の家とは長年交錯している。", "explanation": "ここは〈交際〉の意味。近所の人と親しく付き合うことは交際と言い、入り混じるという交錯は合わない。"}, {"text": "取引先と交錯して、値段を決めた。", "explanation": "ここは〈交渉〉の意味。条件を話し合って決めることは交渉と言い、入り混じる意味の交錯は合わない。"}, {"text": "見張りは三人で交錯して務めた。", "explanation": "ここは〈交代〉の意味。役目を入れ替わって受け持つことは交代と言い、交錯は入り混じる意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交錯", "is_correct": true, "explanation": "正解。「過去と現在が交錯して」で、二つの時間が入り混じって描かれることを表す。"}, {"text": "反発", "is_correct": false, "explanation": "押し返す意味。時間の流れには合わない。"}, {"text": "脱退", "is_correct": false, "explanation": "組織から抜ける意味。過去と現在には使えない。"}, {"text": "失効", "is_correct": false, "explanation": "効力がなくなる意味。時間の描写には合わない。"}], "explanations": {"交錯": "正解。「過去と現在が交錯して」で、二つの時間が入り混じって描かれることを表す。", "反発": "押し返す意味。時間の流れには合わない。", "脱退": "組織から抜ける意味。過去と現在には使えない。", "失効": "効力がなくなる意味。時間の描写には合わない。"}, "sentence_index": 6, "correct_answer": "交錯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "幼なじみとは十年前から交錯している。", "explanation": "ここは〈交際〉の意味。親しく付き合うことは交際と言い、入り混じるという交錯は合わない。"}, {"text": "二台の車が交錯して、大きな音がした。", "explanation": "ここは〈衝突〉の意味。ぶつかることは衝突で、入り混じる意味の交錯は合わない。"}, {"text": "会場は大きな交錯に陥った。", "explanation": "ここは〈混乱〉の意味。秩序が乱れることは混乱と言い、入り混じるという交錯は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では、賛成と反対の意見を交錯して、議論が長引いた。", "corrected_sentence": "会議では、賛成と反対の意見が交錯して、議論が長引いた。", "error_description": "「を」は誤り。正しくは「が」。交錯は自動詞なので、入り混じる主体に「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38987, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ネットには、正しい情報と間違った情報が交錯しいる。", "corrected_sentence": "ネットには、正しい情報と間違った情報が交錯している。", "error_description": "「交錯しいる」は誤り。「し」の後に「て」が必要で、正しくは「交錯している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「住む」は住む場所を「に」で示すので、「他国に住んだ」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「住む」は目的語を取らない動詞なので、「を」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「住む」の場所には合わず「他国が住んだ」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すので、「他国と住んだ」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「住む」は住む場所を「に」で示すので、「他国に住んだ」が正しい。", "を": "「住む」は目的語を取らない動詞なので、「を」は合わない。", "が": "「が」は主語を示すので、「住む」の場所には合わず「他国が住んだ」は不自然。", "と": "「と」は相手や並列を表すので、「他国と住んだ」は意味が通らない。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「他国の祭り」の名詞を修飾する「の」。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象を示すが、「他国より祭り」では比較が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、名詞「祭り」を修飾できない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「他国から祭り」と続けても名詞修飾にならず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「他国の祭り」の名詞を修飾する「の」。", "より": "比較の「より」は比べる対象を示すが、「他国より祭り」では比較が成り立たない。", "へ": "「へ」は方向を表すので、名詞「祭り」を修飾できない。", "から": "起点の「から」は「他国から祭り」と続けても名詞修飾にならず、意味が通らない。"}, "error_tags": {"より": "比較", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の国ではない、ほかの国のこと。", "primary_collocate": null, "pronunciation": "たこく", "ipa": "takokɯ", "syllable_count": 3, "sentences": [{"text": "他国の文化を知ると、自分の国のこともよくわかります。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の文化[ぶんか]を知[し]ると、自分[じぶん]の国[くに]のこともよくわかります。", "sentence_source": "generated"}, {"text": "私は他国に住んだことがないので、少し心配です。", "target_word": "他国", "complexity_tier": "T3", "furigana": "私[わたし]は他国[たこく]に住[す]んだことがないので、少[すこ]し心配[しんぱい]です。", "sentence_source": "generated"}, {"text": "他国から来た友だちが、日本の料理を作ってくれました。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]から来[き]た友[とも]だちが、日本[にほん]の料理[りょうり]を作[つく]ってくれました。", "sentence_source": "generated"}, {"text": "他国の言葉を学ぶのは大変ですが、楽しいです。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の言葉[ことば]を学[まな]ぶのは大変[たいへん]ですが、楽[たの]しいです。", "sentence_source": "generated"}, {"text": "この国は小さいので、他国との貿易が大切です。", "target_word": "他国", "complexity_tier": "T3", "furigana": "この国[くに]は小[ちい]さいので、他国[たこく]との貿易[ぼうえき]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "他国の人と話すときは、ゆっくり話すようにしています。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の人[ひと]と話[はな]すときは、ゆっくり話[はな]すようにしています。", "sentence_source": "generated"}, {"text": "旅行で他国へ行くには、パスポートが必要です。", "target_word": "他国", "complexity_tier": "T3", "furigana": "旅行[りょこう]で他国[たこく]へ行[い]くには、パスポートが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "他国の祭りを見て、自分の国との違いに驚きました。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の祭[まつ]りを見[み]て、自分[じぶん]の国[くに]との違[ちが]いに驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "彼は他国で働いた経験があり、英語が上手です。", "target_word": "他国", "complexity_tier": "T3", "furigana": "彼[かれ]は他国[たこく]で働[はたら]いた経験[けいけん]があり、英語[えいご]が上手[じょうず]です。", "sentence_source": "generated"}, {"text": "他国のニュースも、毎朝テレビで見ています。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]のニュースも、毎朝[まいあさ]テレビで見[み]ています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "他国", "label": "基本形"}], "register": "neutral (polite です・ます style)", "sense_fingerprint": "自分の国以外のほかの国。やさしい説明で使う、日常的な「他国」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "「他国の文化」で、自分の国以外の国々の文化を指す。文脈に合う。"}, {"text": "国境", "is_correct": false, "explanation": "国境は国と国の境目の線で、「国境の文化」とは言えないので合わない。"}, {"text": "国籍", "is_correct": false, "explanation": "国籍は人が所属する国の資格で、文化を持つ対象にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、「天気の文化」とは言わないので合わない。"}], "explanations": {"他国": "「他国の文化」で、自分の国以外の国々の文化を指す。文脈に合う。", "国境": "国境は国と国の境目の線で、「国境の文化」とは言えないので合わない。", "国籍": "国籍は人が所属する国の資格で、文化を持つ対象にはならないので合わない。", "天気": "天気は空模様のことで、「天気の文化」とは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い留学を終えて、他国へ帰国した。", "explanation": "ここは〈母国〉の意味。他国は自分の国以外を指すので、自分が帰る国には使えない。"}, {"text": "転勤で大阪へ行くことになり、他国での生活の準備を始めた。", "explanation": "ここは〈国内の別の地域〉の意味。大阪は日本の中にあるので、他国とは言わない。"}, {"text": "日本で生まれ育った私にとって、日本は他国だ。", "explanation": "ここは〈自分の国〉の意味。他国は自分の国以外を指すので、自国の日本には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "「他国へ行く」の行き先を表す。自分の国以外の国を指すので文脈に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は行き先になる場所ではないので、「旅行で教科書へ行く」は成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は行き先の場所ではないので、「へ行く」の対象にならない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は場所ではないので、「へ行く」の行き先にはならない。"}], "explanations": {"他国": "「他国へ行く」の行き先を表す。自分の国以外の国を指すので文脈に合う。", "教科書": "教科書は行き先になる場所ではないので、「旅行で教科書へ行く」は成り立たない。", "冷蔵庫": "冷蔵庫は行き先の場所ではないので、「へ行く」の対象にならない。", "音楽": "音楽は場所ではないので、「へ行く」の行き先にはならない。"}, "sentence_index": 6, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コインの他国をじっと見た。", "explanation": "ここは〈裏側〉の意味。他国は国を指す語なので、コインの裏側には使わない。"}, {"text": "雨が降ってきたので、近くにいた他国のかさを借りた。", "explanation": "ここは〈他人〉の意味。他国は国を指すので、人のかさの持ち主には使わない。"}, {"text": "宇宙船は、ついに他国に着陸した。", "explanation": "ここは〈惑星〉の意味。他国は地上の国を指すので、ほかの惑星には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は若いころ、他国を一年間働いていました。", "corrected_sentence": "祖母は若いころ、他国で一年間働いていました。", "error_description": "「働く」は働く場所を「で」で示す。ここで「を」を使うと目的語の形になり誤り。正しくは「他国で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38990, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は他国を留学して、英語を学んでいる。", "corrected_sentence": "兄は他国に留学して、英語を学んでいる。", "error_description": "「留学する」は留学先を「に」で示す。「を」は目的語を表すため誤り。正しくは「他国に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「他国の協力」の名詞を修飾する「の」。"}, {"text": "を", "is_correct": false, "explanation": "「協力」は目的語を取らないので、「他国を協力」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「他国が協力」は名詞修飾にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象を示すが、「他国より協力」では文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「他国の協力」の名詞を修飾する「の」。", "を": "「協力」は目的語を取らないので、「他国を協力」は成り立たない。", "が": "「が」は主語を示すため、「他国が協力」は名詞修飾にならず不自然。", "より": "比較の「より」は比べる対象を示すが、「他国より協力」では文脈に合わない。"}, "error_tags": {"を": "目的語", "より": "比較", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「他国の制度」の名詞を修飾する「の」。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すので、「他国と制度を参考にして」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「他国を制度を」と二つ続くため不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「参考にする」の形では使うが、「他国に制度」と名詞を修飾する位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "「他国の制度」の名詞を修飾する「の」。", "と": "「と」は相手や並列を表すので、「他国と制度を参考にして」は意味が通らない。", "を": "「を」は目的語を示すが、「他国を制度を」と二つ続くため不自然。", "に": "「に」は「参考にする」の形では使うが、「他国に制度」と名詞を修飾する位置には合わない。"}, "error_tags": {"と": "相手・並列", "に": "対象・方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の属する国以外の国。外国。", "primary_collocate": null, "pronunciation": "たこく", "ipa": "takokɯ", "syllable_count": 3, "sentences": [{"text": "日本は食料の多くを他国から輸入している。", "target_word": "他国", "complexity_tier": "T3", "furigana": "日本[にほん]は食料[しょくりょう]の多[おお]くを他国[たこく]から輸入[ゆにゅう]している。", "sentence_source": "generated"}, {"text": "他国の協力がなければ、この計画は成功しなかっただろう。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の協力[きょうりょく]がなければ、この計画[けいかく]は成功[せいこう]しなかっただろう。", "sentence_source": "generated"}, {"text": "大統領は他国との関係を大切にすると話した。", "target_word": "他国", "complexity_tier": "T3", "furigana": "大統領[だいとうりょう]は他国[たこく]との関係[かんけい]を大切[たいせつ]にすると話[はな]した。", "sentence_source": "generated"}, {"text": "他国に比べて、この国は物価が安い。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]に比[くら]べて、この国[くに]は物価[ぶっか]が安[やす]い。", "sentence_source": "generated"}, {"text": "地震が起きたとき、他国から多くの支援が届いた。", "target_word": "他国", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きたとき、他国[たこく]から多[おお]くの支援[しえん]が届[とど]いた。", "sentence_source": "generated"}, {"text": "他国の領土に勝手に入ってはいけない。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の領土[りょうど]に勝手[かって]に入[はい]ってはいけない。", "sentence_source": "generated"}, {"text": "彼は他国の大学で経済を学んでいる。", "target_word": "他国", "complexity_tier": "T3", "furigana": "彼[かれ]は他国[たこく]の大学[だいがく]で経済[けいざい]を学[まな]んでいる。", "sentence_source": "generated"}, {"text": "他国の制度を参考にして、新しい法律を作った。", "target_word": "他国", "complexity_tier": "T3", "furigana": "他国[たこく]の制度[せいど]を参考[さんこう]にして、新[あたら]しい法律[ほうりつ]を作[つく]った。", "sentence_source": "generated"}, {"text": "選手たちは他国の代表と決勝で戦った。", "target_word": "他国", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは他国[たこく]の代表[だいひょう]と決勝[けっしょう]で戦[たたか]った。", "sentence_source": "generated"}, {"text": "この島は昔、他国に支配されていた。", "target_word": "他国", "complexity_tier": "T3", "furigana": "この島[しま]は昔[むかし]、他国[たこく]に支配[しはい]されていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "他国", "label": "基本形"}], "register": "written/formal (plain だ・である style)", "sense_fingerprint": "自国に対する外国。貿易・外交・政治などの文脈で使う「他国」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "「から輸入」の輸入元を示す、自国以外の国。文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は輸入元にはならないので、「食料を冷蔵庫から輸入」は成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は輸入元にならないので、「から輸入」の前には置けない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は輸入の起点にならないので、文脈に合わない。"}], "explanations": {"他国": "「から輸入」の輸入元を示す、自国以外の国。文脈に合う。", "冷蔵庫": "冷蔵庫は輸入元にはならないので、「食料を冷蔵庫から輸入」は成り立たない。", "教科書": "教科書は輸入元にならないので、「から輸入」の前には置けない。", "天気": "天気は輸入の起点にならないので、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "転勤で大阪へ移り、他国の支社で働くことになった。", "explanation": "ここは〈国内〉の意味。大阪は日本国内なので、他国の支社とは言わない。"}, {"text": "夏休みに、川の他国に渡った。", "explanation": "ここは〈対岸〉の意味。他国は国を指す語なので、川の向こう岸には使わない。"}, {"text": "転んで、他国の指を痛めた。", "explanation": "ここは〈自分の〉の意味。他国は国を指す語なので、自分の体の部位には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "「大学」を修飾し、外国の大学であることを示す。文脈に合う。"}, {"text": "家族", "is_correct": false, "explanation": "家族は大学の所属先として修飾できないので、「家族の大学」は成り立たない。"}, {"text": "海水", "is_correct": false, "explanation": "海水は大学を修飾しないので、意味が通らない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は大学を修飾しないので、「郵便の大学」は合わない。"}], "explanations": {"他国": "「大学」を修飾し、外国の大学であることを示す。文脈に合う。", "家族": "家族は大学の所属先として修飾できないので、「家族の大学」は成り立たない。", "海水": "海水は大学を修飾しないので、意味が通らない。", "郵便": "郵便は大学を修飾しないので、「郵便の大学」は合わない。"}, "sentence_index": 6, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日本に生まれた私は、他国の人だ。", "explanation": "ここは〈自国〉の意味。自分が属する国を他国とは言わないので、この使い方は不自然。"}, {"text": "来週の金曜日、他国の日に会おう。", "explanation": "ここは〈別の〉の意味。他国は国を指す語なので、日付には使えない。"}, {"text": "札幌の友人に会うため、他国へ行った。", "explanation": "ここは〈国内の遠い地域〉の意味。札幌は日本の中の都市なので、他国とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は他国への支援を受け入れると発表した。", "corrected_sentence": "政府は他国からの支援を受け入れると発表した。", "error_description": "「支援を受ける」の出どころは「から」で示す。「への」は行き先を表すため誤り。正しくは「他国からの」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38991, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は他国に働いて、現地の会社で経理を担当している。", "corrected_sentence": "彼女は他国で働いて、現地の会社で経理を担当している。", "error_description": "「働く」は働く場所を「で」で示す。「に」は誤り。正しくは「他国で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒む", "is_correct": true, "explanation": "「受け入れる」の対義語。申し出や意見を認めず退ける意味で、ここでは反対になる。"}, {"text": "逃げる", "is_correct": false, "explanation": "行動としては反対だが、辞典で対義語とされる関係ではない。"}, {"text": "残す", "is_correct": false, "explanation": "「そのままにしておく」の意味で、受け入れるの対義語ではない。"}, {"text": "作る", "is_correct": false, "explanation": "受け入れるとは意味の上で対になる関係がなく、対義語ではない。"}], "correct_answer": "拒む", "explanations": {"拒む": "「受け入れる」の対義語。申し出や意見を認めず退ける意味で、ここでは反対になる。", "逃げる": "行動としては反対だが、辞典で対義語とされる関係ではない。", "残す": "「そのままにしておく」の意味で、受け入れるの対義語ではない。", "作る": "受け入れるとは意味の上で対になる関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒絶する", "is_correct": true, "explanation": "「受け入れる」の対義語。お詫びを認めずに退ける意味で、ここでは反対になる。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を出す動作で、受け入れるとは対になる関係ではない。"}, {"text": "積む", "is_correct": false, "explanation": "重ねる動作で、受け入れるとは対義語の関係にない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面を整える動作で、受け入れるとは対義語の関係にない。"}], "correct_answer": "拒絶する", "explanations": {"拒絶する": "「受け入れる」の対義語。お詫びを認めずに退ける意味で、ここでは反対になる。", "叫ぶ": "声を出す動作で、受け入れるとは対になる関係ではない。", "積む": "重ねる動作で、受け入れるとは対義語の関係にない。", "磨く": "表面を整える動作で、受け入れるとは対義語の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "誰かがくれたものを、自分の中に入れることです。", "primary_collocate": null, "pronunciation": "うけいれる", "ipa": "ɯkeireɾɯ", "syllable_count": 5, "sentences": [{"text": "友だちの申し出を、よろこんで受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "友[とも]だちの申[もう]し出[で]を、よろこんで受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "彼は私の提案を、笑顔で受け入れてくれた。", "target_word": "受け入れて", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]の提案[ていあん]を、笑顔[えがお]で受[う]け入[い]れてくれた。", "sentence_source": "generated"}, {"text": "母は私の頼みを、少し考えてから受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の頼[たの]みを、少[すこ]し考[かんが]えてから受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "先生がくれたアドバイスを、すなおに受け入れます。", "target_word": "受け入れます", "complexity_tier": "T3", "furigana": "先生[せんせい]がくれたアドバイスを、すなおに受[う]け入[い]れます。", "sentence_source": "generated"}, {"text": "兄が出した条件を、私はそのまま受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "兄[あに]が出[だ]した条件[じょうけん]を、私[わたし]はそのまま受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "彼女は私の誘いを、にっこり笑って受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]の誘[さそ]いを、にっこり笑[わら]って受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "親切な言葉を、そのまま受け入れるのは難しい。", "target_word": "受け入れる", "complexity_tier": "T3", "furigana": "親切[しんせつ]な言葉[ことば]を、そのまま受[う]け入[い]れるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼は友だちの助けを、素直に受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "彼[かれ]は友[とも]だちの助[たす]けを、素直[すなお]に受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "厳しい意見でも、受け入れる気持ちが大事だ。", "target_word": "受け入れる", "complexity_tier": "T3", "furigana": "厳[きび]しい意見[いけん]でも、受[う]け入[い]れる気持[きも]ちが大事[だいじ]だ。", "sentence_source": "generated"}, {"text": "私のお詫びを、彼は静かに受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "私[わたし]のお詫[わ]びを、彼[かれ]は静[しず]かに受[う]け入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受け入れる", "label": "辞書形"}, {"form": "受け入れます", "label": "丁寧形"}, {"form": "受け入れた", "label": "過去形"}, {"form": "受け入れて", "label": "て形"}, {"form": "受け入れない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "相手の申し出・頼み・意見などを断らずに自分のものとして取り入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受け入れた", "is_correct": true, "explanation": "過去形の終止形で、「よろこんで受け入れた。」と文が完結する。"}, {"text": "受け入れ", "is_correct": false, "explanation": "連用形で止まり、文の述語として完結しない。"}, {"text": "受け入れて", "is_correct": false, "explanation": "て形では文が途中で切れ、述語として働かない。"}, {"text": "受け入れさせ", "is_correct": false, "explanation": "使役の語幹で止まっており、文が完結しない。"}], "explanations": {"受け入れた": "過去形の終止形で、「よろこんで受け入れた。」と文が完結する。", "受け入れ": "連用形で止まり、文の述語として完結しない。", "受け入れて": "て形では文が途中で切れ、述語として働かない。", "受け入れさせ": "使役の語幹で止まっており、文が完結しない。"}, "sentence_index": 0, "correct_answer": "受け入れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨粒を受け入れた。", "explanation": "ここは〈受け止める〉の意味。受け入れるは申し出や考えを認める意味で、雨粒を体で受けることには使わない。"}, {"text": "パソコンがウイルスを受け入れた。", "explanation": "ここは〈侵入を許す〉の意味。受け入れるは望ましい申し出やものを迎える意味で、有害なものが入り込むことには使わない。"}, {"text": "夕立が町を受け入れた。", "explanation": "ここは〈降り注ぐ〉の意味。受け入れるは人や組織が申し出やものを認める意味で、天気が町に降ることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受け入れる", "is_correct": true, "explanation": "「のは」に続けて名詞化し、「難しい」の主語になる。"}, {"text": "焼く", "is_correct": false, "explanation": "言葉は焼けないので、文の意味が通らない。"}, {"text": "踏む", "is_correct": false, "explanation": "言葉は踏めないので、文の意味が通らない。"}, {"text": "沸かす", "is_correct": false, "explanation": "言葉は沸かせないので、文の意味が通らない。"}], "explanations": {"受け入れる": "「のは」に続けて名詞化し、「難しい」の主語になる。", "焼く": "言葉は焼けないので、文の意味が通らない。", "踏む": "言葉は踏めないので、文の意味が通らない。", "沸かす": "言葉は沸かせないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "受け入れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学の入試を受け入れた。", "explanation": "ここは〈受ける〉の意味。試験を受けるとは言うが、受け入れるは申し出や考えを認める意味で、試験には使わない。"}, {"text": "飛んできたボールを受け入れた。", "explanation": "ここは〈受け止める〉の意味。受け入れるは物を体で止めることではなく、申し出や考えを認めることに使う。"}, {"text": "テレビの電源を受け入れた。", "explanation": "ここは〈入れる〉の意味。受け入れるは申し出や考えを認める意味で、電源を入れてつけるという動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩の助言に、素直に受け入れた。", "corrected_sentence": "先輩の助言を、素直に受け入れた。", "error_description": "「受け入れる」の目的語は「を」で示す。「に」は誤り（正しくは「を」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受け入れて", "is_correct": true, "explanation": "て形で、「〜てくれた」と続けて恩恵を表す。"}, {"text": "受け入れない", "is_correct": false, "explanation": "否定形。肯定の「受け入れてくれた」の意味と合わない。"}, {"text": "受け入れます", "is_correct": false, "explanation": "丁寧形。「〜てくれた」の普通体の文と文体が合わない。"}, {"text": "受け入れる", "is_correct": false, "explanation": "辞書形では「〜てくれた」に続けられず、文が成り立たない。"}], "correct_form": "受け入れて", "base_form": "受け入れる", "form_label": "て形", "sentence_index": 1, "explanations": {"受け入れて": "て形で、「〜てくれた」と続けて恩恵を表す。", "受け入れない": "否定形。肯定の「受け入れてくれた」の意味と合わない。", "受け入れます": "丁寧形。「〜てくれた」の普通体の文と文体が合わない。", "受け入れる": "辞書形では「〜てくれた」に続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38992, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の忠告を、静かに受け入れるた。", "corrected_sentence": "彼女の忠告を、静かに受け入れた。", "error_description": "過去の「た」に辞書形「受け入れる」を付けた誤り。正しくは「受け入れた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受け入れた", "is_correct": true, "explanation": "過去形で、「素直に受け入れた。」と文が完結する。"}, {"text": "受け入れ", "is_correct": false, "explanation": "連用形で止まり、文の述語として完結しない。"}, {"text": "受け入れさせた", "is_correct": false, "explanation": "使役形。誰かに受け入れさせる意味になり、文の内容が変わる。"}, {"text": "受け入れよう", "is_correct": false, "explanation": "意志形。過去の出来事を述べる文に合わない。"}], "correct_form": "受け入れた", "base_form": "受け入れる", "form_label": "過去形", "sentence_index": 7, "explanations": {"受け入れた": "過去形で、「素直に受け入れた。」と文が完結する。", "受け入れ": "連用形で止まり、文の述語として完結しない。", "受け入れさせた": "使役形。誰かに受け入れさせる意味になり、文の内容が変わる。", "受け入れよう": "意志形。過去の出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「留学生」を目的語として示す格助詞。「受け入れる」の対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」では、留学生が受け入れる側になり文の意味が変わる。"}, {"text": "に", "is_correct": false, "explanation": "「受け入れる」は対象を「を」で示す。「留学生に受け入れている」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では、留学生との関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "「留学生」を目的語として示す格助詞。「受け入れる」の対象を表す。", "が": "主語を示す「が」では、留学生が受け入れる側になり文の意味が変わる。", "に": "「受け入れる」は対象を「を」で示す。「留学生に受け入れている」は不自然。", "で": "手段や場所を示す「で」では、留学生との関係が合わない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒む", "is_correct": true, "explanation": "「受け入れる」の対義語。人や物を迎えることを断る意味で、ここでは反対になる。"}, {"text": "逃げる", "is_correct": false, "explanation": "行動としては反対だが、辞典で対義語とされる関係ではない。"}, {"text": "残す", "is_correct": false, "explanation": "「そのままにしておく」の意味で、受け入れるの対義語ではない。"}, {"text": "作る", "is_correct": false, "explanation": "受け入れるとは対になる関係がなく、対義語ではない。"}], "correct_answer": "拒む", "explanations": {"拒む": "「受け入れる」の対義語。人や物を迎えることを断る意味で、ここでは反対になる。", "逃げる": "行動としては反対だが、辞典で対義語とされる関係ではない。", "残す": "「そのままにしておく」の意味で、受け入れるの対義語ではない。", "作る": "受け入れるとは対になる関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「選手団」を目的語として示す格助詞。「受け入れる準備」の対象を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、選手団が受け入れる対象として働かない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」では、目的語としての役割が果たせない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、「選手団より受け入れる準備」と意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「選手団」を目的語として示す格助詞。「受け入れる準備」の対象を表す。", "へ": "方向を示す「へ」では、選手団が受け入れる対象として働かない。", "と": "相手や並列を示す「と」では、目的語としての役割が果たせない。", "より": "比較の「より」では、「選手団より受け入れる準備」と意味が通らない。"}, "error_tags": {"へ": "方向", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒絶する", "is_correct": true, "explanation": "「受け入れる」の対義語。寄付の申し出を認めずに退ける意味で、ここでは反対になる。"}, {"text": "眠る", "is_correct": false, "explanation": "休む動作で、受け入れるとは対になる関係ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる動作で、受け入れるとは対義語の関係にない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面を整える動作で、受け入れるとは対義語の関係にない。"}], "correct_answer": "拒絶する", "explanations": {"拒絶する": "「受け入れる」の対義語。寄付の申し出を認めずに退ける意味で、ここでは反対になる。", "眠る": "休む動作で、受け入れるとは対になる関係ではない。", "運ぶ": "移動させる動作で、受け入れるとは対義語の関係にない。", "磨く": "表面を整える動作で、受け入れるとは対義語の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "他の人や国などから提供されたものを受け取ること。", "primary_collocate": null, "pronunciation": "うけいれる", "ipa": "ɯkeireɾɯ", "syllable_count": 5, "sentences": [{"text": "市は難民を受け入れることを決めた。", "target_word": "受け入れる", "complexity_tier": "T3", "furigana": "市[し]は難民[なんみん]を受[う]け入[い]れることを決[き]めた。", "sentence_source": "generated"}, {"text": "この学校は毎年、留学生を受け入れている。", "target_word": "受け入れている", "complexity_tier": "T3", "furigana": "この学校[がっこう]は毎年[まいとし]、留学生[りゅうがくせい]を受[う]け入[い]れている。", "sentence_source": "generated"}, {"text": "病院は事故の患者を受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "病院[びょういん]は事故[じこ]の患者[かんじゃ]を受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "会社は新しい技術を受け入れて、仕事のやり方を変えた。", "target_word": "受け入れて", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい技術[ぎじゅつ]を受[う]け入[い]れて、仕事[しごと]のやり方[かた]を変[か]えた。", "sentence_source": "generated"}, {"text": "国は海外からの援助を受け入れた。", "target_word": "受け入れた", "complexity_tier": "T3", "furigana": "国[くに]は海外[かいがい]からの援助[えんじょ]を受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "旅館は急な予約も受け入れてくれた。", "target_word": "受け入れて", "complexity_tier": "T3", "furigana": "旅館[りょかん]は急[きゅう]な予約[よやく]も受[う]け入[い]れてくれた。", "sentence_source": "generated"}, {"text": "町は寄付を受け入れて、新しい図書館を建てた。", "target_word": "受け入れて", "complexity_tier": "T3", "furigana": "町[まち]は寄付[きふ]を受[う]け入[い]れて、新[あたら]しい図書館[としょかん]を建[た]てた。", "sentence_source": "generated"}, {"text": "選手団を受け入れる準備が、市内で進んでいる。", "target_word": "受け入れる", "complexity_tier": "T3", "furigana": "選手団[せんしゅだん]を受[う]け入[い]れる準備[じゅんび]が、市内[しない]で進[すす]んでいる。", "sentence_source": "generated"}, {"text": "その会社は外国から来た研修生を受け入れていない。", "target_word": "受け入れていない", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は外国[がいこく]から来[き]た研修生[けんしゅうせい]を受[う]け入[い]れていない。", "sentence_source": "generated"}, {"text": "市は国からの補助金を受け入れて、道路の工事を始めた。", "target_word": "受け入れて", "complexity_tier": "T3", "furigana": "市[し]は国[くに]からの補助金[ほじょきん]を受[う]け入[い]れて、道路[どうろ]の工事[こうじ]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受け入れる", "label": "辞書形"}, {"form": "受け入れている", "label": "進行形"}, {"form": "受け入れた", "label": "過去形"}, {"form": "受け入れて", "label": "て形"}, {"form": "受け入れない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "他の人・組織・国から来た人や物、援助、要求などを引き受けて迎え入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受け入れる", "is_correct": true, "explanation": "名詞化して「受け入れること」となり、「決めた」の内容になる。"}, {"text": "受け入れ", "is_correct": false, "explanation": "連用形のままでは「ことを」に続かず、文が成り立たない。"}, {"text": "受け入れさせ", "is_correct": false, "explanation": "使役の語幹のままでは「ことを」に続かず、文が成り立たない。"}, {"text": "受け入れ続け", "is_correct": false, "explanation": "連用形では「ことを」に続かず、文が完結しない。"}], "explanations": {"受け入れる": "名詞化して「受け入れること」となり、「決めた」の内容になる。", "受け入れ": "連用形のままでは「ことを」に続かず、文が成り立たない。", "受け入れさせ": "使役の語幹のままでは「ことを」に続かず、文が成り立たない。", "受け入れ続け": "連用形では「ことを」に続かず、文が完結しない。"}, "sentence_index": 0, "correct_answer": "受け入れる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールを受け入れた。", "explanation": "ここは〈受け止める〉の意味。受け入れるは人や組織が申し出や人を迎え入れることに使い、物を体で止める意味では使わない。"}, {"text": "大きな声を受け入れて、耳をふさいだ。", "explanation": "ここは〈遮る〉の意味。受け入れるは提供されたものを受け取る意味で、音をさえぎって防ぐことには使わない。"}, {"text": "干してあった洗濯物を受け入れた。", "explanation": "ここは〈取り込む〉の意味。受け入れるは他の人や国から提供されたものを受け取る意味で、干してある洗濯物を屋内に入れる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受け入れて", "is_correct": true, "explanation": "て形で、後の「新しい図書館を建てた」へ続く流れになる。"}, {"text": "燃やして", "is_correct": false, "explanation": "寄付を燃やしては、図書館を建てる流れと合わない。"}, {"text": "壊して", "is_correct": false, "explanation": "寄付は壊すものではないので、文の意味が通らない。"}, {"text": "隠して", "is_correct": false, "explanation": "寄付を隠すと、図書館を建てたことと結びつかない。"}], "explanations": {"受け入れて": "て形で、後の「新しい図書館を建てた」へ続く流れになる。", "燃やして": "寄付を燃やしては、図書館を建てる流れと合わない。", "壊して": "寄付は壊すものではないので、文の意味が通らない。", "隠して": "寄付を隠すと、図書館を建てたことと結びつかない。"}, "sentence_index": 6, "correct_answer": "受け入れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学の入試を受け入れた。", "explanation": "ここは〈受ける〉の意味。試験を受けるとは言うが、受け入れるは申し出や考えを認める意味で、試験には使わない。"}, {"text": "電車を受け入れて、席に座った。", "explanation": "ここは〈乗る〉の意味。受け入れるは提供されたものを受け取る意味で、乗り物に乗り込むという動作には使わない。"}, {"text": "庭の草を受け入れて、きれいに刈った。", "explanation": "ここは〈刈る〉の意味。受け入れるは他の人や国から提供されたものを受け取る意味で、生えている草を切り取る作業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学は留学生が受け入れた。", "corrected_sentence": "大学は留学生を受け入れた。", "error_description": "「受け入れる」の目的語は「を」で示す。「が」は主語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受け入れている", "is_correct": true, "explanation": "進行形。「毎年〜を受け入れている」と継続している状態を表す。"}, {"text": "受け入れない", "is_correct": false, "explanation": "否定形。「毎年受け入れている」という内容と矛盾する。"}, {"text": "受け入れろ", "is_correct": false, "explanation": "命令形。事実を述べる文には使えない。"}, {"text": "受け入れよ", "is_correct": false, "explanation": "命令形。事実を述べる文には使えない。"}], "correct_form": "受け入れている", "base_form": "受け入れる", "form_label": "進行形", "sentence_index": 1, "explanations": {"受け入れている": "進行形。「毎年〜を受け入れている」と継続している状態を表す。", "受け入れない": "否定形。「毎年受け入れている」という内容と矛盾する。", "受け入れろ": "命令形。事実を述べる文には使えない。", "受け入れよ": "命令形。事実を述べる文には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38993, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は国からの補助金を受け入れるて、道路を直した。", "corrected_sentence": "市は国からの補助金を受け入れて、道路を直した。", "error_description": "「受け入れて」のて形を、辞書形に「て」を付けた誤った形にしている。正しくは「受け入れて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受け入れる", "is_correct": true, "explanation": "辞書形で、「受け入れる準備」と名詞を修飾する。"}, {"text": "受け入れられる", "is_correct": false, "explanation": "可能形。「受け入れられる準備」は、準備が受け入れられるという別の意味になる。"}, {"text": "受け入れさせる", "is_correct": false, "explanation": "使役形。誰かに受け入れさせる準備という意味になり、文の内容が変わる。"}, {"text": "受け入れよう", "is_correct": false, "explanation": "意志形では、名詞を修飾できない。"}], "correct_form": "受け入れる", "base_form": "受け入れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"受け入れる": "辞書形で、「受け入れる準備」と名詞を修飾する。", "受け入れられる": "可能形。「受け入れられる準備」は、準備が受け入れられるという別の意味になる。", "受け入れさせる": "使役形。誰かに受け入れさせる準備という意味になり、文の内容が変わる。", "受け入れよう": "意志形では、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38994, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先に」で、道の先の場所を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」では道の先を対象として扱うことになり、「見える」の場所と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示し、見える場所を表す「に」とは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、見える場所を表す「に」とは合わない。"}], "correct_answer": "に", "explanations": {"に": "「先に」で、道の先の場所を示す格助詞。", "を": "「を」では道の先を対象として扱うことになり、「見える」の場所と合わない。", "で": "「で」は動作の場所を示し、見える場所を表す「に」とは合わない。", "へ": "「へ」は方向を示し、見える場所を表す「に」とは合わない。"}, "error_tags": {"を": "対象", "が": "主語", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38994, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先に」で、木の枝の先の場所を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、小鳥が向かう先の意味になり、「とまっている」の場所と合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、木の枝の先と比べる文になり、場所を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、枝から出発する意味になり、とまっている場所と合わない。"}], "correct_answer": "に", "explanations": {"に": "「先に」で、木の枝の先の場所を示す格助詞。", "へ": "方向を示す「へ」では、小鳥が向かう先の意味になり、「とまっている」の場所と合わない。", "より": "比較の「より」では、木の枝の先と比べる文になり、場所を示せない。", "から": "起点を示す「から」では、枝から出発する意味になり、とまっている場所と合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38994, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものの いちばん はし。また、いく ところ。", "primary_collocate": null, "pronunciation": "さき", "ipa": "saki", "syllable_count": 2, "sentences": [{"text": "えんぴつの先が折れてしまった。", "target_word": "先", "complexity_tier": "T3", "furigana": "えんぴつの先[さき]が折[お]れてしまった。", "sentence_source": "generated"}, {"text": "道の先に、小さな店が見える。", "target_word": "先", "complexity_tier": "T3", "furigana": "道[みち]の先[さき]に、小[ちい]さな店[みせ]が見[み]える。", "sentence_source": "generated"}, {"text": "針の先は、さわると危ない。", "target_word": "先", "complexity_tier": "T3", "furigana": "針[はり]の先[さき]は、さわると危[あぶ]ない。", "sentence_source": "generated"}, {"text": "駅の先まで歩いて行った。", "target_word": "先", "complexity_tier": "T3", "furigana": "駅[えき]の先[さき]まで歩[ある]いて行[い]った。", "sentence_source": "generated"}, {"text": "友だちが行った先を、私は知らない。", "target_word": "先", "complexity_tier": "T3", "furigana": "友[とも]だちが行[い]った先[さき]を、私[わたし]は知[し]らない。", "sentence_source": "generated"}, {"text": "指の先が冷たくなった。", "target_word": "先", "complexity_tier": "T3", "furigana": "指[ゆび]の先[さき]が冷[つめ]たくなった。", "sentence_source": "generated"}, {"text": "この橋を渡った先に、学校がある。", "target_word": "先", "complexity_tier": "T3", "furigana": "この橋[はし]を渡[わた]った先[さき]に、学校[がっこう]がある。", "sentence_source": "generated"}, {"text": "木の枝の先に、小鳥がとまっている。", "target_word": "先", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]の先[さき]に、小鳥[ことり]がとまっている。", "sentence_source": "generated"}, {"text": "矢の先が的に当たった。", "target_word": "先", "complexity_tier": "T3", "furigana": "矢[や]の先[さき]が的[まと]に当[あ]たった。", "sentence_source": "generated"}, {"text": "長い列の先に、人気のパン屋がある。", "target_word": "先", "complexity_tier": "T3", "furigana": "長[なが]い列[れつ]の先[さき]に、人気[にんき]のパン屋[や]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先", "label": "基本形"}, {"form": "先の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "物の一番端の部分、また進んでいった向こうの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38994, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先", "is_correct": true, "explanation": "えんぴつの一番端の部分を指し、「先が折れた」と自然につながる。"}, {"text": "色", "is_correct": false, "explanation": "えんぴつの色は折れないので、文の意味が通らない。"}, {"text": "音", "is_correct": false, "explanation": "音は折れるものではないので、文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は折れないので、文に合わない。"}], "explanations": {"先": "えんぴつの一番端の部分を指し、「先が折れた」と自然につながる。", "色": "えんぴつの色は折れないので、文の意味が通らない。", "音": "音は折れるものではないので、文に合わない。", "天気": "天気は折れないので、文に合わない。"}, "sentence_index": 0, "correct_answer": "先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木の先を掘った。", "explanation": "ここは〈根元〉の意味。先は物の端や行き先を指すので、木の根元を掘るという意味では使えない。"}, {"text": "円の先に、点を打った。", "explanation": "ここは〈中央〉の意味。先は物の端を指すので、円の真ん中に点を打つという意味では使えない。"}, {"text": "バケツの先に、水が残っている。", "explanation": "ここは〈底〉の意味。先は物の端や行き先を指すので、容器の底にたまった水を指す使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38994, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先", "is_correct": true, "explanation": "渡った後の行き先を示し、「渡った先に学校がある」と自然につながる。"}, {"text": "名前", "is_correct": false, "explanation": "橋を渡った名前という言い方は成り立たず、文の意味が通らない。"}, {"text": "匂い", "is_correct": false, "explanation": "橋を渡った匂いという関係が成り立たず、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "橋を渡った季節では、学校の位置を示せず文に合わない。"}], "explanations": {"先": "渡った後の行き先を示し、「渡った先に学校がある」と自然につながる。", "名前": "橋を渡った名前という言い方は成り立たず、文の意味が通らない。", "匂い": "橋を渡った匂いという関係が成り立たず、文に合わない。", "季節": "橋を渡った季節では、学校の位置を示せず文に合わない。"}, "sentence_index": 6, "correct_answer": "先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱の先に、手紙を入れた。", "explanation": "ここは〈内側〉の意味。先は物の端や行き先を指すので、箱の中に入れるという意味では使えない。"}, {"text": "私の先をさすった。", "explanation": "ここは〈背中〉の意味。先は物の端や行き先を指すので、人の背中をさするという意味では使えない。"}, {"text": "鍋の先を囲んで座った。", "explanation": "ここは〈まわり〉の意味。先は物の端や行き先を指すので、鍋のまわりを囲むという意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38994, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペンの先に割れてしまった。", "corrected_sentence": "ペンの先が割れてしまった。", "error_description": "「割れる」の主語は「が」で示す。「に」は誤り（正しくは「が」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
