INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38995, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の一番端の部分。また、行き着く所や相手。例：行き先、受け入れ先。", "primary_collocate": null, "pronunciation": "さき", "ipa": "saki", "syllable_count": 2, "sentences": [{"text": "荷物を送る先を、紙に書いてください。", "target_word": "先", "complexity_tier": "T3", "furigana": "荷物[にもつ]を送[おく]る先[さき]を、紙[かみ]に書[か]いてください。", "sentence_source": "generated"}, {"text": "連絡する先が分からず、困った。", "target_word": "先", "complexity_tier": "T3", "furigana": "連絡[れんらく]する先[さき]が分[わ]からず、困[こま]った。", "sentence_source": "generated"}, {"text": "傘の先で地面をつついた。", "target_word": "先", "complexity_tier": "T3", "furigana": "傘[かさ]の先[さき]で地面[じめん]をつついた。", "sentence_source": "generated"}, {"text": "棒の先にひもを結んだ。", "target_word": "先", "complexity_tier": "T3", "furigana": "棒[ぼう]の先[さき]にひもを結[むす]んだ。", "sentence_source": "generated"}, {"text": "彼が引っ越した先は、遠い町だった。", "target_word": "先", "complexity_tier": "T3", "furigana": "彼[かれ]が引[ひ]っ越[こ]した先[さき]は、遠[とお]い町[まち]だった。", "sentence_source": "generated"}, {"text": "紹介された先は、とても親切な会社だった。", "target_word": "先", "complexity_tier": "T3", "furigana": "紹介[しょうかい]された先[さき]は、とても親切[しんせつ]な会社[かいしゃ]だった。", "sentence_source": "generated"}, {"text": "筆の先に墨をつけて、字を書いた。", "target_word": "先", "complexity_tier": "T3", "furigana": "筆[ふで]の先[さき]に墨[すみ]をつけて、字[じ]を書[か]いた。", "sentence_source": "generated"}, {"text": "姉が就職した先は、大手の商社だった。", "target_word": "先", "complexity_tier": "T3", "furigana": "姉[あね]が就職[しゅうしょく]した先[さき]は、大手[おおて]の商社[しょうしゃ]だった。", "sentence_source": "generated"}, {"text": "山道の先は、雪で通れなかった。", "target_word": "先", "complexity_tier": "T3", "furigana": "山道[やまみち]の先[さき]は、雪[ゆき]で通[とお]れなかった。", "sentence_source": "generated"}, {"text": "荷物を預ける先を、友だちに聞いた。", "target_word": "先", "complexity_tier": "T3", "furigana": "荷物[にもつ]を預[あず]ける先[さき]を、友[とも]だちに聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先", "label": "基本形"}, {"form": "先の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "物の端の部分、また行き着く場所や届ける相手・取引相手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c11ecbf-5fe5-4cbb-bdf4-e678a4fe2ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38995, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先", "is_correct": true, "explanation": "荷物を送る届け先を指し、「送る先を、紙に書いてください」と自然につながる。"}, {"text": "荷物", "is_correct": false, "explanation": "「送る荷物を」となり、意味が通らない。"}, {"text": "写真", "is_correct": false, "explanation": "「送る写真を紙に書く」という内容は成り立たず、文に合わない。"}, {"text": "歌", "is_correct": false, "explanation": "「送る歌を紙に書く」という内容は成り立たず、文に合わない。"}], "explanations": {"先": "荷物を送る届け先を指し、「送る先を、紙に書いてください」と自然につながる。", "荷物": "「送る荷物を」となり、意味が通らない。", "写真": "「送る写真を紙に書く」という内容は成り立たず、文に合わない。", "歌": "「送る歌を紙に書く」という内容は成り立たず、文に合わない。"}, "sentence_index": 0, "correct_answer": "先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木の先を掘った。", "explanation": "ここは〈根元〉の意味。先は届け先や行き先、物の端を指すので、木の根元を掘るという意味では使えない。"}, {"text": "円の先に、点を打った。", "explanation": "ここは〈中央〉の意味。先は届け先や物の端を指すので、円の真ん中に点を打つという意味では使えない。"}, {"text": "バケツの先に、水が残っている。", "explanation": "ここは〈底〉の意味。先は届け先や物の端を指すので、容器の底にたまった水を指す使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38995, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先", "is_correct": true, "explanation": "筆の先端を指し、「筆の先に墨をつけて」と自然につながる。"}, {"text": "名前", "is_correct": false, "explanation": "筆の名前に墨をつけるという内容は成り立たず、文に合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "筆の匂いに墨をつけるという内容は成り立たず、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "筆の季節に墨をつけるという内容は成り立たず、文に合わない。"}], "explanations": {"先": "筆の先端を指し、「筆の先に墨をつけて」と自然につながる。", "名前": "筆の名前に墨をつけるという内容は成り立たず、文に合わない。", "匂い": "筆の匂いに墨をつけるという内容は成り立たず、文に合わない。", "季節": "筆の季節に墨をつけるという内容は成り立たず、文に合わない。"}, "sentence_index": 6, "correct_answer": "先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の先をさすった。", "explanation": "ここは〈背中〉の意味。先は届け先や物の端を指すので、人の背中をさするという意味では使えない。"}, {"text": "箱の先に、手紙を入れた。", "explanation": "ここは〈内側〉の意味。先は届け先や物の端を指すので、箱の中に入れるという意味では使えない。"}, {"text": "鍋の先を囲んで座った。", "explanation": "ここは〈まわり〉の意味。先は届け先や物の端を指すので、鍋のまわりを囲むという意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38995, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷物を届ける先が、名簿に書いてください。", "corrected_sentence": "荷物を届ける先を、名簿に書いてください。", "error_description": "「書く」の目的語は「を」で示す。「が」は誤り（正しくは「を」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38995, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄が転職した先に、大きな会社だった。", "corrected_sentence": "兄が転職した先は、大きな会社だった。", "error_description": "「だった」の主題を示すには「は」を使う。「に」は誤り（正しくは「は」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '291e5617-7171-44a9-a77b-ada5472d955d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
