INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38996, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "はっきりとわかること。", "primary_collocate": null, "pronunciation": "あきらか", "ipa": "akiɾaka", "syllable_count": 4, "sentences": [{"text": "彼が嘘をついていることは明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "彼[かれ]が嘘[うそ]をついていることは明[あき]らかだ。", "sentence_source": "generated"}, {"text": "試験の結果を見れば、努力の差は明らかだった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]を見[み]れば、努力[どりょく]の差[さ]は明[あき]らかだった。", "sentence_source": "generated"}, {"text": "写真を見れば、事故の原因は明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "写真[しゃしん]を見[み]れば、事故[じこ]の原因[げんいん]は明[あき]らかだ。", "sentence_source": "generated"}, {"text": "彼女の顔色が悪いのは明らかで、みんな心配した。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の顔色[かおいろ]が悪[わる]いのは明[あき]らかで、みんな心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "明らかな間違いがあったので、先生が直してくれた。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "明[あき]らかな間違[まちが]いがあったので、先生[せんせい]が直[なお]してくれた。", "sentence_source": "generated"}, {"text": "二つの数字を比べると、違いが明らかになった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "二[ふた]つの数字[すうじ]を比[くら]べると、違[ちが]いが明[あき]らかになった。", "sentence_source": "generated"}, {"text": "調査で、この町の人口が減っていることが明らかになった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "調査[ちょうさ]で、この町[まち]の人口[じんこう]が減[へ]っていることが明[あき]らかになった。", "sentence_source": "generated"}, {"text": "彼の説明は不十分なことが明らかだったので、もう一度聞いた。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]は不十分[ふじゅうぶん]なことが明[あき]らかだったので、もう一度[いちど]聞[き]いた。", "sentence_source": "generated"}, {"text": "明らかに疲れている様子だったので、早く帰らせた。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "明[あき]らかに疲[つか]れている様子[ようす]だったので、早[はや]く帰[かえ]らせた。", "sentence_source": "generated"}, {"text": "空の色を見れば、もうすぐ雨が降ることは明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "空[そら]の色[いろ]を見[み]れば、もうすぐ雨[あめ]が降[ふ]ることは明[あき]らかだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "明らかだ", "label": "終止形"}, {"form": "明らかな", "label": "連体形"}, {"form": "明らかに", "label": "連用形"}, {"form": "明らかではない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "見ればすぐにわかるほど、はっきりしているようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38996, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明らか", "is_correct": true, "explanation": "「嘘をついていることは明らかだ」は、そうだとはっきりわかるという意味で自然につながる。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は目立つ様子を表すので、嘘をついていることの確かさを説明できない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧」は態度や作業が念入りなことを表し、事実の確かさには使えない。"}, {"text": "新鮮", "is_correct": false, "explanation": "「新鮮」は物や考えが新しいことを表し、この文の意味に合わない。"}], "explanations": {"明らか": "「嘘をついていることは明らかだ」は、そうだとはっきりわかるという意味で自然につながる。", "派手": "「派手」は目立つ様子を表すので、嘘をついていることの確かさを説明できない。", "丁寧": "「丁寧」は態度や作業が念入りなことを表し、事実の確かさには使えない。", "新鮮": "「新鮮」は物や考えが新しいことを表し、この文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "明らか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの店員は明らかで、いつも笑顔で挨拶してくれる。", "explanation": "ここは〈明朗〉（明るく気さくなさま）の意味。明らかは事実がはっきりしていることなので、人の性格には使わない。"}, {"text": "彼の名前は明らかだったと思うけど、忘れてしまった。", "explanation": "ここは〈確か〉（記憶があいまいなときの言い方）の意味。記憶の正しさには明らかを使わないので合わない。"}, {"text": "明日の試合は明らかで、勝つかどうかまだわからない。", "explanation": "ここは〈確実〉（まず間違いないさま）の意味。明らかは「はっきりわかる」ことなので、「まだわからない」と続くと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38996, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明らか", "is_correct": true, "explanation": "「人口が減っていることが明らかになった」は、事実がはっきりしたという意味で自然。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は音や様子が静かなことを表し、人口の変化には使えない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やか」は落ち着いた様子を表し、事実がはっきりするという意味にならない。"}, {"text": "大まか", "is_correct": false, "explanation": "「大まか」は細かくないおおよそを表し、ここでは意味が合わない。"}], "explanations": {"明らか": "「人口が減っていることが明らかになった」は、事実がはっきりしたという意味で自然。", "静か": "「静か」は音や様子が静かなことを表し、人口の変化には使えない。", "穏やか": "「穏やか」は落ち着いた様子を表し、事実がはっきりするという意味にならない。", "大まか": "「大まか」は細かくないおおよそを表し、ここでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "明らか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は明らかな頭脳で、難しい問題もすぐ解いてしまう。", "explanation": "ここは〈明晰〉（頭がよく筋道立てて考えられるさま）の意味。明らかは頭脳の性質には使わない。"}, {"text": "その返事は明らかで、何を言いたいのか全くわからなかった。", "explanation": "ここは〈曖昧〉（はっきりしないさま）の意味。明らかは「はっきりしている」ことなので、わからなかったという文と矛盾する。"}, {"text": "来月の旅行は明らかで、日程はまだ決まっていない。", "explanation": "ここは〈確定〉（決まっていること）の意味。明らかは「はっきりわかる」ことなので、「まだ決まっていない」と続くと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38996, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その理由は明らかく、誰にでもわかる。", "corrected_sentence": "その理由は明らかで、誰にでもわかる。", "error_description": "形状詞「明らか」は「く」ではなく「で」で続ける。「明らかく」は誤りで、正しくは「明らかで」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "明らか", "is_correct": true, "explanation": "語幹で、「だった」が続く形。この位置に入る。"}, {"text": "明らかな", "is_correct": false, "explanation": "連体形で、名詞に直接続く形。「だった」の前には入らない。"}, {"text": "明らかだ", "is_correct": false, "explanation": "終止形で、「だった」を続けると「明らかだだった」になるので不可。"}, {"text": "明らかになる", "is_correct": false, "explanation": "「なる」が続く形で、「だった」の前には入らない。"}], "correct_form": "明らか", "base_form": "明らかだ", "form_label": "語幹（だった の前）", "sentence_index": 1, "explanations": {"明らか": "語幹で、「だった」が続く形。この位置に入る。", "明らかな": "連体形で、名詞に直接続く形。「だった」の前には入らない。", "明らかだ": "終止形で、「だった」を続けると「明らかだだった」になるので不可。", "明らかになる": "「なる」が続く形で、「だった」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38996, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "調査で、この町の人口が減っていることが明らかくなったそうだ。", "corrected_sentence": "調査で、この町の人口が減っていることが明らかになったそうだ。", "error_description": "「明らかになる」の形で使う。「明らかくなった」は活用が誤りで、正しくは「明らかになった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "明らか", "is_correct": true, "explanation": "語幹で、「だった」が続く形。この位置に入る。"}, {"text": "明らかに", "is_correct": false, "explanation": "連用形で、「だった」の前には入らない。"}, {"text": "明らかではない", "is_correct": false, "explanation": "否定形で、「だった」の前には入らない。"}, {"text": "明らかになった", "is_correct": false, "explanation": "「なった」が続く形で、「だったので」の前には入らない。"}], "correct_form": "明らか", "base_form": "明らかだ", "form_label": "語幹（だった の前）", "sentence_index": 7, "explanations": {"明らか": "語幹で、「だった」が続く形。この位置に入る。", "明らかに": "連用形で、「だった」の前には入らない。", "明らかではない": "否定形で、「だった」の前には入らない。", "明らかになった": "「なった」が続く形で、「だったので」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
