INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38997, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "疑う余地がなく、はっきりしているさま。", "primary_collocate": null, "pronunciation": "あきらか", "ipa": "akiɾaka", "syllable_count": 4, "sentences": [{"text": "証拠があれば、彼が犯人であることは明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "証拠[しょうこ]があれば、彼[かれ]が犯人[はんにん]であることは明[あき]らかだ。", "sentence_source": "generated"}, {"text": "明らかに相手のミスなのに、彼は謝らなかった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "明[あき]らかに相手[あいて]のミスなのに、彼[かれ]は謝[あやま]らなかった。", "sentence_source": "generated"}, {"text": "練習をしなかったのだから、負けるのは明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "練習[れんしゅう]をしなかったのだから、負[ま]けるのは明[あき]らかだ。", "sentence_source": "generated"}, {"text": "結果は火を見るより明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "結果[けっか]は火[ひ]を見[み]るより明[あき]らかだ。", "sentence_source": "generated"}, {"text": "彼女が一番上手なのは誰の目にも明らかだった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が一番[いちばん]上手[じょうず]なのは誰[だれ]の目[め]にも明[あき]らかだった。", "sentence_source": "generated"}, {"text": "数字が合わないので、計算に誤りがあるのは明らかだ。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "数字[すうじ]が合[あ]わないので、計算[けいさん]に誤[あやま]りがあるのは明[あき]らかだ。", "sentence_source": "generated"}, {"text": "彼の態度から、怒っていることは明らかだった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "彼[かれ]の態度[たいど]から、怒[おこ]っていることは明[あき]らかだった。", "sentence_source": "generated"}, {"text": "規則違反は明らかなので、言い訳はできない。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "規則[きそく]違反[いはん]は明[あき]らかなので、言[い]い訳[わけ]はできない。", "sentence_source": "generated"}, {"text": "彼女の言葉が嘘だったことが、後で明らかになった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の言葉[ことば]が嘘[うそ]だったことが、後[あと]で明[あき]らかになった。", "sentence_source": "generated"}, {"text": "明らかな証拠が出たので、裁判は早く終わった。", "target_word": "明らか", "complexity_tier": "T3", "furigana": "明[あき]らかな証拠[しょうこ]が出[で]たので、裁判[さいばん]は早[はや]く終[お]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "明らかだ", "label": "終止形"}, {"form": "明らかな", "label": "連体形"}, {"form": "明らかに", "label": "連用形"}, {"form": "明らかではない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "疑いようがないほど、事実や結論がはっきりしているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38997, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明らか", "is_correct": true, "explanation": "「彼が犯人であることは明らかだ」は、疑いがないという意味で自然につながる。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は目立つ様子を表すので、犯人であることの確かさには使えない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧」は態度や作業が念入りなことを表し、事実の確かさには使えない。"}, {"text": "新鮮", "is_correct": false, "explanation": "「新鮮」は物や考えが新しいことを表し、この文の意味に合わない。"}], "explanations": {"明らか": "「彼が犯人であることは明らかだ」は、疑いがないという意味で自然につながる。", "派手": "「派手」は目立つ様子を表すので、犯人であることの確かさには使えない。", "丁寧": "「丁寧」は態度や作業が念入りなことを表し、事実の確かさには使えない。", "新鮮": "「新鮮」は物や考えが新しいことを表し、この文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "明らか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの先生は明らかで、いつも笑顔で話しかけてくれる。", "explanation": "ここは〈明朗〉（明るく気さくなさま）の意味。明らかは事実がはっきりしていることなので、人の性格には使わない。"}, {"text": "部屋の電気が明らかで、中がよく見えた。", "explanation": "ここは〈明るい〉（光が強いさま）の意味。明らかは事実がはっきりしていることなので、光の強さには使わない。"}, {"text": "来年の景気は明らかだが、誰にも予測できない。", "explanation": "ここは〈確実〉（まず間違いないさま）の意味。明らかは「はっきりわかる」ことなので、「予測できない」と続くと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38997, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明らか", "is_correct": true, "explanation": "「怒っていることは明らかだった」は、そうだとはっきりわかったという意味で自然。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は音や様子が静かなことを表し、怒りの確かさには使えない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やか」は落ち着いた様子を表し、怒っていることの説明にはならない。"}, {"text": "大まか", "is_correct": false, "explanation": "「大まか」は細かくないおおよそを表し、ここでは意味が合わない。"}], "explanations": {"明らか": "「怒っていることは明らかだった」は、そうだとはっきりわかったという意味で自然。", "静か": "「静か」は音や様子が静かなことを表し、怒りの確かさには使えない。", "穏やか": "「穏やか」は落ち着いた様子を表し、怒っていることの説明にはならない。", "大まか": "「大まか」は細かくないおおよそを表し、ここでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "明らか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は明らかな頭脳で、難しい問題もすぐ解いてしまう。", "explanation": "ここは〈明晰〉（頭がよく筋道立てて考えられるさま）の意味。明らかは頭脳の性質には使わない。"}, {"text": "そのポスターの文字は明らかで、何と書いてあるか読めなかった。", "explanation": "ここは〈曖昧〉（はっきりしないさま）の意味。明らかは「はっきりしている」ことなので、読めなかったという文と矛盾する。"}, {"text": "来月の旅行は明らかで、日程はまだ決まっていない。", "explanation": "ここは〈確定〉（決まっていること）の意味。明らかは「はっきりわかる」ことなので、「まだ決まっていない」と続くと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38997, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犯人の名前は明らかく、ニュースで伝えられた。", "corrected_sentence": "犯人の名前は明らかで、ニュースで伝えられた。", "error_description": "形状詞「明らか」は「く」ではなく「で」で続ける。「明らかく」は誤りで、正しくは「明らかで」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "明らか", "is_correct": true, "explanation": "語幹で、「に」の前に入る形。ここで語幹として使える。"}, {"text": "明らかな", "is_correct": false, "explanation": "連体形で、「に」の前には入らない。"}, {"text": "明らかに", "is_correct": false, "explanation": "連用形で、語幹の位置には入らない。"}, {"text": "明らかではない", "is_correct": false, "explanation": "否定形で、「に」の前には入らない。"}], "correct_form": "明らか", "base_form": "明らかだ", "form_label": "語幹（に の前）", "sentence_index": 1, "explanations": {"明らか": "語幹で、「に」の前に入る形。ここで語幹として使える。", "明らかな": "連体形で、「に」の前には入らない。", "明らかに": "連用形で、語幹の位置には入らない。", "明らかではない": "否定形で、「に」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38997, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合の結果が明らかくなり、みんな喜んだ。", "corrected_sentence": "試合の結果が明らかになり、みんな喜んだ。", "error_description": "「明らかになる」の形で使う。「明らかくなり」は活用が誤りで、正しくは「明らかになり」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "明らか", "is_correct": true, "explanation": "語幹で、「なので」の前に入る形。この位置に入る。"}, {"text": "明らかだ", "is_correct": false, "explanation": "終止形で、「なので」の前には「明らかだなので」となり不可。"}, {"text": "明らかになる", "is_correct": false, "explanation": "「なる」が続く形で、「なので」には直接続かない。"}, {"text": "明らかになった", "is_correct": false, "explanation": "過去形で、「なので」の前には入らない。"}], "correct_form": "明らか", "base_form": "明らかだ", "form_label": "語幹（なので の前）", "sentence_index": 7, "explanations": {"明らか": "語幹で、「なので」の前に入る形。この位置に入る。", "明らかだ": "終止形で、「なので」の前には「明らかだなので」となり不可。", "明らかになる": "「なる」が続く形で、「なので」には直接続かない。", "明らかになった": "過去形で、「なので」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「受験勉強に力を向けて取り組む」の対象を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」だが、注力は「〜に注力する」の形で対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」は、注力の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す「と」は、注力の対象には合わない。"}], "correct_answer": "に", "explanations": {"に": "「受験勉強に力を向けて取り組む」の対象を示す「に」。", "を": "目的語を示す「を」だが、注力は「〜に注力する」の形で対象を示す。", "で": "場所や手段を示す「で」は、注力の対象を示せない。", "と": "相手や引用を示す「と」は、注力の対象には合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「子育て支援に力を向けて取り組む」の対象を示す「に」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、注力の対象は示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、注力の対象には使えない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、「〜を注力する」とは言えない。"}], "correct_answer": "に", "explanations": {"に": "「子育て支援に力を向けて取り組む」の対象を示す「に」。", "が": "主語を示す「が」で、注力の対象は示せない。", "から": "起点を示す「から」は、注力の対象には使えない。", "を": "目的語の「を」は、「〜を注力する」とは言えない。"}, "error_tags": {"が": "主語", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることに、力を集中して取り組むこと。", "primary_collocate": null, "pronunciation": "ちゅうりょく", "ipa": "tɕɯːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "新しい商品の開発に注力するため、今年は広告費を減らした。", "target_word": "注力", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]の開発[かいはつ]に注力[ちゅうりょく]するため、今年[ことし]は広告費[こうこくひ]を減[へ]らした。", "sentence_source": "generated"}, {"text": "彼は受験勉強に注力して、遊びの時間をほとんど持たなかった。", "target_word": "注力", "complexity_tier": "T3", "furigana": "彼[かれ]は受験勉強[じゅけんべんきょう]に注力[ちゅうりょく]して、遊[あそ]びの時間[じかん]をほとんど持[も]たなかった。", "sentence_source": "generated"}, {"text": "会社は海外での販売に注力する方針を発表した。", "target_word": "注力", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は海外[かいがい]での販売[はんばい]に注力[ちゅうりょく]する方針[ほうしん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "今月は人材の育成に注力しているので、研修が増えた。", "target_word": "注力", "complexity_tier": "T3", "furigana": "今月[こんげつ]は人材[じんざい]の育成[いくせい]に注力[ちゅうりょく]しているので、研修[けんしゅう]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "彼女は一つの作品に注力するあまり、体調を崩してしまった。", "target_word": "注力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は一[ひと]つの作品[さくひん]に注力[ちゅうりょく]するあまり、体調[たいちょう]を崩[くず]してしまった。", "sentence_source": "generated"}, {"text": "店長は接客の改善に注力し、客からの苦情が減った。", "target_word": "注力", "complexity_tier": "T3", "furigana": "店長[てんちょう]は接客[せっきゃく]の改善[かいぜん]に注力[ちゅうりょく]し、客[きゃく]からの苦情[くじょう]が減[へ]った。", "sentence_source": "generated"}, {"text": "練習の量より質に注力したほうが、上達は早い。", "target_word": "注力", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の量[りょう]より質[しつ]に注力[ちゅうりょく]したほうが、上達[じょうたつ]は早[はや]い。", "sentence_source": "generated"}, {"text": "市は子育て支援に注力しており、保育園の数が増えている。", "target_word": "注力", "complexity_tier": "T3", "furigana": "市[し]は子育[こそだ]て支援[しえん]に注力[ちゅうりょく]しており、保育園[ほいくえん]の数[かず]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "試合まで時間がないので、守りの練習に注力することにした。", "target_word": "注力", "complexity_tier": "T3", "furigana": "試合[しあい]まで時間[じかん]がないので、守[まも]りの練習[れんしゅう]に注力[ちゅうりょく]することにした。", "sentence_source": "generated"}, {"text": "私たちは環境問題の解決に注力しています。", "target_word": "注力", "complexity_tier": "T3", "furigana": "私たち[わたしたち]は環境問題[かんきょうもんだい]の解決[かいけつ]に注力[ちゅうりょく]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "注力する", "label": "終止形"}, {"form": "注力した", "label": "過去形"}, {"form": "注力している", "label": "進行形"}, {"form": "注力して", "label": "て形"}, {"form": "注力しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "目標に力を集中して取り組むこと（する動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注力", "is_correct": true, "explanation": "「開発に力を集中して取り組む」の意味で、文脈に合う。"}, {"text": "節電", "is_correct": false, "explanation": "電気の使用を減らす意味で、開発に力を向ける文脈には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつける意味で、開発の文脈とは結びつかない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、開発に向けた取り組みには使えない。"}], "explanations": {"注力": "「開発に力を集中して取り組む」の意味で、文脈に合う。", "節電": "電気の使用を減らす意味で、開発に力を向ける文脈には合わない。", "採点": "答案などに点数をつける意味で、開発の文脈とは結びつかない。", "配達": "品物を届ける意味で、開発に向けた取り組みには使えない。"}, "sentence_index": 0, "correct_answer": "注力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道路を渡るときは、車に注力してください。", "explanation": "ここは〈注意〉の意味。注力は力を集中して取り組むことで、危険に気をつける意味では使わない。"}, {"text": "この新作ゲームは発売前から、世界中の注力を集めている。", "explanation": "ここは〈注目〉の意味。注力は取り組みに力を向けることで、人の関心を集める意味はない。"}, {"text": "鍋に水を注力して、火にかけた。", "explanation": "ここは〈注ぐ〉の意味。注力は力を集中して取り組むことで、液体を入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注力", "is_correct": true, "explanation": "「質に力を集中させる」の意味で、「量より質に」の対比に合う。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、練習の質には結びつかない。"}, {"text": "放送", "is_correct": false, "explanation": "番組を電波で流す意味で、練習の文脈では使わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う意味で、練習の量や質の話には合わない。"}], "explanations": {"注力": "「質に力を集中させる」の意味で、「量より質に」の対比に合う。", "換気": "空気を入れ替える意味で、練習の質には結びつかない。", "放送": "番組を電波で流す意味で、練習の文脈では使わない。", "洗濯": "衣類を洗う意味で、練習の量や質の話には合わない。"}, "sentence_index": 6, "correct_answer": "注力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店で定食を注力した。", "explanation": "ここは〈注文〉の意味。注力は力を向けて取り組むことで、品物を頼む意味では使わない。"}, {"text": "注射器で薬を注力した。", "explanation": "ここは〈注入〉の意味。注力は取り組みへの力の集中で、液体を中に入れる意味ではない。"}, {"text": "この言葉の意味は、欄外の注力で確かめられる。", "explanation": "ここは〈注釈〉の意味。注力は取り組みに力を向けることで、本文に添えた説明の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は新しい商品の開発を注力して、広告費を減らした。", "corrected_sentence": "彼は新しい商品の開発に注力して、広告費を減らした。", "error_description": "「注力する」は取り組む対象を「に」で示す。「を」は誤りで、正しくは「開発に注力して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38998, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は新しい公園の建設で注力している。", "corrected_sentence": "市は新しい公園の建設に注力している。", "error_description": "「注力する」は対象を「に」で示す。「で」は手段や場所を表すため誤り。正しくは「建設に注力している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39000, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "保証する内容を示す「を」。「〜を担保する」で使う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」だが、担保の対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象を示す「に」は、担保の目的語には使わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」は、保証の内容を示せない。"}], "correct_answer": "を", "explanations": {"を": "保証する内容を示す「を」。「〜を担保する」で使う。", "が": "主語を示す「が」だが、担保の対象は「を」で示す。", "に": "方向や対象を示す「に」は、担保の目的語には使わない。", "と": "相手や並列を示す「と」は、保証の内容を示せない。"}, "error_tags": {"が": "主語", "に": "方向・対象", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
