INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39000, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "約束したことを必ず実現すること。", "primary_collocate": null, "pronunciation": "たんぽ", "ipa": "tampo", "syllable_count": 3, "sentences": [{"text": "安全性を担保するために、出荷前に何度も検査をします。", "target_word": "担保", "complexity_tier": "T3", "furigana": "安全性[あんぜんせい]を担保[たんぽ]するために、出荷前[しゅっかまえ]に何度[なんど]も検査[けんさ]をします。", "sentence_source": "generated"}, {"text": "この契約書は、約束が必ず守られることを担保している。", "target_word": "担保", "complexity_tier": "T3", "furigana": "この契約書[けいやくしょ]は、約束[やくそく]が必[かなら]ず守[まも]られることを担保[たんぽ]している。", "sentence_source": "generated"}, {"text": "品質を担保できない商品は、店に並べられない。", "target_word": "担保", "complexity_tier": "T3", "furigana": "品質[ひんしつ]を担保[たんぽ]できない商品[しょうひん]は、店[みせ]に並[なら]べられない。", "sentence_source": "generated"}, {"text": "会社は納期を担保すると約束した。", "target_word": "担保", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は納期[のうき]を担保[たんぽ]すると約束[やくそく]した。", "sentence_source": "generated"}, {"text": "公平な審査を担保するため、審査員の名前は公表されない。", "target_word": "担保", "complexity_tier": "T3", "furigana": "公平[こうへい]な審査[しんさ]を担保[たんぽ]するため、審査員[しんさいん]の名前[なまえ]は公表[こうひょう]されない。", "sentence_source": "generated"}, {"text": "個人情報の安全が担保されていないサービスは使いたくない。", "target_word": "担保", "complexity_tier": "T3", "furigana": "個人情報[こじんじょうほう]の安全[あんぜん]が担保[たんぽ]されていないサービスは使[つか]いたくない。", "sentence_source": "generated"}, {"text": "医師の資格は、治療の質を担保する一つの条件だ。", "target_word": "担保", "complexity_tier": "T3", "furigana": "医師[いし]の資格[しかく]は、治療[ちりょう]の質[しつ]を担保[たんぽ]する一[ひと]つの条件[じょうけん]だ。", "sentence_source": "generated"}, {"text": "彼の言葉だけでは、成功は担保されない。", "target_word": "担保", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]だけでは、成功[せいこう]は担保[たんぽ]されない。", "sentence_source": "generated"}, {"text": "工事の完成を担保するために、会社は保証金を預けた。", "target_word": "担保", "complexity_tier": "T3", "furigana": "工事[こうじ]の完成[かんせい]を担保[たんぽ]するために、会社[かいしゃ]は保証金[ほしょうきん]を預[あず]けた。", "sentence_source": "generated"}, {"text": "透明性を担保する仕組みがなければ、市民は信用しない。", "target_word": "担保", "complexity_tier": "T3", "furigana": "透明性[とうめいせい]を担保[たんぽ]する仕組[しく]みがなければ、市民[しみん]は信用[しんよう]しない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "担保する", "label": "終止形"}, {"form": "担保した", "label": "過去形"}, {"form": "担保される", "label": "受身形"}, {"form": "担保して", "label": "て形"}, {"form": "担保できる", "label": "可能形"}], "register": "formal", "sense_fingerprint": "品質や安全など約束した内容が確実に実現されるよう保証すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39000, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担保", "is_correct": true, "explanation": "「安全性を保証する」の意味で、文脈に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "移動して楽しむ意味で、安全性とは結びつかない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつける意味で、安全性の保証とは関係がない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、出荷前の検査の文脈には合わない。"}], "explanations": {"担保": "「安全性を保証する」の意味で、文脈に合う。", "旅行": "移動して楽しむ意味で、安全性とは結びつかない。", "採点": "答案などに点数をつける意味で、安全性の保証とは関係がない。", "換気": "空気を入れ替える意味で、出荷前の検査の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い夜、子犬を毛布で担保した。", "explanation": "ここは〈保護〉の意味。担保は約束した内容を必ず実現させることで、生き物を寒さから守る意味ではない。"}, {"text": "大切な書類を金庫に担保した。", "explanation": "ここは〈保管〉の意味。担保は約束した内容を確実に実現させることで、物を大切にしまう意味ではない。"}, {"text": "彼は新しい営業部を担保している。", "explanation": "ここは〈担当〉の意味。担保は実現を保証することで、仕事を受け持つ意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39000, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担保", "is_correct": true, "explanation": "「治療の質を保証する」の意味で、文脈に合う。"}, {"text": "放送", "is_correct": false, "explanation": "番組を電波で流す意味で、治療の質の話には合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う意味で、治療の質には結びつかない。"}, {"text": "清掃", "is_correct": false, "explanation": "場所をきれいにする意味で、治療の質の文脈には合わない。"}], "explanations": {"担保": "「治療の質を保証する」の意味で、文脈に合う。", "放送": "番組を電波で流す意味で、治療の質の話には合わない。", "洗濯": "衣類を洗う意味で、治療の質には結びつかない。", "清掃": "場所をきれいにする意味で、治療の質の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "繁忙期に備えて、スタッフの人数を担保した。", "explanation": "ここは〈確保〉の意味。担保は約束した内容を実現させることで、人を手元に置く意味ではない。"}, {"text": "交通渋滞を担保するための道路工事が始まった。", "explanation": "ここは〈解消〉の意味。担保は実現を保証することで、問題を取り除く意味ではない。"}, {"text": "出発前にエンジンを担保した。", "explanation": "ここは〈点検〉の意味。担保は約束の実現を保証する意味で、機械を調べる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39000, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は配達の日時が担保すると約束した。", "corrected_sentence": "店は配達の日時を担保すると約束した。", "error_description": "「担保する」は保証する内容を「を」で示す。「が」では主語になり不自然。正しくは「日時を担保する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39000, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この仕組みは、子どもの安全に担保する役割を持つ。", "corrected_sentence": "この仕組みは、子どもの安全を担保する役割を持つ。", "error_description": "「担保する」は保証する内容を「を」で示す。「に」では不自然。正しくは「安全を担保する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
