INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39002, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「海水浴客を見張る」の対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、監視の対象は示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、監視の対象には使わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、監視の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「海水浴客を見張る」の対象を示す「を」。", "が": "主語を示す「が」で、監視の対象は示せない。", "から": "起点を示す「から」は、監視の対象には使わない。", "へ": "方向を示す「へ」は、監視の対象には合わない。"}, "error_tags": {"が": "主語", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39002, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "誰かが悪いことをしないか、じっと見て守ること。", "primary_collocate": null, "pronunciation": "かんし", "ipa": "kaɴɕi", "syllable_count": 3, "sentences": [{"text": "万引きを防ぐため、店内にカメラを置いて客を監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "万引[まんび]きを防[ふせ]ぐため、店内[てんない]にカメラを置[お]いて客[きゃく]を監視[かんし]している。", "sentence_source": "generated"}, {"text": "試験中、先生が教室を歩いて受験生を監視した。", "target_word": "監視", "complexity_tier": "T3", "furigana": "試験中[しけんちゅう]、先生[せんせい]が教室[きょうしつ]を歩[ある]いて受験生[じゅけんせい]を監視[かんし]した。", "sentence_source": "generated"}, {"text": "夜の公園は、警備員が交代で監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "夜[よる]の公園[こうえん]は、警備員[けいびいん]が交代[こうたい]で監視[かんし]している。", "sentence_source": "generated"}, {"text": "刑務所では、囚人の行動が二十四時間監視される。", "target_word": "監視", "complexity_tier": "T3", "furigana": "刑務所[けいむしょ]では、囚人[しゅうじん]の行動[こうどう]が二十四時間[にじゅうよじかん]監視[かんし]される。", "sentence_source": "generated"}, {"text": "子どもが危ないことをしないように、親が遠くから監視した。", "target_word": "監視", "complexity_tier": "T3", "furigana": "子[こ]どもが危[あぶ]ないことをしないように、親[おや]が遠[とお]くから監視[かんし]した。", "sentence_source": "generated"}, {"text": "監視の目が厳しくて、誰もルールを破れなかった。", "target_word": "監視", "complexity_tier": "T3", "furigana": "監視[かんし]の目[め]が厳[きび]しくて、誰[だれ]もルールを破[やぶ]れなかった。", "sentence_source": "generated"}, {"text": "犯人は警察に監視されているとも知らず、同じ場所に戻ってきた。", "target_word": "監視", "complexity_tier": "T3", "furigana": "犯人[はんにん]は警察[けいさつ]に監視[かんし]されているとも知[し]らず、同[おな]じ場所[ばしょ]に戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "海岸では、ライフガードが海水浴客を監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "海岸[かいがん]では、ライフガードが海水浴客[かいすいよくきゃく]を監視[かんし]している。", "sentence_source": "generated"}, {"text": "工場の出入り口は守衛が一日中監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "工場[こうじょう]の出入[でい]り口[ぐち]は守衛[しゅえい]が一日中[いちにちじゅう]監視[かんし]している。", "sentence_source": "generated"}, {"text": "国境の近くでは兵士が不審な人物を監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "国境[こっきょう]の近[ちか]くでは兵士[へいし]が不審[ふしん]な人物[じんぶつ]を監視[かんし]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "監視する", "label": "終止形"}, {"form": "監視した", "label": "過去形"}, {"form": "監視される", "label": "受身形"}, {"form": "監視して", "label": "て形"}, {"form": "監視している", "label": "進行形"}], "register": "neutral", "sense_fingerprint": "悪事や違反が起きないよう人をじっと見張ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39002, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "監視", "is_correct": true, "explanation": "「客をじっと見張る」の意味で、万引き防止の文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつける意味で、見張る意味にはならない。"}, {"text": "節電", "is_correct": false, "explanation": "電気の使用を減らす意味で、客を見る文脈には合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "移動して楽しむ意味で、客を見張る文脈では使えない。"}], "explanations": {"監視": "「客をじっと見張る」の意味で、万引き防止の文脈に合う。", "採点": "答案などに点数をつける意味で、見張る意味にはならない。", "節電": "電気の使用を減らす意味で、客を見る文脈には合わない。", "旅行": "移動して楽しむ意味で、客を見張る文脈では使えない。"}, "sentence_index": 0, "correct_answer": "監視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は夜中に、新しい歌を監視して作った。", "explanation": "ここは〈作曲〉の意味。監視は悪事などを見張ることで、曲を書く意味ではない。"}, {"text": "野良猫を見つけたので、監視して病院へ連れていった。", "explanation": "ここは〈保護〉の意味。監視は見張ることで、弱い者を守る意味ではない。"}, {"text": "観客は、選手を大きな声で監視していた。", "explanation": "ここは〈応援〉の意味。監視は悪事などを見張ることで、励ます意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39002, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "監視", "is_correct": true, "explanation": "「警察に見張られている」の意味で、文脈に合う。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、警察との文脈には合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "場所をきれいにする意味で、見張られている文脈には合わない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、警察に見られている文脈では使えない。"}], "explanations": {"監視": "「警察に見張られている」の意味で、文脈に合う。", "配達": "品物を届ける意味で、警察との文脈には合わない。", "清掃": "場所をきれいにする意味で、見張られている文脈には合わない。", "換気": "空気を入れ替える意味で、警察に見られている文脈では使えない。"}, "sentence_index": 6, "correct_answer": "監視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい社員を監視するパーティーが、夜の会場で開かれた。", "explanation": "ここは〈歓迎〉の意味。監視は悪事などを見張ることで、温かく迎える意味ではない。"}, {"text": "ホールで、彼女はバイオリンを監視した。", "explanation": "ここは〈演奏〉の意味。監視は見張ることで、楽器を弾く意味ではない。"}, {"text": "彼女は夜なべして、娘の服を監視した。", "explanation": "ここは〈縫う〉の意味。監視は見張ることで、布を針で縫い合わせる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39002, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、教室で受験生に監視していた。", "corrected_sentence": "先生は、教室で受験生を監視していた。", "error_description": "「監視する」は対象を「を」で示す（〜を監視する）。「に」では不自然。正しくは「受験生を監視」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39002, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員は、怪しい客の動きに監視していた。", "corrected_sentence": "店員は、怪しい客の動きを監視していた。", "error_description": "「監視する」は対象を「を」で示す。「に」では不自然。正しくは「動きを監視していた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。監視の対象である状態を示す目的語の格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。状態が見張る主体になってしまい、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や位置を示す。監視の対象を示す働きはなく、文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。監視の対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "正解。監視の対象である状態を示す目的語の格助詞。", "が": "主語を示す。状態が見張る主体になってしまい、文が成り立たない。", "に": "相手や位置を示す。監視の対象を示す働きはなく、文が不自然になる。", "へ": "方向を示す。監視の対象を示すことはできない。"}, "error_tags": {"が": "主語", "に": "相手・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。呼吸を監視の対象として示す目的語の格助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。呼吸で監視するという文にはならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。監視の対象を示すことはできず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「呼吸の監視しながら」と続けると動詞として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。呼吸を監視の対象として示す目的語の格助詞。", "で": "手段や場所を示す。呼吸で監視するという文にはならず不自然。", "より": "比較を示す。監視の対象を示すことはできず文が成り立たない。", "の": "連体修飾を示す。「呼吸の監視しながら」と続けると動詞として成り立たない。"}, "error_tags": {"で": "手段・場所", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や物事の動きを注意深く見張り、問題が起きないように管理すること。", "primary_collocate": null, "pronunciation": "かんし", "ipa": "kaɴɕi", "syllable_count": 3, "sentences": [{"text": "医師は患者の血圧を監視し、変化があればすぐ知らせる。", "target_word": "監視", "complexity_tier": "T3", "furigana": "医師[いし]は患者[かんじゃ]の血圧[けつあつ]を監視[かんし]し、変化[へんか]があればすぐ知[し]らせる。", "sentence_source": "generated"}, {"text": "管理者はサーバーの状態を監視して、故障を早く見つける。", "target_word": "監視", "complexity_tier": "T3", "furigana": "管理者[かんりしゃ]はサーバーの状態[じょうたい]を監視[かんし]して、故障[こしょう]を早[はや]く見[み]つける。", "sentence_source": "generated"}, {"text": "火山の動きは、研究所が毎日監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "火山[かざん]の動[うご]きは、研究所[けんきゅうじょ]が毎日[まいにち]監視[かんし]している。", "sentence_source": "generated"}, {"text": "工場では、機械の温度を常に監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]の温度[おんど]を常[つね]に監視[かんし]している。", "sentence_source": "generated"}, {"text": "銀行は不正な取引がないか、口座の動きを監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]は不正[ふせい]な取引[とりひき]がないか、口座[こうざ]の動[うご]きを監視[かんし]している。", "sentence_source": "generated"}, {"text": "川の水位を監視することで、洪水の危険を早く知らせられる。", "target_word": "監視", "complexity_tier": "T3", "furigana": "川[かわ]の水位[すいい]を監視[かんし]することで、洪水[こうずい]の危険[きけん]を早[はや]く知[し]らせられる。", "sentence_source": "generated"}, {"text": "発電所では、数人の担当者が計器を監視している。", "target_word": "監視", "complexity_tier": "T3", "furigana": "発電所[はつでんしょ]では、数人[すうにん]の担当者[たんとうしゃ]が計器[けいき]を監視[かんし]している。", "sentence_source": "generated"}, {"text": "患者の呼吸を監視しながら、手術は続けられた。", "target_word": "監視", "complexity_tier": "T3", "furigana": "患者[かんじゃ]の呼吸[こきゅう]を監視[かんし]しながら、手術[しゅじゅつ]は続[つづ]けられた。", "sentence_source": "generated"}, {"text": "市は大気の汚れを監視し、数値が高い日は注意を呼びかける。", "target_word": "監視", "complexity_tier": "T3", "furigana": "市[し]は大気[たいき]の汚[よご]れを監視[かんし]し、数値[すうち]が高[たか]い日[ひ]は注意[ちゅうい]を呼[よ]びかける。", "sentence_source": "generated"}, {"text": "株式市場の動きを監視する専門の部署が作られた。", "target_word": "監視", "complexity_tier": "T3", "furigana": "株式市場[かぶしきしじょう]の動[うご]きを監視[かんし]する専門[せんもん]の部署[ぶしょ]が作[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "監視する", "label": "終止形"}, {"form": "監視した", "label": "過去形"}, {"form": "監視される", "label": "受身形"}, {"form": "監視して", "label": "て形"}, {"form": "監視している", "label": "進行形"}], "register": "neutral", "sense_fingerprint": "機械・数値・状況などの動きを見張って異常を管理すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "監視", "is_correct": true, "explanation": "正解。血圧の変化を見張って知らせる、という文脈に合う。"}, {"text": "注射", "is_correct": false, "explanation": "「血圧を注射し」では意味が通らない。注射は薬剤を体に打つ行為で、見張る対象には合わない。"}, {"text": "処方", "is_correct": false, "explanation": "医師が薬を出す行為を指し、血圧を見張って知らせる文脈に合わない。"}, {"text": "輸血", "is_correct": false, "explanation": "血液を体内に移す行為で、血圧を対象にすることはできない。"}], "explanations": {"監視": "正解。血圧の変化を見張って知らせる、という文脈に合う。", "注射": "「血圧を注射し」では意味が通らない。注射は薬剤を体に打つ行為で、見張る対象には合わない。", "処方": "医師が薬を出す行為を指し、血圧を見張って知らせる文脈に合わない。", "輸血": "血液を体内に移す行為で、血圧を対象にすることはできない。"}, "sentence_index": 0, "correct_answer": "監視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は孫の成長を監視して、そっと応援していた。", "explanation": "ここは〈見守る〉の意味。監視は問題が起きないよう見張って管理することなので、温かく成長を見守る文脈では使わない。"}, {"text": "彼は楽譜を監視して、新しい曲を書いた。", "explanation": "ここは〈作曲〉の意味。監視は見張って管理することで、曲を書く意味ではない。"}, {"text": "彼は古い時計を監視して、部品を取り替えた。", "explanation": "ここは〈修理〉の意味。監視は見張って管理することで、壊れた部品を直す意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "監視", "is_correct": true, "explanation": "正解。計器の動きを見張る、という文脈に合う。"}, {"text": "送電", "is_correct": false, "explanation": "電力を送る意味で、計器を対象にすることはできない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける行為で、計器には使わない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出す行為で、計器には当てはまらない。"}], "explanations": {"監視": "正解。計器の動きを見張る、という文脈に合う。", "送電": "電力を送る意味で、計器を対象にすることはできない。", "点火": "火をつける行為で、計器には使わない。", "採掘": "地下の資源を掘り出す行為で、計器には当てはまらない。"}, "sentence_index": 6, "correct_answer": "監視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は生徒の答案を監視して、点数をつけた。", "explanation": "ここは〈採点〉の意味。監視は見張り続けることで、答案に点数をつける行為には使わない。"}, {"text": "整備士は車のブレーキを監視して、利きを良くした。", "explanation": "ここは〈調整〉の意味。監視は見張って管理することで、部品の具合を整えて直す調整の意味には使わない。"}, {"text": "鑑定士は絵画の価値を監視して、値段を決めた。", "explanation": "ここは〈査定〉の意味。価値を見極めて値段を決める文で、見張る意味の監視は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ビルの入り口では、警備員が出入りする人を監視ている。", "corrected_sentence": "ビルの入り口では、警備員が出入りする人を監視している。", "error_description": "『監視』はサ変動詞なので、『監視している』の形になる。『監視ている』は『し』が抜けた誤った形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39003, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜間は、警備員が玄関の防犯カメラの映像に監視している。", "corrected_sentence": "夜間は、警備員が玄関の防犯カメラの映像を監視している。", "error_description": "『監視』は『〜を監視する』の形で、対象には『を』を付ける。『映像に監視している』は格助詞が誤り。正しくは『映像を監視している』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「レベル」が「同じ」の主語であることを示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「同じ」は目的語を取らないので、「レベルを同じ」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」を入れると「レベルの同じ」となり、「同じ」の前に名詞の続き方として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、「同じ」の主語としては合わない。"}], "correct_answer": "が", "explanations": {"が": "「レベル」が「同じ」の主語であることを示す。正しい。", "を": "「同じ」は目的語を取らないので、「レベルを同じ」は成り立たない。", "の": "「の」を入れると「レベルの同じ」となり、「同じ」の前に名詞の続き方として不自然。", "で": "「で」は場所や手段を示し、「同じ」の主語としては合わない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上げる」の目的語としてレベルを示す。「レベルを上げる」として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「上げる」は他動詞なので、レベルに「が」を付けると主語になり、文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、上げる対象のレベルには付かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「上げる」の対象であるレベルには付かない。"}], "correct_answer": "を", "explanations": {"を": "「上げる」の目的語としてレベルを示す。「レベルを上げる」として正しい。", "が": "「上げる」は他動詞なので、レベルに「が」を付けると主語になり、文の意味が合わない。", "で": "「で」は場所や手段を示し、上げる対象のレベルには付かない。", "へ": "「へ」は方向を示すが、「上げる」の対象であるレベルには付かない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "レベルは、ものごとのくらいやだんかいのことです。", "primary_collocate": null, "pronunciation": "れべる", "ipa": "ɾebeɾɯ", "syllable_count": 3, "sentences": [{"text": "私の日本語のレベルは、まだ初級です。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "私(わたし)の日本語(にほんご)のレベルは、まだ初級(しょきゅう)です。", "sentence_source": "generated"}, {"text": "このクラスは、みんなのレベルが同じなので、授業が進めやすい。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "このクラスは、みんなのレベルが同(おな)じなので、授業(じゅぎょう)が進(すす)めやすい。", "sentence_source": "generated"}, {"text": "彼女は料理のレベルが高く、プロの店でも働ける。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は料理(りょうり)のレベルが高(たか)く、プロの店(みせ)でも働(はたら)ける。", "sentence_source": "generated"}, {"text": "試験は、受ける人のレベルに合わせて三つに分かれている。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "試験(しけん)は、受(う)ける人(ひと)のレベルに合(あ)わせて三(みっ)つに分(わ)かれている。", "sentence_source": "generated"}, {"text": "兄とはレベルが違いすぎて、一緒に走るのは無理だ。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "兄(あに)とはレベルが違(ちが)いすぎて、一緒(いっしょ)に走(はし)るのは無理(むり)だ。", "sentence_source": "generated"}, {"text": "先生は、生徒のレベルを見てから、宿題を決める。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "先生(せんせい)は、生徒(せいと)のレベルを見(み)てから、宿題(しゅくだい)を決(き)める。", "sentence_source": "generated"}, {"text": "このレストランの味は、値段のわりにレベルが低い。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "このレストランの味(あじ)は、値段(ねだん)のわりにレベルが低(ひく)い。", "sentence_source": "generated"}, {"text": "英語のレベルを上げるために、毎日ニュースを聞いている。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "英語(えいご)のレベルを上(あ)げるために、毎日(まいにち)ニュースを聞(き)いている。", "sentence_source": "generated"}, {"text": "この問題は、小学生にはレベルが高すぎて解けない。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "この問題(もんだい)は、小学生(しょうがくせい)にはレベルが高(たか)すぎて解(と)けない。", "sentence_source": "generated"}, {"text": "大会に出る選手は、みんな同じくらいのレベルだった。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "大会(たいかい)に出(で)る選手(せんしゅ)は、みんな同(おな)じくらいのレベルだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レベル", "label": "基本形"}, {"form": "レベルの", "label": "名詞＋の（連体修飾）"}], "register": "中立", "sense_fingerprint": "レベル：能力や物事の位置を示す段階・くらい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レベル", "is_correct": true, "explanation": "日本語の習熟の程度を表し、まだ初級という文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は日本語の習熟の程度ではないので、この文には合わない。"}, {"text": "面積", "is_correct": false, "explanation": "面積は日本語の習熟の程度ではないので、この文には合わない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は日本語の習熟の程度ではないので、初級という段階には合わない。"}], "explanations": {"レベル": "日本語の習熟の程度を表し、まだ初級という文に合う。", "天気": "天気は日本語の習熟の程度ではないので、この文には合わない。", "面積": "面積は日本語の習熟の程度ではないので、この文には合わない。", "予算": "予算は日本語の習熟の程度ではないので、初級という段階には合わない。"}, "sentence_index": 0, "correct_answer": "レベル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このドレスは、レベルが淡くて、白に近い青だ。", "explanation": "〈色の濃さ〉の代わりにレベルを使った誤り。レベルは色の濃淡を表さない。"}, {"text": "彼は穏やかなレベルで、いつも周りの人に親切だ。", "explanation": "〈性格〉の代わりにレベルを使った誤り。性格を表す場合はレベルとは言わない。"}, {"text": "父はレベルが九十キロもあって、まだ元気に働いている。", "explanation": "〈体重〉の代わりにレベルを使った誤り。レベルは体重を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レベル", "is_correct": true, "explanation": "値段のわりに何の程度が低いかを表す語で、味の水準の話として合う。"}, {"text": "身長", "is_correct": false, "explanation": "身長はレストランの味や値段に対して言う語ではないので合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は料理の味について言う語ではないので、この文には合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は味の程度を言う語ではないので、この文には合わない。"}], "explanations": {"レベル": "値段のわりに何の程度が低いかを表す語で、味の水準の話として合う。", "身長": "身長はレストランの味や値段に対して言う語ではないので合わない。", "体重": "体重は料理の味について言う語ではないので、この文には合わない。", "湿度": "湿度は味の程度を言う語ではないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "レベル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の名前はレベルが三文字で、覚えやすい。", "explanation": "〈名前の長さ〉の代わりにレベルを使った誤り。レベルは文字数を表さない。"}, {"text": "この荷物はレベルが十キロもあって、一人では運べない。", "explanation": "〈重さ〉の代わりにレベルを使った誤り。レベルは重さを表さない。"}, {"text": "この電池はレベルが長く、三年は持つ。", "explanation": "〈寿命〉の代わりにレベルを使った誤り。レベルは使える期間を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の日本語のレベルを上がって、試験に合格した。", "corrected_sentence": "私の日本語のレベルが上がって、試験に合格した。", "error_description": "「上がる」は自動詞なので主語に「が」を取る。「を」（目的語）を付けたのが誤りで、正しくは「レベルが上がって」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39004, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手たちのレベルが上がれ、大会が盛り上がった。", "corrected_sentence": "選手たちのレベルが上がり、大会が盛り上がった。", "error_description": "「上がる」の活用の誤り。連用形「上がり」を命令形「上がれ」にしたもので、文を続ける形が必要。正しくは「上がり」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主人公のレベルが上がる主語を示す。「上がる」の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「上がる」は目的語を取らないので、レベルに「を」を付けると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、上がる主体のレベルには付かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や引用を示すが、ここでレベルが上がる主語としては合わない。"}], "correct_answer": "が", "explanations": {"が": "主人公のレベルが上がる主語を示す。「上がる」の主語として正しい。", "を": "「上がる」は目的語を取らないので、レベルに「を」を付けると文が成り立たない。", "で": "「で」は場所や手段を示し、上がる主体のレベルには付かない。", "と": "「と」は相手や引用を示すが、ここでレベルが上がる主語としては合わない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「保つ」の目的語として品質のレベルを示す。「レベルを保つ」として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「保つ」は他動詞なので、レベルに「が」を付けると主語となり文が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、保つ対象のレベルには付かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、保つ対象のレベルには付かない。"}], "correct_answer": "を", "explanations": {"を": "「保つ」の目的語として品質のレベルを示す。「レベルを保つ」として正しい。", "が": "「保つ」は他動詞なので、レベルに「が」を付けると主語となり文が合わない。", "で": "「で」は場所や手段を示し、保つ対象のレベルには付かない。", "へ": "「へ」は方向を示し、保つ対象のレベルには付かない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "レベルとは、物事の程度や段階、水準を表す言葉です。ゲームなどでは難易度を表すこともあります。", "primary_collocate": null, "pronunciation": "れべる", "ipa": "ɾebeɾɯ", "syllable_count": 3, "sentences": [{"text": "ゲームのレベルを「かんたん」に変えれば、子どもでも遊べる。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "ゲームのレベルを「かんたん」に変(か)えれば、子(こ)どもでも遊(あそ)べる。", "sentence_source": "generated"}, {"text": "敵を倒すたびに、主人公のレベルが一つ上がる。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "敵(てき)を倒(たお)すたびに、主人公(しゅじんこう)のレベルが一(ひと)つ上(あ)がる。", "sentence_source": "generated"}, {"text": "今回の作品は、世界で通用するレベルだと評価された。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "今回(こんかい)の作品(さくひん)は、世界(せかい)で通用(つうよう)するレベルだと評価(ひょうか)された。", "sentence_source": "generated"}, {"text": "町の工事の音は、我慢できないレベルまで大きくなった。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "町(まち)の工事(こうじ)の音(おと)は、我慢(がまん)できないレベルまで大(おお)きくなった。", "sentence_source": "generated"}, {"text": "彼の英語はネイティブと同じレベルで、発音もきれいだ。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "彼(かれ)の英語(えいご)はネイティブと同(おな)じレベルで、発音(はつおん)もきれいだ。", "sentence_source": "generated"}, {"text": "最後のステージはレベルが急に高くなり、何度も失敗した。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "最後(さいご)のステージはレベルが急(きゅう)に高(たか)くなり、何度(なんど)も失敗(しっぱい)した。", "sentence_source": "generated"}, {"text": "昨日の暑さは、命に関わるレベルだったと報道された。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "昨日(きのう)の暑(あつ)さは、命(いのち)に関(かか)わるレベルだったと報道(ほうどう)された。", "sentence_source": "generated"}, {"text": "品質のレベルを保つために、工場では毎日検査をしている。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "品質(ひんしつ)のレベルを保(たも)つために、工場(こうじょう)では毎日(まいにち)検査(けんさ)をしている。", "sentence_source": "generated"}, {"text": "ゲームのレベルが高すぎて、初心者は途中でやめてしまった。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "ゲームのレベルが高(たか)すぎて、初心者(しょしんしゃ)は途中(とちゅう)でやめてしまった。", "sentence_source": "generated"}, {"text": "彼の演奏は、プロと比べても劣らないレベルだ。", "target_word": "レベル", "complexity_tier": "T3", "furigana": "彼(かれ)の演奏(えんそう)は、プロと比(くら)べても劣(おと)らないレベルだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レベル", "label": "基本形"}, {"form": "レベルの", "label": "名詞＋の（連体修飾）"}], "register": "中立", "sense_fingerprint": "レベル：程度・水準。ゲームでは難易度や成長段階", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レベル", "is_correct": true, "explanation": "ゲームの難易度を表し、「かんたん」に変えるという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は難易度ではなく、「かんたん」に変えて遊びやすくする対象ではないので合わない。"}, {"text": "背景", "is_correct": false, "explanation": "背景は難易度ではないので、「かんたん」に変える対象として合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は「かんたん」に変えて遊びやすさを決める対象ではないので合わない。"}], "explanations": {"レベル": "ゲームの難易度を表し、「かんたん」に変えるという文に合う。", "天気": "天気は難易度ではなく、「かんたん」に変えて遊びやすくする対象ではないので合わない。", "背景": "背景は難易度ではないので、「かんたん」に変える対象として合わない。", "音量": "音量は「かんたん」に変えて遊びやすさを決める対象ではないので合わない。"}, "sentence_index": 0, "correct_answer": "レベル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この板は、レベルが三センチもあって、机に乗せると不安定だ。", "explanation": "〈厚さ〉の代わりにレベルを使った誤り。レベルは厚みを表さない。"}, {"text": "この机は、レベルが傾いていて、ボールがすぐ転がってしまう。", "explanation": "〈水平・傾き〉の意味でレベルを使った誤り。程度・水準の意味のレベルは傾きを表さない。"}, {"text": "町に集まった人のレベルが、三百人まで増えた。", "explanation": "〈人数〉の代わりにレベルを使った誤り。レベルは人の数を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レベル", "is_correct": true, "explanation": "命に関わるほどの程度を表し、報道の文として合う。"}, {"text": "予算", "is_correct": false, "explanation": "予算は命に関わる程度を表さないので、この文には合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は暑さの程度を表さないので、命に関わるという文には合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は暑さの程度ではないので、命に関わるという文には合わない。"}], "explanations": {"レベル": "命に関わるほどの程度を表し、報道の文として合う。", "予算": "予算は命に関わる程度を表さないので、この文には合わない。", "色": "色は暑さの程度を表さないので、命に関わるという文には合わない。", "歌詞": "歌詞は暑さの程度ではないので、命に関わるという文には合わない。"}, "sentence_index": 6, "correct_answer": "レベル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "棚のレベルを見ながら、板をまっすぐ水平に置いた。", "explanation": "〈水準器〉の意味でレベルを使った誤り。程度・水準の意味のレベルは測定器具を表さない。"}, {"text": "この台はレベルがずれていて、ボールがすぐ転がってしまう。", "explanation": "〈傾き〉の意味でレベルを使った誤り。程度・水準の意味のレベルは傾きを表さない。"}, {"text": "この大会はレベルが十回もあって、毎年見に行く。", "explanation": "〈回数〉の代わりにレベルを使った誤り。レベルは回数を数える語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最初の敵を倒して、主人公のレベルを一つ上がった。", "corrected_sentence": "最初の敵を倒して、主人公のレベルが一つ上がった。", "error_description": "「上がる」は自動詞なので主語に「が」を取る。「を」は目的語用で誤り。正しくは「レベルが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39005, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の作品は、世界で通用するレベルに達れた。", "corrected_sentence": "彼の作品は、世界で通用するレベルに達した。", "error_description": "「達する」の活用の誤り。「達れた」は正しくない形で、正しくは「達した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「草の根で始まった」は、草の根を起点に始まったという意味で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、始まったという動きの起点には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、「始まった」の前では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、始まるという動きには合わない。"}], "correct_answer": "で", "explanations": {"で": "「草の根で始まった」は、草の根を起点に始まったという意味で正しい。", "を": "「を」は目的語を示すので、始まったという動きの起点には合わない。", "と": "「と」は並列を示すので、「始まった」の前では文が成り立たない。", "へ": "「へ」は方向を示すので、始まるという動きには合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「草の根の努力」と名詞を続ける形で、ここに入る。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、名詞を修飾する位置には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、名詞に続く位置には入らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、この文の位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "「草の根の努力」と名詞を続ける形で、ここに入る。", "より": "「より」は比較を示すので、名詞を修飾する位置には合わない。", "が": "「が」は主語を示すので、名詞に続く位置には入らない。", "から": "「から」は起点を示すので、この文の位置には合わない。"}, "error_tags": {"より": "比較", "が": "主語", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々が自分たちで始める小さな活動のことです。", "primary_collocate": null, "pronunciation": "くさのね", "ipa": "kɯsanone", "syllable_count": 4, "sentences": [{"text": "草の根の活動が少しずつ町を変えている。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の活動[かつどう]が少[すこ]しずつ町[まち]を変[か]えている。", "sentence_source": "generated"}, {"text": "草の根で始まった清掃活動が、今では市全体に広がった。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]で始[はじ]まった清掃[せいそう]活動[かつどう]が、今[いま]では市[し]全体[ぜんたい]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "この図書館は、草の根の取り組みから生まれた。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は、草[くさ]の根[ね]の取[と]り組[く]みから生[う]まれた。", "sentence_source": "generated"}, {"text": "国の助けはなく、草の根の力だけでここまで来た。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "国[くに]の助[たす]けはなく、草[くさ]の根[ね]の力[ちから]だけでここまで来[き]た。", "sentence_source": "generated"}, {"text": "草の根の協力があったから、祭りは成功した。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の協力[きょうりょく]があったから、祭[まつ]りは成功[せいこう]した。", "sentence_source": "generated"}, {"text": "町の人たちが集まって、草の根の読書会を始めた。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちが集[あつ]まって、草[くさ]の根[ね]の読書会[どくしょかい]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "大きな団体ではなく、草の根の小さな集まりだ。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "大[おお]きな団体[だんたい]ではなく、草[くさ]の根[ね]の小[ちい]さな集[あつ]まりだ。", "sentence_source": "generated"}, {"text": "草の根の努力は目立たないが、とても大切だ。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の努力[どりょく]は目立[めだ]たないが、とても大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "子どもたちのために、草の根で勉強会を開いている。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "子[こ]どもたちのために、草[くさ]の根[ね]で勉強会[べんきょうかい]を開[ひら]いている。", "sentence_source": "generated"}, {"text": "彼女は草の根の活動を続けて、町の人気者になった。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は草[くさ]の根[ね]の活動[かつどう]を続[つづ]けて、町[まち]の人気者[にんきもの]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "草の根", "label": "基本形"}, {"form": "草の根の", "label": "連体修飾形"}], "register": "中立", "sense_fingerprint": "ふつうの人たちが自分で始める小さな活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草の根", "is_correct": true, "explanation": "「草の根の活動」は市民が自分で始める活動という意味で、町を変えている文に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は体の感覚で、活動の主体にはならない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹」は体の状態で、活動と結びつかない。"}, {"text": "心配", "is_correct": false, "explanation": "「心配」は気持ちを表す語で、活動の主体にはならない。"}], "explanations": {"草の根": "「草の根の活動」は市民が自分で始める活動という意味で、町を変えている文に合う。", "眠気": "「眠気」は体の感覚で、活動の主体にはならない。", "空腹": "「空腹」は体の状態で、活動と結びつかない。", "心配": "「心配」は気持ちを表す語で、活動の主体にはならない。"}, "sentence_index": 0, "correct_answer": "草の根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "役所の草の根の企画で、町の道路が直された。", "explanation": "ここは〈役所〉が立てる企画の意味。草の根は人々が自分で始める活動なので、役所の企画とは合わない。"}, {"text": "大企業の草の根の計画で、町に新しい店ができた。", "explanation": "ここは〈大企業〉が上から進める計画の意味。草の根は市民が自分で始める活動で、大企業の計画には使えない。"}, {"text": "本部の草の根の方針で、学校の制度が変わった。", "explanation": "ここは〈本部〉が決める方針の意味。草の根は下から始まる活動なので、本部の方針とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
